window.QUIZ_LOCAL = (window.QUIZ_LOCAL||[]).concat([{"q":"○○○과 ○○○는 권이진(1668∼1734) 선생의 호를 따서 지은 건물과 그에 소속된 재실로 보문산 남쪽 기슭 아늑한 곳에 자리잡고 있다. 부모를 간절히 생각하는 효성스러운 마음을 늘 품고 싶다는 뜻을 지닌 ‘유회(有懷)’는 중국 명나라 때 학자인 전목제의 ‘명발불매 유회이인(明發不寐 有懷二人)’이라는 시에서 따온 말이다. ○○○은 앞면 4칸·옆면 2칸 건물로 활수담이라는 작은 연못 뒤쪽에 있으며, 앞면과 양쪽 면에 난간이 돌려진 툇마루가 있고 가운데 넓은 대청마루를 중심으로 양쪽에 온돌방을 배치하였다. 제사를 지내는 재실인 ○○○는 ㄱ자형 건물로서 넓은 대청을 중…","a":"유회당(부)기궁재","c":"시도유형문화유산","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637185.jpg"},{"q":"○○○은 조선중기 때 효자로 아버지가 돌아가시자 슬퍼함이 극진하여 난리(임진왜란)를 만나서도 상복을 벗지 않았다. 또 어머니의 병환이 심해지자 손가락을 베어 피를 마시게 하여 소생케 하였으며 돌아가시자 3년간 시묘를 하여 몸이 야위어 거의 죽을 번하였다고 한다. 고을에 소문이 퍼져 사람들이 관찰사에게 보고하고 임금에게까지 알려져 1608년(선조 41) 정려를 명하여 세워진 효자문이다. ‘完山李時振之閭 萬曆 戊申春 命旌󰡑이라 편액 되어 있다. 남향으로 배치된 정려각의 규모는 정면1칸, 측면 1칸으로 구획하여 사면에 홍살을 둘렀다. 기단은 자연석을 낮게 쌓았으며 그 위에…","a":"충주 이시진 효자각","c":"문화유산자료","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660837.jpg"},{"q":"김정호의 ○○○○를 기초로 펜으로 필사한 지도로, 1892년 경에 제작되었으며 미국인 선교사들이 사용했던 것으로 추정된다. 현전하는 한글본 한양지도가 희소하고, 구한말 한양의 지명을 구체적으로 알 수 있는 등, 지도학사적․어문학적으로 가치가 있다.","a":"수선전도","c":"시도유형문화유산","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636521.jpg"},{"q":"○○○○은 석가모니불의 진신사리를 모셔놓는 건물을 가리킨다. ○○○○○은 지은 시기를 정확하게 알 수 없으나, 영조 47년(1771)에 고쳐 지은 것으로 미루어 18세기 초에 세운 것으로 추정되며 이 후에도 여러 차례 보수하였다. 이곳은 신라 선덕여왕 때 자장율사가 석가모니불의 사리를 ○○○에 수마노탑을 세워 안치하고 이를 지키기 위해 세운 것이다. 앞면 3칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양과 비슷한 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 기둥 위에만 있는 주심포 양식으로 꾸몄다. 안쪽에는 불상이 없고 신중탱화…","a":"정암사적멸보궁","c":"문화유산자료","r":"강원특별자치도","s":"정선군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660377.jpg"},{"q":"넓은 판석 모양의 화강암을 이용하여 돋을새김한 불상으로서, 훼손이 심하기는 하지만 단아하고 원만한 조각미를 지니고 있다. 민머리 위에 상투 모양의 머리묶음이 큼직하고 귀는 긴 편이며, 얼굴은 윤곽이 부드러워 온화한 인상을 나타내고 있다. 옷은 양 어깨를 감싸고 있는데 몸매를 더욱 풍만하게 표현하고 있다. 양 손은 가슴 앞에 모으고 있는 듯하나 훼손이 심하여 자세히 알 수 없다. 사실적이고 균형잡힌 조각기법으로 보아서 통일신라시대의 작품으로 추정된다.","a":"송정동석불입상","c":"시도유형문화유산","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636880.jpg"},{"q":"○○○○는 사찰 입구에 설치하는 것으로, 절에 행사나 의식이 있을 때는 이곳에 당이라는 깃발을 달아두는데, 이 깃발을 걸어두는 길쭉한 장대를 당간이라 하며, 당간의 양쪽에 서서 이를 지탱해주는 두 돌기둥을 ○○○○라 한다. 드물게 당간이 있으나 대부분 두 기둥만 남아 있다. 이 ○○○○는 ○○○ 천왕문 동쪽에 남아 있는 것으로, 두 개의 길다란 돌기둥이 서로 마주보고 있다. 기둥 끝은 안쪽면에서 바깥쪽으로 둥글게 다듬었고, 앞뒷면의 가장자리에는 테두리 선을 돌렸으며, 양 옆면 가운데에는 세로로 돌출된 띠를 새겼다. 마주보는 기둥의 안쪽면에는 당간을 고정시키기 위한 2…","a":"무량사당간지주","c":"시도유형문화유산","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639099.jpg"},{"q":"관음사는 도의선사가 창건한 것으로 전해지는데, 임란 후 17세기 초에 중수되면서 많은 속암(屬庵)이 딸린 대규모 사원이었던 것으로 추측된다. 1707년 이 후 어느 시기에 화재를 당해 다시 재건되지 못한 채 현재에 이르고 있다. ○○○○○는 1707년(숙종 33) 자연암반에 12cm 정도의 깊이를 파 세운 것으로 대좌(臺座)와 비수(碑首)는 없다. 이 비는 폐사된 관음사의 연혁을 알 수 있는 중요한 자료로, 사면비(四面碑)에 찬자(撰者), 서자(書者), 전자(篆者)가 모두 승려라는 점에서 그 특징이 있다. 지방관의 협조 없이 승려의 주도하에 만들어졌을 뿐만 아니라 사…","a":"상주 관음사지 사적비","c":"문화유산자료","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663610.jpg"},{"q":"○○○는 백제 무왕 41년(640)에 자장율사가 세웠다고 전한다. 절 경내에는 ○○○을 비롯하여 대웅전, 영산전, 대광보전, 홍성루 등 많은 건물이 남아 있다. ○○○은 지장보살을 중심으로 좌우에 명부시왕상을 모시고 있어 지장전·시왕전이라고도 한다. 지장보살은 모든 인간을 교화시키는 역할을 맡았으며, 시왕은 염라대왕을 비롯한 10명의 지옥 심판관이다.","a":"마곡사명부전","c":"문화유산자료","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660976.jpg"},{"q":"○○○○○은 가야산의 정상인 칠불봉(해발 1433m)의 동남쪽에 위치하며, 용기골의 좌·우로 상아덤과 재골산의 능선을 따라 축성된 포곡식(包谷式) 산성이다. 처음 축성한 연대에 대해서는 확실하지 않으나,『세종실록지리지』,『신증동국여지승람』등의 문헌자료에 기록이 남아 있다. 대가야의 이궁(離宮)으로 추정되고 있는 곳이다. 임진왜란시 체찰사(體察使) 이원익(李元翼)이 조정의 명을 받아 승장(僧將) 신열(信悅)을 시켜 개축하였으며, 난중에는 인근 백성들의 피난처로 이용되었던 곳으로 전하고 있다. 조선 숙종(肅宗)때 근처에 독용산성(禿用山城)이 수축됨에 따라 그 기능을 발휘…","a":"가야산산성","c":"시도기념물","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654656.jpg"},{"q":"○○○는 백제 성왕 때 창건하였다고 전하나, 통일신라 후기의 승려인 도선국사와 관련된 전설이 전해지고, 이곳에서 발견된 유물들을 볼 때에 통일신라 후기에 창건된 사찰로 보인다. 전설에 의하면 절이 세워지기 전에 근방에 있는 용담천에서 이무기가 나타나 사람들을 괴롭혔는데, 도선국사가 이 절을 세운 뒤 부터는 행패를 부리지 않았다고 한다. 조선 전기의 숭유억불정책으로 절은 사라지고, 현재는 이 탑과 함께 석불입상(보물)과 석등이 남아 있다. 탑은 1층 기단(基壇) 위에 7층의 탑신(塔身)을 얹었는데, 너무 길쭉하고 홀쭉한데다가 지붕돌이 몸돌보다 두터워서 불안정한 모습이다…","a":"용담사칠층석탑","c":"시도유형문화유산","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639375.jpg"},{"q":"이 ｢○○○○○｣은 고려 충렬왕 14(1288)년경에 간행된 목판본으로 추정되는 불경이다. ○○○○○은 삼승(성문･연각･보살)의 각기 다른 것을 깨닫게 하여 일불승으로 합일시킴을 주안으로 하는 가장 대표적인 대승경전으로 흔히 ‘법화경’이라 부른다. 우리나라 천태종의 근본경전이며, 부처가 되는 길이 누구에게나 열려 있다는 것을 기본사상으로 하고 있다. ｢화엄경｣과 함께 우리나라 불교사상의 확립에 크게 영향을 끼쳤으며, 우리나라에서 유통된 불교경전 가운데 가장 많이 간행된 경전이다. 이 판본은 구마라습鳩摩羅什의 번역본에 의거하여 ｢법화경｣의 대의를 조리 있게 이해할 수…","a":"묘법연화경 권2ㆍ4ㆍ5ㆍ6","c":"시도유형문화유산","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638869.jpg"},{"q":"○○○는 승주 송광사, 합천 해인사와 더불어 우리나라 3대 사찰중 하나로 경내는 크게 상로전, 중로전, 하로전으로 나뉜다. ○○○은 하로전의 중심건물인 영산전 동쪽에 있는데 고려 공민왕 18년(1369)에 성곡대사가 지었다고 전한다. 앞면 3칸·옆면 3칸으로 지붕 옆모습이 여덟 팔(八)자 모양인 팔작지붕으로 되어 있다. 지붕을 받치기 위해 장식하여 만든 공포는 기둥 위와 기둥 사이에도 있는 다포계 양식의 건물이다. 내부에는 아미타불상을 모시고 있으며 벽은 모두 불화와 산수화로 그려져 있다. ○○○○○은 비교적 규모가 작은 건물이지만 건물의 짜임새와 외관이 뛰어난 건물…","a":"양산 통도사 극락전","c":"시도유형문화유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641815.jpg"},{"q":"경남 함양군에 있는 ○○○○은 해발 508m 정도의 ○○○ 정상을 둘러 쌓은 테뫼식 산성이다. 자연석을 이용하여 성벽을 쌓아 올렸는데 현재 훼손이 심하여 확실히 알 수 없지만 조선시대 이전에 만든 것으로 추정한다. 인근에 있는 사근산성과 황석산성 등을 고려한다면 삼국시대나 고려시대에 이 지역 주민들의 방어용으로 쌓은 것으로 보여 산성 연구에 중요한 자료가 된다. 이 산성은 현재 거의 붕괴된 상태이며 부분적으로 흔적이 남아 있다. 그 중 양호한 상태의 남벽은 자연석을 이용하여 쌓았으며 남아 있는 성벽은 높이 2m, 길이 50m이다.","a":"함양마안산성","c":"시도기념물","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656125.jpg"},{"q":"2층 기단(基壇) 위로 5층의 탑신(塔身)을 올린 모습의 석탑으로, 주변에 절터로 보이는 건물터와 석불의 대좌로 보이는 석물 등이 남아있다. 아래층 기단의 각 면에는 둥글넓적한 안상(眼象)을 얕게 새기고, 위층 기단에는 각 면의 모서리와 가운데에 기둥 모양을 새겼다. 탑신부는 몸돌과 지붕돌을 각각 하나의 돌로 쌓아 올렸는데, 1층 몸돌은 큰 편이며, 2층부터는 높이가 급격히 낮아졌다. 지붕돌은 밑면에 3단의 받침을 두고, 네 귀퉁이는 높이 치켜 올라갔는데, 각층이 비슷한 크기로 거의 변화가 없는 것이 특징이다. 꼭대기에는 노반(露盤:머리장식 받침) 위로 앙화(仰花:활…","a":"강릉관음리오층석탑","c":"시도유형문화유산","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638145.jpg"},{"q":"○○○ 소장 칠성여래목각탱은 10매의 판목을 세로로 나란히 배치한 후, 상하좌우에서 각 1매의 목재로 고정시켜 틀을 만들어 화면을 형성한 것이다. 칠성불화를 목각에 묘사한 이 작품은 조선후기에 제작된 몇몇의 현존 목각탱이 浮彫와 透彫를 병행한 것과 달리, 부조의 단조로운 형식을 취하고 있다. 칠성여래목각탱의 구성은 치성광여래를 중심으로 좌우 일․월광보살이 협시하고 있다. 이 삼존을 중심으로 좌우에는 7위의 七元星君과 太上老君이 있으며, 그 위로 7여래가 있으며, 이 존상들은 수평으로 3단을 이룬다. 권속들은 1/4정도로 안면을 측면을 틀어 본존을 향하고 있다. 각 존…","a":"단양 방곡사 목조칠성여래설법상","c":"문화유산자료","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2022072115385900.JPG"},{"q":"개암사 종각에 보관되어 있으며, 전체 높이 89.0㎝, 입 지름 61.5㎝이다. 종의 윗부분에는 종을 매다는 고리인 용뉴와 소리의 울림을 도와주는 용통이 있다. 어깨부위에는 사각형으로 띠를 둘렀으며, 그 안에 다시 원을 그리고 범자를 새겨 넣었다. 일부는 이 사각형의 구획안에 2행의 한자 명문을 양각하였다. 어깨 아래쪽으로는 4각형 모양의 유곽과 보살입상이 4개씩 교차로 배치되어 있다. 유곽 테두리 안쪽으로 9개의 꽃무늬를 한 유두가 있다. 보살입상은 구름위에 천의를 입고 두 손을 모아 꽃을 받들고 있다. 종 입구는 어깨부위와는 다르게 띠를 두르고 꽃무늬를 새겼다.…","a":"개암사동종","c":"시도유형문화유산","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639558.jpg"},{"q":"일제강점기 때 영양지역에서 막대한 부(富)를 축적하여 자선사업을 크게 베풀었던 대은(大隱) 권영성(權永成, 1881-1959)이 1934년(甲戌年 9월 초파일)에 건립한 정자이다. 권영성은 영양향교, 김천중학교, 대구의학전문학교, 영양초.중.고등학교, 화천초등학교, 대구농림학교 등에 각종 육영사업을 베풀었으며, 수재와 극빈 구제를 위해서는 양곡을 기부하였으므로, 그를 기리는 공덕비들이 곳곳에 세워져 있다. 정자는 정면 3칸 측면 1칸 반 규모의 전통적인 누정형태인데, 정자로 오르내리는 계단이나 담장 등에는 붉은 벽돌, 인조석 씻어내기, 타일 등 근대적인 재료와 수법을…","a":"영양사정","c":"문화유산자료","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663499.jpg"},{"q":"조선시대 아산군 관아 입구에 세웠던 문루건물로, 사방을 트고 마루를 한층 높게 지은 다락형식의 집이다. 조선 태종 11년(1411) 현감 최안정이 낡은 객사를 고쳤다고 하는데, 태종 13년 백성들의 도움을 얻어 객사 동편에 지었다고 한다. 앞면 3칸·옆면 2칸 규모로, 지붕은 옆에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 새날개 모양인 익공양식이다. 기둥 사이에는 꽃받침 모양의 건축 재료를 가운데 칸에 3개, 나머지 칸에는 2개씩 만들어 처마를 받치면서 건물의 무게 균형을 맞추고 있다. 1층 3칸에 각각 문을 달아…","a":"여민루","c":"시도유형문화유산","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639024.jpg"},{"q":"전북특별자치도 익산시 ○○○에 위치한 이 산성은 일명 ‘용화산성’으로 불리는데, 옛날에는 ○○○을 용화산이라 했기 때문이다. 고조선시대 기준왕이 이곳으로 내려와 쌓았다고 하여‘기준성’이라고도 부르기도 하지만, 마한의 여러 나라 중 하나가 이곳을 중심으로 세력을 누리고 있었던 것으로 보아, 산성도 그때 만들어진 것으로 추정된다. 고려 태조가 후백제의 신검과 견훤을 쫓을 때 이를 토벌하여 마성에서 신검의 항복을 받았다고 하는데, 그 마성이 바로 이 산성이다. ○○○○은 둘레 약 1287m, 높이 2.4m이며, 정상에서 사방으로 능선을 따라 성이 만들어졌고, 그 중 하나는…","a":"익산미륵산성","c":"시도기념물","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653330.jpg"},{"q":"○○○○○에서 소장하고 있는 ○○○○○으로, 이 불상은 연기군 조치원에 위치한 대성천의 준설작업 중 발견된 불상으로 전하며, 14∼15년 전에 현재의 ○○○로 이관하여 보존하고 있다. 불상의 높이는 67cm, 어깨넓이는 34.5cm, 무릎넓이는 54.5cm이다. 광배(光背)의 윗부분이 깨어져 붙여 놓았고, 오른쪽 무릎 일부도 깨진 상태이며, 무릎에서 오른쪽으로 가늘고 긴 균열이 있어 부분적으로 메워 놓은 상태로서 거신광배(擧身光背)에 결가부좌로 앉아 있다. 법의의 옷주름은 굵으면서 매우 도식적(圖式的)이며 오른손에는 연꽃 가지를 들고 왼손은 배에서 수평으로 놓았으며…","a":"천안 성불사 석조보살좌상","c":"문화유산자료","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661565.jpg"},{"q":"○○○○○은 서울특별시 서초구 우면동 291-1 태봉산 정상에 위치하고 있다. '○○'이란 왕가에 출산이 있을 때 왕족의 태를 봉안하고 표석을 세운 곳을 의미하며, 태봉(胎封)이라고도 한다. 조선시대에는 ○○도감(胎室都監)을 임시로 설치하여 이 일을 맡게 하였다. ○○○○○은 자는 자미(子美), 호는 풍월정(風月亭)으로, 덕종(德宗)의 맏아들이며, 성종의 형이다. 일찍이 아버지를 잃은 ○○○○은 할아버지인 세조의 총애를 받으면서 궁궐에서 자랐다. 7세 때인 1460년(세조 6) 월산군에 봉해졌고, 1468년(예종 즉위년) 동생인 잘산군(乽山君: 성종)과 함께 현록대부…","a":"월산대군 이정 태실","c":"시도기념물","r":"서울특별시","s":"서초구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1644897.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. ○○○○는 고려 충렬왕 2년(1276)에 세웠다고 전해지나, 확실한 근거는 없고 대개 조선시대에 창건한 것으로 여겨지고 있다. 원래는 지금의 마산시 합성동에 있었으나 임진왜란(1592) 후 이곳으로 옮겼다고 한다. 경내에는 뒤쪽에 제사를 지내는 공간으로 ○○○과 동·서무가 있고, 학업의 공간인 명륜당과 유생들이 기거하던 동·서재, 풍화루가 앞쪽에 배치되어 있다. ○○○은 앞면 3칸·옆면 4칸의 규모로 지붕 옆모습이 사람 인(人)자 모양인 맞배지붕집이다. 공자를 비롯한 중국…","a":"창원향교 대성전","c":"시도유형문화유산","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641695.jpg"},{"q":"『○○○○○』은 ‘○○○○바라밀경’또는 ‘금강경’이라고도 하는데, 금강석과 같은 지혜로 모든 고통의 고리를 끊어야만 깨달음의 세계에 도달하게 된다는 내용을 담고있는 경전이다. 우리나라에서는 공(空)사상을 근본으로 하는 반야부 계통의 경전 가운데『반야심경』다음으로 널리 읽히고 있다. 이 책은 고려 우왕 4년(1378)에 충주 청룡사에서 간행한 것으로,『○○○○○』에 대해 설명한『○○○○○』를 다시 한번 풀이한 것이다. 닥종이에 찍은 목판본으로 크기는 가로 16㎝, 세로 29㎝이며, 마지막 장의 한면이 누락된 것을 제외하면 보존상태도 매우 양호한 편이다. 600년이 넘는…","a":"금강반야경소론찬요조현록","c":"시도유형문화유산","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639643.jpg"},{"q":"부인사에 서 있는 3층 석탑이다. 부인사는 신라 선덕여왕 때 창건한 사찰로 추정되며, 절이 한창 번성할 때에는 전국에서 유일하게 승려들만의 승시장(僧市場)이 섰었다는 흥미로운 이야기가 전하고 있다. 이 탑은 금당터 주변에 쌍탑으로 건립된 2기의 석탑 중 서쪽에 있는 탑으로, 1966년에 복원되었다. 2층 기단(基壇) 위에 3층의 탑신(塔身)을 올렸는데 꼭대기의 머리장식은 없어지고 그 받침돌만 남아있다. 기단은 각 면마다 기둥모양을 새기고 윗면에 2단의 괴임을 새겨 윗돌을 받치게 하였다. 탑신의 각 몸돌은 모서리마다 기둥모양을 새겼고, 지붕돌은 비교적 완만한 경사가 흐…","a":"부인사서탑","c":"시도유형문화유산","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636875.jpg"},{"q":"연악산(淵岳山) ○○○는 신라 흥덕왕 5년(830) 진감선사에 의하여 개창되었다. 그 후 고려 경종 원년(976) 화재로 인하여 건물이 다소 소실되고 극락전과 청천료만 남았다. 다시 명종 15년(1185) 각원대사에 의하여 대대적인 불사가 이룩되었다. 그 후 원종 14년(1273) 대수해로 인하여 대부분의 전각이 유실되었고 조선시대에 들어와서 사명대사가 중건하여 절의 이름을 ○○○라 하였다. 대웅전 내에 봉안된 ○○○○○은 근래의 개금불사로 인하여 외형상 목조의 느낌이 거의 들지 않을 정도지만 자세히 살펴보면 소나무의 결이 보인다. 나발의 두정(頭頂)에 약간의 육계의…","a":"구미 수다사 목조아미타여래좌상","c":"시도유형문화유산","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641076.jpg"},{"q":"충청남도 천안시 성거읍에 있는 ○○○는 고려 태조 4년(921)에 도선이 지은 사찰로, 석가모니불과 5층 석탑을 만들어 놓았다고 하나 신빙성은 없다. 높이 164㎝의 불상은 관음전 뒤편에 있는 자연동굴 속 암벽에 조각되어 있다. 머리를 잃어버려서 시멘트로 새로 만들었는데 신체에 비해 좀 크게 느껴진다. 깊게 새겨진 옷은 왼쪽 어깨를 감싸고 있으며, 오른손은 무릎 위에 내려 땅을 향하고 왼손은 왼발 위에 올려 놓았다.","a":"만일사 석불좌상","c":"문화유산자료","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661313.jpg"},{"q":"○○○는 횃불과 연기를 이용하여 급한 소식을 전하던 옛날의 통신수단을 말한다. 높은 산에 올라가서 불을 피워 낮에는 연기로 밤에는 불빛으로 신호를 보냈다. 경상남도 ○○시의 ○○○○○는 해발 370m의 ○○○ 정상에 있으며 산 정상에서 덕포동과 장목면의 경계를 형성한다. 봉화를 피우기 위한 연대(煙臺)는 자연석을 이용하여 축대를 쌓고 잔돌을 채워 넣어 만들었다. 현재는 바깥 2단까지 흔적이 남아 있으나 그 위는 경사가 급해 확인할 수 없고 다만 3단까지 연통이 있었을 것으로 예상한다. 만든 시기는 정확하지 않지만 구조적으로 조선 전기에 설치한 ○○도의 옥녀봉 ○○○와…","a":"거제 강망산 봉수대","c":"시도기념물","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656560.jpg"},{"q":"장춘정은 마을 가까이의 경승지에 건립된 유실형(有室形) 정자이다. 처음 건립은 1561년에 고흥류씨 유충정(1509∼1574)이며, 1818년과 1930년에 중수한 건물로서 건립연대가 오래되었으며, 옛 모습을 잘 보전하고 있다. 뼈대가 굵고 가구구조가 건실하며, 치목이 잘 되어 있다. 그리고 대청의 우물마루, 빗살창, 선자 서까래나 활주 등에서 세련미를 보인다. 역사적인 측면에서도 건립의 유서나 이곳을 중심으로 인문활동을 했던 인물(면앙 송순, 석천 임억령, 원기 오상, 풍암 임복, 사암 박순, 고봉 기대승, 손재 박광일, 백호 임제)들의 면면을 볼 때 영산강 권역의…","a":"나주장춘정","c":"시도기념물","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654359.jpg"},{"q":"○○○○○은 ○○ 지역에서 처음 확인되는 백제 사비기 ○○○으로 ○○시 흥덕구 강내면 ○○○의 미호천변에 위치하고 있다. ○○○○○은 지형상 단독 구릉지에 위치하나, 경사가 비교적 심하고 암석이 노출되어 있는 지형이다. 서쪽에 인접하여 미호천이 북에서 남으로 곡류하고 있고, 북·동·남쪽에는 충적대지가 형성되어 있다. 조사결과 백제시대 목책열 1기(주공柱孔 76기), 주거지 5기, 원형 저장공 18기, 집수장 1기, 수혈유구 16기, 주혈군 1기(주공 9기), 조선시대 토광묘 4기, 시대미상 구상유구 1기 등, 총 47기의 유적을 확인하였다. ○○○○○은 저장공과 목책…","a":"청주 석화리 목책성","c":"시도기념물","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2020051517493300.jpg"},{"q":"조선 전기의 문신인 신선경의 묘를 비롯한 거창 신씨들의 ○○이다. 신선경은 세조 1년(1456) 사헌부 장령을 거쳐 동지중추부사를 지냈다. 거창 신씨는 원래 중국 송나라 개봉부 출신인 신수(愼修)가 송나라 사신으로 고려의 수도 개경에 왔다가 고려에 귀화하여 고려인이 됨으로써 거창 신씨의 시조가 되었다. 거창 신씨 ○○ 내에 문화 류씨 ○○이 자리 잡고 있는데, 이는 공조참의 ○○○의 묘소이다. ○○○는 신선경의 사위로 이 묘는 부부합장묘이다. 묘소는 서울특별시 송파구 오금공원 내에 있는데, 이 가운데 신선경의 묘는 약 500년 전에 조성된 것으로 정부인 한씨와의 쌍분…","a":"신선경과 류인호 묘역","c":"시도유형문화유산","r":"서울특별시","s":"송파구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636253.jpg"},{"q":"「○○」은 ○○시 ○○동에 위치한 ○○ 충렬사(사적 제 236호) 아래의 2기의 우물을 일컫는다. 위쪽 샘을 일정(日井), 아래쪽 샘을 월정(月井)이라 불렀다고하며 이를 합쳐 「○○」이라 일컫는다. 일정의 물은 이(李) 충무공의 향사에 이용하고 월정의 물은 일반 민가에서 사용했다고 하며 , 1670년 제 51대 김 경(金鏡) 통제사 때 이 우물을 팠다고 전하여지고 있다. 처음에는 우물을 하나만 팠더니 물이 탁하고 수량이 적어 하나 더 팠더니 비로소 물이 맑고 수량(水量)도 많아졌다고 한다. 그러나, 그 이전의 기록에 ○○리(明井里), ○○동(明井洞) 등 이 우물과 관…","a":"통영 명정","c":"시도기념물","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657559.jpg"},{"q":"조선 후기에 지은 이 지방 부농의 집으로 고봉산 지맥이 지네와 같은 형상을 이루는 지형의 가장 중요한 곳에 자리잡고 있다. 안채는 철종 11년(1860)에 지었고 사당은 1901년에 지었다. 원래는 건물이 여러 채 있었으나 현재는 안채, 사랑채, 사당만이 남아있다. 비탈진 지형때문에 기단을 이중으로 쌓았으며, 북쪽 전면에 대문간, ㄷ자형의 사랑채가 있고 그 뒤에 一자형 안채가 있다. 건물 규모가 커지고 툇마루가 각 방을 연결하면서 길게 이어지는 등 조선 후기 주택의 특징을 잘 보여 주는 가옥이다.","a":"채원병가옥","c":"시도민속문화유산","r":"전북특별자치도","s":"군산시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658313.jpg"},{"q":"○○○ 사역 서쪽 언덕에 위치한 부도는 전각형에 편구형 탑신을 지닌 전형적인 조선후기 부도의 양식을 띠고 있다. 기단부의 하대석과 중대석, 상대석을 비롯하여 구형의 탑신과 팔각의 전각형 옥개석 그리고 상륜을 모두 갖춘 완형의 부도이다. 옥개석은 8각의 지붕형태로 묘사되었는데, 처마가 매우 두텁게 표현되어 둔중감을 준다. 처마의 전각부 2곳에는 원공이 남아있으며, 이는 풍경과 같은 부착물을 달았던 것으로 보인다. ○○○의 창건주인 백양대사의 탑이라고는 전해지나, 신라시대 부도와는 양식적으로 맞지는 않다. 전체적으로 표면의 치석수법이 거칠지만 단독으로 부도전을 마련하여…","a":"백양사 석조부도","c":"시도유형문화유산","r":"울산광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637297.jpg"},{"q":"농은 민안부의 절의를 기리기 위해 세운 서원이다. 민안부는 고려 후기 충신이며 두문동 72현(賢) 중 한 사람이다. 고려 공양왕(재위 1389∼1392) 때 예의판서에 이르렀으나, 조선의 개국으로 72현과 함께 두문동에 들어갔다. 후에 산음현의 대포리로 내려와 은둔하여 살며 고려에 대한 충성과 의리를 지켰다. ○○○○은 숙종 19년(1693)에 세웠으나, 흥선대원군의 서원철폐령으로 폐쇄되었다. 그 뒤 고종 11년(1874) 유림과 후손들이 숭절사, 숭의제, 동재·서재 등을 고쳐 세웠다.","a":"산청 대포서원","c":"문화유산자료","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664311.jpg"},{"q":"지례리에서 대대로 살아오던 고성 이씨의 종가이다. 고성 이씨의 입향시조 이후장의 손자 이원보가 숙종 36년(1710)에 세웠고 맏손자의 이름을 따서 ‘○○○○○’이라는 이름이 붙었다. 원래는 임동면 지례리에 있던 것을 임하댐 건설로 1989년 지금 있는 자리로 옮겨 세운 것이다. 一자형 사랑채와 ㄷ자형 정침으로 구성되어 ㅁ자형을 이루고 있다. 사랑채는 단촐한 건물로 지붕은 팔작지붕이며, 부엌과 방으로 구성된다. 정침은 제사를 지내거나 일을 보는 곳으로 사용하던 건물로 앞면 4칸·옆면 3칸 규모를 갖추고 있다.","a":"이태형고택","c":"문화유산자료","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662435.jpg"},{"q":"○○○○는 통일신라 신문왕 4년(684)에 양개조사가 세운 절이라고 전한다. 조선시대에 고승 무학대사가 수도한 곳이기도 하며, 사명대사가 임진왜란 때 승병들의 훈련장으로 사용하기도 하였다. 그 뒤 임진왜란 때 불탔던 것을 효종 4년(1653) 인혜대사가 ○○○과 함께 다시 세웠으나, 순조 6년(1806)에 또 화재를 2년 뒤 다시 세웠다고 한다. ○○○은 법당과 생활공간의 기능을 겸한 특이한 평면을 가진 건물로, 앞면 3칸·옆면 2칸 규모이다. 그러나 실제로 법당의 기능보다 강당의 기능을 가진 건물로 ‘인법당’으로도 부르고 있다. ○○○○○은 부분적으로 옛 건축수법을…","a":"남지장사 청련암","c":"시도유형문화유산","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636903.jpg"},{"q":"선정비란 어진 다스림을 베푼 관리의 덕을 기념하기 위하여 세우는 것으로, 이 비는 홍천 현감을 지낸 원만춘(元萬春)의 덕을 기리고 있다. 다듬지 않은 바닥돌 위로 철로 만든 비를 세운 모습으로, 비 윗변에 귀 모양 같은 것이 양 쪽에 하나씩 앙증맞게 솟아 있다. 비 앞면 중앙에는 세로로 비의 이름을 새겨두고, 양 옆으로 두 줄씩 비문을 도드라지게 새겨 놓았다. 뒷면에는 이 비를 만든 장인(匠人)의 이름도 기록되어 있어 독특한 모습이다. 원래는 홍천군 홍천읍 희망리 홍천군청 앞 도로가에 서 있었으나, 홍천박물관 내로 이전하여 관리하고 있다.","a":"홍천철비","c":"문화유산자료","r":"강원특별자치도","s":"홍천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660426.jpg"},{"q":"광주광역시 서구 ○○○에 있는 불상으로 원래 쌍촌동 운천사에 있던 것으로 1939년 지금의 위치로 옮겨 왔다. 전하는 이야기에 의하면 당시 극락면이었던 ○○○은 사람의 왕래가 많고 주민들도 많이 살았는데 마땅히 소원을 빌 만한 대상이 없어 운천사에 있던 불상을 지금의 위치로 옮겼다고 한다. 부처님의 코를 먹으면 아들을 낳는다는 소문이 퍼져 주민 뿐만 아니라 지나가는 행인들까지 코를 깎아가는 바람에 현재 얼굴 윤곽이 명확하지 않다. 머리 뒤쪽에 일부 남아있는 무늬, 상투 모양의 머리묶음, 엄지와 검지를 가볍게 쥐고 있는 오른손의 모습 등은 뚜렷하게 남아 있다. 신체는…","a":"유촌동석조여래좌상","c":"문화유산자료","r":"전남광주통합특별시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659675.jpg"},{"q":"○○○○○은 충청남도 천안시 직산면 해발 176m 성산의 계곡을 감싸고 둘러쌓은 성이다. 『동국여지승람』에 의하면 사산성은 흙으로 쌓은 성이며, 둘레는 2,947척이며 성안에 우물터가 1개 있다고 전하나 찾을 수 없다고 기록하고 있다. 이곳에서는 5∼6세기 전반의 백제나 고구려의 것으로 보이는 토기들과 6세기후반의 신라계 유물에 속하는 굽다리접시(고배), 그리고 줄무늬·격자무늬를 새긴 기와조각 등이 발견되었다. 학계에서는 마한의 목지국이 쌓은 것으로 추정하기도 한다. 문헌사 및 고고학상 매우 중요한 유적으로 평가되고 있다.","a":"직산사산성","c":"시도기념물","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652866.jpg"},{"q":"용화사는 신라시대 때 세운 절로 알려진 유서깊은 절이다. ○○○은 고려 태조 26년(943) 도솔선사가 지은 것으로, 이에 관한 설화가 전한다. 도솔선사가 미륵산의 암굴에서 수도할 때 호랑이와 가깝게 지냈는데 어느날 호랑이가 처녀를 업어와 바쳤다고 한다. 선사는 호랑이를 꾸짖고 처녀를 고향으로 데려갔는데 처녀의 아버지가 은혜를 갚기 위해 300냥을 선사에게 주었고, 그 돈으로 ○○○을 지었다고 한다. 지금도 ○○○ 위쪽에 이 바위굴이 남아 있다. 현존하는 ○○○은 앞면 3칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다.","a":"통영 도솔암","c":"문화유산자료","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663954.jpg"},{"q":"이 불상은 ○○○를 창건한 철우선사께서 금강산에서 수행할 때 석조석가여래좌상, 금동관음보살입상과 함께 폐사지에서 수습하여 모시다가 1952년부터 현재의 ○○○에 봉안하여 온 것이다. 불상의 높이는 47cm, 불두 높이는 11cm, 어깨 폭 12cm 대좌의 높이 14cm, 대좌 직경 22cm 이다. 두발은 나발로 표현되어 있으며 의상은 통견이다. 또한 큼직한 불두에 비해 어깨폭은 조금 좁아 보인다. 가슴 아래부터 U자형 의문(衣文)을 가지고 있어 주목된다. 대좌는 6엽 연화문을 서로 엇갈리게 배치하였다. 왼손의 약호[약병]는 지름 2.2cm이며, 이도 한꺼번에 주조된…","a":"구미금강사금동약사여래입상","c":"시도유형문화유산","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641119.jpg"},{"q":"1604년(선조 37) 호성공신(扈聖功臣)에 녹훈된 ○○○의 공신도상이다. ○○○은 정종(定宗)의 10번째 아들 덕천군(德泉君) 후생(厚生)의 현손이다. 1592년(선조 25) 임진왜란 당시 선조(宣祖)를 의주까지 호종한 공로로 1604년(선조 37) 호성공신 2등으로 녹훈되어 완양부원군(完陽府院君)에 봉해졌다. ○○○ 호성공신도상은 17세기 초반기에 제작된 공신도상 가운데 필치가 정밀하고 화격이 매우 높다. 공신도상의 기본 형태인 전신교의좌상(全身交椅坐像)에 공수(拱手) 자세를 취하였다. ○○○ 공신도상은 초상화의 핵심인 얼굴 표현에 있어 맑고 투명한 안색을 구사하…","a":"송암 이충원 영정","c":"시도유형문화유산","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2023041309521300.jpg"},{"q":"○○○ 종중의 소장 유물은 16세기에서 17세기에 걸쳐 생존했던 ○○○ 부자 및 그 후손과 관련된 교지(敎旨)·분재기(分財記)·호구단자(戶口單子) 등 고문서 및 『소고문집』 목판, 각대(角帶) 등이다. 이 중 고문서는 ○○○ 등의 교지(敎旨)·첩지(牒旨) 17장, 분재기 3장, 호구단자 22장, 시권 1장, 선현유묵 2장, 도(圖) 2장 등이 있다. ○○○의 본관은 반남(潘南)이며, 호는 소고(嘯皐)이다. 퇴계 문하에서 수학하고, 1540년(중종 35) 식년문과에 급제한 후, 승문원·예문관·승정원·홍문관 등에서 여러 청환직(淸宦職)을 역임하고, 1569년(선조 2)에…","a":"영주박승임종중소장전적및유물","c":"시도유형문화유산","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641145.jpg"},{"q":"○○○ 삼성각에 보존하고 있는 그림으로, 크기가 가로 211.5㎝, 세로 97.2㎝이며 비단 바탕에 채색하였다. 칠성신을 의인화하여 묘사한 것으로, 화폭의 좌우대칭으로 무리들을 배치하고 상하 2단으로 나눈 수평구조이다. 근엄함이나 신격이 사라진 각 상들의 모습, 경직된 형태와 선, 그리고 탁한 색채 등은 20세기 초 당시의 불화기법을 잘 반영하고 있다.","a":"지장사 칠성도","c":"문화유산자료","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018102513340600.jpg"},{"q":"조선시대 선조 25년(1592) 4월에 일어난 임진왜란 때 의병을 일으켜 지키다 전사한 송빈, 이대형, 김득기, 유식 선생의 공을 기리기 위하여 고종의 명으로 8년 (1871)에 건립한 묘단이다. 처음에는 동상동 873번지에 있었던 것을 ○○의 도시계획으로 동상동 227-6, 228번지로 옮겨 세운 것을 또다시 동상동 161번지 일원에 확장 이건하였으며 매년 음력 4월 20일 추모제를 지내고 있다.","a":"김해 사충단","c":"시도기념물","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655385.jpg"},{"q":"김종서 장군의 7대 손이자 김장생의 부인인 순천 김씨의 사당이다. 고종 19년(1882)에 지은 이 건물은 앞면 4칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 1987년에는 부패되어 손상된 기둥 밑부분을 절단하고 화강석으로 보강하였다.","a":"염선재","c":"문화유산자료","r":"충청남도","s":"계룡시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661418.jpg"},{"q":"봉수(烽燧)는 높은 산에 올라가서 불을 피워 낮에는 연기[燧]로, 밤에는 횃불[烽]로 급한 소식을 전하던 전통 시대의 통신 제도이다. 봉수제는 기록상으로 고려 중기(12. 3세기)에 나타나지만, 실제로는 삼국시대 이전부터 있었던 것으로 추정된다. 그러나 체계적으로 정비된 때는 왜구의 침입이 극심해진 고려 말과 조선 초기에 들어서였다. 봉수를 밝히는 ○○○는 대략 수십 리의 일정한 거리 간격으로 시야가 확 트인 산꼭대기에 설치하였다. 그리하여 평시에는 하나의 불꽃이나 연기[一炬 또는 一煙], 바다에 적이 나타나면 둘, 적이 해안에 근접해 오면 셋, 바다에서 접전이 이루…","a":"합천 금성산 봉수대","c":"시도기념물","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656776.jpg"},{"q":"○○○는 광주이씨 석전문중의 대표적인 건물로서 낙촌 이도장(各村 李道長)의 덕행을 기리기 위해 1913년에 세운 정면 4칸 측면 2칸 홑처마 팔작지붕 목조 와가의 낙촌정, 장자 귀암 이원정(歸巖 李元禎)의 유덕과 공적을 알리기 위해 1903년에 세운 정면 4칸 측면2칸 홑처마 팔작지붕의 목조와가 경암재, 장손 정제 이담명(靜齋 李聃命)의 별사봉향을 위해 세운 정면4칸 측면1칸 홑처마 맞배지붕 목조와가의 소암재와 묘실, 대문채, 관리사를 일괄하여 이름을 붙인 것이다. 재사(齋舍)와 정사(亭舍)가 하나의 일곽을 이루면서 건립 순서와 세계(世系)가 역순 이면서도 건축구성상…","a":"동산재","c":"문화유산자료","r":"경상북도","s":"칠곡군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663589.jpg"},{"q":"○○향교 서쪽 서촌에 자리잡은 옛집이다. 조선 고종 24년(1887)에 지은 집으로 안채와 사랑채, 곳간채, 문간채 등으로 구성되어 있다. 안채는 앞면 7칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 앞뒤로 퇴칸이 있고 내부는 많이 개조되어 있는 상태이다. 사랑채는 앞면 4칸·옆면 1칸 규모로 지붕은 팔작지붕이다. 뒤쪽에 부분적으로 퇴칸이 있으나 후대에 사랑방 옆면 부엌으로 확장하였고, 지붕을 덧달았다. 중사랑채는 앞면4칸·옆면 1칸 규모이며, 지붕은 옆면이 사람 인(人)자 모양의 맞배지붕이다. 후대에 1칸을 확장하여 지붕면이…","a":"밀양 교동 손병준 고가","c":"문화유산자료","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664277.jpg"},{"q":"○○○은 조선 후기의 문신이다. 본관은 전주이고, 호는 임은(林隱)이다. ○○○의 영정은 2점이 전해 온다. 1점은 관복본이고 나머지 1본은 유복본(儒服本)이다. 이렇게 2본을 함께 그린 사례는 17세기 후반 이후 유행했으며, 경기도 유형문화유산인 박세당(朴世堂), 장만(張晩), 박세채(朴世采), 이인엽(李寅燁) 등의 초상화에서 볼 수 있다. 관복본은 고개를 오른쪽으로 약간 돌린 방향으로 그렸다. 두 손을 모은 공수자세를 취했고, 표범가죽이 깔린 의자에 앉아 두 발은 나란히 발받침대에 올려놓았다. 가슴에는 단학흉배를 달았고, 얼굴 표현에서는 하얀 호분을 많이 사용한…","a":"임은이민곤영정","c":"문화유산자료","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660192.jpg"},{"q":"황희 정승의 학문과 덕행을 기리기 위한 서원이다. 황희(1363∼1452)는 조선 전기 문신으로 성품이 어질고 청렴하며 충효가 깊어 조선왕조를 통하여 가장 명망있는 정승으로 칭송받고 있다. 조선 숙종 21년(1695)에 세운 ○○○○은 고종 5년(1868)에 흥선대원군의 서원철폐령으로 폐쇄되었다가, 1955년에 다시 세웠다. 현재 남아 있는 건물로 상현재가 있는데, 앞면 3칸·옆면 1칸 규모로 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 서원 안에는 황희 정승을 중심으로 황수신·강백진·장응두 등의 위패를 모시고 있으며, 해마다 7월에 제사를 지내고 있…","a":"창계서원","c":"문화유산자료","r":"전북특별자치도","s":"장수군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661656.jpg"},{"q":"조선 전기의 문신인 우졸재 ○○○ 선생의 공을 기리고자 세운 비이다. ○○○는 김종직의 문인으로 성종 16년(1485) 문과에 급제하여 벼슬길에 오른 뒤 한성부참군, 사헌부감찰, 성균관전적 등을 지내다 부모님을 모시기 위해 스스로 청하여 창녕현감으로 내려왔다. 현감으로 있으면서 어진 다스림을 펼쳐 임금이 비단과 교서로서 포상하였다. 무오사화(1498)가 일어나자 붕당을 지어 국정을 비방하였다는 죄로 벽동으로 유배되었고, 갑자사화(1504)로 인해 처형 당하였다. 중종반정(1506) 후에 억울한 죄명에서 풀려나 도승지로 추증되었다. 인조 7년(1629) 비와 비각을 세…","a":"함안 박한주 여표비","c":"문화유산자료","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664535.jpg"},{"q":"○○지역 안동 권씨 집안의 회계서원 분원으로 조선 고종 4년(1867)에 세웠다. 처음에는 제사지내는 제실 겸 한학의 글방으로 사용하였으나 1910년 일제시대가 되자 사립학교인 경행학교로 사용하였다. 지방 신식교육을 담당하면서 민족운동의 근원지로 많은 애국열사를 배출하였는데, 대표적 인물로는 상해임시정부에서 활동하다 순국한 이교재와 3.1운동 당시 삼진지구의 주역이었던 권영조를 꼽을 수 있다. 1927년 폐교한 이후에는 지역의 문화시설로 이용하여 왔다. 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이며, 1988년 보수공사 때 마루를 늘려 규모가 커졌으나…","a":"창원 경행재","c":"문화유산자료","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664140.jpg"},{"q":"로마네스크 양식의 3층 교회건물이다. 조선 고종 27년(1890)에 우리나라에 온 ○○○ 1대 주교인 코프의 전도활동으로 ○○○의 기초가 잡히게 되자, 3대 주교인 마크 트롤로프가 건립하였다. 영국인 딕슨의 설계로 감독관 브로크가 1922년에 공사를 시작하여 1926년 5월에 완공하였다. 十자형의 평면구조를 갖고 있는 이 교회는 기초부와 뒷면의 일부는 화강석을 사용하고 나머지 벽체는 붉은 벽돌을 사용하여 지었다. 건물 전체에 공간상의 높낮이를 다르게 하여 율동감을 느낄 수 있다. 특히 종탑부는 중앙의 큰 종탑과 그 앞의 작은 종탑이 생동감있게 연결되어 있다. 서울 ○…","a":"성공회 서울성당","c":"시도유형문화유산","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636117.jpg"},{"q":"충청북도 ○○군 ○○읍 ○○○에는 조선시대에 만들어진 나무로 된 여래좌상과 관음보살좌상이 모셔져 있다. 높이 85㎝의 ○○○○○은 머리에 작은 소라 모양의 머리칼을 붙여 놓았으며, 눈·코·입이 조화를 이루어 정돈된 느낌을 준다. 목에는 3줄의 주름인 삼도(三道)가 뚜렷하고, 양 어깨를 감싼 옷을 걸치고 있다. 양 손목과 무릎에 걸쳐 두껍게 표현된 옷주름은 조선시대 특유의 양식이다. 엄지와 검지의 손끝을 맞대어 오른손은 들고 왼손은 내려 부처가 설법할 당시의 손모양을 표현하였다. 높이 72㎝의 관음보살좌상은 머리에 화려한 관(冠)을 쓰고 있다. 얼굴은 원만하여 자비스러…","a":"괴산 개심사 목조여래좌상 및 목조관음보살좌상","c":"시도유형문화유산","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638664.jpg"},{"q":"고려 후기의 학자인 익재 이제현(1287∼1367) 선생의 초상화이다. 이제현은 충선왕이 원나라에 세운 만권당에서 조맹부 등과 함께 고전을 강론하였고, 벼슬이 문하시중에 까지 올랐으며, 말년에는 왕명으로 실록을 편찬하기도 하였다. 성리학을 전파하고 발전시키는데에도 중요한 역할을 하였으며,『익재난고』·『익재집』·『역옹패설』등 많은 저서를 남겼다. 선생의 초상화는 모두 4점이 전하고 있는데, 이 초상화는 그 중 하나로, 왼쪽을 바라보고 의자에 앉아 있는 전신상이다. 소매가 넓고 비단으로 테두리를 두른 심의(深衣)를 입고 있으며, 손은 맞잡아 소매 속에 넣고 있다. 작자는…","a":"익재영정","c":"문화유산자료","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662543.jpg"},{"q":"이 불상은 조선시대 조성된 것으로 추정되는 아○○○○○이다. 불상의 크기는 전체높이 132cm, 불두높이 25cm, 무릎높이 25cm, 무릎너비93cm이다. 본존은 머리와 육계의 경계가 명확하며 머리의 정상에는 원통형의 계주가 솟아있고, 머리 중심부에는 타원형의 중앙계주가 표현되었다. 눈은 옆으로 길고 좁게 퍼져있으며, 눈썹은 둥근 기미로 처리하였다. 코는 약간 둥근 각을 이루고, 입술은 은은한 미소가 흐르도록 표현하였다. 착의는 상의 위에 대의를 입은 이중 착의법이며, 가슴은 비교적 넓고 오른쪽 어깨에 반달형 대의 자락이 걸쳐 있다. 수인은 전법륜인을 취하고 있다.…","a":"의성옥련사목조아미타여래좌상","c":"시도유형문화유산","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641122.jpg"},{"q":"충청북도 ○○시 서원구 남이면 ○○○의 대적광전 안에 주존불(主尊佛)로 모셔져 있는 불상이다. 높은 대좌(臺座) 위에 앉아 있으며, 부러져 있던 목을 잘못 복원하여 머리가 오른쪽으로 약간 틀어져 있다. 양 어깨에서부터 흘러내린 옷은 가슴 앞에서 U자 모양의 주름을 이루면서 좌우대칭으로 처리되어 무릎을 감싸고 있다. 손은 오른손 검지를 왼손으로 감싸고 있는데 이는 일반적인 지권인과는 손의 위치가 반대이다. 대좌는 3단으로 구성되는데, 상대에는 화려한 꽃술로 장식된 복판複瓣의 연화문으로 표현되었다. 중대는 팔각으로 모서리의 기둥을 모각하였고, 각 면에는 안상을 새기고 그…","a":"청주 동화사석조비로자나불좌상","c":"시도유형문화유산","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638656.jpg"},{"q":"○○○는 조선 중기에 탐진당과 적묵당을 지었는데, 이곳 자리가 좋다하여 금산의 보광사 대웅전 등을 지금 있는 자리로 옮기고 절의 이름도 ○○○라 하였다. 절의 입구에 있는 ○○○은 조선 숙종 28년(1702)에 지었다. 앞면 3칸 ·옆면 3칸 규모이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 안쪽에는 사천왕을 모시고 있는데, 다른 절의 경우 마귀를 밟고 있는 형상이지만 이곳의 사천왕은 부정한 양반이나 관리를 밟고 있다. 동쪽은 지국천왕, 남쪽은 증장천왕, 서쪽은 광목천왕, 북쪽은 다문천왕이 비파, 칼, 용, 창 등을 들고 절을 드나드는 사람들을…","a":"남해 용문사 천왕각","c":"문화유산자료","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664193.jpg"},{"q":"○○○는 ○○○을 비롯한 4곳의 암자를 포함한 사찰이다. ○○○ 안의 ○○○은 험준한 바위 위에 세운 법당으로 상○○○이라고 부른다. 조선 중종 6년(1511)과 숙종 20년(1694), 순조 17년(1817)에 다시 지었다. 이 건물은 거대한 바위 위에 세웠기 때문에 기단없이 편편한 곳에 자리잡아 원형 주춧돌만 두었다. 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕으로 꾸몄다. 기둥은 둥근기둥을 사용하였고, 벽선에 亞자형 2짝 여닫이문을 달았는데, 가운데 칸과 양 옆칸은 그 간격을 다르게 하여 예불 공간을 크게 하였다. 천장의 구조는 우물 정(井)자 모…","a":"선운사도솔암내원궁","c":"문화유산자료","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661752.jpg"},{"q":"충청남도 일대에서 유행한 돌기둥 모양의 조각상으로 높이는 3.2m이다. 대체적으로 머리 부분과 몸체에 약간의 모양만 내어 단순함과 육중함만을 나타내었다. 머리에는 보관(寶冠)을 쓴 것으로 보이며 네모난 얼굴은 도식적이다. 이목구비는 돌이 많이 닳아 명확하지 않지만 얼굴의 크기에 비해 유난히 작게 표현하여 밋밋한 돌기둥 형식으로 보인다. 오른손은 배에 대고 왼팔은 가슴에 붙였는데 신체에 비해 팔이 작은 편이다. 원통형의 신체는 양감이나 조각형태가 거의 없고 옷주름을 판별하기 어려울 정도이다. 몸체의 측면과 뒷면에는 조각을 전혀 하지 않았는데, 이는 고려말 또는 조선초…","a":"석남동석불입상","c":"문화유산자료","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661250.jpg"},{"q":"경상남도 ○○군 도천면 ○○○에 모셔진 불상이다. 자연암석의 한쪽 면을 다듬어서 선으로 새긴 마애불로, 불신과 몸 뒤의 광배(光背)를 나타냈다. 얼굴은 길고 온화하게 표현되었으며 전체적인 조각수법에서 시대가 뒤떨어짐을 알 수 있다. 한국전쟁 때 ○○○가 전부 불탔었는데, 그 때의 충격으로 불상의 중간 부분에 금이 갔다.","a":"창녕 관음사 미륵불비상","c":"문화유산자료","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663826.jpg"},{"q":"경상북도 예천군 보문면 승본리의 산 속에 서 있는 높이 160cm의 석불이다. 머리 위에는 상투 모양의 머리묶음이 뚜렷하고, 코와 귀에 약간의 손상이 있지만 온화한 인상이다. 양 어깨에 걸친 옷은 배 앞에서 가지런한 옷주름을 나타낸다. 두 손은 가슴에 모아 약그릇을 들고 있어서 이 불상이 중생의 질병을 구제한다는 약사여래를 형상화한 것임을 알 수 있다. 불상이 서 있는 대좌(臺座)는 아랫부분이 땅에 묻혀 있고 윗부분만 남아 있는데, 둥근 형태의 돌에 연꽃무늬가 새겨져 있다. 불상의 양식상 신라말 또는 고려초의 작품으로 추정된다.","a":"예천승본동석불입상","c":"문화유산자료","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663191.jpg"},{"q":"이 비는 조선 시대 1563년(명종18년)～1633(인조11년) 동안 조정의 문신으로 활약한 우복(愚伏)선생의 유적을 적은 비이다. 이 비석은 당초 도로 입구에 세워졌으나 지금은 주위가 개간되어 논 중간에 위치하고 있다. ○○○ 선생의 증손 정석교(鄭錫僑)가 경상감사 이명준(李命俊)으로부터 기증을 받은 남포석(藍浦石)에 비각 작업을 하고 세우지 못하던 것을 현손 정주원(鄭?源)이 음기(陰記)를 찬(撰)하고 1758년에 6대손 정종로(鄭宗魯)에 의하여 건립되었다. 비석 규모가 장대하고 글씨 보존이 전체적으로 양호하다. 우복 선생은 禮學(예학)에 밝아 예학자로 불리었으며…","a":"우복정경세신도비","c":"시도유형문화유산","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641055.jpg"},{"q":"경상남도 ○○군 웅양면 한기리에 있는 성곽으로 성벽은 계곡을 포함한 산 정상부를 둘러 쌓은 포곡식 산성이다. 성벽은 자연석을 이용하여 쌓았는데, 길이는 1500m, 높이는 2m 정도이며 현재 성안은 경작지로 이용되고 있다. 언제 성을 쌓았는지는 정확히 알 수 없으나, 삼국시대 백제가 신라의 침입을 막기 위하여 처음 쌓았다고 전해지며, 임진왜란 때 왜적의 침입을 막기 위하여 다시 쌓았다고 한다. 정유재란 때 이일(李鎰) 장군이 가등청정의 군사와 치열하게 싸움을 벌인 곳이기도 하다. 이 성은 남매가 쌓았다는 이야기가 전해지는데, 누이동생이 치마폭에 돌을 담아 날랐다하여,…","a":"거창 하성","c":"문화유산자료","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664032.jpg"},{"q":"○○○은 안동권씨의 재실로써 1900년에 조성된 정자인데, 위양지에 조성된 섬의 중앙에 정자를 설치하고 배로 출입하도록 한 특별한 구성은, 중앙에 정자의 문화가 많이 남아있지 않은 경남지방 및 조선 후기의 조원의 사례로서 대표적인 모범이 될 만한 구성이다.","a":"밀양 완재정","c":"문화유산자료","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2023053016522600.jpg"},{"q":"마을의 풍년과 평안을 기원하던 곳으로, ‘제신당’또는 ‘탑신제당(塔身祭堂)’이라고도 불리는 신당유적이다. ○○군 동이면 ○○○에 자리하고 있으며, 막돌을 둥글게 쌓아올린 탑·장승·솟대·산신당으로 이루어져 있다. 탑은 절에서 흔히 보는 탑의 모습과는 달리 크기가 일정하지 않은 돌을 쌓아 위로 갈수록 좁아지는 형태로, 꼭대기에 길다란 돌 하나가 솟아 있다. 그 옆의 솟대는 약 5m의 높이로, 긴 장대끝에 나무로 깍은 새의 모습을 얹어 두었다. 장승은 통나무에 사람의 모습을 먹으로 그렸는데, 마을을 지키는 수문장이 되고 있다. 산신당은 뒷산 소나무를 신이 깃든 나무로 여겨…","a":"옥천 청마리 제신탑","c":"시도민속문화유산","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658200.jpg"},{"q":"이 ○○은 조선종의 특징인 음통을 갖추고 있는 1728년 주조된 조선후기의 ○○으로서 유곽과 보살상의 모습등이 생동감있는 양식을 보여주고 있으며 , 특히 꽃을 든 보살상의 모습은 조선후기 전라도지역의 대표적인 주성장인 사인 비구와 같은 승려장인의 계열에 속하는 장인이 주조한 것으로 추정된다. 현재 종의 표면에 검은 칠이 되어 있고 명문과 문양부분이 일부 마멸되기는 하였지만 초주년대(1623년)와 재주년대(1728년) 및 처음 봉안한 장소(龍頭山 龍壽寺)등이 정확하게 밝혀져 있는 조선후기 ○○의 귀한 자료이다","a":"옥천사 소장 범종","c":"문화유산자료","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661887.jpg"},{"q":"이 집은 현재 주인인 이서영의 조부인 ○○○이 1917년에 초창(初創) 하였는데, 건축 당시에는 안채, 사랑채, 행랑채, 문간채, 곳간채 등 여러 채가 있었으나, 현재는 안채와 사랑채, 담장과 대문 일부만이 남아 있다. 안채와 사랑채는 사이에 내담을 두고 복도를 설치하여 통행이 가능하도록 되어 있었으나, 1959년 사랑채를 원불교 교당으로 사용하면서 분리되었고, 현재 대문 좌측에는 창고가 있는데, 이는 증조부가 살던 초가가 위치하고 있었다고 한다.. ○○○○○은 그의 부친(이석순)이 누룩사업으로 부를 축적하면서 함라면의 부농(만석꾼)으로 성장하였고, 또한 삼성 농장을…","a":"이배원 가옥","c":"시도민속문화유산","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658344.jpg"},{"q":"남이웅(1575∼1648) 선생의 영정을 모신 사당으로 광무 10년(1906) 유림들이 세웠다. 조선 선조, 광해군, 인조 때 정치가였던 선생은 평소 법을 준수하고 사치를 하지 않은 인물이었다. 광해군 5년(1613) 문과에 급제하여 예조좌랑, 병조좌당 등 여러 벼슬을 하였으며, 병자호란 때는 소현세자가 중국 심양으로 잡혀갈 때 극진히 모시고 따가갔다와 후에 춘성부원군에 봉해졌다. 인조 16년(1638) 대사헌이 된 후 법을 철저하게 집행하였으며, 미신을 없애려고 무당을 박해하기도 하였다. 사당 뒤쪽으로 선생의 묘소와 묘비가 있다.","a":"금남 남산영당","c":"문화유산자료","r":"세종특별자치시","s":null,"i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666861.jpg"},{"q":"전라남도 고흥군 두원면 ○○○에 있는 높이 2.7m의 거대한 ○○○○상이다. 의자에 앉아 있는 모습인데, 오른발을 의자 위에 걸치고 있으면서 다른 신체 부위보다는 작게 표현해서 독특한 자세를 보여준다. 머리에는 작은 부처가 새겨진 높은 관(冠)을 쓰고 있다. 계란형의 얼굴은 살이 올라 풍만하며, 눈·코·입과 더불어 둔중해 보인다. 우람한 체격에 주먹을 쥔 채 내려진 왼팔은 터무니없이 크게 표현되어 있다. 굵은 어깨와 팔뚝에 비해서 손은 너무나 작고, 허리는 가늘게 표현해 균형감이 떨어진다. 왼쪽 어깨만 걸친 얇은 옷은 소매자락에서 넓어져서 아래로 휘어져 있다. 의자에…","a":"고흥용산리석조보살좌상","c":"시도유형문화유산","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640060.jpg"},{"q":"커다란 판석에 두 불상을 나란히 돋을새김 하였는데, 하나의 광배(光背)에 두 불상을 새긴 이른바 일광이불상(一光二佛像)으로 두 불상은 크기와 양식이 비슷하며 귀여운 모습을 보여주고 있다. 갸름하고 고운 어린아이같은 얼굴에 천진스러운 미소를 짓고 있으며 신체에는 부드러운 굴곡이 잘 표현되었다. 양 어깨를 감싸고 있는 간략한 옷차림과 좌우로 엇바뀐 두 손의 표현 등에서 불상의 순진무구한 성격이 잘 나타나고 있다. 탄력이 줄어든 단아한 묘사와 간략한 기법 등에서 고려시대의 석조병존불입상으로 생각되며, 이러한 병존불입상은 석가불과 다보불의 병존불좌상과 연관이 있을 가능성도…","a":"청주 보살사 석조이불병립상","c":"시도유형문화유산","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638433.jpg"},{"q":"읍성이란 군이나 현의 주민을 보호하고, 군사적·행정적인 기능을 함께하는 성을 말한다. 충남 서천군 비인면 성내리에 있는 ○○○○은 한 도읍 전체를 둘러싸고 군데군데 문을 만들어 바깥과 통하게 만든 성이다. 『동국여지승람』에 의하면 세종 3년(1421) 왜구의 침입을 막기 위하여, 고려 중기에 흙으로 쌓은 성을 돌로 다시 쌓았다고 기록되어 있다. 성의 높이는 2m, 길이는 3,000m 정도이며, 지금은 성의 형태만 남아있고 대부분 훼손되었다.","a":"비인읍성","c":"문화유산자료","r":"충청남도","s":"서천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661113.jpg"},{"q":"영산강의 충적지 가장자리에 있는 평동저수지 위의 낮은 구릉에 있는 삼국시대 무덤이다. 봉분의 평면은 사다리꼴과 원형을 이어 놓은 형태이며, 사다리꼴의 밑변을 제외한 부분은 도랑이 감싸고 있어 전체적인 형태가 방패형이다. 봉분의 길이는 33m이고 원형부분에 돌방(석실)을 만들었으나, 도굴과 파괴로 석실의 구조는 알 수가 없다. 발견된 유물도 매우 적으나 사다리꼴과 원형의 연결부분 가장자리를 따라 봉분에 박혀있는 원통형토기는 그 배치형태가 우리나라에서 처음 발견된 예로 학계의 주목을 받고 있다. 또한 무덤 밑에서 청동기시대의 집터가 발견되어, 이지역에서 오래전부터 사람이…","a":"명화동장고분","c":"시도기념물","r":"전남광주통합특별시","s":"광산구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645769.jpg"},{"q":"봉림사가 소장중인 불교전적류 모두 8건으로 각각의 명칭은 묘법연화경권제1, 묘법연화경권제3,4, 묘법연화경권제4~7, 금강반야바라밀경(상), 약사유리광여래본원공덕경, 불정심관세음보살대다라니경, ○○○○○21(상), 불설대보부모은중경이다. 구마라습이 지은 묘법연화경 제1권은 목판본으로 간기는 없으나 지질, 판식 등으로 보아 14세기에 간행된 절첩장으로 보인다. 절첩장(折帖裝)은 권자본에 이어 고려 중후기에 많이 만들어진 것으로 서지학적으로 중요한 자료로 취급되고 있다. 본 불경의 경우 인쇄상태가 선명하므로 불경연구, 서지학연구 및 장정연구 등에 아주 귀중한 자료이다.","a":"월인석보 제이십일(상)","c":"시도유형문화유산","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001642622.jpg"},{"q":"○○○○ 종중의 요여는 홍성 노은서원이 철폐된 1871년에 종중에서 봉사(奉事)를 위해 제작하여 성삼문(成三問)의 신주를 논산시 상월면의 암천공 재실로 봉안할 때와 1903년 성삼문의 사손(祀孫)이 결정되어 문절사(文節祠)에 신주를 봉안할 때에 사용되었다. 요여는 붉은색, 회색, 백색으로 외부를 칠하였고, 천정은 직조물을 사용하여 납작한 반구형의 모양을 하였으며 지붕의 중앙 부분에 보주형의 장식을 달았다. 사방에 붉은색의 처마를 만들었고, 좌․우․후면에는 들창문을, 정면에는 쌍창문을 하였다. 또한 가마의 아래에 툇마루와 철제난간을, 4면의 문틀 상․하․좌․우에는 안상…","a":"무안박씨요여","c":"시도민속문화유산","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658274.jpg"},{"q":"○○○에 있는 원효대사와 의상대사가 수도하던 곳이다. ○○○은 지은 시기를 알 수는 없고, ○○○이라는 절 이름과 의상대가 있는 것으로 보아 의상대사가 세운 것으로 추정하지만 확실하지는 않다.","a":"함안 원효암 칠성각","c":"문화유산자료","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663809.jpg"},{"q":"경상남도 ○○시에 있는 ○○○은 조선 연산군 6년(1500)에 쌓은 성으로, 둘레는 1172m, 높이 2.61m, 폭 5m정도이고 북쪽과 서쪽이 양호한 상태이다. 성의 형식은 인근의 사등성이나 고현성과 같이 큰돌을 밑에 쌓고 작은돌을 그 위에 올려 쌓았다. 성 안은 대부분 민가가 들어선 마을이고 성 밖은 논으로 사용되고 있으며, 조선 초기 이후의 성의 형태를 살피는데 중요한 자료가 된다.","a":"거제 오량성","c":"시도기념물","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655502.jpg"},{"q":"○○○란 병인양요와 신미양요를 승리로 이끈 흥선대원군이 서양사람들을 배척하고 그들의 침략을 국민에게 경고하기 위해 서울 및 전국 각지에 세우도록 한 비로, 이 비도 그 중의 하나이다. 낮은 사각받침돌 위에 비몸을 세우고, 맨 위에 지붕돌을 올려놓아 다른 ○○○와는 다른 모습이다. 이는 당시 대원군의 명으로 ○○○를 곳곳에 세우자, 이 지역의 관청에서 그것을 본 떠 세우면서 양식을 달리 한 것으로 보인다. ○○○를 일제히 세우던 고종 8년(1871)에 함께 세운 것으로, 대원군이 러시아 공사관으로 납치된 후 세계 각국과의 교류가 이루어지면서 대부분의 비들이 철거되었으나…","a":"남해 척화비","c":"문화유산자료","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664570.jpg"},{"q":"이 ○○은 ○○에 약 500여년간 세거해 온 안동권씨 사용공파의 대표적인 건물이다. 경북 북부지역의 뜰집이 튼 ‘ㅁ’ 자형에서 ‘ㅁ’ 자형으로 발전하는 과정의 배치형태, 중부형 살림채의 평면구성, 살림채에 정자까지 갖춘 상류주택이다. 일부 수리가 있긴 했으나 건립시의 입체적인 벽면 구성과 구조·형태는 잘 간직하고 있어 당시의 가옥구조 및 주생활 연구에 좋은 자료가 된다.","a":"영주 원리 도율종중 고택","c":"문화유산자료","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018101510263500.jpg"},{"q":"괘불은 절에서 큰 법회나 의식을 행하기 위해 법당 앞뜰에 걸어놓고 예배를 드리던 대형 걸개그림을 말한다. ○○○에 보관된 이 괘불은 석가를 비롯한 삼존과 문수보살, 보현보살을 비단 바탕에 채색하여 그린 그림으로, 가로 287.3㎝, 세로 456㎝ 의 크기이다. 상단에 그려진 삼존은 전체적으로 부자연스럽게 표현되어 형식화된 느낌이고, 하단에 그려진 문수보살과 보현보살은 비교적 자유롭고 활달하게 묘사되어 위와 대조를 이룬다. 적색과 녹색, 청색이 주로 사용되었으며, 특히 이 시기에 제작된 다른 불화들보다 색채가 밝아 눈길을 끈다. 이 그림은 19세기 말에서 20세기에 이…","a":"지장사 괘불도","c":"시도유형문화유산","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2588019.jpg"},{"q":"한 채의 비각 안에 나란히 서 있는 3기의 비이다. 왼쪽에 있는 것은 ○○○○로, 대구판관을 지낸 이서 선생의 치적을 기리기 위해 대구 주민들이 세운 것이다. 당시 대구는 하천이 중심부로 흘러 홍수 때마다 큰 피해를 당하였었다. 조선 정조 즉위년(1776) 대구판관으로 부임해온 이서 선생은 주민들의 어려움을 알고 1778년 자신의 재산을 털어 제방을 쌓아 물길을 돌리게 하였다. 홍수의 피해에서 벗어난 주민들은 물길을 돌려 새로 만든 냇물을 ‘신천 ’이라 부르고, 제방의 명칭도 ‘○○○ ’라 한 후 정조 21년(1797)에 이 비를 세워 그를 기리고자 하였다. 원래 수…","a":"이공제비및군수이후범선영세불망비","c":"시도유형문화유산","r":"대구광역시","s":"수성구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636881.jpg"},{"q":"○○○ 이순신 장군이 정유재란 때인 조선 선조 30년(1597) 10월에서 다음해 3월까지 머물면서 군량미 및 군수물자를 모아 전쟁에 대비하던 곳이다. 장군은 이곳에 돌로 남·서 길이 1㎞, 높이 2m, 폭 1m의 성을 쌓아 적의 배를 구별하고, 군자금을 모으기 위해 오가는 배들에게 1∼3석의 식량을 내어 놓고 통행첩을 받아가도록 하여 열흘만에 일만 석의 군량미를 비축하였다. 또한 이곳에서 무기와 배를 만들며 전열을 가다듬었다고 한다.","a":"고하도이충무공유적","c":"시도기념물","r":"전남광주통합특별시","s":"목포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653965.gif"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 태조 7년(1398)에 지어진 후 임진왜란(1592) 때 불타 없어진 것을 그 뒤에 다시 지었다. 현재 남아있는 건물은 ○○○·명륜당·동재·서재·제기고·내외삼문·홍살문·하마비 등이 있다. ○○○은 제사공간의 중심이 되며, 중국과 우리나라 성현들의 위패를 모시고 제사지내는 곳이다. 앞면 3칸·옆면 2칸 반이며, 지붕 옆면이 사람 인(人)자 모양인 맞배지붕집으로 겹처마이다. 기둥 위에서 지붕 처마를 받치는 공포가 기둥 위와 기둥 사이에도 있는 다포양식으로, 가운데 칸은 간격이…","a":"익산향교대성전","c":"시도유형문화유산","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639542.jpg"},{"q":"강원특별자치도 소금강산 구룡폭포에서 왼쪽으로 산기슭을 따라 올라가면서 돌로 쌓은 성으로, 아미산성 또는 만월성이라 불린다. 전설에 의하면 신라의 마의태자가 쌓았다고 하며, 고려 충숙왕의 사위인 최문한의 아들 최극임이 의병을 이끌고 성을 쌓았다고도 한다. 구룡폭포의 동·서쪽 능선을 따라 쌓은 성으로, 동쪽의 성벽은 소금강산의 정상부를 거쳐 다시 계곡까지 약 3㎞에 걸쳐 있으나, 서쪽의 성벽은 폭포 부근에만 약 400m정도 나타난다. 동쪽 성벽은 남·서쪽으로 뻗는 산기슭을 따라 약 400m의 성벽이 남아있고, 정상부에서 서쪽으로 뻗은 산기슭을 따라 약 700m의 성벽이…","a":"금강산성","c":"문화유산자료","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660418.jpg"},{"q":"선조 1년(1568)에 귀봉 김수일(1528∼1583)이 지은 정자이다. 김수일은 과거에 합격하였으나 벼슬길에 나가지 않고, 고향에 남아 자연과 더불어 학문 연구와 후진양성에 힘썼다. 정자는 앞면 3칸·옆면 2칸 규모로 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다. 현판은 허목이 썼는데, 분실의 우려가 있어 별도로 보관하기 때문에 현재는 아무 것도 걸려있지 않다.","a":"백운정","c":"문화유산자료","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662754.jpg"},{"q":"○○○○○은 2책으로서, 하협(1583∼1625, 호 단지)과 하선에게 내려진 공신녹권이다. 각 책의 첫 페이지 서두에 수급자의 이름이 제시되어 있고 다음 페이지부터는 내용이 같다. 1614년(광해군 6)에 만들어졌고 금속활자본이다. 규격은 22.5×33.5cm이고, 상하내향삼엽화문, 사주쌍변, 계선이 있는 10행 17자의 형태를 취하고 있다.","a":"진주 단지종택 정운원종공신녹권","c":"시도유형문화유산","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642975.jpg"},{"q":"일월산 기슭에 자리잡은 이 집은 조선 중기의 문신 회곡 권춘란(1539∼1617)이 노년에 살던 곳이다. 권춘란은 아들이 없어 동생 춘계의 맏아들을 양자로 삼았는데, 이 집은 권춘계가 임진왜란 이전에 지은 것으로 추정되고 있다. 정침과 사당이 남아 있으며, 사당은 원래 정침의 오른쪽 뒤에 있던 것을 영조 14년(1738)에 지금의 위치로 옮겨 지었다. 정침은 앞면 5칸·옆면 5칸의 ㅁ자형이며, 처음 지을 당시의 흔적이 부분적으로 남아있다. 사당 안에는『회곡선생문집』과 교지·호패·공신록·행장기 등이 보관되어 있다.","a":"회곡고택","c":"시도민속문화유산","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658770.jpg"},{"q":"○○○는 전라남도 장흥군 가지산에 있는 절로, 860년 신라의 승려 체징에 의해 창건되었다. 이 책은 ○○○○○의 배안에 넣어서 보관하던 유물 가운데 하나이다. 『○○○○』는 조선 전기에 널리 유행하던 ‘금강반야바라밀경’, ‘대방광불화엄경입부사의해탈경계보현행원품’, ‘대불정수능엄신주’, ‘불설아미타경’, ‘관세음보살예문’, ‘묘법연화경관세음보살보문품’등 여섯가지 경전을 모아 한 책으로 엮은 것이다. 우리나라에서 간행된 가장 오래된 것은 세종 6년(1424)에 전라도 고산 안심사에서 만든 판본이며, 이 밖에도 현재까지 알려진 판본은 20여종 이상이 되고 있다. 이들 대…","a":"보림사사천왕상복장육경합부","c":"시도유형문화유산","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020022814022800.jpg"},{"q":"조선시대 중종때 우찬성겸병조판서를 역임한 ○○○의 ○○는 금관지의 재질로 되어 있으며, 가로 118㎝, 세로 69㎝ 규격의 52자의 글자가 새겨져 있다.","a":"이장곤 교지","c":"시도유형문화유산","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642213.jpg"},{"q":"서울시 노원구 중계동 천보산 중턱에 자리잡고 있는 ○○○이라는 단아한 암자에 모셔져 있는 마애불로, 거대한 바위면에 돋을새김으로 새긴 높이 13.4m의 ○○○○이다. 바위 측면에 새겨진 기록에는 고종 7년(1870) 명성황후가 불심(佛心)으로 만들었다는 내용이 남아 있으며, 고종 15년(1878) ○○○을 고치면서 마애불상을 보강하였다고 적고 있다. 당당한 체구에 얼굴은 원만한 모습이며 머리에는 화려한 관(冠)을 쓰고 있다. 관의 정면에는 작은 부처가 새겨져 있어 ○○○○을 표현한 것임을 알 수 있다. 양 어깨를 감싸고 입은 얇은 옷은 보살이 앉아 있는 화려한 연꽃무…","a":"학도암 마애관음보살좌상","c":"시도유형문화유산","r":"서울특별시","s":"노원구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636309.jpg"},{"q":"○○○ 천왕문 내 좌우측에 목조천왕좌상이 각각 2구씩 배치되어 있다. 향우측에 東方 指國天王, 南方 增長天王, 향좌측에 西方 廣目天王, 北方 多聞天王이 위치하며, 4구 모두 발을 아래로 내린 기형으로 발밑에는 잡귀 1구씩 각각 밟고 있다. 두부에는 화려한 보관을 쓰고 몸에는 갑옷을 착용하였는데, 양쪽 어깨에서 발 아래까지 천의자락이 흘러내리고 있다. 손의 지물로 동방은 琵琶, 서방은 龍과 如意珠, 남방은 長刀, 북방은 寶叉를 쥐고 있다. ○○○○의 제작방법은 분할제작 기법으로 각 이음부분에 나무심을 끼워 처리하였으며, 때로는 철심으로 고정하였다. 상호는 방형이며 모두…","a":"남해용문사목조사천왕상","c":"시도유형문화유산","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642585.jpg"},{"q":"○○시(구 진양군)와 사천시(구 사천군)의 경계를 표시하여 이정표 역할을 하던 비로, 직사각형의 자연돌을 약간 다듬어 놓은 모습이다. 전하는 이야기에 따르면, 천태산 마구 할머니가 물레를 하려고 바위 3개를 가져오는데, 1개는 머리에 이고, 1개는 지팡이로 짚고, 1개는 치마에 담아 가져오다가 2개는 숲에 버리고, 치마에 담고 오던 바위만 지금의 자리에 세워두었다 한다.","a":"진주 두문리 이정표석","c":"문화유산자료","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664268.jpg"},{"q":"강릉 오죽헌 시립박물관 앞뜰에 자리잡고 있는 비들로, 모두 19기에 이른다. 역대 강릉 부사 및 관찰사를 지낸 이들의 공적을 기리고 있는데, 그 중에는 임진왜란 당시 굶주림속에서도 부사의 목숨을 구해준 노비의 행적을 기리는 ‘충노 문리동 행적비’도 함께 자리하고 있어 눈길을 끈다. 비들은 땅위로 얕게 드러난 받침돌 위에 올려져 있으며, 머릿돌을 올려 조각으로 장식한 것도 있고, 그렇지 않은 것들도 있다. 원래는 명주군청에 있었으나, 1954년 남문동의 남대천가로 옮겼다가 1992년 이곳으로 옮겨 세웠다.","a":"강릉비석군","c":"문화유산자료","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660420.jpg"},{"q":"이곳은 박문효(1568∼1593)의 사당이 있던 장소이다. 박문효는 중종반정의 공신인 박원종의 후손으로서, 종묘서직장이라는 관직에 있었다. 임진왜란이 일어나 선조가 의주로 피신하자 임금을 따랐으며, 다음해 서울로 돌아오다 개성 싸움에서 26세의 젊은 나이로 순절하였다. 후에 호남 유림들의 상소에 의해 순조 17년(1817)에 이조참의로 증직되었다. 조선 순조 19년(1819)에 처음 지어졌으나 고종 5년(1868) 철거되었다. 현재 서현사터에는 부인 송씨를 위해 세운 정려와 유허비가 남아있다.","a":"서현사지","c":"시도기념물","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653487.jpg"},{"q":"○○○의 자는 자후(子厚), 호는 의암(毅菴)이며 본관은 청주(淸州)로 諡(시)는 襄惠(양혜)이며 淸州韓씨(청주한씨) 襄惠公派(양혜공파) 中始祖(중시조)이다. 1446년 음서로 관직에 나아간 후 장사랑, 소격전직장, 경복궁사연 등의 관직을 거쳤다. 1444년(세종 26) 식년문과에 급제, 내시별감(內侍別監)에 속해 있었다. 1462년 그의 딸이 동궁에 들어가면서 의흥위부사, 의빈부도사를 거쳐 공조정랑에 제수되었고 1468년 예종이 즉위하자 딸이 왕후(안순왕후)가 되자 국구(國舅)로서 보국숭록대부 청천군 겸 오위도총부도총관에 봉해졌으며 남이의 역모를 평정하는데 공을 세…","a":"한백륜 묘역","c":"시도기념물","r":"인천광역시","s":"검단구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2016082611061200.JPG"},{"q":"암울했던 일제시대의 상황을 시를 지으면서 달래던 곳으로 이 지역 선비들이 1930년에 지은 건물이다. 앞면 3칸·옆면 3칸 규모로, 가운데 1칸은 온돌방을 두었고 좌우 양쪽은 마루를 깔았다. 뒷면을 제외한 3면에는 난간을 돌렸다. 지리산 골짜기 경치 좋은 곳에 자리잡고 있으며, 우리나라 전형의 정자 형태를 취하고 있다.","a":"방호정","c":"문화유산자료","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661953.jpg"},{"q":"고성 ○○○에 있는 배찬열씨 초가이다. 안채는 4대째 살고 있다고 하며 아래채는 배찬열씨 할아버지 때 지은 것이라고 한다. 안채는 앞면 2칸·옆면 1칸 크기로 옆면과 뒷면 벽채는 막돌을 쌓고 틈은 진흙으로 메웠다. 아래채는 앞면 3칸·옆면 1칸 크기로 앞쪽 반칸에 툇마루와 아궁이를 놓았다. 가운데 칸이 온돌방이고, 양쪽 칸은 헛간이다. 안채는 민가의 가장 원시적인 형태를 띠고 있어 눈길을 끈다.","a":"고성봉동리배씨고가","c":"시도민속문화유산","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659055.jpg"},{"q":"율곡 이이·우계 성혼·사계 김장생·정암 조광조·퇴계 이황·우암 송시열 등의 선현에게 제사를 지내고 후학을 교육하기 위해 세운 서원이다. 이이(1536∼1584)는 강릉 오죽헌에서 태어났다. 어려서부터 어머니인 신사임당으로부터 학문을 배웠으며 아홉 번의 과거에 모두 장원급제하였다. 그는 이황과 더불어 조선 성리학을 대표하는 학자로, 원리를 중시한 이황에 맞대어 경험을 중시했다. 성혼(1535∼1598)은 과거에 응시하지 않고 학문에만 전념하였다. 젊어서부터 이이와 학문을 교류하였으며 많은 벼슬자리에 추대되었으나 거절하다가 이이의 권유로 관직생활을 시작했다. 이 서원은…","a":"죽림서원","c":"문화유산자료","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661002.jpg"},{"q":"○○○○는 조선시대 문신인 금계(錦溪) 황준량(黃俊良, 1517~1563)이 학문을 닦고 교육을 하던 곳이다. 황준량은 이황(李滉)이 행장(行狀 : 죽은 사람의 평생의 행적을 기록한 글)을 지을 정도로 아끼는 제자였다. 황준량의 자는 중거(仲擧), 호는 금계이며 본관은 평해이다. 중종 35년(1540) 과거에 급제한 후 성균박사, 호조좌랑 겸 춘추관 서기관, 성주목사를 역임하였으며, 중종·인종 양대 임금의 실록 편찬에도 참가하였다. 건물의 좌측에는 온돌방이, 우측에는 대청이 설치되어 있고 전면과 좌측에는 쪽마루가 설치되어 있다. 평면구성은 16세기 중엽 창건 당시 모…","a":"영주금양정사","c":"시도유형문화유산","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018101509314800.jpg"},{"q":"이 영정은 ○○○○○의 좌안7분면 바닥가부좌상으로, 왼손에는 불자를 들고, 오른손은 염주를 쥔 채 불자의 술을 만지고 있다. 바닥에 화문석을 깔지 않았고 돗자리를 경계로 배경을 이분화하는 구도를 취하지 않았으므로 이단구도에 선행하는 형식임을 느끼게 한다. 그리고 배경에 문양이 없는 점, 인물이 안정된 삼각형 구도를 갖추지 않고 있는 점, 지물이나 법의의 표현이 도식화되지 않은 점 등으로 보아 통도사 소장의 바닥가부좌상 가운데 비교적 앞선 시기의 작품으로 추정된다. 화면 향우측으로 ‘○○○대선사○○진(花谷堂大禪師誡天眞)’의 화제만이 있을 뿐이다. 화면 크기는 가로 56…","a":"화곡당 계천 진영","c":"시도유형문화유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643007.JPG"},{"q":"물암 김융(1549∼1594)이 후진을 양성하기 위해 세운 건물이다. 김융은 퇴계 이황의 가르침을 받고 여러 벼슬을 두루 거쳤다. 임진왜란 때에는 왜적을 물리치고 백성을 구할 수 있는 방책을 유성룡에게 건의하기도 하였으며, 죽은 뒤에 승정원 좌승지에 임명되었다. 선조 2년(1569)에 세운 이 서당은 앞면 4칸·옆면 2칸 규모의 건물로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 가운데 2칸은 마루, 양 옆으로는 온돌방을 배치하였으며, 현판은 퇴계 이황의 친필이다.","a":"두릉서당","c":"문화유산자료","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662967.jpg"},{"q":"고려 후기의 무신인 경렬공 정지(1347∼1391) 장군의 묘소이다. 공민왕 14년(1365)에 사마시에 장원급제하고 이듬해 문과에 급제하여 벼슬길에 올랐다. 공민왕 23년(1374)에 우리나라 최초로 수군 창설 계획을 올려 전라도 안무사로 발탁되었으며, 우왕 3년(1377)에는 순천 도병마사가 되어 순천·낙안 등지에 침입한 왜군을 격퇴하였다. 우왕 14년(1388)에 이성계의 위화도회군에 종군하여 그 공로로 공양왕 2년(1390)에 2등공신에 봉해지면서 판개성부사로 임명되었으나 부임하지 못하고 병으로 세상을 떠났다. 현재 묘역에는 돌로 만들어진 묘와 묘비, 석인(石…","a":"정지장군예장석묘","c":"시도기념물","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645733.jpg"},{"q":"복장에서 발견된 발원문에 따르면, 이 불상은 1674년(현종 15)에 백운산(白雲山) 영은사(靈隱寺)에 봉안하기 위해 200명에 달하는 시(施)·발원자(發願者)들이 동참하여 만들었고, 원래는 아미타여래를 본존으로 좌우에 관음과 대세지보살이 협시하는 아미타삼존상으로 조성되었음을 알 수 있다. 현재 좌우 협시인 관음·대세지보살상은 소실되었으며, 본존 아미타여래만이 ○○○ 대웅전의 주불로 예배되고 있다. 불상의 제작은 수화원(首畵員) 성조(性照)를 비롯하여 한운(閑云), 자규(自圭), 학청(學淸), 성수(性修), 설매(雪梅), 사원(思遠) 등 7명의 조각승들이 함께 제작하…","a":"함양 백운암 목조아미타여래좌상","c":"시도유형문화유산","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643162.jpg"},{"q":"고조부 안영제가 1906년(광무 10, 병오)에 건립한 근대한옥으로, 입산마을에 세거하는 ○○○○의 종가로 안채의 대청 종도리 받침장여 밑면에 “大韓光武十年丙午....”라고 쓴 상량 묵서가 있어 1906년에 지은 것임을 알 수 있다. 전통적인 건축형식에 근대의 합리성과 효율성을 반영한 건물로 사용한 부재가 견실하고, 치목수법이 우수하여 일제강점 이전시기의 경남지방 부농층의 정침 모습을 잘 보여주는 자료이다.","a":"의령 탐진안씨 종택","c":"문화유산자료","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666372.jpg"},{"q":"강원특별자치도 철원군 ○○○ 해발 350m의 금학산 동쪽자락 중턱의 거대한 바위면을 다듬어 조각한 ○○○입상이다. 동남향을 하고 있는 불상은 전체 높이 576㎝, 불신 높이 450㎝, 머리 높이 134㎝이다. 몸 부분은 바위면에 직접 새기고 머리 부분은 다른 돌로 만들어 몸통에 꽂아 결합시켰다. 평면적인 불신에 비하여 머리는 입체적인 형태로, 삼도(三道)가 뚜렷한 원통형의 굵고 길다란 목이 함께 붙어 있다. 민머리 위에는 상투 모양의 높직한 머리묶음이 표현되었으며, 얼굴은 긴 네모꼴의 타원형으로 원만한 인상을 하고 있다. 손모양은 아름다운 선을 사용하여 비교적 사실적…","a":"동송읍마애불상","c":"문화유산자료","r":"강원특별자치도","s":"철원군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660381.jpg"},{"q":"고려 태조 왕건을 도와 후백제를 평정하는데 공을 세운 밀양손씨의 입향조이자 중시조인 손긍훈(孫兢薰)의 ○○이다. 손긍훈은 고려 건국공신으로 태조 왕건을 도와 후백제 견훤의 아들인 신검을 황산전투에서 사조잡은 공로로 좌명공신에 선정되고, ○○○에 봉해졌으며 그가 죽은 후에 ○○○○○에 추증되었다. 1894년 갑오경정 이후 관향이 폐지되자 후손들이 춘복재의 현충사로 이봉하여 모셨으며 현재는 밀양시립박물관에 보관 중이다. ○○은 붉은 관복을 입고 오른손에 긴 칼을 들고서 의자에 앉은 무인의 모습을 나무로 깎아 만들었는데 매서운 눈과 큰 키로 보아 힘찬 호령을 하는 듯한 표…","a":"삼중대광사도광리군 목상","c":"문화유산자료","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664351.jpg"},{"q":"울릉도 내에서 가장 많은 무덤이 밀집하여 분포한 무덤들이다. 완만한 경사면에 40여기가 분포하고 있다. 무덤의 형태는 기단을 만들고 가운데 직사각형의 돌방(석실)을 만들어, 시체를 넣고 그 위에 돌을 이용하여 봉분을 만든 이른바 석총으로 삼국시대의 것으로 생각된다. ○○○ 포동무덤들은 울릉도 지역에서만 볼 수 있는 특징적인 형태를 가지고 있는 석총으로 이 지역 무덤연구에 중요한 곳이다.","a":"울릉현포동고분군","c":"시도기념물","r":"경상북도","s":"울릉군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654520.jpg"},{"q":"충청남도 예산군 덕산면 ○○○ 절터에서 나온 이 보살입상은 함께 발견된 3층석탑과 같이 마을 회관에 보존되어 있다. 불상은 탑의 맞은 편에 세워져 있으며 아랫부분이 땅에 묻혀 있다. 정수리 부분이 평평하고 귀는 긴 편이나 어깨에 닿지는 않는다. 목에는 3줄로 새겨진 삼도(三道)가 있는데 뚜렷하지 않다. 왼손은 가슴 앞까지 들어 손가락을 펴고 있는 모습이고, 양 어깨를 감싼 채 길게 입은 옷은 발까지 내려져 있다. 전하는 이야기에 의하면 약 300년 전에 지금의 마을회관 동쪽 150m되는 지점에 절이 있었는데 난리 중에 불에 타 버렸다고 한다.","a":"석곡리미륵불","c":"문화유산자료","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661204.jpg"},{"q":"○○○은 낙동강이 굽이도는 연안 마을 등성이에 북향으로 배치되어 낙동강을 바라보고 있다. 초창은 1420년대이나 1636년에 폐하였다가 다시 중건하였다. 1827년 경상감사(慶尙監司)로 부임한 정기선(鄭基善)에 의해 중건되었다. 그 후 세 차례 이건하였으나 1909년에 구기(舊基)에 다시 돌아와 중건되었다. 또한 옛 모습을 비교적 잘 지니고 있으며, 가운데 마루방을 둔 평면형식은 아주 드문 예로 희소가치가 크다.","a":"예천 삼수정","c":"문화유산자료","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663542.jpg"},{"q":"강원특별자치도 원주시 ○○○에 있는 사람키 만한 ○○○○ 입상이다. 머리에는 관(冠)을 쓰고 있으며, 풍만한 얼굴에 눈·코·입은 작게 표현되어 있지만 미소를 띠고 있어 친근한 인상이다. 오른손은 가슴에 대고, 왼손은 배에 대고 있으며, 신체에 비해 팔은 가늘고 손이 작아서 불균형한 모습이다. 상체의 옷은 양복처럼 보이고, 큰 체구에 구름무늬 같은 하체의 옷주름이나 머리에 쓴 관 모양이 일반적인 보살과 거리가 먼 특이한 형태이다. 친근한 인상과 옷이나 신체 등 형식적인 세부표현에서 고려 보살상의 특징과 지방색이 어우러져 있는 작품으로, 이 지방의 불상양식을 알 수 있는…","a":"원주봉산동석조보살입상","c":"시도유형문화유산","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638019.jpg"},{"q":"봉의산 기슭에 자리 잡고 있는 ○○○은 삼국시대에 세운 것으로, 처음에는 이요루라고 부르던 것을 조선 순종 때 부사 윤왕국이 ○○○이라 고쳐 불렀다. 원래는 지금보다 아래쪽인 소양강 남안에 있었다. 조선 선조 38년(1605) 홍수로 없어진 것을 광해군 2년(1610) 부사 윤희당이 다시 짓고, 인조 25년(1647)에는 부사 엄황이 고쳐 짓는 등 여러 차례 고쳐 지었으며, 지금 있는 건물은 한국전쟁 때 소실된 것을 1966년 다시 지은 것이다. 건물 규모는 앞면 4칸·옆면 2칸이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다.","a":"소양정","c":"문화유산자료","r":"강원특별자치도","s":"춘천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660300.jpg"},{"q":"율재 정경(1490∼1564)을 모신 사당으로 후손들이 세웠다. 정경 선생은 조선 중종 때 무신으로, 효성이 지극하고 청렴결백하여 인근에 그 이름이 알려졌다. 임진왜란으로 건물이 무너져 정조 14년(1790)에 다시 지었으며 1970년대에 와서는 처마를 아름답게 단장하였다. 앞면 4칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양의 팔작지붕이다. 대청마루를 사이에 두고 좌우에 방을 두었는데 방·부엌·마루·건넌방·건넌방 부엌으로 구성되어 있다.","a":"영동 송담재","c":"문화유산자료","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660759.jpg"},{"q":"고종 31년(1894) 동학농민운동이 터졌을 때, 관군이 동학군과 싸워 나주성을 지킨 것을 기념하기 위해 세운 비이다. 거북을 새긴 받침돌 위에 비몸을 세우고 그 위에 지붕돌을 올린 모습이다. 받침돌은 땅 속에 파묻혀 그 윗부분만 보이고 있다. 비문의 내용은 크게 세부분으로 나뉘어 농민운동이 일어나 나주에까지 동학군이 쳐들어오게 된 과정과 당시 나주목의 수령이던 민종열 목사가 여러 장수들을 지휘하여 치밀한 방어계획을 세웠던 사실, 그리고 관군과 동학군이 나주목에서 싸우는 과정등을 자세하게 서술하였다. 동학군에 반대했던 유림들이 뜻을 모아 세운 것으로 짐작되며, 비문은…","a":"금성토평비","c":"문화유산자료","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662167.jpg"},{"q":"충청남도 논산시 ○○○에 있는 이 ○○○은 대둔산 정상 부분의 바위면에 움푹 들어가게 새긴 것으로 전체적인 형상은 완전하나 비바람으로 인해 마멸이 많이 되었다. 양 어깨를 감싼 옷은 발 부분까지 내려져 있으며, 손모양은 오른손은 자연스럽게 아래로 늘어뜨리고, 왼손은 손가락을 편 채 가슴 위로 들어 올려 몸에 붙였다. 제작 연대와 제작자는 알 수 없으나, 불상의 조각수법으로 보아 고려말 조선초에 만들어진 작품으로 추정된다.","a":"논산수락리마애불","c":"문화유산자료","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661325.gif"},{"q":"○○○ 소장 ○○○○○상도는 1901년에 조성된 것으로 본존을 중심으로 보살상, 사천왕, 제자상과 그 외 권속들이 좌우대칭을 이룬 군집구도이다. 도상구성은 화면 중앙의 석가를 중심으로 대좌 전면 좌우에 합장한 아난과 가섭을 배치하고, 본존의 양쪽에 보살상 3위, 사천왕상 2위씩 각각 배치하고, 화면 가장 위쪽에는 두광 좌우측에 분신불과 제자상을 각각 나타내고 있다. 본존은 연화좌 위에 결가부좌한 자세로 오른손은 가슴 위로 들고 왼손은 무릎 위에 두어 중품하생의 수인을 결하고 있다. 본존 앞의 두 보살상은 두부에 비해 신장이 긴 편으로, 향우측의 보살은 연꽃줄기를, 향…","a":"산청문수암석가영산회후불탱","c":"시도유형문화유산","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642655.jpg"},{"q":"이 마을의 부자로 알려진 두릉 정원달(1853∼1924)이 1890년경에 지은 건물이다. 뒤에 산을 두고 앞에 강이 흐르는 곳에 자리잡은 집으로 이 집터는 옛날 길안현의 관아터로 알려지고 있다. 원래는 3칸 규모의 대문채가 있었는데, 20여년 전에 없어지고 지금은 정침(正寢)만 남아 있다.","a":"두릉구택","c":"문화유산자료","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662976.jpg"},{"q":"○○○○○는 1932년에 용화면 월전리에 있던 정참봉의 집을 옮겨 지었다고 전해오는 주택으로 ‘영사재’라 불린다. 오래된 건물은 아니지만 특징 있는 세부 소재를 갖추고 있다. ㄱ자형의 안채와 ㅡ자형의 부속건물 그리고 행랑채의 지붕보다 한단 높이 만든 솟을대문 등이 남아있다. 안채는 자연석을 쌓아 만든 기단 위에 마루 앞면에는 긴 주춧돌을 놓고 다른 부분에는 4각으로 다듬은 주춧돌을 놓았다. 지붕은 옆모습이 여덟 팔(八)자 모양인 팔작지붕이다.","a":"영동 묵정리 고가","c":"시도유형문화유산","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638620.jpg"},{"q":"○○○ 극락전에 모셔져 있는 ○○○ 불상이다. 오른손을 어깨 위로 들고, 왼손을 무릎에 둔 채 각각 엄지와 중지를 맞댄 ○○○불 특유의 설법인(說法印) 손갖춤을 맺었다. 양손은 따로 만들어 끼워 넣었다. 전체 높이가 138cm에 이르러 조선 후기에 제작된 불상 가운데 중형에 속하며, 상체를 약간 앞으로 내밀어 구부정한 자세를 취하고 있다. 정수리와 머리 중앙에 있는 큼직한 상투 매듭 구슬, 사각형의 얼굴과 신체 구성, 상체를 뒤로 젖히고 머리를 약간 앞으로 내민 모습, 폭이 넓고 단순한 옷주름 형태 등에서 조선 후기 불상의 특징을 잘 보여준다.","a":"현등사목조아미타좌상","c":"시도유형문화유산","r":"경기도","s":"가평군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2227640.jpg"},{"q":"충청남도 천안시 ○○○에 있는 백제의 토성과 성 안에 있는 청동기시대의 집자리 유적이다. 토성은 해발 120m의 야산 구릉 정상에 테를 두른 모양으로 쌓았으며, 둘레는 약 260m이다. 성벽은 흙을 다져 쌓은 방법으로 축조하였는데, 이를 위해 기둥을 세웠던 흔적이 120∼150㎝ 간격으로 배치되어 있다. 성 밖으로는 직선 5∼6m 거리에 성벽 주위를 돌려 판 도랑이 있다. 토성 안에는 기원전 10세기에서 9세기경에 조성된 것으로 보이는 움집 3기가 있는데, 바닥을 약간 파내려가게 만든 직사각형 형태이다. 내부에는 여러 개의 화덕이 있으며, 민무늬토기와 돌칼 등의 석기…","a":"천안백석동선사유적및백제토성","c":"시도기념물","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652868.jpg"},{"q":"○○○는 횃불과 연기를 이용하여 급한 소식을 전하던 옛날의 통신수단을 말한다. 높은 산에 올라가서 불을 피워 낮에는 연기로 밤에는 불빛으로 신호를 보냈다. 조선시대의 문헌에 ○○○ 주봉에서 북쪽으로 벗어난 능선의 서쪽 봉우리에 있다고 표시되어 있어, 이 곳이 ○○○○○임이 밝혀졌다. 함경도 경흥에서 시작하여 강원도를 거쳐 온 연락을 남산에 최종적으로 보고하던 곳이다. 터만 남아있던 것을 서울정도 600년 기념사업의 하나로 1994년 모형을 설치하였다.","a":"아차산 봉수대 터","c":"시도기념물","r":"서울특별시","s":"중랑구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1644795.jpg"},{"q":"○○○ 진남루 북서쪽에 있으며, 조선 영조 10년(1734)에 처음 세운 정자이다. 인조가 이괄이 일으킨 반란(1624)을 피하여 공주로 잠시 피난 왔을 때, 이곳에 머물렀던 일을 기념하기 위해 세운 것이라고 한다. 이후 여러 차례 보수되어 오다 1970년에 전체적으로 해체하여 지금의 모습으로 복원하였다. 건물은 앞면 3칸·옆면 2칸이며, 지붕은 옆에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다.","a":"공산성쌍수정","c":"문화유산자료","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660946.jpg"},{"q":"○○○○○은 탑정저수지 북쪽 끝에 위치한 고려시대 석탑으로, 전승에 의하면, 고려 태조가 남쪽으로 견훤을 정벌할 때 이곳에 주둔하여 '어린사(魚鱗寺)'라는 절에 있던 탑이라는 설과 후백제 때 대명(大明) 스님의 부도(浮屠)였다는 설이 함께 전한다. 원래의 탑은 일제강점기 저수지 조성 과정에서 원래 자리에서 약 50m 북쪽으로 옮겨진 것으로 알려져 있다. 탑의 전체적인 구조는 부도탑(浮屠塔, 사리나 유골을 안치하기 위한 묘탑)으로, 기단(基壇)과 탑신(塔身)으로 구성되어 있으나, 현재는 1층만 남아 있어 원형을 정확히 파악하기 어렵다. 기단은 하대석(下臺石), 간석(竿…","a":"논산탑정리석탑","c":"시도유형문화유산","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639101.jpg"},{"q":"○○○ 김열의 별당이다. ○○○은 이율곡(1536∼1584)과 같은 시대의 사람으로 학문과 덕행이 뛰어났다. 평소에 친하게 지내던 율곡은 집 주변에 소나무를 심고 가꾸면서 청빈하게 살아가던 ○○○을 높이 칭송하면서 선물로 호송설(護松說)을 지어 주기도 하였다. 앞면 3칸·옆면 2칸 규모이며, 지붕 옆면이 여덟 팔(八)자 모양인 화려한 팔작지붕집이다. 소나무 숲을 배경으로 하여 2단의 장대석 위에 지어진 집으로, 별당 이름은 김열의 호를 따서 지은 것이다. ○○○의 뒷쪽에 위치한 ㅁ자형 집은 본채로서 ○○○과 함께 수 차례의 수리를 거쳐 오늘날에 이르고 있다. 건물의…","a":"임경당","c":"시도유형문화유산","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637972.jpg"},{"q":"이 전적은 중국 송나라 사마광이 지은 편년체통사인 ○○○○에서 송나라 주희가 춘추의 체례에 따라 주요 사실을 강(綱)으로 하고 그에 대한 주자학적인 안목의 해설을 목(目)으로 엮어 ○○○○○으로 제명한 것이다. 세종은 이 ○○○○○의 인출을 위해 필요한 방대한 용지를 중앙과 지방관서에 만들게 하는 한편, 강(綱)의 본문은 진양대군에게 큰 글자를 쓰게 하여 1436년 연(鉛)으로 주조하고 병진자(丙辰字)로 명명하였다. 그리고 목의 중간 글자와 작은 글자는 1434년에 주조한 갑인자(甲寅字)를 사용하여 1438년에 찍어 낸 것이 바로 이 책이다.","a":"자치통감강목 권23상","c":"시도유형문화유산","r":"인천광역시","s":"연수구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637131.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 중종 12년(1517)에 처음 세운 것으로 선조 24년(1591)과 광해군 2년(1610)에 고쳐 지었다. 인조 21년(1643)에 향교의 위치가 너무 높아 평지인 지금 있는 자리로 옮겼다. 건물 배치는 앞쪽에 배우는 공간으로 강당인 명륜당이 있고, 뒤쪽에 제사 공간인 대성전이 있어 전학후묘의 구조로 되어 있다. 명륜당은 앞면 5칸·옆면 2칸 규모로 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는…","a":"홍산향교","c":"시도기념물","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652969.jpg"},{"q":"담양 ○○○에 소장된 조선후기의 목조 ○○○○○이다. 2005년 2월 확인된 복장물의 발원문(28.5cm×131cm)을 통하여 1660년 5월 15일 담양 용구산 회적암에서 ○○○불 1구를 조성하여 봉안(順治十七年庚子五月十三日造成彌陀一軀畢功安于龍龜山晦迹庵)했음을 알 수 있다. 불상의 형식은 촘촘하게 밀집된 나발에 상단 계주와 하단계주가 선명하며, 얼굴은 사각형이지만 턱 부분이 약간 좁으며 이마 중앙에는 백호가 돌출해 있고 예리하게 뻗은 가는 눈썹과 정면 아래쪽을 향하고 있는 일자형의 눈, 뭉뚝한 코와 사실적인 입술을 하고 있는 이목구비가 비교적 선명한 편이다. 목에는…","a":"담양호국사목조아미타여래좌상","c":"문화유산자료","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662322.jpg"},{"q":"임진왜란 때의 의병장인 ○○○ 장군의 묘이다. ○○○은 임진왜란이 일어나자 고향인 안성에서 외삼촌 홍자수와 함께 의병을 일으켜 북진하는 왜적을 수차례 격퇴하였다. 그 뒤 용인·죽산·양지에 진을 구축하는 동시에 서운산성에 토성을 쌓아 경기·충청 지방의 의병들과 합세하여 왜적을 무찌르다 전사하였다. 1718년(숙종 44)에는 묘소에서 1㎞ 떨어진 장군의 생가에 정문(旌門; 충신, 효자, 열녀 등을 표창하고자 그 집 앞에 세우던 붉은 문)이 세워지고 병조참의의 벼슬이 내려졌다. 묘역은 부인과 함께 매장된 쌍분(雙墳 ; 두개의 봉분)의 형태이다. 원래 묘표(墓表 ; 무덤 주…","a":"이덕남장군묘","c":"시도기념물","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645978.jpg"},{"q":"○○○은 남이면 건천리와 역평리 성치산(해발 759m) 동쪽에의 정상부에 있는 석성으로, ○○군 제원면과 추부면을 지나 충북 영동과 옥천으로 연결되는 전략적 요충지에 위치하고 있다. 형태는 산 정상 부분을 둘러 쌓은 두른 테뫼식이며, 성의 둘레는 207m이다. 성벽의 동쪽, 남쪽, 북쪽은 대부분 허물어졌으나 서벽은 비교적 잘 남아있다. 성벽의 너비는 4m이다. 유물로는 백제시대 각종 명문와를 포함한 다량의 기와편과 토기편 등이 출토되었다.","a":"금산 백령성","c":"시도기념물","r":"충청남도","s":"금산군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652822.jpg"},{"q":"『○○○○』는 조선 중기의 문신이자 정유재란 때의 의병장인 수은 강항(姜沆,1567∼1618)이 중국의 역사서인『자치통감』과『통감강목』을 보완, 정리한 것이다. 숙종 28년(1702)에 새긴 것으로, 목판은 총 642매이다. 강항은 1593년 문과에 급제하여 교서관정자, 공조와 형조의 좌랑 등을 지냈다. 정유재란 때 왜적의 포로가 되어 일본으로 끌려갔다가 그곳에서 후지와라, 아카마쓰 등과 친분을 나누며 그들에게 학문적인 영향을 주었다. 그후 그들의 도움으로 포로생활에서 풀려나 귀국하였고, 여러 벼슬에 임명되었으나 스스로 죄인이라 하여 나아가지 않았다. 그가 죽은 후…","a":"영광내산서원강감회요목판","c":"시도유형문화유산","r":"전남광주통합특별시","s":"영광군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640138.jpg"},{"q":"○○○○은 대전광역시 동구 소호동에 있는 산성으로 소호동산성으로 불리우기도 한다. 예전에 소호동과 대별동을 넘나드는 고개를 ‘비파치’라 불렀는데, 고개 이름을 따서 ○○○○이라 불렀다. 자연석을 이용하여 산꼭대기를 빙둘러 쌓은 산성으로 현재는 거의 대부분이 붕괴되어 원형을 찾아볼 수 없다. 성을 쌓은 방법도 알 수 없으며, 다만 문의 넓이가 2.2m가 되는 남문터만 확인할 수 있다. 성 안의 평평한 곳에서는 백제의 것으로 보이는 평행선무늬를 새긴 토기 조각과 줄무늬, 격자무늬가 있는 기와 조각들이 발견되었다. ○○○○은 보문산성과 직접 연결되고 있으며, 대전의 동쪽에…","a":"비파산성","c":"시도기념물","r":"대전광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645810.jpg"},{"q":"○○○는 우리나라 3대 사찰 중 하나로 통일신라 애장왕(재위 800∼809) 때 순응과 이정이 세웠다고 전하며 팔만대장경판을 보관하고 있다. ○○○○○은 원래 경홍전이라고도 불렀는데 왕과 태자의 만수무강을 비는 건물이다. 고종 29년(1892) 민형식의 뜻에 따라 범운화상이 지었고 경홍전이라 불렀다. 그 뒤 1946년 주지스님인 환경이 이름을 ○○○으로 바꾸고 해행당에 모시고 있던 역대 고승들의 영정을 이곳에 모셨다. 지금은 해인승가대학의 도서관으로 사용되고 있다.","a":"합천 해인사 경학원","c":"시도유형문화유산","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642258.jpg"},{"q":"경남대학교 박물관 소장 ‘데라우치문고’(寺內文庫)는 조선 제3대 통감(統監)과 초대 총독(總督)을 지내고 일본의 총리대신(總理大臣)을 역임한 데라우치 마사다케(寺內正毅, 1852～1919)가 한국 재임 중에 수집한 자료를 일본으로 가져가 세운 데라우치문고(寺內文庫, 현 야마구치현립대학 소장)로부터 돌려받은 조선시대 문헌을 말한다. 일본 야마구치현립대학의 데라우치문고에는 조선과 관계된 문헌이 약 1,000여종 1,500여점 소장되어 있다고 한다. 경남대학교 박물관은 이중 98종 135책 1축(1,959점)을 1996년 1월 24일에 일본 야마구치현립대학(山口縣立大學)으…","a":"정축입학도첩","c":"시도유형문화유산","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018102913562800.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 지상에 무덤방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅속에 무덤방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 경상남도 ○○시 장마면에 있는 이 고인돌은 바둑판식으로 원래 7기의 고인돌이 북두칠성 모양으로 무리지어 있었는데, 지금은 파괴되어 2기만 남아 있다. 1기는 덮개돌이 있고 그 밑에 평평한 판석을 이용하여 길이 1m, 너비 0.3m…","a":"창녕 지석묘","c":"시도기념물","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654733.jpg"},{"q":"경상남도 ○○군 위천면 상천리 강남사 절터에 있는 ○○○○○으로 부처의 몸에서 나오는 빛을 형상화한 광배(光背)를 가지고 있다. 얼굴은 마모가 심하며, 목에는 3줄의 주름인 삼도(三道)가 뚜렷하게 표현되었다. 양 어깨를 감싸고 입은 옷을 입고 있는 것 같으나 전체적으로 마모가 심해 형체를 알아볼 수가 없다.","a":"거창 강남사지 석조여래입상","c":"시도유형문화유산","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642244.jpg"},{"q":"오천 정씨 집안의 묘와 강의공 정세아의 무덤가에 세운 비를 보호하기 위하여 지은 집과 비각이다. 조선 인조 15년(1637)에 진주목사 정호인이 처음 지었다고 한다. 지금의 건물은 후에 다시 지은 것으로 보이며, 영천댐 건설로 인하여 1976년 지금의 위치로 옮겨 지어졌다. 강의공 정세아는 임진왜란(1592) 때 의병대장에 추천되어 많은 공을 세웠다. 그러나 그 공으로서 상을 바라지 않고 관직을 떠나 시골에서 제자를 기르며 학문을 닦은 덕망이 높은 선비였다. 경내에는 ○○○, 신도비각 등이 있는데 모두 단순하고 소박하게 지은 건물이다.","a":"하천재<부비각>","c":"시도유형문화유산","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640368.jpg"},{"q":"안동 ○○○ 백화전에 보존되어 있는 그림으로, 비단바탕에 채색으로 그려진 ○○○○와 ○○○○이다. 탱화란 천이나 종이에 그림을 그려 액자나 족자 형태로 만들어지는 불화를 말한다. ○○○는 창건연대와 그 밖의 내력에 대해서는 전하는 바가 없으나 의상조사가 창건하였다는 사실과 도광 22년에 백화전을 중수하였다는 기록이 ○○○ 중수기에 기록되어 있다. ○○○○는 지장보살을 중심으로 좌우에 십대왕과 권속을 배치한 전형적인 조선후기 불화양식이며, 색조 또한 적록이 잘 조화되어 안정감이 있고 필치가 섬세하고 유려하나 현재 좀이 심하게 쓸은 상태이다. ○○○○는 일반 ○○○○에서…","a":"안동모운사지장탱화,제석탱화","c":"문화유산자료","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663392.jpg"},{"q":"제작 연대가 분명하고 만든 스님의 이름까지 알 수 있는, 조선 시대 후기의 대표적인 중형 나무 불상 가운데 하나이다. 이 ○○○의 본존 부처는 앉은 자세에서 오른손을 곧게 펴서 무릎 아래로 내린 이른바 항마촉지인(降魔觸地印)이라는 석가모니불 특유의 손갖춤(수인)을 하고 있어 ○○○○○로 불려 왔다. 그러던 중 2007년에 ○○○의 표면 금칠을 새로 하면서 왼쪽 협시보살에서 ‘왼쪽 보좌 미륵보살(左補處彌勒菩薩)’이라고 쓴 발원문(發願文; 바라고 원하는 것을 적은 글)이 발견되어 이 ○○○이 석가모니불을 중심으로 그 왼쪽에 미륵보살이, 오른쪽에 제화갈라보살이 보좌하는 수…","a":"안성칠장사대웅전목조석가삼존불좌상","c":"시도유형문화유산","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637785.jpg"},{"q":"선조 37년(1603) 강원도 관찰사 이광준이 벗들과 함께 금강산을 유람하고 적은 글이다. 금강산은 문인이라면 꼭 들러야하는 순례지로 인식될 정도로 금강산에 오르길 원했다. 『○○○○○』은 현재 복간본 3책이 전해지고 있는데 이광준의 후손가, 이광준의 3남 민환의 사위 송세빈 후손가, 부산의 고서화 수집가 도종현씨가에 소장되어 있다. 이 작품은 이광준 후손가에 전해지고 있는 것으로, 선조 37년(1603)에서 영조 11년(1735) 사이에 만들어졌다. 유금강산기 외에 이호민이 짓고 한석봉이 쓴 감상문, 이정의 묵죽도와 이익의 감상문이 첨부되어 있다. 이에 비해 송세빈…","a":"유금강산권","c":"시도유형문화유산","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641025.jpg"},{"q":"○○○은 영남지역에서 재지사족으로 자리 잡고 있는 기호학파의 노론계열인 ○○ 법전의 진주강씨 강재항을 기리는 정자이다. ○○ 법전의 진주강씨는 입향 이래 영남지방의 재지사족과 유대를 강화하면서 중앙정계를 출입하였다. 특히 강재항은 관직에서 은퇴한 이후 향리에서 강학 활동을 하며 삼계서원의 향음주례에 참여하는 등 영남학파의 선비들과 활발하게 교유하고 있어 주목된다. ○○○은 구릉지의 암반 위에 건축된 특이한 정자이며, 소장되어 있는 책판과 현판도 매우 주목되는 문화유산이다. 뿐만 아니라 조선후기의 독특한 정자 건물로 몇 차례의 보수를 거쳤으나 그 원형이 잘 보존되고 있…","a":"봉화 뇌풍정","c":"문화유산자료","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663782.jpg"},{"q":"○○○은 조선 영조 12년(1736)에 용궁 전씨의 시조인 전섭의 47대손인 전후회가 세웠다. 율곡 선생의 학덕을 흠모하여 자신의 호를 경율이라 하고, 서당 이름도 ○○○이라 했다. 후손들의 학문 연수와 인격 수양의 장소로 훌륭한 인재가 많이 배출됐다. 앞면 4칸·옆면 2칸으로, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕으로 되어있고 4면 모두 마루가 있어 전형적인 서당의 구조형식을 보여주고 있다. 지붕 마루 끝에 있는 기와에 ‘옹정30년을유’라는 글이 있어 1730년대의 건물임을 알 수 있다. 현재는 해마다 전씨 문중의 제사를 지내는데 이용되고 있다.","a":"옥천 경율당","c":"시도유형문화유산","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638695.jpg"},{"q":"조선 철종 8년(1857) 담양지역의 부사 벼슬을 지내던 황종림이 이 지역 노인들을 돌보고 젊은이들을 교육하기 위하여 지은 2개의 정자 중 하나이다. 1925년에 고쳐 지었고, 1981년에는 고속도로 건설로 인해 88올림픽 고속도로 옆으로 옮겨 지었다. ○○○은 앞면 2칸·옆면 2칸 규모로 이루어져 있으며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. ○○○처럼 노인을 돌보고 젊은이를 교육하기 위하여 지은 정자는 매우 드물고 중요한 사례이다.","a":"남희정","c":"문화유산자료","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661918.jpg"},{"q":"○○○는 전라남도 장흥군 가지산에 있는 절로, 860년 신라의 승려 체징에 의해 창건되었다. 이 책은 ○○○○○의 배 안에 넣어서 보관하던 유물 가운데 하나로, 모두 41종 58책이다. 금강경과 법화경을 비롯한 경전류가 주종을 이루고 있는 것이 특징인데, 금강경은 ‘금강반야바라밀경’의 줄임말로 반야심경과 더불어 조계종의 근본 경전으로 많이 읽힌다. 또 ‘묘법연화경’이라 불리는 법화경은 천태종의 근본 경전으로, 화엄경과 함께 한국 불교사상 확립에 크게 영향을 미친 불경이다. 이들 책의 대부분은 전라도 지역에 있는 사찰에서 간행된 것이 특징인데, 이 점으로 미루어 ○○○…","a":"보림사사천왕상복장경전불서","c":"시도유형문화유산","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020022814451400.jpg"},{"q":"○○○○○에 보존되어 있는 동학교에 관한 ○○로, 총 177종 1,084점에 이른다. 동학은 조선 철종 11년(1860) 최제우가 창시한 종교로서, 처음엔 서민층에 널리 유포된 단순한 신앙형태이었으나, 나중에는 사회개혁운동의 주체로 변모되어 민족운동의 역사에 큰 획을 긋게 되었다. 2대교주 최시형을 거쳐 3대 손병희에 이르러서는 내부의 대립이 심화되어 30여 개의 교파로 나뉘고 각기 독립된 교당을 설립하였다. 1922년 김낙세 부자의 노력으로 설립된 ○○○○○은 대대적인 간행사업을 벌이기도 하는 등 활발한 활동을 편 끝에 ○○, 문경, 안동 등 경북을 중심으로, 충청…","a":"상주 동학교당 유물","c":"시도민속문화유산","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658834.jpg"},{"q":"언제 지어졌는지 정확히 알 수는 없지만, 고운 최치원 선생이 함양태수로 있을 때 이 누각에 자주 올랐다 하여 학사루라 불리었고 통일신라시대에 지은 것으로 추정된다. 원래는 관아에 딸린 건물로 옆에 객사가 있었고, 동쪽에는 제운루, 서쪽에는 청상루, 남쪽에는 망악루가 있었다고 전한다. 지방관리가 피로한 마음을 풀기 위하여 이곳에 올라 시를 짓고 글을 쓰며 몸과 마음을 달래던 곳으로 알려져 있다. 조선 숙종 18년(1692)에 다시 지었다고 전하며, 1979년에 지금의 위치인 함양군청 정문 앞에 옮겨 지었다. 김종직이 이곳 군수로 있을 때 학사루에 걸린 유자광의 시를 내…","a":"함양학사루","c":"시도유형문화유산","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641549.jpg"},{"q":"○○○과 보성선씨 및 강행의 묘 3기이다. 3기의 무덤은 평면 長方形이며, 護石은 가장 아래에 납작한 地臺石을 놓은 뒤 들여쌓기로 板石을 立垂積하고 맨 위에 판석을 橫平積하여 마무리하였으며, 護石의 4모서리 上段石은 屋蓋石 모양으로 처리한 것이 특이하다. 무덤은 가장 위쪽의 姜國興 무덤을 기준으로 그 아래에는 婦人 寶城宣氏, 다시 그 아래에는 姜國興의 아들 姜行의 무덤이 축조되어 있는데, 위에서 아래로 내려올수록 主軸線이 약간씩 좌측으로 틀어져 있다. 묘의 형태 및 석물 등으로 진주.○○지역의 조선 초기 묘제를 잘 파악할 수 있는 자료 임","a":"산청 강국흥 묘역","c":"시도기념물","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657573.jpg"},{"q":"○○○○○은 1931년 근촌 백관수, 백낙윤 등 96명의 장학계원들이 상해임시정부에 보낼 독립군자금 모집과 인재 양성 등 항일 운동을 위해 지은 건물이다. 흥동장학계는 1914년 근촌 백관수 선생이 친지 백낙윤 등과 함께 항일독립투쟁을 위하여 만든 모임으로, 성내면에서 82명, 서울 등 다른 지역에서 14명의 회원을 모집하였다. 고창지역 독립만세운동을 주도하였고, 상해임시정부에 군자금을 전달하였으며, 장학계원들이 출자한 자금으로 성내보통학교와 고창고보의 설립을 후원하는 등 민족교육진흥과 장학사업을 펼쳐 반일 독립사상을 고취시켰다. 학당의 건물은 앞면 6칸·옆면 3칸이…","a":"흥동장학당","c":"문화유산자료","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661783.jpg"},{"q":"대구 ○○○ 중앙봉의 정상 가까운 절벽에 새겨진 거대한 크기의 ○○○○불상이다. 민머리 위에는 상투 모양의 머리묶음이 큼직하며, 탄력있고 우아한 얼굴은 이목구비가 세련되고 단아하다. 둥근 어깨는 탄력있어 보이며, 허리는 잘록하게 표현되었다. 무릎에서 밖으로 내려뜨린 오른손과 무릎 위에 얹어 약 그릇을 들고 있는 왼손의 세련성 등은 이상적인 사실주의 양식을 보여주고 있다. 왼쪽 어깨를 감싼 옷은 몸의 굴곡이 드러날 정도로 얇은 편인데 옷주름은 자연스럽고도 규칙적이며, 가슴에서 옷깃이 한번 뒤집히는 등 8세기 불상의 특징을 보이고 있다. 광배(光背)는 불꽃이 타오르는 모…","a":"팔공산마애약사여래좌상","c":"시도유형문화유산","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636843.jpg"},{"q":"○○○는 횃불과 연기를 이용하여 급한 소식을 전하던 옛날의 통신수단을 말한다. 높은 산에 올라가서 불을 피워 낮에는 연기로 밤에는 불빛으로 신호를 보냈다. ○○○○○는 일운면 와현리 및 구조라리에 있는 해발 303m의 망산 옆에 위치한 ○○○로서 지세포성과는 약 5㎞이내에 자리잡고 있다. 현재의 상태를 보면 산 정상부의 지면을 조정한 후 2단으로 석축하여 올린 것처럼 되어 있으나 아래의 석축은 방호벽으로 쌓은 것으로 보이고, 그 위의 석축은 봉화부가 붕괴된 상태로 추정된다. 방호벽은 원형으로 담장과 같이 축조된 것으로 추정되는데 석축을 보강하기 위함인지 일정 간격으로…","a":"거제 와현봉수대","c":"시도기념물","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657118.jpg"},{"q":"조선 후기의 실학자로 새로운 학풍을 일으키는 데에 큰 역할을 한 반계(磻溪) ○○○ 선생의 묘이다. ○○○은 『반계수록』 등을 통해 조선의 개혁안을 제시한 실학의 선구자다. 묘역은 부인 풍산 심씨(豐山沈氏)와 합장된 단분(單墳 ; 하나의 봉분)의 형태이다. 1971년에 정비한 곡장(曲墻; 봉분이 있는 구역을 보호하기 위해 주위에 두르는 담)을 제외하면 원형을 보유하고 있다. 묘표(墓表; 무덤 주인공의 이름 등을 새긴 비석)는 봉분의 정면 오른쪽에 세웠다. 1768년(영조 44)에 제작되었으며, 묘표의 옆면과 뒷면에는 홍계희가 지은 글을 새겼다. 원수방부형(圓首方趺形;…","a":"유형원선생묘","c":"시도기념물","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646012.jpg"},{"q":"○○○○○ 건물은 1923년 교인들의 헌금으로 지은 한옥 예배당이다. 1902년 감리교 전도사 윤정일이 복음을 전도하기 위해 이곳 주문도리에 들어왔고, 1905년에는 교회와 신도가 마음을 모아 영생학교를 설립하여 민족의식을 고취시켰으며, 1923년 교인들의 헌금으로 이 교회를 새로 지었다. 1978년 주문교회에서 ○○○○○로 이름을 바꾸어 오늘에 이르고 있다. 지붕은 옆에서 볼 때 여덟 팔(八)자 모양의 팔작지붕이며, 홑처마집이다. 건물 안은 중세 전기의 서양교회 양식을 하고 있으나 매우 단순하여, 예배실로 쓰이는 좁은 신랑(身廊)과 측랑(側廊), 중앙의 강단으로 구…","a":"강화 서도 중앙교회","c":"문화유산자료","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659556.jpg"},{"q":"○○○○○에 보존되어 있는 그림으로, 산수를 배경으로 나한상이 다양한 모습으로 배치되어 있는 16나한도이다. 이 16나한도는 비단 바탕에 채색하여 그려진 것으로, 원래 총 4폭이었으나 1폭이 결실되어 3폭만으로 구성되어 있다. 나한상의 육신은 붉은색에 백색안료를 많이 섞은 분홍색으로 피부를 표현하였고, 육신선은 가는 먹선 위에 엷은 붉은색 선을 겹쳐서 나타내었으며, 육신선에 따라 붉은색으로 바림하여 입체감을 살리고 있다. 머리 부분은 노승(老僧)의 경우 흰 선으로 머리털을 표현하고, 약승(若僧)의 경우 녹청을 발라 묘사하였다. 옷차림은 대개 녹청 혹은 군청 장삼에 홍…","a":"마하사 응진전 십육나한도","c":"문화유산자료","r":"부산광역시","s":"연제구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659362.jpg"},{"q":"조선시대 유학자인 남명 ○○ 선생의 시문집을 널리 간행하기 위해 만든 책판이다. ○○은 평생 학문에 힘썼으나 과거에는 나아가지 않았다. 1567년 임금이 불러도 나아가지 않고, 다만 왕을 만나 난을 다스리는 방도와 학문을 마칠 것임을 밝히고 다시 고향으로 돌아갔다. 일상생활에서도 철저한 절제로 일관하여 의(義)가 아닌 것과는 절대 타협하지 않았다. 같은 시대에 살았던 퇴계 이황과 쌍벽을 이루는 학풍을 만든 인물로, 임진왜란이 일어나자 의병으로 참여하는 등 국가에 위기가 닥치면 몸소 앞장서서 싸움에 참여하였다. 그가 죽은 후 차례로 대사헌, 영의정에 추증되었고, 여러…","a":"조식 남명문집 목판","c":"시도유형문화유산","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641763.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배계층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식, 땅속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 북제주군 애월읍 광령리에 돌담에 있는 이 고인돌은 덮개돌이 반으로 쪼개져 경사면에 쓰러져 있으며 받침돌은 보이지 않는다. 원래는 밭 한가운데에 있던 것을 경작지를 만들 때 밀어낸 것으로 보인다. 덮개돌은 직사각형의 바둑판 모양으로 윗면은…","a":"광령지석묘 3호","c":"시도기념물","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657673.jpg"},{"q":"｢妙法蓮華經｣은 ‘法華經’이라 약칭하기도 하며 天台宗의 根本經典으로 부처가 되는 길이 누구에게나 열려 있음을 基本思想으로 하고 있다. ｢華嚴經｣과 함께 우리나라 佛敎思想의 확립에 가장 크게 영향을 끼쳤으며 三國時代 이래로 가장 많이 流通된 佛敎 經典이다. 이 간본은 1561년(명종 16)에 간행된 목판본이다. 발문에는 성달생(成達生, 1376～1444)이 해운(海雲)의 부탁을 받아 능엄경 필사를 하였고, 또 법화경 필사를 시작하였으나 함길도도제사가 되어 북방의 일을 하는 연유로 마치지 못하였다고 하고, 임효인(任孝仁)과 조절(曺楶)이 필사를 마친 후에 혜신(惠信) 등…","a":"묘법연화경 권6~7","c":"시도유형문화유산","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638872.jpg"},{"q":"일제시대 문인인 심훈이 1934년 직접 설계하여 지은 집이다. 심훈은 소설가이자 시인으로, 그의 작품은 민족주의와 저항의식을 기본정신으로 하고 있다. 그는 이곳에서 1935년 농촌계몽소설로 유명한 대표작인 ‘상록수’를 썼다. 필경사는 한때 교회로 사용되기도 하였는데, 그의 장조카인 고 심재영 옹이 다시 사서 관리하다가 당진군에 기증하였다. 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다.","a":"당진필경사","c":"시도기념물","r":"충청남도","s":"당진시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652869.jpg"},{"q":"조선 중기의 문학자였던 지봉(芝峰) ○○○ 선생의 묘이다. 1614년(광해군 6)에는 『지봉유설』을 간행하여 우리나라 최초로 천주교와 서양문물을 소개함으로써 실학 발전의 선구자가 되었다. 묘역은 부인 안동김씨(安東金氏)와 합장된 단분(單墳 ; 하나의 봉분)의 형태이다. 동자석인은 두 손을 공손히 모아 서 있는 모습으로 미소를 띠고 있다. 머리는 쌍계형(雙髻形 ; 두 개의 상투머리가 위로 솟은 형태)으로 묶고 어깨장식을 둘렀으며, 허리띠를 묶어 내린 17세기의 전형적인 동자석인이다. 망주석은 소형이지만 균형이 잘 잡혔고, 귀(耳; 몸돌에 조각된 손잡이 형태의 조형) 장…","a":"이수광선생묘","c":"시도기념물","r":"경기도","s":"양주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646092.jpg"},{"q":"○○○○○군은 초기철기~원삼국시대의 주변 마을을 조성했던 당시 주민들이 축조한 무덤유적으로 ○○○ 고인돌은 서귀포시 서남부 지역에 위치하고 있으며 행정구역상으로는 제주특별자치도 서귀포시 대정읍 ○○○ 1614번지, 1628번지 외 3필지[○○○○○ 1호], 1607번지[○○○○○ 2호], 1619번지[○○○○○ 3호], 1619번지[○○○○○ 4호]에 각각 축조되어 있다. 가시악(加時岳)[106.5m 오름] 하단의 구릉상에 위치하고 있다. ○○○○○ 3호는 덮개돌의 형태가 타원형에 가깝게 이루어져 있다. 긴 쪽의 방향은 북에서 동쪽으로 35° 정도 기울어져 있다. 덮…","a":"동일리지석묘3호","c":"시도기념물","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657736.jpg"},{"q":"조선시대에 만들어진 총 높이 86㎝, 몸체 높이 66㎝, 입 지름 63㎝인 범종이다. 종을 매다는 부분인 용뉴는 각각 여의주을 물고 있는 2마리의 용으로 장식하였는데, 용머리 위에도 불꽃에 휩싸인 1개의 여의주을 장식하였다. 용머리 장식이나 발의 조각기법은 약간 경직되어 있다. 음통을 대신하여 종의 윗부분에 2㎝ 정도의 구멍을 종의 윗부분에 뚫었다. 종 위쪽 띠에는 범자 문양 띠를 둘렀으며, 띠 아래에는 사각형의 유곽과 4구의 보살상이 동일선상에 번갈아 배치되었다. 유곽과 보살상 사이에 왕실의 안녕을 비는 글이 새겼다. 유곽 안에는 연꽃무늬의 바탕에 연봉오리 모양의…","a":"원효사소장만수사범종","c":"시도유형문화유산","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637152.jpg"},{"q":"○○○ 소장의 벽암존자○○은 전형적인 18세기 후반 초상화의 양식적 특징을 잘 보여주고는 있으며 화면 중앙에 오른쪽을 향하여 의자에 앉아 있는 벽암존자상(碧巖尊者像)을 단독 배치한 ○○으로 대각선 구도를 보여 정적인 화면에 운동감을 부여하고 있다. 근엄한 듯 자상한 얼굴에 오른 손은 무릎 위로 내려 검지손가락을 들어 변화를 주고 있으며, 왼손은 의자 팔걸이에 기댄 채 왼 어깨에 걸친불자(拂子)를 잡고 있다. 내의 깃과 소맷자락 및 흰색 동정과 대조를 이루어 깔끔한 느낌을 주는 다갈색 섞인 녹색장삼 (長衫)은 전반에 걸쳐 녹색 돋을 선을 사용하여 옷주름과 문양이 표현되…","a":"합천 해인사 국일암 벽암선사 진영","c":"시도유형문화유산","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643133.jpg"},{"q":"조계종 화엄사에 딸린 말사로, 1196년(고려 명종 26) 보조국사 지눌이 창건하였다. 지눌이 수행할 곳을 찾다가 여기에 절을 지으면 '나라가 흥한다'는 신령한 노승의 말에 따라 지금의 자리에 절을 세우고 '○○○'라고 이름 지었다 한다. 몽골군의 침입으로 불타 없어졌다가 조선 시대에 다시 세웠으나 임진왜란과 정유재란을 겪으면서 법당과 요사가 완전히 불타버린 것을, 1624년(인조 2) 계특대사가 다시 지었다. 백두대간 끝자락 지리산에서 여수로 뻗어 내린 산줄기의 한 갈래인 진례산과 영취산이 연꽃처럼 감싸도는 곳에 자리잡고 있으며, 대웅전, 팔상전, 원통전, 무사전…","a":"흥국사","c":"문화유산자료","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661962.jpg"},{"q":"경남대학교 박물관 소장 ‘데라우치문고’(寺內文庫)는 조선 제3대 통감(統監)과 초대 총독(總督)을 지내고 일본의 총리대신(總理大臣)을 역임한 데라우치 마사다케(寺內正毅, 1852～1919)가 한국 재임 중에 수집한 자료를 일본으로 가져가 세운 데라우치문고(寺內文庫, 현 야마구치현립대학 소장)로부터 돌려받은 조선시대 문헌을 말한다. 일본 야마구치현립대학의 데라우치문고에는 조선과 관계된 문헌이 약 1,000여종 1,500여점 소장되어 있다고 한다. 경남대학교 박물관은 이중 98종 135책 1축(1,959점)을 1996년 1월 24일에 일본 야마구치현립대학(山口縣立大學)으…","a":"강표암선생유묵(경산이한진전서첩)","c":"시도유형문화유산","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018102913494100.jpg"},{"q":"영양 남씨 괴시파종택(경상북도 민속문화유산) 오른쪽에 서향으로 자리잡고 있다. 규모는 앞면 3칸·옆면 1칸 반이고, 큰마루 앞면에는 4짝 여닫이문을 설치하여 마루방으로 꾸몄다. 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕으로 꾸몄으며, 서당 주위에는 네모반듯한 모양의 담장을 둘렀다. 또한 앞면 담장 사이에는 4개의 기둥문을 세워 출입구로 삼았다.","a":"물소와서당","c":"문화유산자료","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663283.jpg"},{"q":"정조 때 왕실 내사품으로 알려진 방형의 ○○○○ 2점이다. 고대 중국 청동기인 방정(方鼎)을 방제(倣制)한 것이다. 몸체의 문양은 대칭을 이루며 상단에는 용이 교차하는 문양을 3구씩 배치하고, 하단에는 도철(饕餮)이라는 상상의 동물을 표현하였다. 세밀하게 장식된 문양을 통해 높은 수준의 주조기술로 제작된 작품임을 알 수 있다.","a":"금동향로","c":"시도유형문화유산","r":"경기도","s":"화성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637356.jpg"},{"q":"뒤에는 갓등산이 둘러있고 앞에는 반변천이 흐르는 아늑한 자리에 서남향으로 자리잡고 있는 건물이다. 이 정자와 살림집은 조선 중기 효종 때 삼수당 조규(1630∼1679) 선생이 지은 것이다. 솟을대문을 들어서면 왼쪽에 정자가 놓이고 그 앞쪽에 살림집이 있다. ○○○은 앞면 3칸·옆면 2칸의 정자로 왼쪽은 2칸의 온돌방을 두었고 가운데와 오른쪽에는 4칸의 대청마루를 두었다. 건물의 4면에는 돌출한 좁은 마루를 돌렸으며, 대청은 누마루로 높이 올렸다. 세부 건축양식은 일반적인 조선 중기의 모습을 잘 간직하고 있다. 살림집은 ㅁ자형을 기본으로 하면서, 전면이 양쪽으로 돌출…","a":"학초정및정침","c":"시도민속문화유산","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658738.jpg"},{"q":"동래부사 이문원의 기부금과 동래부 유지들의 모금을 바탕으로 동래부의 남문 밖에 있던 네 곳의 나무다리를 돌다리(石橋)로 바꾼 것을 기념하여 세운 비석이다. 원래 동래고등학교 앞 길가에 있던 것을 도로확장공사로 인하여 금강공원 안의 임진동래의총 입구에 옮겼다가 그후 지금의 자리로 다시 옮긴 것이다. 나무다리는 1∼2년마다 다시 고쳐 쌓게 되는데 그때마다 백성에게 그 비용을 거두었으므로 백성들의 고통이 심하였다. 이에 강위성이 지역 주민의 부담을 덜기 위하여 돌다리를 만들자는 의견을 내놓고 박도유, 박사인 등 4∼5명이 지역을 돌며 모금하자 당시 동래부사까지 자신의 녹봉…","a":"사처석교비","c":"시도기념물","r":"부산광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2328903.jpg"},{"q":"○○○ 마을의 여러 곳에 놓여 있는 세 쌍의 돌장승이다. 마을 뒤쪽의 높은 언덕 위에 자리한 남상(男像) 2기, 맞은 편 밭가에 자리한 여상(女像) 2기가 상신장(上神將)이고, 벅수골이라는 마을의 당산 나무 아래 있는 남상 2기가 하신장(下神將)이다. 원래는 네 쌍이 건립되었지만 이 중 하신장의 여상 한 쌍이 도난당하여, 1980년 같은 자리에 새로 만들어 세웠는데 이는 민속자료 지정에서 제외되었다. 6기의 장승 중 남장승은 묘 앞에 세우는 문인석과 비슷한 모습으로 앳된 얼굴이다. 관모를 쓰고 앞에서 모아 쥔 손에는 홀(笏)-임금을 뵐 때 신하가 조복에 갖추어 손에…","a":"사천 가산리 석장승","c":"시도민속문화유산","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659028.jpg"},{"q":"1. 자료의 내용 1) 성책류 ｢敎官公實記｣(1책, 20.5× 30cm) : 藪隱 沈明楫(1808-1883)의 실기. 필사본. ｢揚武原從功臣錄券｣(1책, 21.5× 32cm) : 영조 4년 戊申亂에서 공을 세운 공신들이 기록된 녹권이다. 서두에 ‘武閑良 沈太俊’이라 인쇄되어 있어 심태준에게 주어진 녹권임을 알 수 있다. 2) ○○류 ｢敎旨｣(80× 67cm) : 光緖 17년(1891) 折衝將軍行龍驤衛副護軍 沈太俊에게 ‘嘉善大夫戶曹參判兼同知義禁府事’라는 증직을 내린 교지이다. ｢敎旨｣(65× 56cm) : 광서 17년 심태준의 처 淑夫人 徐氏에게 ‘貞夫人’이라는 직첩이…","a":"청송심씨 퇴휴당 종중 문서","c":"문화유산자료","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666650.jpg"},{"q":"어촌 ○○ 선생의 묘 앞에 서 있는 비이다. ○○은 병자호란 때 청나라군의 침입으로 인조가 남한산성에 포위당해 있다는 소식을 듣고 의령일대에서 의병을 모아 싸움에 나아갔으나, 죽령에 이르러 청나라군과 화친했다는 말을 듣고 다시 돌아왔다. 비는 네모난 받침돌 위에 비몸을 세우고 장식이 특이한 머릿돌을 얹은 모습이다. 비문은 허적 선생이 손수 글씨를 썼는데, 선생이 살았던 시대로 미루어 조선 중기에 비를 세웠을 것으로 보인다.","a":"창녕 양훤 묘비","c":"문화유산자료","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663970.jpg"},{"q":"○○○○○, 천파공 오상(1614~1672), 충정공 오두인(1624∼1689) 등 해주 오씨의 이름난 학자들을 배출한 유서 깊은 곳이다. <안성 ○○○○○ 고택>이 위치하는 덕봉마을은 사액서원인 덕봉서원과 ○○○ 고택, 종친의 무덤이 모여 있어 해주 오씨의 역사를 보여준다. ○○○의 손자인 오핵이 남긴 기록에 따르면 고택은 덕봉리 입향조 오현경에 의해 1510년에 처음 지었으며, 1650년에 현재 위치로 옮겼다고 한다. 사랑채에 걸린 ‘퇴전당(退全堂)’이라는 현판은 ○○○의 호를 1662년에 우암 송시열의 글씨로 새긴 것이라고 한다. 이 가옥은 문간채가 전면에, 그…","a":"안성정무공오정방고택","c":"시도유형문화유산","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637714.jpg"},{"q":"조선 고종(재위 1863∼1907)의 친아버지인 흥선대원군의 별장으로 원래는 김흥근의 소유였던 것을 고종 즉위 후 대원군이 사용하였다. 한국전쟁 후 고아원·병원 등으로 사용되다가, 현재는 개인소유 건물이다. 정자의 앞산이 모두 바위라 대원군이 ‘○○○’이라 이름지었으며 삼계동 정자라 하기도 한다. 커다란 바위와 바위산에서 흐르는 시냇물, 뜰에 서 있는 소나무를 배경으로 한 ○○○은 매우 아름답다.","a":"석파정","c":"시도유형문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636103.jpg"},{"q":"□ 規 格 : 【부도(舍利塔)】 총고 311.0 cm 하층기단(가로/세로/높이) 186.0/186.0/55.0 cm 상층기단(가로/세로/높이) 124.0/124.0/45.0 cm 초층탑신(가로/세로/높이) 51.6/51.6/55.5 cm 초층옥개(가로/세로) 114.5/114.5 cm 이층탑신(가로/세로/높이) 45.0/45.0/18.0 cm 이층옥개(가로/세로) 89.0/89.5 cm 삼층탑신(가로/세로/높이) 32.0/32.0/14.0 cm 삼층옥개(가로/세로) 74.5/74.5 cm 노반(가로/세로/높이) 31.5/31.5/15.0 cm 보주높이 (가로/세로/높…","a":"합천 해인사 용성선사 승탑 및 탑비","c":"시도유형문화유산","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643155.jpg"},{"q":"○○○ 대웅전 내에 있는 신중탱화로서, 인도의 재래적인 토속신인 신중을 그린 불교 그림이다. 신중은 불교의 토착화 과정에서 수용된 불교의 호법신들인데, 이처럼 별도로 그림을 그려 신앙의 대상을 삼기도 하였다. 비단 바탕에 채색하여 그렸으며, 크기는 가로 200㎝, 세로 140㎝의 크기이다. 화면을 상하로 구분하여 상단에 제석을 중심으로 하늘의 천인상을 그려 놓고, 하단에는 호법신인 신장을 그려 넣었다. 색상의 사용법, 인물의 표현기법, 제작연대 등이 같은 대웅전 안에 있는 영산회상도와 같다.","a":"보문사 신중도","c":"시도유형문화유산","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2587794.jpg"},{"q":"연대는 횃불과 연기를 이용하여 정치·군사적으로 급한 소식을 전하던 통신수단을 말한다. 봉수대와는 기능면에서 차이가 없으나 연대는 주로 구릉이나 해변지역에 설치되었고 봉수대는 산 정상에 설치하여 낮에는 연기로 밤에는 횃불을 피워 신호를 보냈다. 조천진에 소속되었던 ○○○○는 북제주군 조천읍 함덕리 서쪽에 있는 제주대학교 해양연구소 안에 있다. 현재 훼손이 많이 되어 아랫부분 가로 7.9m 세로 8.1m, 높이 1.6∼2.4m 정도가 남아 있다. 조천진 소속장군 6명과 봉수군 12명이 배치되어 교대로 24시간 지켰으며, 동쪽으로 서산 봉수대를 거쳐 무주연대, 서쪽으로는…","a":"함덕연대","c":"시도기념물","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657831.jpg"},{"q":"충청도와 경기 남부를 중심으로 고려 시대에 유행한 불상 양식의 계보를 보여주는 ○○○○이다. 신체에 비해 큰 머리에는 원정모(圓頂帽 ; 챙이 둥글고 정상부가 봉긋한 형태의 모자로, 원나라 귀족들이 쓰던 모자였으나 원 간섭기 이후 고려의 관리와 승려들이 착용) 형식의 갓이 얹혀 있다. 양감이 없는 얼굴에는 가로로 긴 눈과 도톰한 코, 다물고 있는 작은 입이 표현되었고 두 귀는 어깨까지 늘어져 있다. 양 어깨를 덮고 내려오는 법의는 양쪽 팔뚝에서 굵은 띠 모양의 주름을 형성하고 있다. 오른손에 정병을 들고 왼손으로 이를 받치고 있는 특이한 자세를 보이고 있다. 그런데 법…","a":"안성대농리석불입상","c":"문화유산자료","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659994.jpg"},{"q":"광주광역시 광산구 박호동에 있는 ○○○○○은 충민공 양산숙 일가 7명을 기리기 위해 인조 13년(1635)에 세운 정려문(旌閭門)이다. 정려문은 충신, 효자, 열녀 등을 표창하기 위해 나라에서 그 동네에 세워주는 문을 뜻한다. ○○○○○은 정면 5칸·측면 1칸짜리 맞배지붕의 평범한 건물이다. 원래는 양산숙을 비롯하여 효자, 열녀, 절부 각 2명씩을 모셨으나, 회진임씨 문중으로 출가한 양산룡의 딸은 임씨문중에서 모시고 있어 현재는 6분의 정려만을 모시고 있다. 충신으로 모셔진 양산숙은 임진왜란(1592) 때 진주성 전투에서 왜군과 싸우다 김천일장군과 함께 순절한 무인이…","a":"양씨삼강문","c":"시도기념물","r":"전남광주통합특별시","s":"광산구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645750.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 고려 공민왕(재위 1351∼1374) 때 지었고, 조선 명종(재위 1545∼1567) 때 다시 지었으나, 임진왜란 때 불타 없어졌다. 광해군 7년(1615)에 도천산 아래로 옮겼다가 영조 4년(1728)에 지금 있는 자리로 옮겨 세웠다. 1900년과 1922년에 대성전을 수리하였고 1924년에 명륜당을, 1926년에 다시 대성전을 수리하였다. 지금 남아 있는 건물은 대성전, 명륜당, 모성루, 동재 등이다. 대성전에는 공자를 중심으로 그의 제자와 중국과 우리나라…","a":"자인향교","c":"문화유산자료","r":"경상북도","s":"경산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662577.jpg"},{"q":"○○ 한씨 시조인 한란(韓蘭)의 유적지에 세워놓은 비로, 글자가 심하게 닳아 읽기 어렵다. 조선 선조 38년(1605) 당시 ○○목사였던 한백겸이 ○○ 한씨 시조인 한란의 유적을 고증하여 찾은 뒤, 그의 동생인 이조참판 한준겸이 한란의 내력을 자세히 서술하여 모든 후손들이 제사 때마다 읽고 알 수 있도록 세운 비석이다. 이 때에 위토(位土:제사 또는 이와 관련된 사항들을 집행하는데 드는 비용을 충당하기 위하여 마련된 토지)를 마련하여 제단을 쌓고 담을 둘러 경계를 표시해 놓았다. 17세기 역사지리학의 대가이며 ○○○○ 후손인 한백겸에 의해 시조의 옛 터가 고증되어 세…","a":"청주 청주한씨 시조제단비","c":"시도유형문화유산","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638657.jpg"},{"q":"조선 전기의 무관으로 용성군수 등의 벼슬을 두루 역임하다가 1529년(중종 24)에 사망한 송와공(松窩公) ○○○(1492~1529)의 묘소이다. 묘역 앞에는 높이 쌓아 올린 대나 터인 축대가 있고, 뒤에는 담장이 있어 묘역은 축대와 담장으로 둘러싸여 있다. 축대와 담장 모두 널빤지처럼 얇으며, 푸른 빛깔인 띤 돌로 쌓은 것이 특징이다. 담장을 포함한 묘역 전체의 범위는 30×30m 정도이고, 축대의 높이는 최대 2m, 담장은 1m 내외이다. 그 안에 2기의 분묘가 나란히 있고 그 사이에 묘에 묻힌 사람의 신분을 밝히는 표지인 묘표와 향을 피우기 위해 향로를 올려놓는…","a":"고성 허원필 묘","c":"시도기념물","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657537.jpg"},{"q":"동헌은 아헌이라고도 하며, 관청의 중심이 되는 건물로 조선시대 감사나 수령이 공무를 처리하던 곳이다. 세워진 연대는 정확히 알 수 없지만 순조(재위 1800∼1834) 때 고친 것으로 전한다. 한때 보은경찰서로 사용되면서 내부구조가 많이 바뀌긴 했으나, 17세기 말경에 지어진 것으로 추정하고 있다. 앞면 7칸·옆면 3칸으로 1층이며, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 내부는 평면이 특징있게 꾸며져 있다. 전면 1칸은 모두 마루이고 오른쪽 4칸은 대청이며, 왼쪽 3칸은 온돌방을 두었다. 대청 중 동쪽 1칸과 후면을 높게 해서 누마루를 만들었는데, 조선…","a":"보은동헌","c":"시도유형문화유산","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638576.jpg"},{"q":"만덕사는 고려 충혜왕 서자인 석기가 유폐되었던 곳으로 전해진다. 금당지로 추정되는 건물터를 중심으로 그 주변에는 건물의 축대와 주춧돌, 와당, 무늬없는 벽돌이 발견되었고, 석탑, 불상대좌, 석등에 쓰인 석재들이 흩어져 있었다. 1979년 2월 부산시립박물관은 흩어진 석탑의 부재를 모아 3층석탑 1기를 박물관 정원에 복원하였다. 만덕사는 3층석탑의 양식, 당간지주의 형식으로 보아, 고려 전기에 지어져 고려 후기까지 있었던 절로 추정할 수 있다.","a":"만덕사지","c":"시도기념물","r":"부산광역시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1644914.jpg"},{"q":"이 ○○책판들은 경남 ○○군의 ○○○에 소장된 것으로, 모두 33종 1743판이다. ○○○에는 해인사 다음으로 많은 경판들이 소장되어 있다. 이 ○○들은 육조 현능대사의 가르침을 받은 제자들이 기록하여 만든 것으로 국내 유일본이며, 정확한 간행연도는 알 수 없지만 선조 36년(1603) 경에 간행된 것으로 추정된다. ○○○의 말사인 능인암에서 간행하여 ○○○로 옮겨온 것이 주류를 이루고 있으며, ○○○ 본사에서 간행한 것과 승려문집도 있다.","a":"하동 쌍계사 불경 목판","c":"시도유형문화유산","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641797.jpg"},{"q":"조선 전기의 고승인 함허화상 기화(己和)의 시문집으로 1책의 목판본이다. 간행기록에 의하면 이 책은 세종 22년(1440) 7월 문인인 문수(文秀)에 의해 문경 봉암사에서 간행되었다. 이 책에는『영가집』을 풀이한 「영가집십장찬송병서」,『원각경』과 『법화경』의 요지를 요약한 「원각경송」16수, 「법화경송」31수, 「대승기신론석제병서」등이 수록되어 있다. 이 밖에 함허 자신의 깨달음의 세계를 찬송하고 음미한 것, 아미타불의 공덕과 극락세계의 공덕, 그리고 염불하여 왕생하는 공덕을 찬양한 것 등 다수가 있다. 이 책은 한국불교 수행의 중심과제였던 선(禪)·교(敎)·염불(念…","a":"범어사 함허어록","c":"시도유형문화유산","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636665.jpg"},{"q":"○○○○은 원래 영조 10년(1734)에 곡남리 진동산에 창건되었으나, 오랜 시간이 흘러 건물이 허물어지면서 유림과 후손들의 정성으로 현재의 위치에 다시 건립되었다고 한다. 사당은 정면 3칸, 측면 2칸의 맞배지붕의 건물이다. 조헌 선생은 조선 중기 문신이자 의병장이며 유학자이다. 조선 명종 20년(1565) 성균관에 입학하였으며 1567년 문과에 급제하였다. 선조 1년(1568) 처음으로 관직에 올라 교수를 역임하였고 선조 5년(1572)에는 교서관에 속하였다. 선조 15년(1582)에는 모함을 받아 파직되었다가 다시 복직되었다. 그러나 왕의 진노를 사서 관직에서…","a":"조헌사당(표충사)","c":"문화유산자료","r":"충청남도","s":"금산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660897.jpg"},{"q":"○○○는 기계유씨(杞溪兪氏) ○○지역 입향조인 부호군(副護軍) 유은(兪檃)의 재실로 사망년도인 1690년에서 광국지경록 판목(光國志慶錄 板木; 유형문화유산)의 제작 시기인 1771년 사이에 초창된 것으로 추정되며 지붕, 서까래와 마루 청판 일부가 보수된 것 외에는 목구조가 건립 당시의 형태로 비교적 잘 남아 있다. 본 건물은 ○○지역 종중 관련 유적으로 묘소, 보실, 판목(光國志慶錄 板木) 등 다양한 유물 및 유적과 관련된 장소로 지역 성씨의 토착화 과정을 엿볼 수 있는 의미 있는 장소이다. 후에 고친 부분이 있으나 비교적 내부 구조가 조선시대의 고식을 잘 유지하고…","a":"보은 영모재","c":"문화유산자료","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2020032316271500.JPG"},{"q":"지촌 김방걸 선생의 덕을 기리기 위해 세운 서원이다. 김방걸(1623∼1695) 선생은 현종 1년(1660)에 증광문과에 병과로 급제하여 벼슬길에 올라 많은 관직을 지냈다. ○○○○은 정조 24년(1800)에 지었으나 고종 때 흥선대원군의 서원철폐령으로 철거되었다. 그 뒤 1926년에 복원하였으며, 1988년 임하댐 건설로 지금 있는 자리에 옮겨 세웠다. 서당 건물은 앞면 5칸·옆면 2칸 규모의 一자형이다. 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 새 날개 모양인 익공 양식으로 꾸몄다.","a":"지산서당","c":"문화유산자료","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662440.jpg"},{"q":"종택에는 오봉 신시제(1562∼1624)의 위패를 모신 사당이 있다. 그는 문과에 급제하고 예안 현감을 지냈으며 임진왜란이 일어나자 의병을 모집하여 일본군과 맞서 싸웠다. 수령으로 제임할 때 많은 치적을 남겼고 의성에 근무할 때 ‘장대서원’을 세워 지방고을 자제의 교육에 힘썼다. 이 건물은 아주 신씨의 종가인 낙선당과 담장 하나를 사이에 두고 있는데 사당은 10여 개의 돌계단을 오르면 4각으로 두른 흙담장 중앙에 정남향을 향하고 있으며, 종택의 중심건물인 낙선당과 담장 하나를 사이에 두고 있다.","a":"오봉종택","c":"문화유산자료","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662789.jpg"},{"q":"○○○는 청동기시대에 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 제주시 외도동에 있는 고인돌 무리는 제주시 서쪽을 흐르는 외도천(外都川)일대의 구릉지대에 있으며, 인근의 북제주군 애월읍 광령리 고인돌과 함께 20여 기가 무리를 지어 위치하고 있다. 외도고인돌 3호는 덮개돌의 단면이 아치 모양을 이루는…","a":"외도지석묘3호","c":"시도기념물","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657664.jpg"},{"q":"이중환의 택리지에 ‘조선인재반재영남(朝鮮人材半在嶺南)’이라는 대목이 나온다. ‘조선 인재의 반이 영남에서 태어났다’는 뜻이다. 특히 진주는 강․하․정씨가 본관을 두고 있을 정도로 많은 인물들이 탄생하였으니, 진주지역에도 인명록 출판이 성행하였다. 곧, 연계안(蓮桂案)이나 향안(鄕案)이 그것들이다. 연계안은 진주출신으로서 과거에 급제한 인물들의 이름을 적은 명부이고, 향안은 진주에서 학식과 덕행을 두루 갖춘 선비의 이름을 적은 인명록이다. 조선시대 향안과 연계안에 이름이 기록된 조상을 둔 후손들은 진주시 옥봉동에 연계재(蓮桂齋)를 지어서 인명록을 소중하게 보관하면서 큰…","a":"연계재임안","c":"시도유형문화유산","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001642565.jpg"},{"q":"다산리 마을에 자리하고 있는 비로, 임진왜란 때 순절한 이희룡 장군과 그의 아들 이문진 및 며느리 김씨의 행적을 기리고 있다. 이희룡은 임진왜란 때 왕을 의주까지 호위하였으며, 영남의 적을 정찰하라는 왕명을 받고 임무를 마치고 돌아오는 길에 충주에서 적을 만나 전사하였다. 아들 문진은 아버지의 시신을 찾으려다 신령에서 적과 대치하다 죽었다. 며느리 김씨가 이 소식을 듣고 손수 시신을 찾았지만 결국 찾지 못하고 3개월만에 스스로 목숨을 끊었다. 조정에서는 이들의 공을 기리어 조선 숙종 36년(1710)에 벼슬을 올려주고 정려각을 하사하였다. 비는 네모난 비받침 위에 비…","a":"이씨삼강묘비","c":"시도유형문화유산","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640744.jpg"},{"q":"여헌 장현광을 중심으로 동봉 권극립·우헌 정사상·윤암 손우남·수암 정사진 등을 기리고 있는 서원이다. 장현광(1554∼1637)은 조선 중기 문신이며 성리학자이다. 평생 학문에 전념하였으며 여러 차례 관직에 추천되었으나 정치에 뜻을 두지 않아 부임하지 않았다. ○○○○은 효종 8년(1657)에 세웠으며 고종 5년(1868) 흥선대원군의 서원철폐령으로 폐쇄되었다. 1907년 일제에 의해 묘우가 소실되었으며 1913년과 1972년에 복원하였다. 서원 경내에는 묘우와 강당을 비롯하여 일제당, 만활당 등의 부속 건물이 있다. 묘우에는 위패를 모시고 있으며 해마다 2월에 제사…","a":"입암서원 일원","c":"시도기념물","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654516.jpg"},{"q":"높이 4.3ｍ로 ○○○ 마을 안에 모셔져 있는 석불상이다. 돌기둥 같은 신체에 머리에는 원형에 가까운 보개(寶蓋 ; 인도에서 귀인의 외출시에 사용하던 양산을 불상의 머리 위에 갓처럼 씌운 것)를 쓰고 있다. 발목 이하는 땅에 묻혀 있으며 불상 앞에는 자연석의 넓은 돌을 두어 불단으로 이용하고 있다. 민머리에 얕은 육계(肉髻; 상투 모양으로 솟은 붓다의 정수리, 붓다의 지혜를 상징)가 있고, 이마 중앙에는 백호(白毫; 흰 터럭이 말린 것으로 이곳에서 빛이 나온다고 함)가 표현되었다. 양 어깨에 걸쳐져 내려오는 법의는 가슴에서 넓은 ‘U’자형의 주름을 형성하면서 신체 하…","a":"용인미평리약사여래입상","c":"문화유산자료","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659987.jpg"},{"q":"와룡산 중턱에 있는 ○○○는 통일신라 문무왕 16년(676)에 의상대사가 처음 지었다고 전한다. 그 뒤의 역사는 전하지 않지만, 임진왜란(1592) 때 사명대사가 승병을 이끌고 이곳에서 왜적과 싸웠다고 하며, ○○○은 이 때 불타없어졌다. 그 뒤 영조 7년(1731)에 다시 지어져 오늘에 이르고 있다. ○○○○○은 앞면 5칸·옆면 3칸의 규모이며, 지붕 옆면이 사람 인(人)자 모양인 단순한 맞배지붕집이다. 지붕을 받치면서 장식을 하는 공포가 복잡한 다포식으로 기둥 위와 기둥 사이에도 포가 배치되어 있다. ○○○ 내부에는 괘불(경상남도 유형문화유산)과 조선 후기에 제작…","a":"고성 운흥사 대웅전","c":"시도유형문화유산","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641520.jpg"},{"q":"조선 숙종 9년(1683) 통신사로 일본에 갔던 윤지완이 쓰시마섬주와 왜관에서 발생하는 문제의 처리를 놓고 5개 조항에 달하는 조약을 체결하고 돌아와, 이를 널리 알리기 위해 세운 비이다. 네모난 받침돌 위에 윗변을 둥글게 다듬은 직사각형의 비몸을 세운 모습이다. 비문의 내용은 첫째로, 출입을 금한 경계 밖으로 넘어 나온 자는 크고 작은 일을 논할 것 없이 사형으로 다스린다. 둘째, 노부세(路浮稅:통행 수수료)를 주고받은 것이 발각되면 준 자와 받은 자를 모두 사형으로 다스린다. 셋째, 시장을 열었을 때 각 방에 몰래 들어가 암거래를 하는 자는 피차 사형으로 다스린다…","a":"약조제찰비","c":"시도기념물","r":"부산광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645015.jpg"},{"q":"영남 사림의 대표적 인물인 이황 선생의 제자로서 학문적인 책을 많이 남긴 이덕홍(1541∼1596) 선생이 공부 하던 정자이다. 선생은 10여 세에 이황의 제자로 들어가 오로지 학문에만 열중하였다. 임진왜란 당시 바다에는 거북선을 육지에는 거북선 모양의 수레를 사용할 것을 주장하기도 하였다. 임진왜란 후에는 백성을 구제하는데 온 힘을 기울였으며, 많은 책을 남겼다. ○○○은 조선 선조 3년(1570)에 지은 것으로, 앞면 3칸·옆면 2칸 규모이며 지붕은 여덟 팔(八)자 모양으로 가장 화려한 팔작지붕이다. 정자의 앞쪽에는 군자당이란 연못이 있고, 서쪽에는 이덕홍의 학문…","a":"군자정","c":"시도유형문화유산","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640863.jpg"},{"q":"영광 ○○○○은 남쪽으로 바다와 접한 구릉의 남사면에 있으며, 평면상 직사각형의 형태를 이루고 있다. 『신증동국여지승람』에는 둘레 1,688척, 높이 12척으로, 『동국여지지』에는 둘레 1,688척으로, 〈○○○진지(法聖鎭鎭誌)〉에는 둘레 3,062척, 높이는 8척 7촌으로 기록되어 있다. ○○○○은 돌로 쌓은 석성으로, 동―서 너비 약 200m, 잔존 최대높이 300㎝ 내외, 성벽의 너비 700㎝ 내외의 규모이다. 남벽이 모두 파괴되어 남―북의 길이를 정확히 알 수 없으나 동―서의 길이는 250m이다. 현재 남아 있는 성벽의 길이는 동벽 75m, 북벽 250m, 서…","a":"영광법성진성","c":"시도기념물","r":"전남광주통합특별시","s":"영광군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654363.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 광령○○○ 제○○○는 남방식(2형식)으로, 지하매장주체 형식을 띄고 있으며, 장축 214㎝, 단축 123㎝, 두께 62㎝이다.","a":"광령리지석묘10호","c":"시도기념물","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657732.jpg"},{"q":"안성 ○○○ 비로전에 봉안되어 있는 높이 109㎝의 석불상이다. 현재 드러난 부분으로 평면 팔각의 연화대좌임을 알 수 있다. 대좌위에 비교적 넓게 자리 잡아 안정감 있게 앉은 가부좌의 모습과 둥글고 당당한 어깨에 둥글고 유연한 신체 윤곽선, 신체에 전체적으로 볼륨감이 살아있으며 약간의 층단을 이루는 띠 모양의 옷주름 표현 등에서 통일 신라 말기의 불상 양식을 엿볼 수 있다. 나발(螺髮 ; 소라처럼 말린 머리카락)의 머리에는 육계(肉髻 ; 상투 모양의 머리묶음)가 표현되었다. 둥글넓적한 얼굴에는 약간 살이 올랐으며, 이마의 백호와 함께 적당한 크기의 눈코입이 정연하게…","a":"안성운수암석조비로자나불좌상","c":"시도유형문화유산","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018102211453800.JPG"},{"q":"이 불화는 현재 ○○○ 칠성각의 후불탱(後佛幀)으로 봉안된 불화로서 1910년에 제작된 것이다. 가로가 긴 화면에는 치성광여래(熾星光如來)를 중심으로 칠성(七星)과 성군(星君) 등이 묘사되었다. 중앙의 청연화(靑蓮花) 위에 결가부좌(結跏趺坐)한 치성광여래(熾星光如來)는 붉은 법의(法衣)를 걸치고 오른손은 가슴 부위에, 왼손은 무릎 위에 대고 앉아 있는데 유난히 뾰족한 육계(肉髻) 위에는 원형(圓形)의 정상계주(頂上髻珠)가 표현되었다. 치성광여래(熾星光如來)의 좌우에는 향우측에 넷, 향좌측에 셋 등 모두 7구의 칠성여래(七星如來)가 치성광여래(熾星光如來)를 향하여 합장…","a":"진관사 칠성도","c":"시도유형문화유산","r":"서울특별시","s":"은평구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636399.jpg"},{"q":"중국 춘추 시대의 학자인 공자(孔子, B.C.551년-B.C.479년)의 후손이며, 조선 전기 문신인 공서린(孔瑞麟, 1483년-1541년)이 후학들을 가르치기 위해 세운 곳이다. 1792년에 이곳을 공자가 살던 노나라의 마을 이름을 따라 ‘궐리’로 바꾸었고, 사당을 세운 후 그 이름을 ‘○○○’라고 했다. 이곳은 고종의 서원철폐(書院撤廢 ; 1871년 전국의 47개소 서원(사우 포함)만 남기고 모두 없앰)로 없어졌다가 1900년에 다시 세워졌다. ○○○는 크게 성묘(聖廟 ; 공자의 영정이 있는 건물)와 ‘성상전’(聖像殿 ; 공자의 석상이 있는 곳) 구역으로 구분된다…","a":"오산시궐리사","c":"시도기념물","r":"경기도","s":"오산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646789.jpg"},{"q":"○○○의 절 한켠에 자리하고 있는 비로, 벽암대사의 행적을 적고 있다. 벽암대사는 조선 중기의 승려로, 법명은 각성이며, 벽암은 그의 호이다. 임진왜란 때에는 해전에 참여하였고, 인조 때 남한산성을 쌓을 때에는 8도도총섭으로 임명되어 승려들을 이끌고 3년만에 공사를 완성시키었다. 인조 14년(1636) 병자호란이 일어나 왕이 남한산성으로 천도하자 승려 수천 명을 모집하여, 호남의 군사들과 함께 적들을 섬멸하였다. 남한산성으로 향하던 중 전쟁이 끝나버리므로 승려들을 돌려보내고 지리산으로 들어갔다. 인조 24년(1646) 가을 속리산 ○○○에서 동문인 희언과 머물렀고,…","a":"보은 법주사 벽암대사비","c":"시도유형문화유산","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638498.jpg"},{"q":"『○○○○○』은 필사본으로서 이러한 모습의 것으로는 유일본으로 보인다. 이 책의 내용 가운데 노극홍의 시문은 약간의 글자 출입이 있다 하더라도 『광주노씨세고(光州盧氏世稿)』의 「옥촌고(沃村稿)」에 실려 있지만, 한강이 생질인 노극홍 및 그 생질의 아들과 손자에게 보낸 편지는 한강의 문집에도 실려 있지 않는 것이다. 한강문인록 또한 비교적 초기의 것으로 후대의 기록과 대조해 보면 한강 정구(寒崗 鄭逑)와 그 문인들의 학문 성향을 이해하는데 매우 중요한 자료이다.","a":"창녕 동산서당 한강연원록","c":"문화유산자료","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665365.jpg"},{"q":"이 가옥은 1903년(광무 7)에 건축한 근대한옥으로, 입산마을에서 가장 이른 시기에 지은 부농주택이다. 입산마을 중앙에 위치하고 있으며 대문 및 부속건물은 멸실되고 안채 1동만이 남아 있다. 입산리 ○○○○○은 제헌국회의원을 역임한 ○○○의 생가로 1903년에 건축된 근대의 한옥 건물로 근대초기 입산마을 부농주택의 원형으로 생각되는데 이는 이후 건축된 부농주택들이 이 집의 평면형식과 구조 및 의장수법을 따라 건축한데서 알 수 있다.","a":"의령 안준상 고택","c":"문화유산자료","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666377.jpg"},{"q":"청량산 중턱에 위치한 ○○○는 백제 의자왕 4년(644)에 자장이 지은 절이다. 당나라의 청량산에서 수행을 하고 돌아온 자장은 우연히 이곳을 지나다가 취령산이 청량산과 비슷하다 느끼고, 이곳에 절을 지은 후 ○○○라 하였다. ○○○○○은 조선 영조 40년(1764) 신화화상이 이 절을 다시 지을 때, 이곳에서 발견된 문수보살상을 모셔두기 위해 지은 법당건물이다. 석조문수보살상은 상체가 큰 불상으로 좌대와 하반신 일부가 땅에 묻혀있는 것이 특색이다.","a":"문수사문수전","c":"시도유형문화유산","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639446.jpg"},{"q":"언덕 위에 자리한 천주교 성당으로, 서양 중세 때 유행하던 고딕건축 양식 건물이다. 평면이 약간 변형된 라틴식 십자가형으로, 외관이 붉은 벽돌로 되어있다. 중앙 현관의 꼭대기에는 높은 종탑이 있고, 현관 출입구와 창의 윗부분은 끝이 뾰쪽한 아치로 장식되어 있다. 내부는 중앙에 여러사람이 앉을 수 있는 긴 의자를 놓고 그 양쪽에 복도를 둔 형식이다. 중앙의 넓은 공간과 복도 사이에는 6개의 돌기둥이 있는데 단면이 6각형을 이루고 있다. 1934년에 착공하여 1936년에 완공한 것으로, 전통적인 목조건물에서 현대 건축으로 넘어가는 과정을 엿볼 수 있다.","a":"공주중동성당","c":"시도기념물","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653032.jpg"},{"q":"차령산맥의 주된 봉우리인 서운산(해발 539m)에 있다. 정상부에서는 안성, 평택, 천안, 아산만 등 사방이 잘 조망되는 전략적 요충지이다. 성벽은 서운산 정상부의 봉우리 2개를 연결하여 산 복부를 감싸도록 쌓았다. 남벽 일부 외에는 성벽이 비교적 잘 남아있다. 성의 둘레는 620m이고, 흙을 쌓은 곳은 450m 가량 된다. 전체적인 평면 형태는 동-서로 길쭉한 장방형이다. 성벽은 능선을 따라 흙을 성토하여 쌓았다. 자연지형에 따라 성벽을 쌓지 않거나 삭토하여 경사를 확보한 구간도 있다. 북쪽과 남쪽에 성문터가 있는데 주로 남쪽으로 출입했던 것으로 보인다. 성안에는…","a":"서운산성","c":"시도기념물","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646184.jpg"},{"q":"조선시대 정조(재위 1776∼1800)가 아버지인 사도세자의 능에 참배하러 가는 도중에 잠시 들러 휴식하던 곳으로 욕은지(浴恩池)와 함께 자리 잡고 있다. 원래 욕은지는 다른 곳에 있었는데, 고종 24년(1887)에 수리하면서 이곳으로 옮겨 왔다고 한다. 정조는 활쏘기를 즐겨 신하들에게도 활을 쏘게 하였다는데, ○○○에서 활을 쏘고 욕은지에서 손을 씻었다는 이야기가 전한다.","a":"어사대","c":"문화유산자료","r":"인천광역시","s":"계양구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659524.jpg"},{"q":"1층 기단(基壇)에 3층의 탑신(塔身)을 세운 후 머리장식을 얹은 탑으로, 백제탑 양식을 일부 보이고 있다. 기단은 밑바닥돌이 탑의 보수 당시 콘크리트에 묻혀 버렸다. 탑신부는 각 부분을 조립하듯 여러 돌로 짜 맞추었는데, 1층 몸돌은 큰 편이나, 2·3층의 몸돌은 높이가 급격히 낮아졌다. 1층 지붕돌은 별도의 돌로 2단의 받침을 두었다. 지붕돌은 얇고 넓으며 네 귀퉁이가 살짝 올라갔다. 꼭대기에는 노반(露盤:머리장식받침), 복발(覆鉢:엎어놓은 그릇모양장식), 앙화(仰花:활짝 핀 연꽃모양장식) 등이 남아 머리장식을 하고있다. 옛 백제 지역에 세운 고려시대의 석탑으로서…","a":"탑동삼층석탑","c":"시도유형문화유산","r":"전북특별자치도","s":"군산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639467.jpg"},{"q":"남한산성을 쌓을 때, 동남쪽 건축 책임자였던 이회(李晦, 1567-1625)와 그의 아내, 첩 그리고 벽암대사(碧岩大師)를 모신 사당이다. ○○○은 마을의 신을 모시는 신당의 성격을 띠고 있다. 청량산에 지어져 ‘○○○’이라고 불렸고 수어장대(守禦將臺) 옆에 위치한다. 이 사당에 전해져 내려오는 이야기가 있다. “이회는 1624년에 남한산성을 건축할 때, 동남쪽의 공사를 맡았다. 그는 경비를 함부로 사용하고 공사에는 힘쓰지 않아, 기한 내 마치지 못했다는 억울한 누명을 쓰고 사형을 당했다. 그의 아내 송씨와 첩 유씨가 남편의 성 쌓는 일을 돕기 위해 삼남지방(三南地方…","a":"청량당","c":"시도유형문화유산","r":"경기도","s":"광주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637317.jpg"},{"q":"직육면체 모양을 하고 있는 이 작품은 원래 탑의 중심이 되는 탑신부(塔身部)의 몸돌이었을 것으로 보인다. 아래윗면을 제외한 4면에 부처의 모습을 새겼는데, 모두 머리와 몸으로부터 빛이 나오는 형상을 표현하였고, 각기 손모양이 다르다. 윗면에는 도드라진 연꽃무늬를 두었다. 조각수법으로 보아 통일신라시대의 작품으로 보이며, 지금까지 우리나라에서는 그 비슷한 예를 찾아볼 수 없는 특이한 모습이다.","a":"경주동천동사방불탑신석","c":"시도유형문화유산","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640422.jpg"},{"q":"지석묘는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. ○○○ 고인돌은 전형적인 바둑판식으로 계곡 평지에 10여 기가 분포하고 있으며, 덮개돌의 길이가 3∼4m 내외인 고인돌이 무리를 이루고 있다. 유물로 간돌칼·민무늬토기 등이 발견되었는데, 특히 길이 4.1m, 너비 2.76m인 5호 고인…","a":"여수 오림동 지석묘군","c":"시도기념물","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654310.jpg"},{"q":"1890년대 상무좌우사의 접장을 지낸 ○○○의 공을 기념하기 위해 세운 것이다. 상무사는 광무 3년(1899) 상업을 관장하는 기관으로 설립되어 전국 보부상단의 관리를 하였으며, 등짐장수인 부상단을 좌사로, 봇짐장수인 보상단을 우사로 그 명칭을 정했다. 접장은 좌사와 우사를 통틀어 상무사의 우두머리로, 모든 업무를 담당하고 총회를 소집하여 사회를 보는데, 격년제로 뽑으며 각 지역대표 중에서 투표로 선출한다. ○○○은 시장관리를 양심에 따라 공정하게 처리하여 상인들의 권리를 보호하고 발전시키는데 큰 공을 세웠다. 1911년 시장사람들이 세워 놓은 비로, 지역경제사를 이…","a":"함양 하경순 포선불망비","c":"문화유산자료","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664563.jpg"},{"q":"대조사 원통보전 앞에 서 있는 탑으로, 일부만 남아있던 것을 1975년에 다른 일부를 찾아 다시 세운 것이다. 탑은 전체의 무게를 지탱해 주는 기단(基壇)을 2층으로 마련하고, 그 위로 3층의 탑신(塔身)을 올려놓은 모습인데, 탑신의 2·3층 몸돌과 꼭대기의 머리장식은 새로 만들어 놓은 것이다. 기단은 각 층마다 면의 모서리와 가운데에 기둥 모양을 본 뜬 조각을 두었다. 탑신의 지붕돌은 밑면에 받침을 두었는데, 1·2층은 3단, 3층은 2단으로 새겨 불규칙한 모습이다. 지붕돌의 처마는 가운데에서 수평을 이루다 네 귀퉁이에 이르러 가볍게 위로 들려있다. 위로 올라갈수록…","a":"대조사석탑","c":"문화유산자료","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661034.jpg"},{"q":"이 판본은 1906년 화서 이항로(1792∼1868)의 제자인 김평묵과 유중교가 중국 송·원시대의 전적과 고려시대의 전적을 모아 기록한 『삼강오륜』의 강목으로서, 올바른 예의와 아름다운 풍속을 국민에게 가르치기 위해 제작한 것이다. 판본의 크기는 가로 33㎝, 세로 21㎝로 현재 총 1,382매가 보관되어 있다. 이항로는 조선 후기의 덕망 높은 성리학자로 고종이 재위할 때 장원서 별제, 전라도도사를 거쳐 공조참판의 벼슬을 하였다.","a":"송원화동사합편강목 목판","c":"시도유형문화유산","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638454.jpg"},{"q":"‘○○○○○’는 조선 중기의 문신 ○○○의 영정을 모신 사당이다. ○○○은 선조~인조 대까지 영의정을 여섯번이나 지냈지만, 소박한 성품으로 청빈하게 살았다. 일반적으로 사당에는 위패만 모시지만, 이곳 영우 내부에는 감실(龕室; 위패, 초상화 등을 봉안하기 위하여 만든 건조물)을 따로 만들어 영정을 모시고 있다. 사당은 1693년(숙종 19)에 지어졌으며, 숙종이 오리영우(梧里影宇)라는 현판을 내려주었다. 현판은 이관징(李觀徵, 1618~1695)에 의해 작성되었고, 1693년 인조가 하사한 관감당 옛터에 이 사우를 건립한다는 내용을 담고 있다. 현재 사당은 ○○○ 종…","a":"오리이원익영우","c":"시도유형문화유산","r":"경기도","s":"광명시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637687.jpg"},{"q":"문경공(文敬公) 허조(許稠)의 위패를 모시기 위해 건립한 서원이다. 준도문(遵道門)이라 편액한 외삼문을 들어서면 정면하여 강당인 수교당이 자리 잡고 있으며 마당의 좌측에는 평기와를 얹은 4칸 규모의 맞배기와집인 성경재(誠敬齋)를 두었다. 성경재와 마주보는 마당 우측의 경사진 대지 위에는 사당이 배치되어 있는데, 사당의 주위에는 방형의 토석담을 둘러 별도의 공간을 이루게 하였으며 담의 정면에는 3칸 규모의 평대문인 내삼문을 세웠다.","a":"하양부호리금호서원","c":"문화유산자료","r":"경상북도","s":"경산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663479.jpg"},{"q":"천태산 서쪽 구릉지대에 있는 3기의 무덤들이다. 현재 봉분은 유실이 심하여 높이 2m, 길이 14m 정도의 원형무덤으로 처음에는 4m 정도의 높이였을 것으로 생각된다. 무덤은 구덩식돌방무덤(수혈식석실묘)으로 높은 봉분을 가지고 있는데 이러한 형태는 이 지방 특유의 양식으로 백제 전기에 속한다. 도굴에 의해 파괴된 무덤을 정리 조사한 결과 일부 유물이 일본 천황릉의 배총에서 출토된 것들과 같은 유형의 유물이었다. ○○○무덤들은 백제 문화의 일본전파와 두나라의 관계를 이해하고 연구하는데 중요한 자료이다.","a":"운학리고분군","c":"시도기념물","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653520.jpg"},{"q":"연대가 오래되지는 않았지만 19세기 후반~20세기 전반 서울,경기 지역에서 유행한 괘불의 전형적인 양식을 보여주는 작품으로 괘불의 지역적 특징을 잘 반영하는 작품이다. 특히 1909년에 조선의 마지막 황제 순종과 순종비 순정효황후(純貞孝皇后) 및 황태자 영친왕의 수명장수를 기원해서 금어 혜과(惠果)와 한곡(漢谷)이 그린 괘불탱이어서 다른 예보다 우수한 편이다.","a":"사자암 영산회괘불도","c":"시도유형문화유산","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2595115.jpg"},{"q":"제주목 관아가 모두 불탄 뒤 세종 17년(1435)에 최해산(崔海山) 안무사가 홍화각 등 여러 건물을 다시 지었는데『○○○○』는 바로 그 간의 경위를 밝히기 위해 고득종이 지은 글이다. 글 전체의 내용은 제주도의 지형과 역사를 간략히 서술한 뒤에 최해산의 인품과 백성들에게 선정을 베푼 것을 찬양하고, 다음으로 홍화각의 건립 내력과 홍화각이라 명명한 이유를 기록하고 있다. 또 ‘홍화각(弘化閣)’이라는 제액 세 글자도 고득종 자신이 직접 써서 게시하였음을 밝히고 있다. 현재『○○○○』와 홍화각 액자는 모두 고양부 삼성사재단에 소장되어 있다.","a":"홍화각기","c":"시도유형문화유산","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643289.jpg"},{"q":"나주시청 앞쪽의 300여m 국도변에 있는 샘물이다. 고려 태조 왕건과 장화왕후 오씨부인이 인연을 맺은 장소로, 이 샘을 빨래샘 즉 ‘완사천(浣紗泉)’이라 부르고 있다. 전하는 말에 의하면, 왕건이 고려를 건국하기 전 나주에 10년간 머무르게 되었는데, 어느날 진 위쪽 산 아래에 다섯가지 색의 상서로운 구름이 있어 가보니 샘에서 아리따운 여인이 빨래를 하고 있었다. 왕건이 물 한그릇을 청하자, 여인이 버들잎을 띄워 주었는데, 급히 물을 마시지 않게 하기 위함이었다 한다. 왕건은 여인의 총명함과 미모에 끌려 그녀를 아내로 맞이하였는데 그 분이 장화왕후 오씨부인이고, 그…","a":"나주완사천","c":"시도기념물","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654244.jpg"},{"q":"○○마을 남쪽 평지에 자리잡은 ○○ 손씨 가문의 옛집이다. 조선 고종 광무 5년(1901)에 지었으며, 대문간채와 안채, 사랑채, 광채로 구성되어 있다. 대문을 들어서면 앞면 5칸·옆면 2칸 규모의 사랑채가 있다. 사랑채 옆으로 앞면 5칸·옆면 1칸의 중문간채가 이어져 있고 ㄱ자로 꺾여서 앞면 4칸 규모의 작은사랑이 연결되어 있다. 오늘쪽부터 사랑방·대청·부엌이 있고, 사랑방과 마루 앞에 반 칸 너비의 툇마루를 두었다. 부엌 옆으로는 광·헛간·중문간·마구간이 있으며, 작은 사랑방·광·아랫방이 안마당 쪽으로 꺾여 배치되었다. 중문을 들어서면 정면에 안채가 있는데, 앞면…","a":"밀양 교동 손대식 고가","c":"문화유산자료","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664264.jpg"},{"q":"○○○ 약사전(보물 제179호)에 보존되어 있는 후불탱인데, 탱화란 천이나 종이에 그림을 그려 액자나 족자 형태로 만들어지는 불화를 말한다. 조선 고종 21년(1884)에 제작된 그림으로 정사각에 가까운 화폭 중앙에 약사여래좌상과 좌우협시인 일광·월광보살을 배치하고 상하 좌우에는 사천왕을, 약사불 뒤에는 가섭과 아난을 그린 병렬식 구도를 보이고 있으며, 색채는 18세기 후반의 색 배합을 계승하고 있다. 전체적으로 전통적인 도상을 계승하고 안정된 화면 구성, 꼼꼼한 필력을 갖추고 있어 19세기 불화양식 연구에 귀중한 자료이다.","a":"강화 전등사 약사여래설법도","c":"시도유형문화유산","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018101610044800.jpg"},{"q":"○○○은 조선조 성종의 12남인 무산군의 손자이다. 나라에 공이 있어 순평군(順平君)에 봉해졌으며 그의 부인은 현부인에 올랐다. 부평 동면(현 동양동)에 낙향하여 정착하였는데, 그의 아들 이필혐은 동양동에서 출생하여 벼슬길에 올라 한성판관을 지냈다. 병자호란이 일어나자 가족이 강화도로 피난을 갔을 때, 청나라 군사가 강화도에 상륙하여 닥치는 대로 양민을 학살하자 현부인 엄 씨는 적군에 잡혀 욕을 보이느니 스스로 죽음을 택했다. 그러자 그의 자부인 이필혐의 처 구 씨도 어린 여자종의 치마폭에 유서를 써넣고 시어머니의 뒤를 따라 자결하고 말았다. 훗날 이 사실이 알려짐에…","a":"이선봉 묘역","c":"시도기념물","r":"인천광역시","s":"계양구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645690.jpg"},{"q":"건축양식이나 공간 구성적인 면에서 이전 시기의 정자건물에 비하여 부재들의 치수가 작고, 결구수법이 간결해지는 등 근대적 변화를 보여주고 있으며 민속마을 보존차원에서 보존할 가치가 있다.","a":"동계정","c":"문화유산자료","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659510.jpg"},{"q":"장승은 마을입구나 길가에 자리하여 그 마을의 수문신·수호신 등의 구실을 하는 민간신앙의 한 형태이다. 이 ○○○은 남·여 한쌍의 모습으로, 마을 입구 길 양 쪽에 1구씩 놓여 있다. 오른쪽 높은 곳의 돌담사이로 서 있는 것이 ‘상원주장군’이고, 길 건너 낮게 서 있는 것이 ‘하원당장군’이다. 상원주 장군은 여자의 형상으로, 민머리에 얼굴은 거의 평면이다. 생김새는 주름진 이마에 갈매기 모양의 눈썹을 가지고 있으며 동그란 눈, 방망이 모양 코, 뚜렷한 콧구멍 등이 표현되어 있다. 또한 약간 벌린 입술 사이로 치아를 희미하게 새겨 넣었으며 턱에는 덩굴 모양 비슷한 무늬를…","a":"해평리석장승","c":"문화유산자료","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661987.jpg"},{"q":"허암 ○○○○○지는 연산조의 문신 ○○○이 은거하던 옛집터인데 검암동의 허암산 북쪽 기슭에 위치하고 있다. 현재는 겨우 터전만이 확인될 따름이다. ≪부평부읍지≫고적조에 「허암구지는 모월곶면 허암산 밑에 있는데 한림학사 ○○○이 복거하면서 호를 허암이라 하였으나 뒤에 자취를 감추어 끝마친 곳을 알지 못한다」고 하였다. 이것으로 볼 때 ○○○의 호 허암은 허암산에서 취한 것임을 알 수 있다. 조선 중기의 문신 ○○○은 본관은 해주, 자는 수부, 호는 허암으로 철원부사 연경의 아들로 1469년(예종)서울에서 태어났다. 사림파의 종조 김종직의 문하에서 수학하였고, 1492년…","a":"정희량 유허","c":"시도기념물","r":"인천광역시","s":"서해구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2016082509333600.JPG"},{"q":"태실이란 왕이나 왕실 자손의 태를 모셔두는 돌로 만든 방으로, ○○○는 태실에 태를 모신 것을 기념하는 비이다. 이 비는 ○○○○의 태를 모신 후 세운 비로, ○○○ 절내에 사적비와 나란히 서 있다. 원래는 절 뒤편 산기슭에 있었으나 일제 때 태실을 발굴해간 뒤, ○○○의 스님들에 의해 이 자리로 옮겨온 것이다. 비는 거북받침돌 위로 비몸을 세우고 머릿돌을 올려놓은 모습이다. 거북받침은 머리가 용머리화 되어 입에 여의주를 물고 있다. 머릿돌은 네모난 형태로, 앞면에 두 마리의 용이 서로 엉켜 있는 장면을 도드라지게 새겼다. 거북받침의 표현이 투박하긴 하나, 짜임새와…","a":"명봉사문종대왕태실비","c":"시도유형문화유산","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640648.jpg"},{"q":"○○○○○ 석불좌상은 목이 절단된 것을 새로 붙여 두는 등 군데군데 시멘트로 두텁게 보수하기는 하였지만, 그나마 상호와 상반신의 전면이 그대로 남겨져 있다. 특히 상호와 입가의 미소는 인근 명주지역의 신복사지, 월정사지 석조보살좌상과 유사한 모습이어서 이들과 동일시기인 고려 초에 제작된 것으로 판단된다. 광배는 舟形인데 상단의 일부분이 깨진 것을 제외하고는 상태가 비교적 양호하다. 함께 반출된 대좌의 중대석은 원래 3개의 돌로 이루어져 있었으나 현재 2점만이 남겨져 있다. 8각 중대의 8면에 중 중앙 1면에는 향로가 있으며, 향로를 중심으로 좌우에 3구씩의 공양자가…","a":"강릉 청학사 소장 청동보살입상","c":"문화유산자료","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660656.jpg"},{"q":"○○○는 원나라 승려인 원명이 세웠다는 기록과, 신라 성덕왕 24년(725)에 서역 금지국의 승려인 정명이 세우고 남송 임천사의 승려 원명이 고쳐 세웠다는 기록이 있지만 지은 시기를 정확하게 밝히기는 어렵다. ○○○의 부속 암자인 ○○○은 원나라 승려인 원명이 지었다고 한다. 현재 ○○○ 내에는 법당, 요사채, 축성각이 있다. 법당 내부에는 목조아미타불삼존불이 있고 그 앞에 숙종 7년(1681)에 만든 석등이 있으며 ○○○ 입구에는 조선 후기에 만든 부도 5기가 있다.","a":"법천사 목우암","c":"문화유산자료","r":"전남광주통합특별시","s":"무안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662020.jpg"},{"q":"통영성은 왜적을 방어하고 거주지와 생업지를 갈라놓는 두 가지 목적으로 쌓은 성으로, 조선 숙종 4년(1678)에 쌓기 시작하였다. 평지와 산지의 지형을 절충하여 지은 성곽으로, 해발 174.2m의 여황산 양쪽 등성 약 1,000m는 흙으로 쌓았고 나머지는 돌로 쌓았다. 성의 둘레는 2800m, 높이 4.5m이다. 성의 구조는 4대문과 2개의 암문(적 또는 상대편이 알 수 없도록 꾸민 작은 성문)과 3개의 포루가 있으나 지금은 인가가 들어서면서 성문의 주춧돌만 몇 개 남아있다.","a":"통영성지","c":"시도기념물","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655482.jpg"},{"q":"조선 중종 14년(1519)에 기묘사화가 일어나면서 김대유가 관직을 버리고 내려와 지내면서 후진들을 교육하기 위해 세운 건물이다. 김대유의 호를 따라 ○○○라 이름 지었으며, 주세봉·조식·박하담 등과 토론과 이야기를 하던 곳이다. 규모는 앞면 3칸·옆면 2칸으로, 지붕은 옆에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 사방에 토담을 쌓고 문을 두어 그 안에 정자를 배치했다. 방 2칸과 부엌, 우물, 마루를 ㄱ자형으로 배열해 놓았다. ○○○ 밑에는 김대유의 신도비와 참봉 김용희가 쓴 중수기문이 있다.","a":"청도 삼족대","c":"시도민속문화유산","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658971.jpg"},{"q":"마성(馬城)은 말이 도망가는 것을 막기 위해 목장 둘레를 돌로 막아 쌓은 담장이다. 조선시대에는 나라에서 쓸 말을 기르기 위해 주로 해안가와 섬 등을 중심으로 200여개의 목장을 설치하였다. 울산지역의 목장은 조선전기에 방어진목장[구목장], 방암산목장, 이길곶목장 등 모두 3개의 목장이 설치되었으나, 방암산목장과 이길곶목장은 완성을 보지 못하고 바로 폐지된 것으로 보인다. 울산에 있는 목장은 중앙의 사복시 소속의 목장으로『경상도속찬지리지(慶尙道續撰地理誌)』(1469년)에 의하면 「방어진에 목장이 있었으며, 여기에서 키운 말이 360필, 그 둘레가 47리」라는 기록이…","a":"남목마성","c":"시도기념물","r":"울산광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645887.jpg"},{"q":"○○○에 보관되어 있는 청동으로 만든 동고(銅鼓)로 징과 같은 형태이다. ○○○는 고려 의종 원년(1146)에 각화사 주지인 성원이 암자를 지으면서 개창되었다. 1896년에 불타버린 것을 이후 다시 지어 오늘에 이르고 있다. 이 동고는 가로 31.3㎝, 세로 30.3㎝ 크기로, 절을 다시 지을 때 발견되어 보관하게 되었다. 동고의 위부분과 그 양옆에 각각 1개씩의 고리가 있으며, 아랫부분에는 길이 15.5㎝, 최대 폭 6.2㎝의 울림통이 있다. 앞면 중앙에는 연꽃무늬가 있고 중간에는 문양을 새긴 띠가 있으며, 그 바깥쪽에는 글자와 당초무늬가 있고 뒷면에도 가장자리를…","a":"안동용수사대정삼년명금동고","c":"시도유형문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641059.jpg"},{"q":"○○의 창건은 신라말 고려초라고 전해지나 문헌이나 고증이 없어 상세한 사실은 알 길이 없고 현재의 ○○가 세워진 것은 조선 선조 년간이다. ○○군수로 부임한 황응규가 1576년(선조9)에 走狗山의 산세는 풍수지리학상 개가 달아나는 형상이라 하여 달아나는 개를 떡을 주어 머물게 하기 위해 절을 짓고 “떡절”, 한자로는 병사(餠寺)라고 표기하였으나 후에 변화되어 德寺로 부르게 되었다고 한다. ○○○에는 석가불, 미륵보살, 제화갈라보살 등 삼존불을 중심으로 16나한상과 2구의 신장상 등 총 21구가 좌우로 배열되어있다. 석가삼존불은 상태가 양호하나 나한상 중 3구는 신체에…","a":"청도 덕사 영산전 석조여래삼존상 및 십육나한상","c":"시도유형문화유산","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641194.jpg"},{"q":"전라남도 남원시 노암동에 있는 ○○○ 미륵전에 모셔진 ○○○○이다. 머리에는 상투 모양의 머리묶음이 큼직하며, 긴 얼굴은 경직되어 있다. 목에는 3개의 주름인 삼도(三道)가 새겨져 있으며, 어깨는 직각으로 처리되었고 수직으로 내려오는 몸은 경직된 표현을 보여준다. 무릎 위에 올려 놓은 왼손에는 약항아리를 들고 있으며, 오른손은 무릎 아래로 향하게 하여 손끝으로 땅을 가리키고 있다. 대좌(臺座)는 연꽃이 새겨진 하대석 위에 정사각형의 중대석이 놓인 특이한 형태를 하고 있다. 부처의 몸에서 나오는 빛을 형상화한 광배(光背)는 다른 돌로 만들었으며, 크게 표현된 머리광배는…","a":"덕음암석불좌상","c":"문화유산자료","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661681.jpg"},{"q":"척화비란 병인양요와 신미양요를 승리로 이끈 흥선대원군이 서양사람들을 배척하고 그들의 침략을 국민에게 경고하고자 서울 및 전국의 중요 도로변에 세우도록 한 비로, 이 비도 그 중의 하나이다. 아주 낮고 자그마한 받침돌 위로 비몸을 세우고, 반달 모양의 머릿돌을 올린 모습으로, 비몸 앞면에 비문을 새겨두었다. 고종 8년(1871) 전국에 동시에 세운 비로, 한·일합방이 되면서 일제에 의해 대부분의 척화비들은 철거되거나 훼손되었는데, 이 비는 본래의 모습으로 넘어져 있어 바로 세워 놓았다.","a":"함양척화비","c":"문화유산자료","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664557.jpg"},{"q":"조선 후기 운강 박시묵의 아들 박재소(1840∼1873)가 분가하면서 세운 가옥이다. 본가인 운강고택을 중심으로 남서쪽에 있으며 다른 형제들의 가옥이 근처에 있어 마을을 형성하고 있다. 사랑채와 대문채가 1990년 도로확장공사로 철거되어 지금는 안채, 중문채, 도장채 등이 남아 있다. 안채는 ㄱ자형의 구조이고 중문채와 도장채는 ㅡ자형으로 되어 있다. 안채는 돌아서 통행하도록 되어 있어 양반가옥에서 보이는 남·녀 공간의 엄격한 구분을 보여 준다.","a":"청도 섬암고택","c":"시도민속문화유산","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658973.jpg"},{"q":"○○○ 불상은 현재 서울 ○○○ 주지실에 보관 중인 석조삼존불로서, 최근 향좌측 불상 대좌 아래에서 발견된 조성발원기에 의하여 1902년(광무 6)에 개금, 도분(塗粉)하여 삼각산 ○○○ 대웅전에 봉안하였음이 밝혀졌다. 전하는 바에 의하면 강원특별자치도 철원 심원사에서 모셔온 것이라 전하는데, 불상의 크기와 재질(불석), 양식 등으로 볼 때 천불상 중의 일부분으로 보이며, 수인과 착의법에서 약간의 차이를 제외하고는 크기와 형식, 양식 등이 동일하여 함께 조성된 것으로 추정된다. 전체적으로 신체에 비해 얼굴이 큰 편이지만 삼각형을 이루는 안정감 있는 자세와 조형성에서…","a":"청룡사 석 삼불상","c":"시도유형문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2593183.png"},{"q":"정국군 박위와 조선 전기 문신 박시를 기리기 위해 세운 건물이다. 박위는 이성계의 위화도회군 때 공을 세웠으며, 대마도를 정벌하는 등 많은 왜구를 물리친 장군이다.","a":"밀양 신남서원 경보당","c":"문화유산자료","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664508.jpg"},{"q":"박춘성·박흥남·박연수 등 3명의 밀양 박씨 충신을 모신 사당으로 삼충사(三忠祠)라고도 한다. 양촌 박춘성은 조선 중기의 문신으로 선조 25년(1592)에 임진왜란이 일어나자 왕의 수호를 맡았으며, 군사적인 작전을 여러 차례 왕에게 건의하기도 하였다. 그 공으로 1604년에 호성원종공신 3등에 올랐으며 아울러 밀산군(密山君)에 봉해졌다. 구암 박흥남은 조선 중기 의병으로 일찍이 무과에 급제하였다. 1592년 임진왜란이 일어나자 동생과 함께 금산의 이치·웅치 등의 싸움에서 많은 공을 세웠다. 진주 전투에서 분투하였으나 성이 함락되고 김천일·최경회 등과 함께 전사하였다.…","a":"구천사","c":"문화유산자료","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661676.jpg"},{"q":"○○○의 본존불인 ○○○불을 중심으로 좌우에 관음과 대세지보살이 삼존형식으로 배치되어 있다. 방형의 수미단위에 3단 대좌를 놓고 그 위에 앉아 계신다. ○○○불은 복장 발원물에 강희 3년 기사년에 조성되었다 하나 강희 3년은 갑진년이어서 강희 4년 기사년 즉, 1665년으로 보는것이 바르다. ○○○구품인중 중품하생의 수인을 취한다. 관음대시지보살은 복장발원문에 의해 강희 19년 즉 1680년에 조성되었음이 밝혀졌다. 크기는 ○○○불 높이 122㎝, 관음보살 높이 119㎝, 대세지보살 높이 117㎝이다.","a":"곡성도림사보광전목조아미타삼존불상","c":"시도유형문화유산","r":"전남광주통합특별시","s":"곡성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2026011215290690.jpg"},{"q":"높이 86.8cm의 크기로 조선 후기의 작품이다. 종 몸체에 새겨진 명문(銘文)에 의하면 1790년(정조 14)에 만들어 진 것임을 알 수 있다. 정상부의 용뉴(龍鈕)에는 두 마리의 쌍용(雙龍)이 완만히 솟은 천판(天板) 위에서 입을 크게 벌려 정면을 응시한 자세를 취하고 있다. 양 발의 발톱 주위에는 당좌와 같이 둥근 원형의 연화문을 장식한 점이 독특하다. 여기에 천판 가장자리를 돌아가며 고려시대 후기 범종에서 처음 등장한 연잎을 세워 둥글게 돌아가며 장식한 입상화문대(立狀花文帶)을 따른 톱니 모양의 장식을 배치한 점에서 한국 전통형 종을 계승한 것임을 알 수 있다…","a":"화성 용주사 중종","c":"시도유형문화유산","r":"경기도","s":"화성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637798.jpg"},{"q":"강원특별자치도 원주시 치악산에 있는 입석사의 큰 길로부터 서북 방향으로 30m 떨어진 암벽에 조각되어 있다. 불상의 얼굴은 매우 도드라지게 새겼으며, 몸체는 낮게 새겨져 있다. 불상을 대각선으로 가로지르는 균열이 있지만 전체적으로 잘 보존되어 있다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았고, 얼굴은 풍만한 모습이며 전체적으로 눈·코·입의 비례가 좋다. 양 어깨에 걸친 옷자락은 다소 두꺼운 편인데, 옷주름은 간략화되어 있다. 오른손은 어깨까지 들어 손바닥을 밖으로 향하고 있고, 왼손은 배 앞부분에 놓고 손바닥을 위로 하고 있다. 양 발을 무릎 위에 올리고 발바닥…","a":"원주흥양리마애불좌상","c":"시도유형문화유산","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638155.jpg"},{"q":"○○○○○은 낙동강을 사이에 두고 김해평야와 마주보고 있는 금정산 서쪽 능선 아래쪽에 자리 잡고 있다. 유적 뒤편에는 높이 6m 내외의 암벽이 병풍처럼 길게 둘러싸고 있는데, 유적의 보존상태는 양호하며 특별한 훼손없이 당시 모습을 잘 보여주고 있다. 1972년 12월부터 1973년 1월 사이에 부산대학교박물관에서 발굴조사를 실시하여 바위그늘 내부에 조성된 3개의 야외노지(野外爐址)와 바위그늘 바깥의 적석유구(積石遺構) 1기를 확인하였다. 바위그늘 아래쪽으로는 즐문토기 등이 포함된 패총이 형성되어 있었으나, 발굴조사로 인해 지금은 ○○○○○만 남아 있다. 바위그늘 내부…","a":"금곡동 율리 바위그늘유적","c":"시도기념물","r":"부산광역시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645324.jpg"},{"q":"이것은 권성(權偗, 1653～1730)선생의 영정이다. 華山祠는 원래 權忭과 權偗을 제사 지내던 사당으로 이들의 영정을 봉안해 왔는데, 1871년 대원군의 서원철폐령으로 헐려서 宗家에 옮겼다가 근년에 화산리에 影堂을 짓고 이곳에 영정을 봉안하였다.","a":"권성선생영정","c":"문화유산자료","r":"충청남도","s":"서천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661443.jpg"},{"q":"○○ 가경4지구 택지개발지구와 우회도로 공사구간에서 발견되어 1995년 충북대학교박물관이 발굴조사한 유적이다. 이 유적에서는 청동기시대의 생활유적과 삼국~조선시대에 이르는 광범위한 시기의 유구가 대량 확인 되었다. 특히 ○○○ 홍골~감나무실 사이의 구릉지역 일부 구간에서는 처음 나타나는 형식의 백제 목곽묘와 목관묘가 조사되었으며, 생활유구인 주거지와 매장유구인 무덤이 일정하게 구역을 정하여 가까운 간격을 두고 있었음을 확인하였다. 특히 백제시대 주거지 3기, 저장구덩 7기, 토광묘 13기와 완전한 형태의 백제토기 가마 등 다양한 백제시기 유구가 확인되었다. 출토유물은…","a":"청주 가경동 유적","c":"시도기념물","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650801.jpg"},{"q":"고려시대의 명관인 육려·임옥산·박이항 등 3인을 기리기 위한 서원이다. 조선 정조 13년(1789)에 세웠는데, 정조 22년(1798)에 박이겸과 정조 23년(1799)에 김설을 더하여 모셨다. 그 뒤 고종 5년(1868)에 흥선대원군의 서원철폐령으로 폐쇄되자 후손들이 제단을 만들어 제사만 지내오다가 1958년에 다시 세웠다. 현재 서원 안에 있는 건물로 강당인 울흥재, 사당인 압계사, 내삼문, 외삼문 등이 있다. 압계사에는 5인의 위패를 모시고 있으며 해마다 3월에 제사를 지낸다.","a":"압계서원","c":"문화유산자료","r":"전북특별자치도","s":"장수군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661652.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 언제 세웠는지 잘 알 수 없으나 조선 전기에 세운 것으로 보인다. 원래 부여읍 구교리의 서쪽 기슭에 세웠던 것을 18세기 중엽에 지금 있는 자리로 옮겼고, 여러 차례 보수를 거쳐 오늘에 이르고 있다. 건물의 전체적인 배치는 공부하는 공간인 명륜당이 앞쪽에 있고, 제사 공간인 대성전이 뒤쪽에 있어 전학후묘의 구조로 되어 있다. 명륜당은 앞면 5칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕 건물이다. 대성전은 앞면 3칸·옆면 3칸…","a":"부여향교","c":"시도기념물","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652962.jpg"},{"q":"○○○은 조선 중기 학자인 유장원(1724∼1796)이 학문을 연구하고 제자를 가르치기 위해 지은 정자이다. 유장원은 영·정조 시대의 학자로 경학과 성리학에 조예가 깊었다. 영조 39년(1763) 사마시에 합격하였고, 만년에 대산 이상정의 밑에서 공부하여 『상변통고』등 많은 저서를 남겼다. 규모는 앞면 3칸·옆면 2칸이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 원래 안동의 수곡리에 있었으나 1987년 임하댐 건설로 지금 있는 자리에 옮겨 지었다.","a":"동암정","c":"문화유산자료","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662469.jpg"},{"q":"○○○○는 조선중기 무신이자 문사인 송당 박영(松堂 朴英:1471~1540)이 1496년(연산군 2년)에 고향인 선산(善山)으로 낙향하여 낙동강가에 세운 강학지소(講學之所)로, 현재 건물은 1860년대에 중건된 것이다. 송당은 문무와 의학이라는 기술까지 학문을 종합해서 습득하고 실천했을 뿐 아니라 도학의 인맥을 종합하여 아우른 그의 학맥은 오늘날까지 영남, 특히 선산지역의 여러 문중을 모여 그를 기리고 시회를 잇도록 영향을 끼치고 있다. ○○○○는 간결하고 소박한 구조로 구성되어 있고, 건물의 규모와 구성에 대한 내용이 기술된, 흔치 않은 중건기(重建記)가 전해 오고…","a":"구미 송당정사","c":"문화유산자료","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019052017031500.jpg"},{"q":"○○○은 조선 선조와 인조 때 활동하였던 풍암 김덕보(1571∼?)가 지은 정자로 ‘풍암’이라는 이름은 그의 호를 따서 붙인 것이다. 김덕보는 임진왜란 때에 큰형 덕홍이 금산싸움에서 죽고 의병장으로 크게 활약하던 작은형 덕령까지 억울하게 죽자, 이를 슬퍼하여 무등산 원효계곡을 찾아와 학문을 연구하며 평생을 살았다. 후에 의열사에 신주를 모셨다. ○○○은 앞면 2칸·옆면 2칸 규모로 이루어져 있다. 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄고 ‘○○○사’라고 쓴 현판이 걸려 있다.","a":"풍암정","c":"문화유산자료","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659610.jpg"},{"q":"○○○는 교룡산성 안에 있는 절로 산성내에 있다고 산성절이라 부르기도 한다. 신문왕 5년(685)에 세워졌으며, 이곳에 용천이 있다고 하여 용천사라 하였다. ○○○로 이름이 바뀐 시기는 분명하지 않다. 절의 건물은 교룡산성을 지키는 군본부로 사용되었으며, 전성기에는 300여 명의 승려가 머물렀다고 한다. ○○○○○은 아미타불을 모시는 법당으로 통일신라 신문왕(재위 681∼692) 때 세워졌다고 전해지며 정조 3년(1779)에 다시 지었다. 지붕은 옆면이 여덟 팔(八)자 모양으로 가장 화려한 팔작지붕이다. 기둥 위에서 지붕 처마를 받치는 공포가 기둥 위에만 있는 주심포…","a":"선국사대웅전","c":"시도유형문화유산","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639541.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 지방의 교육기관이다. 고려 공민왕 6년(1357)에 반월산 아래에 처음 지었고 조선 태종(재위 1400∼1418)대에 송릉동으로 옮겼다가 광해군 4년(1612)에 지금 있는 자리로 다시 옮겨 세운 것이다. ○○○은 성종 원년(1470)과 1976년에 보수하였다. 지금 남아 있는 건물로는 ○○○과 동무·서무, 교육 공간인 명륜당, 휴식공간인 태화루 등이 있다. ○○○은 공자를 비롯하여 중국과 우리나라 성현의 위패를 모시고 제사를 지내는 곳이다. 지붕은 옆면에서 볼 때 사람 인(人)자 모…","a":"평해향교 대성전","c":"문화유산자료","r":"경상북도","s":"울진군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662715.jpg"},{"q":"현재 이름을 알 수 없는 절터에 세워져 있는데, 현재의 자리가 원래의 자리는 아니고 출토지는 알려지지 않았다. 몸에서 나오는 빛을 표현한 광배(光背)와 부처가 앉은 자리인 대좌(臺座)를 모두 갖추고 있다. 광배의 윗부분이 깨어졌고, 부분적으로 마모된 곳이 있기는 하지만 보존 상태는 양호한 편이다. 광배와 불상은 하나의 돌을 깎아 만들었다. 얼굴에는 광대뼈가 두드러지고, 입의 양끝이 아래로 처져 있다. 양무릎은 평면적으로 조각되었으며, 손은 가늘고 빈약하게 표현되어 있다. 오른손은 가슴까지 들어 손바닥을 밖으로 향하게 하였고, 왼손은 다리 위에 올려놓았다. 광배는 2줄…","a":"강릉보광리석조여래좌상","c":"시도유형문화유산","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638142.jpg"},{"q":"고려시대의 무신인 ○○○ 장군의 묘이다. 목종 때 문과에 급제하였으며, 현종 3년(1012) 안찰사로서 영일 등지에 쳐들어온 여진을 격퇴하였다. 현종 9년(1018) 거란의 소배압이 10만 대군을 이끌고 쳐들어오자 강감찬 장군의 부장으로 출전하여 흥화진에서 격파하였다. 그 공로로 1019년에 응양상장군주국·우산기상시가 되고 추성치리익대공신에 기록되었으며, 이듬해 병부상서가 되었다. 묘소는 예산군 대술면 이치리에 있는데, 반구형의 봉분 아랫부분에 잘 다듬은 둘레석을 둘렀다. 묘의 앞에는 상석·장명등(長明燈:무덤 앞에 세우는 돌로 만든 등)이 있고, 좌우로 동물상·동자상…","a":"강민첨장군묘","c":"문화유산자료","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661426.jpg"},{"q":"○○○○○은 동구 ○○○ 영신학교 부지 동남쪽에 접한 구릉에 분포한다. ○○○○○이 밀집된 구릉은 사적 제262호 불로○○○○과는 경부고속도로(좁은 산간저지)를 사이에 두고 남북으로 대치하는 위치에 입지하고 있어 불로○○○○과 더불어 고분시대와 그 외 시대의 지역 주민의 장법 및 문화적 변모상을 밝히는데 중요한 유적이 된다. 2003년 영신학교 부지정지 때 ○○○○○의 북단부에 해당하는 구릉 하단부에서 소형봉토분 5기, 석곽묘 7기, 고려 석곽묘 4기, 토광묘 1기를 발굴조사하였다. 봉토분은 횡구식석실 구조로서 주실의 4벽은 최하단을 대형 판상석을 2~3매 쌓고, 그…","a":"봉무동고분군","c":"시도기념물","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645403.jpg"},{"q":"집회 및 집무를 처리하던 동헌이라고 전해지는 이 건물은 명월정이라고도 한다. 조선 숙종 7년(1681)에 처음 지어졌으며, 영조 2년(1726)에 다시 옮겨 짓고 이름을 ○○○으로 바꾸었다. 광무 4년(1900)에 전체적으로 보수하였는데, 충주댐 건설로 인하여 1983년 지금의 위치로 옮겨 복원하였다. 앞면 6칸·옆면 3칸 규모이며, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 건물의 오른쪽은 대청이고 왼쪽은 온돌방이다. 죄인을 가두어두던 부속건물이 있었으나 조선 말기에 없어졌다.","a":"제천 청풍 금병헌","c":"시도유형문화유산","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2021012016120700.jpg"},{"q":"○○○는 중국 명나라에서 귀화한 사암 천만리(思庵 千萬里) 장군을 모시는 사당이다. 천만리 장군은 서쪽 중북산 천고봉 밑에 살았다 하여 성을 천씨로 하였다고 전해진다. 임진왜란이 일어나자 조선이 명나라에 원병을 요청하였는데, 이때 천만리 장군은 아들 상과 함께 이여송을 따라 조선에 왔다. 평양전투를 비롯하여 여러 전투에서 공을 세웠으며 정유재란 때에는 울산에서 공을 세웠다. 전쟁이 끝난 후에도 돌아가지 않고 조선에 머물러 살자, 선조는 그의 공을 생각하여 화산군*에 봉하고 전답 30결을 내려 주었으며 그의 아들 상도 한성부 좌윤에 봉하였다. ○○○는 구릉의 동쪽 비탈…","a":"고성 호암사","c":"문화유산자료","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663870.jpg"},{"q":"읍성이란 군이나 현의 주민을 보호화고, 군사적·행정적인 기능을 함께 하는 성을 말한다. 경상남도 밀양시 ○○○○은 성종 10년(1479)에 만든 것으로, 다른 읍성들을 임진왜란 직전에 만들기 시작한 것에 비하면 100년 이상 일찍 만든 것이다. 『동국여지승람』의 기록에 따르면 ○○○○은 둘레가 4,670척, 높이 9척이며 성 안에 우물이 4개, 연못이 1곳 있다고 한다. 1902년 경부선 철도부설 공사 때 성문과 성벽을 모두 헐어 철도부설공사에 이용하여, 지금은 성문의 위치와 일부 성곽만 남아 있다. 아동산과 아북산을 잇는 산등성이에는 성곽이 남아 있다.","a":"밀양읍성","c":"시도기념물","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656045.jpg"},{"q":"순창군 동계면 만수탄 위에 자리잡고 있는 정자로, 언제 지었는지는 알 수 없다. 귀암 양배는 남원 사람으로 일찍부터 학문을 닦아 그 지식이 높았으나 무오사화와 갑자사화로 어진 사람들이 되려 화 당하는 것을 보고 자연 속에 묻혀 아우 돈(墩)과 함께 세상을 잊고 살았다. 조정에서는 그의 학문과 덕행이 높음을 듣고 사헌부 장령의 벼슬을 내렸으나 벼슬길에는 나가지 않았다. 지금도 적성강 상류 만수탄에는 형제가 고기를 낚던 바위가 남아 있어 배암·돈암이라 부르거나 합쳐서 형제암이라 부르고 있다. 그가 죽은 뒤에 사림에서는 ‘지계사’를 지어 제사를 모시고 있으며, 후손들은 그…","a":"구암정","c":"문화유산자료","r":"전북특별자치도","s":"순창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661764.jpg"},{"q":"조선 철종 7년(1856)에 지은 옛 집으로, 안채, 사랑채, 행랑채, 문간채가 있다. 안채는 앞면 4칸·옆면 3칸 규모이며, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 안채 앞쪽에 있는 사랑채는 앞면 4칸·옆면 2칸 규모로, 지붕 옆면이 사람 인(人)자 모양인 맞배지붕집이며, 기둥은 원기둥이다. 앞에서 볼 때 왼쪽 첫칸의 지붕은 다른 3칸보다 훨씬 낮고 각기둥으로 되어 있는데, 이는 후에 달아낸 것이기 때문이다. 행랑채는 앞면 3칸·옆면 2칸의 팔작지붕집이고, 공기가 잘 통하도록 땅에서 40㎝높이에 널판으로 바닥을 깔았다. 앞면 3칸·옆면 1칸의 문간채는…","a":"장재영가옥","c":"시도민속문화유산","r":"전북특별자치도","s":"장수군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658310.jpg"},{"q":"○○○은 사찰을 찾은 불자들이 부처님께 합장하고 예를 올리는 데 사용되는 상징적 공간으로, ○○○ 석등(보물)에서 약 10m 동쪽으로 떨어진 화단 안에 위치한다. 규모는 길이 2.4m, 폭 1.03m, 높이 0.4m이다. 형태는 직사각형의 받침돌 형태로, 옆면에는 얕게 안상(眼象) 문양을 새긴 후, 그 안에 고사리무늬 같은 버섯구름 문양을 새겨 넣었다. 윗면 중앙에 큰 연꽃을 배치하고, 좌우에는 그보다 약간 작은 연꽃 2개와 연줄기를 새겨 넣었다. 전체적으로 조각이 정제되고 장중한 아름다움을 지니며, 오랜 세월에도 원형이 잘 남아 있는 작품으로, 조성시기는 고려시대로…","a":"관촉사배례석","c":"시도유형문화유산","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639093.jpg"},{"q":"연화산에 있는 ○○○는 신라 문무왕 16년(676)에 의상조사가 지은 절이다. 화엄 10대 사찰로서 이곳에는 보물 자방루, 경상남도 문화유산으로 지정된 대웅전, 향로, 반종들이 있으며, 청연암, 백연암, 연대암 등 3개의 암자와 청담스님의 사리탑이 빼어난 조형미를 갖추고 있어 연간 30만명의 관광객이 찾아들고 있다.","a":"고성옥천사일원","c":"시도기념물","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655772.jpg"},{"q":"○○○는 알[卵] 모양의 구멍들이 있는 바위라는 뜻이다. 이 구멍들은 돌 표면을 쪼아서 형태를 잡은 다음 회전 마찰을 통해 다듬은 것으로, 성혈(性穴)이라고도 한다. 주로 고인돌의 덮개돌이나 자연암반에 새겨지며, 흔히 ‘알구멍’, ‘○○○’ 등으로 불린다. 성혈은 주로 태양, 여성의 성기 등을 상징하며, 이는 풍요와 다산의 의미로 해석된다. 청동기시대 농경의 발달은 인구 증가와 동시에 많은 생산량을 필요로 하게 되었으며, 이것이 다산과 풍요를 기원하는 신앙적 의식의 표현으로 이어졌을 것으로 추정된다. ○○○○○는 ○○○ 하방마을 입구에 있는 작은 동산에 위치하고 있으…","a":"방기리알바위","c":"시도기념물","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645875.jpg"},{"q":"이 불상은 소조(塑造)의 석가○○○○으로 현재 ○○○ 나한전(羅漢殿)의 본존상(本尊像)으로 봉안되어 있다. 중앙의 석가여래좌상(釋迦如來坐像)을 중심으로 두 보살상(菩薩像)이 시립(侍立)하고 있는데, 현재 복장(腹藏)이 개봉되지 않았고 개금(改金) 또한 두터워 정확한 연대를 알기어려우나 삼존불(三尊佛)의 머리표현과 얼굴 형태, 법의(法衣)의 주름 등 전체적인 양식적 특징으로 볼 때 16세기 후반～17세기 전반 경의 양식을 보여주는 작품이다. 세 불상은 모두 소조불(塑造佛)로 조성되었는데, 손 부분은 후에 나무로 만들어 새로 끼웠다. 본존(本尊)은 상체가 약간 긴 듯한…","a":"진관사 소 삼존불상(석가불,미륵보살,제화갈라보살)","c":"시도유형문화유산","r":"서울특별시","s":"은평구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636342.jpg"},{"q":"남은 서섭과 취정 서효재의 학문과 덕을 추모하기 위해 세운 서원이다. 서섭은 세종(재위 1418∼1450) 때 이조판서를 지냈고, 후일 사육신의 순절을 애통해 하여 시골로 내려와 은둔생활과 후학을 기르며 여생을 보냈다. 달성 서씨 문중의 서당이었던 풍성당을 무풍면 지성리로 옮겨 고쳐 짓고, 1901년 분양정사라 하고 제사지내 오다가 1945년 동편에 숭모사를 세웠다. 1973년 ○○○○으로 이름을 바꿔 오늘에 이르고 있다. 현재 남아 있는 건물로는 숭모사, 강당, 화수헌 1동, 수직사 1동 등이 있다. 숭모사는 앞면 3칸·옆면 1칸 규모로, 지붕은 옆면에서 볼 때 사…","a":"분양서원","c":"문화유산자료","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661822.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 광령○○○ 제8호는 남방식(2형식)으로, 지하매장주체 형식을 띄고 있으며, 장축 232㎝, 단축 130㎝, 두께 54㎝이다.","a":"광령리지석묘8호","c":"시도기념물","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657730.jpg"},{"q":"경상남도 ○○시 물금읍 물금리에 있는 산성으로, 임진왜란 때 왜장 다데마사무네가 쌓았다고 한다. 산의 정상을 깎고 큰 돌을 이용해 산성을 쌓아 근거지로 삼았다. 지형에 따라 동쪽과 서쪽의 2곳에 성을 쌓고, 양쪽으로 통할 수 있도록 한 것이 특이하다.","a":"양산 증산리 왜성","c":"문화유산자료","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664605.jpg"},{"q":"연대는 횃불과 연기를 이용하여 정치·군사적으로 급한 소식을 전하던 통신수단을 말한다. 봉수대와는 기능면에서 차이가 없으나 연대는 주로 구릉이나 해변지역에 설치되었고 봉수대는 산 정상에 설치하여 낮에는 연기로 밤에는 횃불을 피워 신호를 보냈다. ○○○○는 귀덕초등학교 북쪽에 있으며, 명월진에 소속되어 있다. 옛날의 모습은 남아있지 않고, 지금의 연대는 최근에 보수하여 세운 것이다. 이 연대에는 명월진 소속의 별장 6명, 봉군 12명이 배치되어 6교대로 하루 종일 해안선을 지켰다고 한다. 동쪽으로 애월 연대, 서쪽으로 우지 연대와 연결되어 있다.","a":"귀덕연대","c":"시도기념물","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657841.jpg"},{"q":"｢○○○○○｣은 천태종의 근본경전이며, 부처가 되는 길이 누구에게나 열려 있다는 것을 기본사상으로 하고 있다. ｢화엄경｣과 함께 우리나라 불교사상의 확립에 크게 영향을 끼쳤으며, 우리나라에서 유통된 불교경전 가운데 가장 많이 간행된 경전이다. 이 ｢○○○○○｣은 고려 우왕 8(1382)년경에 간행된 목판본으로 추정되며 중국 송나라 계환이 정강 정미(1127, 고려 인종 5)년에 주해한 것을 저본으로 간행한 소자본이다. 3권1책(권1-3)의 영본이나 보물 ○○○○○와 동일한 판본이다. 보물 ○○○○○의 권말의 이색의 기록에 의하면, 송나라 계환의 ｢○○○○○｣의 글씨가…","a":"묘법연화경 권1~3","c":"시도유형문화유산","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638922.jpg"},{"q":"의열사의 건립과정과 그곳에 모신 인물에 관한 내용을 기록한 비이다. 의열사는 조선 선조 8년(1575) 부여현감 홍가신에 의해 건립된 것으로, 선조 10년(1577)에 임금이 이름을 지어 현판을 내렸다. 비의 형태는 네모진 바닥돌 위에 비몸을 세우고 지붕돌을 올린 모습이다. 비문의 내용에 의하면 이 고장 출신이었던 백제의 3충신(忠臣)인 성충, 흥수, 계백과 고려시대에 신돈을 탄핵하다가 물러난 이존오의 공로가 후대에 전해지지 않음을 안타깝게 여긴 홍가신이 사당을 지어 이들을 모시게 되었다고 한다. 후에는 조선시대의 정택뢰, 황일호를 모셨다는 내용도 적혀 있다. 경종…","a":"의열사비","c":"시도유형문화유산","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639081.jpg"},{"q":"이 산성은 대강면과 주생면에 걸쳐 있는 포곡식 산성으로 남원∼순창간 국도를 따라 가다가 비홍치 정상에서 남으로 직선거리 500m 남짓한 곳에 성의 북쪽면이 시작된다. 성벽은 적당히 깎은 가공석을 이용하여 내외면의 면을 맞추고 그 안쪽에는 할석을 채웠으며 내탁법으로 쌓아올린 성벽 중 6m 가량 높이가 남은 곳도 있으며 대체적으로 잔존 성벽 상부 폭은 4.7m 내외이다. 또한 『고적조사』에 의하면 주위는 약 900m 정도로 알려져 있다. 망루지와 건물지로 추정되는 터가 보이고 있으며, 삼국시대의 것으로 추정되는 토기편과 기와편이 보이고 있다.","a":"비홍산성","c":"문화유산자료","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661850.jpg"},{"q":"민절공 김륵(1540∼1616)의 묘를 지키기 위해 세운 재사 건물이다. 김륵은 조선 중기 문신이며 호는 백암이다. 조선 선조 9년(1576) 문과에 합격하고 예조원외랑·도승지·이조참판·대사성 등 많은 벼슬을 지냈다. 임진왜란 때는 영남지방에 가서 선비들에게 왜적을 물리치자는 뜻을 전하고 백성들을 잘 다스렸으며 안동부사로 있을 때는 자주 넘치는 낙동강의 재해를 막기 위해 제방을 수축하기도 하였다. 죽은 뒤에는 이조판서로 추증되었고 저서로는 『백암문집』이 있다. ○○○○는 앞면 5칸·옆면 5칸 건물로, 벽은 흙으로 되어 있고 기둥은 둥근 것과 네모진 것을 사용하였다.…","a":"백암재사","c":"문화유산자료","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663104.jpg"},{"q":"○○○은 연대가 비교적 오래되고 입지가 뛰어날 뿐만 아니라 평면 구성과 입면표현, 수장, 치목 등의 측면에서 근대기에 들어 전통 건축의 자생적 진화과정을 보여주는 좋은 예이므로 학술적·역사적으로 보존가치가 있어 문화유산자료로 지정되었음","a":"의령 청금정","c":"문화유산자료","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666632.jpg"},{"q":"조선 중기의 문신인 ○○○李基祚(1595~1653)과 부인 고령 신씨의 무덤이다. ○○○는 광해군 치세 때 문과에 급제하였고, 인조반정 이후에 관직에 본격적으로 나아갔다. 이괄의 난이 일어났을 때 난을 평정하여 국왕의 신임을 받았고, 이후 효종 연간에는 이조판서와 공조판서를 역임하였다. 그가 병으로 죽은 후에 숙종 24년(1698)에 조정에서 ‘충간忠簡’이라는 시호를 받았으며, 숙종 31년(1705)에 신도비를 설치하였다. ○○○ 신도비는 박세채朴世采가 글을 짓고 손자 이명필李命弼이 글씨를 썼으며, 상단의 전서체 글씨는 외손자 신완申琓이 글씨를 썼다. 봉분 주변으로…","a":"이기조선생묘","c":"시도기념물","r":"경기도","s":"군포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2021102814462300.jpg"},{"q":"이 ○○○○은 복장기에 의해 1612년 玄眞, 學文, 明隱, 義能 등의 금어에 의하여 조성되고, 1677년에 중수되었음을 알 수 있다. 이 관음상은 총고 39.5cm 크기의 단아한 목조각상으로 조각기법이 뛰어난 작품이다.","a":"함양상연대목조관음보살좌상","c":"시도유형문화유산","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643059.jpg"},{"q":"윤찬·윤여임·백선남·윤지선·윤자민의 학문과 덕을 추모하기 위해 세운 서원이다. 윤찬은 조선 중기 무신이다. 임진왜란 당시 야인으로서 선조의 수레를 호위하여 피난길을 도왔다. 후에 선전관에 제수되고, 오위도총부부총관에 이른다. 윤여임은 조선 중기 무신이다. 무과에 급제하고 광해군 14년(1622) 조총·대포 등을 만들어 포상받아 선전관이 되었다. 병자호란 때 쌍령전투에서 싸우다 전사하였다. 후일 병조판서에 추증된다. 윤지선은 조선 후기 문신이다. 광해군 14년(1662) 문과에 급제하여 좌의정까지 오른다. 성품이 온건하고 원만하여 당쟁의 와중에 휩쓸리지 않았고, 경직된…","a":"백산서원","c":"문화유산자료","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661818.jpg"},{"q":"부도란 승려의 무덤을 상징하는 것으로, 시신을 화장한 후 그 유골이나 사리를 그 안에 모셔두는 것이다. 문수사 내에 자리하고 있는 이 2기의 부도는 절내에 마련된 두 군데의 부도밭 중 서쪽에 있는 부도밭에 놓여 있다. 이 곳에는 6기의 부도들이 나란히 자리잡고 있는데, 앞에서 보아 두번째와 세번째에 해당하는 것이 이들이다. 둘 다 같은 양식으로 각 부분이 8각의 평면으로 구성되어 있어서, 세부분으로 이루어진 기단(基壇) 위로, 탑신(塔身)을 올린 후 머리장식을 얹어 마무리하였다. 조선시대에 세운 것으로, 제법 균형미가 느껴지며 만든 솜씨도 섬세하다. 규모에 있어서도…","a":"문수사부도","c":"시도유형문화유산","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639629.jpg"},{"q":"조선 선조(재위 1567∼1608) 때의 학자 유연당 김대현과 그의 자제 8형제의 위패를 모신 사당인 추원사와 그에 딸린 강당으로 강당은 순조 5년(1805)에 세웠으며 사당은 그 이듬해에 세운 것이다. 강당은 앞면 5칸·옆면 2칸으로 전체 10칸으로 되어 있으며, 가운데 6칸은 마루를 깔고 양 옆에는 온돌방을 두었다. 이 건물은 지붕구성이 독특한데 옆모습이 사람 인(人)자 모양인 맞배지붕의 양끝에 다시 맞배지붕이 직각으로 교차하여 전체적으로 Ｉ자형의 용마루를 구성하고 있다. 추원사는 강당의 뒷면 오른쪽에 단을 높여 만들었는데, 앞면 3칸·옆면 3칸의 맞배지붕을 한…","a":"오미동도림강당","c":"시도유형문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640567.jpg"},{"q":"○○○는 중국 삼국지에 나오는 이름난 장수 관우 운장의 제사를 지내는 곳이다. 이 사당은 조선 선조 31년(1598) 당시 ○○에 주둔하던 쉬후첸이 지은 것이다. 지금 있는 자리로 옮긴 시기는 선조 39년(1606)이라는 설과 인조 14년(1636)이라는 2가지 설이 있으나 어느 것이 맞는지는 알 수 없다. 다만 ○○향교와 마주보고 있는 것을 꺼려 ○○○를 옮기게 되었다고 한다. 현재 건물은 1904년 해체·복원한 것으로 ○○○ 가운데 유일한 석상(石像)이 모셔진 곳이기도 하다. 광감루를 지나 좌우에 동재·서재가 있고 조금 더 오르면 묘우 삼문이 있다. 대문에 ‘무안…","a":"안동 관왕묘","c":"시도민속문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658518.jpg"},{"q":"화순 최씨의 종중 재실로, 최한정(1427∼1486)과 그의 아들인 최중온의 위패를 모시고 있다. 화순 최씨는 고려 때 경주 최씨에서 분관한 성씨이며, 위패를 모시고 있는 최한정 선생은 세조 2년(1456) 진사시에 합격하고 3년 뒤에 병과에 급제하였다. 성종이 그를 신뢰하여 대사관에 임명했는데 그 뒤 이조참의를 거쳐 예조참의를 지냈다. 이 건물은 현종 11년(1669)에 세웠고 1928년에 고쳐 지었다. 앞면 4칸·옆면 2칸 규모로 건물 중앙에 대청마루를 깔고 접어지는 문을 달아 제사지낼 때 들어 올려 공간을 마련하였다. 좌우 대칭으로 온돌방을 1칸씩을 두었으며,…","a":"금남 모인당","c":"문화유산자료","r":"세종특별자치시","s":null,"i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666863.jpg"},{"q":"괘불은 옥외에서 법회를 행할 때에 밖에 내다 걸 수 있게 만든 걸개그림 형식의 불화로, 임진왜란 이후 많은 사찰이 복원되면서 괘불의 제작이 활발해졌다. ○○○에 보관되어 있는 이 괘불은 철종 7년(1856)에 제작되어 ○○○ 팔상전에 봉안했다는 기록이 있어 ○○○를 중건한 후 제작한 것으로 보인다. 내용은 석가여래가 영취산에서 제자들을 모아놓고 설법하는 모습을 그린 영산회상도로, 중앙에는 수미대좌 위에 항마촉지인(부처가 도를 터득하기 전 마귀들의 항복을 받을 때 취했다는 손의 모양)을 하고 있는 석가여래상을 크게 표현하였다. 좌우에는 문수보살과 보현보살을 배치하고 그…","a":"삼척영은사괘불","c":"시도유형문화유산","r":"강원특별자치도","s":"평창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638137.jpg"},{"q":"향로란 절에서 마음의 때를 씻어준다는 의미를 가진 향을 피우는데 사용한 도구이다. 높이 20.2㎝, 입 지름 19.5㎝인 이 향로는 나팔모양의 높은 받침대를 가지고 있다. 입부분은 넓은 테가 있고, 테에는 8개의 구름무늬를 새겼다. 몸통 가운데에는 4곳에 원을 만들고, 그 안에 범자를 써 넣었으며, 나머지 공간에는 덩굴무늬로 채웠다. 몸통 맨 아래에는 굵은 선으로 연꽃잎을 새겼다. 나팔모양의 받침대에는 윗부분에 구름과 엎어놓은 연꽃잎을 두었고, 아래에는 덩굴무늬를 새겼다. 몸통과 받침대는 따로따로 만들어 연결 시킨 것으로, 연결 부위에는 작은 반원 모양의 받침장식이…","a":"마곡사동제은입사향로","c":"시도유형문화유산","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639029.jpg"},{"q":"무과에 합격하지 못한 각 고을 무반(武班)들이 봄·가을 2차례 모임을 갖고 활쏘기와 잔치를 베풀며 여러 가지 일들을 의논하던 곳이다. 가락천 서쪽에 처음 지었던 것을 조선 숙종 17년(1691)에 지금 있는 자리로 옮겨 짓고 ○○○이라 이름지었다. 그 뒤 정조 21년(1797)에 이름을 ○○○이라고 고쳤다. 조선 전기에는 좌수의 처소로 쓰이다가 고종 16년(1879)에 신성여학교 자리로 이용하였다. 이 건물은 1981년에 동남향이던 방향을 동북향으로 바꾸어 다시 지은 것이다. 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕으로 꾸몄다.","a":"향사당","c":"시도유형문화유산","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643273.jpg"},{"q":"정려란 나라에서 충신·효자·열녀를 칭찬하기 위해 그들이 살던 고을 입구에 세우던 비석 또는 문을 가리킨다 이것은 들을 위해 세운 것이다. 이 각은 선조 30년(1597) 정유재란 때 영광군에 피신해 있다가 왜군의 추적을 받자 칠산 앞바다에 뛰어들어 정절을 지킨, 동래 정씨와 진주 정씨 문중의 아홉 부인을 기리기 위해 숙종 7년(1681)에 세웠다. 처음에는 8분을 모신 정려를 함평에 세우고 정등의 부인인 밀양 박씨는 따로 그녀의 고향인 영광군에 세웠으나 한국전쟁으로 모두 소실되어 그 후손들이 1960년 지금 있는 자리에 다시 세웠다","a":"영광정렬각","c":"시도기념물","r":"전남광주통합특별시","s":"영광군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654013.jpg"},{"q":"○○○ 안에 있는 ○○이다. ○○은 보통 금당이나 탑 앞에 두는데, 이 ○○도 원래는 용화전(龍華殿) 앞에 있던 것을 일제시대에 절내의 종루와 그 자리를 바꿔놓은 것이다. ○○은 3단의 받침 위에 불을 밝혀두는 화사석(火舍石)과 지붕돌을 올린 일반적인 형태로, 각 부재가 8각을 이루고 있다. 받침부분은 가운데기둥을 사이에 두어 아래받침돌에는 엎어놓은 연꽃무늬를, 윗받침돌에는 솟아오르는 연꽃무늬를 새겨 대칭적으로 표현하였다. 화사석은 4면에 네모난 창을 두었는데 창의 가장자리마다 창문을 달았던 10개의 구멍흔적이 남아있다. 지붕돌은 여덟 귀퉁이가 살짝 들려있고, 꼭대기…","a":"범어사 석등","c":"시도유형문화유산","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636646.jpg"},{"q":"○○○은 춘천관아 건물인 문소각(聞韶閣)을 신축할 때 내삼문(內三門)으로 함께 건립되었다. 고종 27년인 1890년 춘천관아에 이궁(離宮)이 설치되면서 ○○○은 이궁의 내삼문으로 사용되었다. 한국전쟁으로 인한 문소각 소실과 강원도청사 건립으로 몇 차례 이전되어 있던 것을 2013년 4월 이 자리에 이전을 완료하였다. 현판글씨는 조선후기 명필이었던 송하옹(松下翁) 조윤형(曺允亨)이 쓴 것이다. 정면 3칸, 측면 2칸 규모의 맞배지붕으로 내삼문의 전형인 솟을대문 양식을 온전히 갖추고 있다. 한 단의 장대석(長臺石) 기단을 놓고 앞뒤 8개의 원형기둥을 사각형의 주춧돌 위에…","a":"위봉문","c":"시도유형문화유산","r":"강원특별자치도","s":"춘천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637826.jpg"},{"q":"부도는 승려의 무덤을 상징하여 그 유골이나 사리를 모셔두는 곳이다. 상이암의 뒷마당에 자리하고 있는 이 2기의 부도는 각각 ‘해월당’, ‘두곡당’이라는 호를 가진 두 승려의 사리를 모시고 있다. 해월당 부도는 하나의 돌로 이루어진 3단의 받침 위로, 항아리 모양을 한 탑신(塔身)의 몸돌을 두고, 지붕돌을 얹었다. 받침돌에는 세련되지 못한 연꽃무늬가 있고, 지붕돌은 여덟 귀퉁이가 위로 살짝 들려 있다. 꼭대기에는 밑부분이 깨진 꽃봉오리 모양의 돌이 놓여 머리장식을 하고 있다. 두곡당부도는 8각의 받침돌 위로 종모양의 탑신을 올리고, 꽃봉오리 모양의 머리장식을 얹은 구조…","a":"상이암부도","c":"문화유산자료","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661751.jpg"},{"q":"조선 후기에서 일제시대 초기 사이에 지은 개량한옥으로, 행랑대문채와 본채로 구성되어 있다. 본채는 사랑채 부분과 건넌방 부분이 복도를 사이에 두고 남북으로 배치되어 있다. 사랑채 부분은 왼쪽에 현관과 홀을 내었고 서남쪽에 대청을 두어 정원을 내다볼 수 있게 하였다. 대청왼쪽에는 온돌방을, 그 앞쪽에는 주인실을 배치하고 툇마루를 돌렸다. 현관홀 뒤쪽에는 온돌방 2칸을 두어 객실로 쓰고 있으며 복도를 통하여 안청 대마루에 이른다. 안청 대마루 오른쪽에는 안방을 두고 그 위쪽에 부엌을 마련하였다. 안방 뒤쪽에는 골방이 달려 있고, 부엌 오른쪽에는 마루를 두어 찬마루를 쓰고…","a":"가회동한씨가옥","c":"시도민속문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658051.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 경상남도 ○○군 하일면 ○○○의 마을 주위 논밭에는 모두 8기의 고인돌이 밀집하여 분포되어 있는데, 이들은 모두 큰 덮개돌 아래에 작은 받침돌을 마련한 바둑판식 형태를 보인다. 덮개돌의 크기는 대체로 길이 2.5m, 너비 1.5m 정도이며,…","a":"고성 오방리 지석묘","c":"시도기념물","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654899.jpg"},{"q":"경상북도 안동시 북문동에 자리잡고 있는 이곳은 고려의 개국공신인 김선평, 권행, 장정필 3명의 태사(太師)의 위패를 모신 곳이다. 930년 태조가 안동에서 견훤(甄萱)을 토벌할 때 세운 공로로, 권행과 장정필은 대상(大相)이란 벼슬을, 김선평은 대광(大匡)이란 벼슬을 받았다. 기록에 의하면 고려 성종 2년(983)에 처음으로 3명의 제사를 안동부사가 거행하였다고 한다. 현 위치의 묘우는 조선 중종 37년(1542)에 세운 것인데, 한국전쟁 때 불에 타 1960년대에 다시 세운 것이다. 묘우 안에 있는 보물각에는 붉은잔, 비단, 관, 가죽신, 부채 등 보물 제451호로…","a":"안동태사묘","c":"시도기념물","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654417.jpg"},{"q":"조선 광해군 8년(1616)에 세운 ○○○의 정문이다. 그러나 일제가 경성중학교를 건립하고자 궁내의 많은 전각을 헐면서 그 기능을 상실했다. 그 후 일제는 1932년 남산 자락에 이등박문(伊藤博文)을 위한 사당인 박문사(博文寺)를 건립할 때 정문으로 사용하였다. 해방후 박문사는 폐사되고 ○○○은 영빈관(迎賓館) 및 신라 호텔의 정문으로 사용되기도 했다. 1988년 서울시는 ○○○ 복원 계획의 일환으로 ○○○을 지금의 자리로 이전(移轉) 복원하였다. 그러나 원 자리는 동향을 보고 배치했다고 하나, 그 위치는 현재 찾기 힘들다. 정면 3칸, 측면 2칸의 우진각 지붕의 다…","a":"경희궁 흥화문","c":"시도유형문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636097.jpg"},{"q":"조선 단종(재위 1452∼1468) 때 불사이군(不事二君)의 충절을 지키다 순절한 죽림 권산해(?∼1456)의 절의를 본받고 후진을 양성하기 위해 세운 서원이다. 권산해는 조선 전기의 의인(義人)이다. 세조 원년(1455) 수양대군이 단종의 왕위를 빼앗자 두 임금 섬기기를 거부하며 낙향했다. 그 뒤 사육신과 더불어 단종의 복위를 꾀하다가 뜻을 이루지 못하고 순절했다. ○○○○은 정조 18년(1794)에 세웠으나, 고종 3년(1866) 서원철폐령으로 폐쇄되었고 1921년 지방 유림들의 지원으로 다시 세웠다. 앞면 5칸·옆면 1칸 반 크기의 강당을 비롯하여 5동의 건물로…","a":"노봉서원","c":"문화유산자료","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662672.jpg"},{"q":"현재 강원특별자치도 양양군 서면 서림리 상평초등학교 현서분교 교정에 3층석탑과 함께 보존되어 있는 불상으로, 1965년 가까운 논에서 발견되어 옮겨 놓은 것이다. 불상의 머리는 없어졌고 몸도 손상이 많은 상태이다. 두 손을 가슴에 모아 오른손으로 왼손 검지를 감싼 형태로 보아 ○○○○○을 표현한 것임을 알 수 있다. 8각형의 대좌(臺座)는 결실된 부분이 있지만 조각솜씨가 매우 우수하다. 밑받침돌 위에 4매의 석재로 구성된 하대석을 올려 놓았는데, 각 면마다 1구씩의 사자를 돋을새김하였다. 8각 중대석은 각 모서리에 기둥모양을 새기고 그 사이에 1구의 향로와 7구의 보…","a":"양양서림사지석조비로자나불좌상","c":"문화유산자료","r":"강원특별자치도","s":"양양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660556.jpg"},{"q":"이 비석은 비석 가운데 가장 간단한 형태의 ○○이며 비문의 찬자인 동고 최립이 이 비문을 짓게 된 내력과, ○○○의 묘소를 발견하고 수호한 전말 등을 기록해 둔 것으로 ○○○의 묘소가 조선초기에 발견되는 경위를 구체적 인물을 등장시켜 기술하고 있으며, 더욱이 임진왜란 이전에 세워진 비석으로 그 중요성을 감안하여 문화유산자료로 지정함","a":"의령 남군보 묘표","c":"문화유산자료","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666679.jpg"},{"q":"*특이 사항 -삼성혈 입구(동) : 왼손을 가슴위에 올려놓고 있다. -삼성혈 입구(남) : 오른손을 가슴위에 올려놓고 있다. -건시문 입구(동) : 오른손을 가슴위에 올려놓고 있다. -건시문 입구(남): 왼손을 가슴위에 올려놓고 있다.","a":"돌하르방","c":"시도민속문화유산","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659120.jpg"},{"q":"중국의 승려 혜감(慧鑑)이 814년에 창건한 사찰로 전해지는 ○○○에 있는 불상으로 중앙의 본존불을 중심으로 좌우에 협시보살을 배치한 삼존불상이다. 본존불은 사각형의 평판화된 얼굴에 비교적 당당한 체구이며, 양 손을 들어서 엄지와 약지를 맞대고 있어 아미타불을 형상화한 것임을 알 수 있다. 둥글게 움추리고 있는 어깨와, 도식화된 옷자락 표현에서 조선 후기 불상의 특징이 잘 드러나고 있다. 좌·우 보살은 복잡한 보관(寶冠)이나 가슴의 구슬장식, 두 손에 잡은 연꽃가지 등 장식적 요소를 제외하면 본존불과 흡사하다. 이 불상은 둥근맛 나는 양감과 온화한 얼굴표정으로 보아…","a":"금당사목불좌상","c":"시도유형문화유산","r":"전북특별자치도","s":"진안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639386.jpg"},{"q":"바위의 윗부분을 평평히 다듬고 네모난 받침돌을 놓아 3층의 탑신(塔身)을 올린 석탑이다. 탑신의 1·3층 몸돌은 각각 한 돌로 되어있고, 2층 몸돌은 1층 지붕돌과 한 돌로 조성되었다. 지붕돌은 밑면에 3단씩의 받침을 높게 새긴 점이 특징적인데, 네 귀퉁이의 치켜올림과 잘 어울려 안정감을 준다. 꼭대기에는 머리장식을 받치던 네모난 받침돌만 남아 있다. 각부의 양식수법으로 보아 고려시대의 것으로 추정된다.","a":"증평 남하리사지 삼층석탑","c":"시도유형문화유산","r":"충청북도","s":"증평군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638611.jpg"},{"q":"살림집과 정자가 언덕 위에 조화롭게 배치된 집으로 1900년대 초에 지었다. 동북쪽이 낮고 서남쪽이 높은 지형을 살려 낮은 곳에 사랑채와 안채를 동서 중심축에 배치하였다. 주거공간의 왼쪽에 연못과 하은정을 그 뒤쪽에는 연파정을 배치하여 자연과 어울리도록 하였다. 안채마당에서 돌계단을 따라 동산에 올라가면 오래된 벗나무에 둘러싸인 하은정과 연파정이 있다. 하은정과 연파정은 1933년에 지은 정자이다. 연파정은 원래 김용학의 아버지 김희수가 할아버지를 위하여 지었는데, 김용학이 아버지를 위하여 하은정을 지으면서 불이나 다시 지었다고 한다. 이 집은 오래되지는 않았지만 아…","a":"김용학가옥","c":"시도민속문화유산","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658115.jpg"},{"q":"신라 무염대사가 처음 지었다는 ○○○의 대웅전 앞마당에 자리한 ○○○○으로서, 원래는 ○○○에서 200m 정도 떨어진 곳에 있었다가 이곳으로 옮겨진 것이라고 한다. 1층의 받침돌 위에 7층의 지붕돌을 올리고 맨 위에는 작은 연꽃봉우리 모양의 머리장식을 얹은 모습으로 전체적으로 높다란 느낌을 준다. 바닥돌 위에 있는 받침돌에는 엎어 놓은 모습의 연꽃문양과 위를 향한 모습의 연꽃문양이 아래 위로 각각 새겨져 있다. 탑몸돌과 지붕돌이 1매의 돌로 이루어져 있으며 탑몸돌에는 기둥 모양이 생략되었다. 지붕돌 받침은 3개로 표현되어 있고 경사가 완만한 지붕돌의 처마끝은 모서리에…","a":"심곡사칠층석탑","c":"시도유형문화유산","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639701.jpg"},{"q":"1층 기단(基壇)에 5층의 탑신(塔身)을 올린 석탑이다. 기단의 네 모서리와 탑신의 몸돌에는 기둥모양을 조각하였다. 지붕돌은 은은한 곡선을 이루던 처마가 네 귀퉁이에서 살짝 들려 있고 밑면에는 5단의 받침을 두었다. 꼭대기에는 노반(露盤:머리장식받침)과 복발(覆鉢:엎어놓은 그릇모양의 장식)이 올려져 머리장식을 하고 있다. 탑신의 1층 몸돌이 헌칠하게 높고 2층 이상은 급격히 낮아졌으나, 지붕돌의 크기가 거의 일정하여 밋밋한 감을 준다. 옛 백제 지역에 세워 놓은 고려시대 석탑으로, 1층 기단과 지붕돌의 곡선미 등이 백제 석탑의 양식을 잘 따르고 있어 지방색이 강했던…","a":"장문리오층석탑","c":"시도유형문화유산","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639377.jpg"},{"q":"○○○ 극락전내에 ○○○여래좌상을 중심으로 관음보살과 세지보살이 협시하고 있는 상태이다. ○○○여래좌상은 목이 짧고 움츠린 듯한 어깨에 허리가 약간 구부정한 자세를 취하고 있으며, 턱이 짧아지고 각이 져 딱딱해 보이는 얼굴은 눈을 가늘게 뜨고 입꼬리를 살짝 치켜올려 엷은 미소가 번져나는 듯 하다. 오똑한 코에 목에는 삼도가 뚜렷하며 법의는 통견의로서 왼쪽 팔로부터 흘러내린 소매자락은 대퇴부 쪽에서 발가락을 덮고 있다. 자연스러운 옷주름과 사실적 표현의 손으로 인하여 전체적인 분위기는 원만하며 높이 67cm, 무릎폭 43.5cm, 어깨폭 30cm 내외이다. 좌협시인 관…","a":"안국사 목조아미타삼존불상","c":"시도유형문화유산","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639750.jpg"},{"q":"삼강문은 충신, 효자, 열녀를 기리기 위해 세운 정려(旌閭)이다. 이 삼강문은 임진왜란 때 금산전투에서 순국한 의병장 고경명(高敬命,1533~1592)과 그 가족 6명의 충효열을 기리기 위해 세웠다. 1844년에 건립한 이 건물은 일반적으로 사용하는 정려의 건축 양식으로 평면은 정면 4칸, 측면 1칸으로 맞배지붕이다.","a":"고씨삼강문","c":"시도기념물","r":"전남광주통합특별시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645751.jpg"},{"q":"이 불화는 성북구 ○○○에 봉안되어 있는 석가모니불화로서 1897년에 조성되었다. 원래는 남장사 관음선원의 혜봉스님이 원불로 모시던 것을 1947년 현 ○○○ 주지이신 광우스님에게 기증한 것이라고 한다. 화폭은 세로 117cm, 가로 91cm로 작은 편인데, 일부 채색이 박락되긴 하였지만 전체적으로 보존상태는 양호한 편이다. 화면의 중앙에는 본존인 석가모니불이 화면의 반 이상을 차지할 만큼 큼직하게 묘사되어 있고, 좌우로 협시보살과 제자 등 총 9존만이 배치된 간단한 구성을 취하고 있다. 본존은 원형의 두광과 거대한 신광을 배경으로 하여 안정된 자세로 연화대좌 위에…","a":"정각사 석가불도","c":"문화유산자료","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659309.jpg"},{"q":"○○○은 의병승장 영규대사가 계룡산 갑사와 이 곳 보석사를 왕래하며 수도할 때 처소로 이용하던 곳이다. 영규대사는 임진왜란 때 의병을 일으켜 싸운 승려로 의병장 조헌과 합세하여 금산에 들어온 왜구를 물리치다 칠백의사와 함께 순절하였다. 건물은 정면 3칸, 측면 1칸의 맞배지붕 건물로 창녀위(昌寧尉) 김병주(金炳疇)가 ‘○○○'이라 쓴 현판이 걸려 있다.","a":"의선각","c":"문화유산자료","r":"충청남도","s":"금산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660926.jpg"},{"q":"1691년(숙종 17) 숙종은 70세 이상의 노모를 모신 신하들에게 쌀과 비단을 내려주고, 이를 기념하는 연회를 열었다. 이 연회에는 노모를 모신 신하들 가운데 일곱 명이 참여하였다. 따라서 그 일곱 집의 대부인(大夫人)과 며느리, 손자며느리 및 사대부들이 초청되었다. 그 연회의 장면을 그림으로 재구성하여 그린 것이 이 ‘○○○○○’이다. 이 그림이 경기도유형문화유산으로 지정될 때 소장처가 여주시 강천면으로 되어 있어서 명칭을 ‘○○○○○’라고 했다. 두루마리에는 먼저 문자로 쓴 연회장의 배치, 연회 장면을 그린 그림, 그리고 권해(權瑎, 1639~1704)가 지은…","a":"여주군경수연도","c":"시도유형문화유산","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637638.jpg"},{"q":"○○○에는 ○○ 2기가 대웅보전 안에 있다. ○○ 1은 좌대와 패신으로 나뉘어 지는데, 패신 앞면에는 ‘우순풍조 국태민안(雨順風調 國泰民安)’이라는 글자(원래 한글로)가 적혀 있으며, 액자 주위로는 황용과 운문 등 화려한 문양을 장식하였으며, 크기는 높이 71.8 × 폭 40.5cm이다. ○○ 2는 좌대는 결실(현 복원됨)되고 앙련대와 패신만 남아있는데, 중앙의 액자에는 명문을 확인할 수 없으며, 주위로 봉황, 운문과 꽃을 화려하게 장식하였으며, 크기는 높이 34 × 폭 24.2cm이다. ○○ 1의 패신 뒷면에는 ○○를 조성하게 된 발원문이 묵서되어 있는데, 이에 의…","a":"울진 불영사 불패","c":"시도유형문화유산","r":"경상북도","s":"울진군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641185.jpg"},{"q":"○○○ 김운해가 건립한 정자로 인조 18년(1640)에 세웠다. 원래는 조주(趙注)가 지은 별장이 있던 자리였으나, 광산 김씨의 소유가 되어 그 터에 건물을 지었다. 여러 차례의 보수공사를 거쳐 비교적 잘 보존되어 있다. 금성산을 뒤로하고 펼쳐진 평야 속에 자리한 3개의 언덕 중에서 가장 큰 언덕의 숲속에 자리하고 있다. 앞면 3칸·옆면 3칸 규모의 지붕이 여덟 팔자 모양인 팔작지붕집이다. 내부에는 글씨를 잘 썼던 민규호, 신헌 등이 쓴 현판을 비롯하여 11개의 현판을 보존하고 있다. ○○○은 전체적으로 균형이 잡힌 아름다운 정자이다.","a":"벽류정","c":"시도유형문화유산","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640120.jpg"},{"q":"○○○는 횃불과 연기를 이용하여 급한 소식을 전하던 옛날의 통신수단을 말한다. 높은 산에 올라가서 불을 피워 낮에는 연기로 밤에는 불빛으로 신호를 보냈다. ○○○○○는 동부면과 남부면 경계지점에 있는 ○○○ 정상에 있으며, 서쪽으로는 한배곶 ○○○, 북쪽으로 계룡산 ○○○와 서로 연결되었다고 한다. ○○○가 있던 자리는 전체적으로 사각형을 이루며 현재는 주위의 석축이 양호하게 남아있다. ○○○ 아래에는 계단이 있던 흔적이 있고 그 아래에는 ○○○에 딸린 건물터가 있다.","a":"거제 가라산 봉수대","c":"시도기념물","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655848.jpg"},{"q":"충청남도 부여군 은산면에 있는 해발 60m의 낮은 산봉우리를 둘러 싼 토성으로, 안쪽의 내성과 바깥쪽의 외성으로 구분된다. 토성은 흙으로 성벽을 쌓되 산비탈의 자연적인 경사면은 더욱 가파르게 깎아 성벽으로 이용하는 것을 말한다. 성 둘레는 내성이 약 180m이고 외성이 약 250m이다. 외성은 대부분이 개간되어 평지화 되었으며, 내성은 흙으로 쌓은 형태가 부분적으로 남아있고, 북쪽에는 너비 5∼6m의 물길인 도랑이 있다. 산성의 서남쪽 기슭 암벽 아래에는 별신당이 있는데, 백제부흥운동군과 관련된 은산별신제의 전설이 전해오고 있다.","a":"은산당산성","c":"시도기념물","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653092.jpg"},{"q":"갑사는 백제 구이신왕 원년(420)에 아도화상이 처음 지었고, 통일신라 문무왕 19년(679)에 의상이 고쳐 지었다고 한다. 그 뒤 고려시대와 조선시대를 거치면서 여러 차례 고치고 넓혀 지어 오늘에 이르고 있다. 팔상전에는 석가모니불과 팔상탱화, 그리고 신중탱화를 모시고 있다. 팔상탱화는 석가여래의 일대기를 8부분으로 나누어 그린 그림이며, 신중탱화는 불교의 호법신을 묘사한 그림으로 호법신은 대개 우리나라 전통의 신들이다. 건물 규모는 작지만 지붕 처마를 받치기 위해 장식하여 만든 공포가 기둥 위와 기둥 사이에도 있는 다포 양식으로 꾸며 격식을 갖추고 있다.","a":"갑사팔상전","c":"문화유산자료","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660959.jpg"},{"q":"벽진 이씨 외재공파의 중시조이며, 조선 중기의 학자인 외재 ○○○의 문집을 새긴 책판이다. ○○○은 한강 정구 선생의 문하에 들어가 성리학을 배웠으며, 광해군 때 이시발, 김우옹의 추천으로 세자 익위사세마에 임명되었으나, 사퇴하였다. 1627년 정묘호란이 일어나자 강화도까지 왕을 모시고 다녀왔으며, 그 공으로 서울로 돌아와서는 음성현감을 지냈다. 성리학을 연구하는 데에 몰두하였으며, 죽은 후에는 경상남도 영산의 덕봉서원에 모셔졌다.","a":"이후경 외재집 및 이도보 익암집 목판","c":"시도유형문화유산","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642288.jpg"},{"q":"중앙에서 파견된 관리나 외국사신이 묵던 숙소로 세워진 시기는 알 수 없다. 원래는 지금의 선산초등학교 부근에 있던 ○○○○ 건물들 중의 하나였으며『동국여지승람』에 의하면 그곳에는 남관, 북관, 청회루, 양소루가 있었다고 한다. 1914년에서 1984년까지 선산읍사무소로 쓰이다가 1986년 경상북도 유형문화유산으로 지정되어 오늘에 이른다. 앞면 5칸·옆면 4칸의 1층 건물로, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕으로 되어있다. 앞면의 가운데 칸에는 현관을 만들었으며 기둥 사이마다 꽃받침을 두어 앞면에는 귀신얼굴을, 좌우 옆면에는 개와 코끼리를 조각했다. 또 지붕…","a":"선산객사","c":"시도유형문화유산","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640740.jpg"},{"q":"○○이란 수렵, 어로, 채집에 의하여 살아온 옛 사람들이 조개를 먹은 뒤 버린 조개껍데기와 생활쓰레기가 함께 쌓여 이루어진 유적으로 조개더미라고도 한다. ○○○○○은 신석기시대의 전기·중기·후기에 해당하는 3개의 문화층으로 형성되어 있는 유적으로 ○○○ 입구에 있다. 이 ○○에서 조사된 유구는 둥근 화덕자리와 둥근돌무지유구, 그리고 널무덤을 비롯한 7기이다. 널무덤에서 출토된 사람의 뼈는 10세 전후의 여자아이의 것으로 추정되며, 뼈의 상태는 불량하나 두개골은 비교적 제 모습을 유지하고 있다. 둥근 화덕자리와 둥근돌무지유구는 배치상태나 주변 환경으로 보아 어패류나 동…","a":"범방동 패총","c":"시도기념물","r":"부산광역시","s":"강서구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645183.jpg"},{"q":"<○○○○○>은 1817년(순조 17) 3월 11일 성균관에서 치러진 효명세자[孝明世子, 1809-1830, 뒤에 익종(翼宗)으로 추존]의 입학례를 기념한 화첩이다. 입학례의 과정을 다섯 장면으로 구성하고, 이튿날(3월 12일)에 있었던 진하례 장면을 마지막에 그려넣었다. 표지에는 ‘○○○출궁도(王世子出宮圖)’라고 쓰인 표제가 붙어 있으나 이 표제는 ○○○ 입학례 절차 중에서 세자가 성균관으로 가기 위해 궁궐을 나오는 처음 일부분만을 의미하므로 이 화첩의 명칭은 전체 내용을 포괄하는 <○○○○○>으로 지정한다. 그림에 앞서 입학 의주(儀註)[출궁의(出宮儀), 작헌례(…","a":"왕세자입학도첩","c":"시도유형문화유산","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636536.jpg"},{"q":"지석묘는 청동기시대의 대표적인 무덤으로 ○○○이라고도 부른다. 우리나라의 ○○○은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓는 탁자식과, 땅속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. ○○○○○의 지석묘는 ○○○ 탑평마을 중심부에 위치하며 민가에 둘러싸여 있다. 여러 개의 자연돌을 고임돌로 사용하고 그 위에 커다란 덮개돌을 올려 놓은 전형적인 바둑판식 ○○○의 형태를 갖추고 있다. 특히 다른 지방의 ○○○과 달리 덮개돌 위에 평면 타원형의 돌을 올려 놓아 3층의 탑과 같은 구조를 이루고 있…","a":"충주 조동리 고인돌","c":"시도기념물","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650785.jpg"},{"q":"충청북도 ○○군 청천면의 채운사는 고려 충렬왕 3년(1277) 도일 스님이 창건하여 수도암이라 하던 것을 혜식 스님이 이름을 고쳐 부른 것이라고 한다. 불상이 모셔져 있는 대웅전은 한국전쟁 때 인민군이 3번이나 불태우려 했지만 타지 않자 겁을 먹고 물러갔다는 일화가 전해진다. 불상은 오른손을 들어 손바닥을 밖으로 하고, 왼손은 무릎 위에 올려 설법하는 모양을 하고 있다. 전체적으로 정제된 조각기법을 보여주고 있으며, 만들어진 연대를 밝혀주는 유물이 불상 속에서 나왔다는 점에서 중요하다. 조선 경종 3년(1723)에 만들었다는 기록을 통해 조선 후기 불상 연구의 기준이…","a":"괴산 채운암 목조여래좌상","c":"시도유형문화유산","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638693.jpg"},{"q":"수원 ○○○ 용화전 내 불단에 봉안된 석불상이다. 본존불은 가부좌를 틀고 앉아 있으며 그 좌우에 모셔진 보살상들은 서 있는 자세이다. ○○○ 석조 ○○○은 대웅보전 뒤편 언덕에서 건물을 지으려고 터를 닦던 도중에 충토되었다고 한다. ○○○상은 모두 표면의 마멸이 심하고 부분적으로 떨어져 나가는 등 세부를 알아보기 어렵다. 그러나 애초에 형태가 부정확하고 새김이 깊지 않으며, 불상이나 보살상이 갖추어야 할 손 모습에서 벗어나 어떤 상을 조성한 것인지 정확히 파악하기가 힘들다. 세 상 모두 방형의 얼굴인데 머리 상부와 얼굴의 마멸로 형태는 거의 알아볼 수가 없다. 본존불…","a":"봉녕사 석조삼존불","c":"시도유형문화유산","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637659.jpg"},{"q":"○○○○○은 치성광여래(熾盛光如來)를 위시한 칠성여래(七星如來)와 일광·월광보살 및 칠원성군(七元星君)과 8권속을 비단 바탕 위에 먹과 채색안료를 사용하여 제작한 불화이다. 전체적인 구도는 화면을 크게 양분하여 상단 중앙에는 청연화좌(靑蓮花座)에 결가부좌한 치성광여래를 일광· 월광 두 협시보살과 함께 삼각형의 구도로 배치하고 있다. 협시보살 측면에는 좌우 각각 4구씩 8권속을 묘사하고 있으며, 주존 광배 후면 양 측면에는 6여래를 각각 3위씩 나누어 배치하고 있다. 하단에는 거의 화면 절반 크기로 칠원성군을 큼직하게 배치한 후 뒷면을 구름으로 처리하여 상·하단 경계를…","a":"함안 능가사 칠성탱","c":"문화유산자료","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665854.jpg"},{"q":"조선후기 건립된 살림집으로 ‘ㄱ’자 형의 안채와 ‘-’자형의 문간채로 구성되어 있다. 안채는 7칸×2칸 규모로 홑처마 팔작지붕으로 가운데 대청마루를 두고 좌우에 방을 배치하였으며 ‘ㄱ’자로 꺾여진 끝에 부엌과 고방을 배치한 홑집구조로 충청지방의 전형적인 배치와 평면구조를 보여주고 있다","a":"아산 김효직가옥","c":"시도민속문화유산","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658280.jpg"},{"q":"○○○○은 해발 380m의 산꼭대기에 가파른 경사를 이용하여 쌓은 성으로, 안심과 하양으로 이어지는 통로상에 있어, 지형상 중요한 군사적 요충지였던 것으로 짐작된다. 성벽의 둘레는 약 1㎞이며, 성의 서쪽과 남쪽의 산기슭에서 능선으로 이어지는 완만한 경사지에는, 인공적으로 절벽을 만들어 적의 침입에 대비하였다. 절벽 앞에는 문터로 보이는 입구가 있으며, 성 안의 동북쪽에는 우물터가 있다. 성 안에서 신라 토기조각들이 발견되는 점으로 미루어, 삼국시대에 만들어진 성으로 추측된다. 임진왜란 때 대구지방의 의병들이 이 성에 모여 활동했다는 것으로 보아, 삼국시대부터 그 후…","a":"용암산성","c":"시도기념물","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2387590.jpg"},{"q":"조선 정조 15년(1791)에 송계 봉유례·풍애 봉즙·묵헌 봉여해 등을 추모하기 위해 단을 설치했던 곳이다. 그 뒤 정조 17년(1793)에 신당인 ○○○를 세워 봉여예만 모시다가 철종 13년(1862)에 봉유례·봉즙·봉단의를 추가로 모시게 되었다. 고종 5년(1868) 흥선대원군의 서원철폐령으로 훼철되었다가 1903년에 다시 세웠다. 건물로는 ○○○, 별묘, 숭절당, 고직사, 내삼문, 외삼문이 있다. 신당인 ○○○는 앞면 3칸·옆면 2칸 규모이며 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕으로 꾸몄다. 강당인 숭절당은 앞면 4칸·옆면 2칸 규모이다.","a":"장성 만곡사","c":"문화유산자료","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662034.jpg"},{"q":"○○○○○는 좌대와 비신, 지붕돌로 구성되어 있다. 1737년 김진동 등이 주도하여 문중사람들의 참여하여 2년 뒤인 1739년 기미에 세웠다. 높이 249cm의 비 전면에는 「신라왕자○○○」라 하였고, 앞면 오른쪽에 「○○○명(遺墟碑銘)」이란 제하의 119자의 내용이 쓰여 있으며, 왼쪽에 비를 세우는 일에 참여한 4명의 이름과 관직 등 26자가 각인되어 있다. 뒷면에 김진상(金鎭商)이 쓴 「○○○음기」라는 제목하에 180자의 내용과 23자의 세운 시기와 글씨를 쓴 사람의 이름이 새겨져 있다. 비각은 정면 1칸, 측면 1칸의 규모인데 팔작지붕의 건물이다. 후면의 음기…","a":"담양평장동광산김씨유허비","c":"시도기념물","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654356.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 언제 지었는지는 확실하지 않지만, 조선 전기에 세운 것으로 보인다. 원래는 구교리에 있던 것을 숙종 14년(1688)에 지금 있는 자리로 옮겼다. 그 뒤 여러 차례 고쳐 지어 오늘에 이른다. 지금 남아 있는 건물로는 대성전, 명륜당, 동재, 서재 등이다. 대성전 안에는 공자를 비롯하여 그의 제자들과 우리나라 성현의 위패를 모시고 있다. 조선시대에는 나라에서 토지와 노비·책 등을 지원받아 학생들을 가르쳤으나, 지금은 교육 기능은 없어지고 제사 기능만 남아 있다.","a":"임천향교","c":"시도기념물","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652966.jpg"},{"q":"유봉시(1654∼1709)가 두 아들의 공부를 위해 안동시 임동면 위동으로 이사하였는데, 두 아들이 모두 학문에 전념한 보람이 있어 학덕과 벼슬이 세상에 알려지자 이곳에 서재를 짓고 세 그루의 나무를 심어 ○○○이라 하였다. 조선 현종 15년(1674) 안동군 임동면 위리에 지었다가 1922년에는 박곡리로 옮겨 지었으나, 1987년 임하댐 건설로 지금 있는 자리에 다시 옮겨 지었다.","a":"삼가정","c":"문화유산자료","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662443.jpg"},{"q":"○○○란 임금이나 고관의 평생업적을 기록하여 그의 무덤 남동쪽에 세워놓은 비를 말한다. 이 비는 조선 중기의 문신인 이귀(1557∼1633) 선생을 기리고 있다. 이귀는 이이·성혼의 가르침을 받았으며, 임진왜란 때에는 군인을 모집하여 나라를 구하는데 힘썼다. 광해군을 몰아내고 인조를 왕위에 오르게 하는 인조반정때 공을 세워 일등공신이 되었으며, 그후 ○○○○○에 봉해졌다. 비는 거북받침돌 위에 한돌로 이루어진 비몸과 머릿돌을 세웠다. 거북받침돌은 머리를 수평으로 내밀고 있으며, 머릿돌에는 두 마리의 용과 구름을 사실적이고 생동감 있게 나타내었다. 비문은 조익이 글을…","a":"연평부원군신도비","c":"시도유형문화유산","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639147.jpg"},{"q":"○○○○은 조선시대 연산현(連山縣)의 관아를 출입하던 정문이다. 앞면 3칸·옆면 2칸의 2층 누각건물로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 아래층은 각 칸마다 문을 달아 통행로로 이용하였고, 위층은 누마루로 4면에 난간을 둘렀다. 주춧돌(礎石)이 없는 대신 돌기둥(石柱)으로 아래층 중간 부분까지 오도록 하였고 그 위에 나무기둥(木柱)을 이어댔다. 후면에는 객사터(客舍址)가 있었던 것으로 전한다. ○○○○은 지금 남아있는 조선 후기 관아건물 중 대표적인 양식의 문루이다.","a":"연산아문","c":"시도유형문화유산","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639008.jpg"},{"q":"임진왜란 때 수영성을 지키며 왜적과 장렬히 싸우다 순절한 25명의 의로운 충절을 기리고 있는 제단이다. 조선 선조 25년(1592) 임진왜란이 일어나자 경상좌수사로 있던 박홍은 성을 버리고 달아났다. 이 때 수병(守兵)과 성민(城民) 25인이 성문 밖의 선서바위에 모여 피로써 맹세한 후, 바다와 육지에서 적을 상대로 7년간 대항하였다. 이러한 사연은 광해군 원년(1609) 지방민들의 청원으로 알려지게 되어, 동래부사 이안눌이 이 때의 일들을 모아『정방록』을 만들고, 이들의 집 문에 ‘의용(義勇)’이라는 두 글자를 써붙여 그 뜻을 기리도록 하였다. 순조 때에는 동래부사…","a":"25의용단","c":"시도기념물","r":"부산광역시","s":"수영구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2022040418093800.jpg"},{"q":"조선 세종대의 효자 ○○○의 효행을 기리기 위하여 1633년(인조 11)에 세운 정려문이다. 규모는 정면 1칸,측면 1칸의 맞배지붕 목조기와집으로 사면을 홍전(紅箭)으로 막고, 처마 밑 중앙에는 서하(墅河) 임헌회(任憲晦)가 짓고 전우(田愚)가 쓴 정려기를 달았다. 건물 내부에는 현판 외에 효자비가 자리하고 있다. ○○○은 한산군수(漢山郡守)의 직(職)을 버리고 고향으로 돌아와 부모봉양에 온 힘을 기울였으며, 아버지가 잉어가 먹고 싶다고 하여 여계소(女溪沼)에 앉아서 어름을 녹이니 잉어가 튀어나오고, 꿩고기가 먹고 싶다고 하면 손가락을 펴서 들고 들에 서 있으면 꿩이…","a":"진천 김덕숭 효자각","c":"시도기념물","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651357.jpg"},{"q":"조선 광해군 때의 문신인 내암 ○○○ 선생 관련 고문서 82점과 문집외 10종류 16권이다. ○○○은 선조 6년(1573) 황간현감으로 재직하면서 많은 선행을 베풀었으며, 임진왜란이 일어나자 합천에서 의병을 모아 왜군을 물리쳤다. 선조 35년(1602) 대사헌으로 승진하고 그 후 좌참찬, 우의정, 좌의정, 영의정을 지냈다. 그러나 인조반정 때 집권 서인들에게 억울하게 죽임을 당하였다. 순종 2년(1908)에 명예가 회복되어 관직이 복구되었고, 후에 매천 황현과 단재 신채호는 ○○○을 실천하는 개혁적 인물로 평가했다.","a":"정인홍 관계 문적","c":"시도유형문화유산","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642261.jpg"},{"q":"○○○은 조선 명종 즉위년(1545)에 오양손(吳梁孫)이 처음 짓고 1922년 후손들이 고친 것이다. 해주오씨로는 처음으로 삼은리에 들어 온 오양손은, 김굉필(1454∼1504)의 문인으로 참봉을 지냈다. 그는 중종 14년(1519) 기묘사화(己卯士禍) 때 조광조 등 많은 선비들이 화를 입는 모습을 보고, 경기도 수원과 남원 목기촌으로 은거하였다가, 중종 16년(1521)에 삼은리로 들어왔다. 이후 그는 이곳에 ○○○을 짓고 시와 술을 벗삼으며, 후학을 지도하는 일에 전념하였다. 1856년에 중창하였고, 그 뒤 1922년에 중건하여 오늘에 이르고 있다. ○○○이란 이…","a":"오괴정","c":"문화유산자료","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661837.jpg"},{"q":"연곡 면사무소의 서남쪽 산봉우리에 있는 신라의 무덤이다. 뚜껑돌의 일부가 파손되었지만 비교적 보존상태가 좋은 편이다. 무덤의 구조는 정확한 학술조사가 없어 확실히 알 수 없으나, 주변에 남아있는 무덤 유적과 비교해 볼 때 4면을 돌로 벽을 쌓고 뚜껑돌을 덮은 돌방무덤(석실분)으로 생각된다. 주변에서는 굽다리접시(고배), 둥근바닥긴목항아리(원저장경호), 둥근바닥항아리(원저단경호) 등의 전형적인 신라 토기 조각이 수습되었다.","a":"연곡고분","c":"문화유산자료","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660428.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○를 처음 지은 정확한 연대는 알 수 없으나 고려시대로 보인다. 조선 성종 13년(1482)에 지금 있는 자리로 옮겨 지었으며 이후 여러 차례 수리하였다. 건물 배치는 뒤쪽에 ○○○과 내삼문, 앞쪽에 명륜당을 일직선상으로 하고 좌·우에 동재와 서재 등을 배치한 전학후묘의 형식이다. ○○○은 앞면 3칸·옆면 3칸의 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 안쪽에는 공자를 비롯한 중국과 우리나라 유학자의 위패를 모시고 있다. 조선시대에는 나…","a":"해남향교대성전","c":"문화유산자료","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662014.jpg"},{"q":"조선시대의 ○○○○이 있었던 곳이다. 1879년 간행된 『○○○지』에 따르면 ○○○○은 돌로 쌓은 성으로, 둘레 8,263척 높이 9척이며, 동·서·남·북에 성문이 있었다고 한다. 1979년에 간행된 『광주시사』에 의하면 일본군이 한말 의병항쟁을 탄압하기 시작한 1908년부터 1918년 사이에 철거되었으며, 4대문의 위치와 성 밖에는 주위에 물길을 만든 도랑이 있었음을 밝히고 있다. 동쪽의 서원문은 대의동 옛 광주문화방송 4거리, 서쪽의 광리문은 황금동 옛 미국공보관 4거리, 남쪽의 진남문은 광산동 옛 전남대학교 의과대학가는 4거리, 북쪽의 공북문은 충장로 4가 충장…","a":"광주읍성유허","c":"문화유산자료","r":"전남광주통합특별시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018080717200600.jpg"},{"q":"○○○은 고려 말 조선 초의 문관으로 본관은 안동(安東)이다. 장상들과 함께 이성계를 추대해 개국공신(開國功臣) 1등에 봉해졌으며, 상락백(上洛伯)의 작위를 받았다. 1398년 제1차 왕자의 난 때, 백관을 거느리고 대궐에 가 적장(嫡長)을 후사로 세울 것을 요청해 정종의 즉위를 도운 공으로 정사공신(定社功臣) 1등에 책록되었다. 개국공신 중에서는 배극렴(裵克廉) 다음으로 지위가 높았던 고려의 원로 구신(舊臣)이며, 가문이 귀하고 높아 마음이 청고해 이성계가 아꼈다고 한다. ○○○의 묘는 부인 죽산 박씨(竹山朴氏)와 합장된 단분(單墳)이다. 봉분은 6각형으로 호석(護…","a":"익원공김사형묘역","c":"문화유산자료","r":"경기도","s":"양평군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660198.jpg"},{"q":"○○○는 이애와 그의 아내 진성 백씨의 묘 근처에 세운 재실 건물이다. 이애(1480∼1561)는 황해도 관찰사를 지낸 근재공의 아들로 중종 10년(1515) 과거에 급제한 후 선전관, 사헌부 감찰, 경주 판관 등을 지냈다. 20여년간 병으로 벼슬에 오르지 못하다가 명종 15년(1560) 통정의 벼슬을 받았으나 이듬해에 죽었다. 명종 20년(1565) 처음 지은 ○○○는 효종 10년(1659) 고쳐 지은 뒤, 몇 차례의 보수공사를 하였는데 당시 건축의 원형이 잘 남아 있다.","a":"사암재","c":"문화유산자료","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663111.jpg"},{"q":"이 건물은 임란 때 의병장으로 활약하였던 ○○○ 권우(權祐, 1520 ~ 1593)가 1580년경에 건립한 살림집이다. 현재의 종택(宗宅)은 1780년을 전후하여 중수(重修)한 것인데, 안 대청의 좌우에 둔 도장방이나, 사랑방 공간이 발달되지 못한 점, 도장방 상부에 있는 더그매와 대청 뒷벽의 구성 등은 건립 당시의 모습을 보여 주고 있어 주거사 연구의 좋은 자료가 되어지고 있다.","a":"예천권씨영사당종택","c":"문화유산자료","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663494.jpg"},{"q":"석가여래유적도(釋迦如來遺蹟圖)는 목판에 새긴 것으로서, 그 크기는 가로 33cm, 세로 74cm, 두께 3.7cm이다. 전면에는 석가라는 문자는 없어지고, ‘○○○○○’라고 양각되어 있는데 그 크기는 길이 50cm, 넓이 17cm이다. 여기에는 열 네 개 무늬가 있는 부처님의 두 발바닥이 새겨져 있고, 그 아래에 기원하는 바를 적은 글이 기록되어 있다. 뒷면 아래에 조선 순조 12년(1812)에 제작된 것임을 밝히는 글자가 새겨져 있다. 여기에는 석가모니를 중심으로 오른쪽에 아미타불, 왼쪽에 미륵불 그리고 하단에 지장보살을 중심으로 지옥의 수 및 보살의 수가 정연하게…","a":"여래불적도","c":"시도유형문화유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639480.jpg"},{"q":"무안지서 바로 옆에 자리하고 있는 비로, 현재는 돌담이 둘러진 비각안에 보존되어 있다. 사명대사의 충절을 기리고 있는 비로, 일명 ‘사명대사비’라고도 불리운다. 비는 네모난 받침돌 위로 비몸을 세우고, 맨 위에 머릿돌을 얹은 구조로, 특이하게도 비몸은 까만 대리석을 사용하였다. 비문에는 표충사(表忠寺)의 내력, 서산대사의 행적, 사명대사의 행적 등을 4면에 고루 새겨 놓아, 서산대사의 제자이기도 한 사명대사가 임진왜란 당시 스승의 뒤를 이어 의병을 일으켜 활약한 사실, 가토 기요마사와의 담판내용, 정유재란 이후 선조의 어명을 받들어 일본에 건너가 포로 3천여명을 데리…","a":"밀양 표충비","c":"시도유형문화유산","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641364.jpg"},{"q":"전북특별자치도 정읍시 ○○○에 있는 돌로 된 입불상이다. 머리에는 마치 갓과 같은 테가 큰 모자를 쓰고 있어 유교적인 성격이 가미되었음을 알 수 있다. 어깨는 다소 움츠린 모습이며, 턱 밑에는 U자형의 옷주름이 있다. 배 아래에서는 옷주름이 V자형으로 처리되었고, 손목 아래에는 3줄의 평행선이 내려지고 있다. 오른손은 어깨 높이로 들어 손바닥을 보이며 손끝은 위를 향하고 있다. 왼손은 마찬가지로 손바닥을 보이는데 손끝이 땅을 향하고 있다. 얼굴 표현과 손 표현에 노력이 집중된 불상으로 민속적인 특색을 띠고 있다.","a":"망제동석불입상","c":"시도유형문화유산","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639545.jpg"},{"q":"이 각자는 농암 이현보(1467∼1555) 선생의 정자 옛 터를 표시하기 위해 앞면을 다듬은 4개의 바위에 새기었다. 이현보는 연산군 4년(1498) 문과에 급제한 뒤 내직으로 예문관검열, 사간원정언과 외직으로 밀양과 안동, 충주 등지의 지방관을 지냈다. 이후 형조참판, 호조참판 등의 벼슬을 지내고 1542년 76세 때 병을 핑계로 벼슬을 그만두고 말년을 고향에 돌아와 지냈다. 조선시대에 자연을 소재로 삼아 시조를 지은 대표적인 문인으로 국문학 사상 중요한 자리를 차지하고 있는 인물이다. 이 바위에는 ‘농암선생정대구장(壟巖先生亭臺舊庄)’이라고 두 글자씩 음각되어 있다…","a":"농암각자","c":"시도유형문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640304.jpg"},{"q":"○○○ 선생은 본관이 안동(安東)이며, 호는 청음(淸陰)·석실산인(石室山人) 등이다. 병자호란이 일어나자 예조판서로 주화론(主和論)을 배척하고 끝까지 주전론(主戰論)을 폈다. 1645년 특별히 좌의정에 제수되고, 기로소(耆老所)에 들어갔다. ○○○○○ 묘는 선영(先塋) 중 조부 김생해(金生海) 묘 아래 단독으로 조성되어 있다. 봉분 앞에는 묘표, 혼유석, 석상, 향로석이 설치되어 있으며 그 아래로 묘명비(墓銘碑)와 문인석 1쌍이 건립되어 있다. 묘표는 운수방부(雲首方趺; 구름이 조각된 비신 머리와 네모난 비좌) 형태로 운수는 앞뒤 면에 일출(日出)을 형상화했다. 문인…","a":"김상헌선생묘","c":"시도기념물","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646377.jpg"},{"q":"이 마애불상은 자연바위 한쪽 면에 얕게 새긴 ○○○○으로서 머리부분은 양각(陽刻)되어 있으나 나머지 면은 선각(線刻)에 가깝게 조각되어 있다. 대좌와 광배가 생략되어 있으나 인위적인 손상이 없는 완형이며, 조각솜씨가 미숙한 면이 있으나 어수룩하고 소박한 분위기를 주는 등 고려시기 지방양식을 잘 반영하고 있다.","a":"영주휴천동마애여래좌상","c":"문화유산자료","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663591.jpg"},{"q":"부산광역시 기장의 ○○○ 마을 해안 가까이에 있는 구릉을 이용하여, 임진왜란 때 왜군의 장수 구로다가 조선·명나라 연합군의 공격을 방어하고 남해안에 장기간 머물기 위해 쌓은 성이다. 돌로 쌓았으며 둘레는 약 960m, 성벽높이는 약 4m이다. 왜성은 대개 강이나 바다에 가까운 구릉을 택하여 수송·통신 등에 자유롭고 선박의 출입이 편리한 장소에 성을 쌓는다. 이 성은 부산왜성과 형태가 비슷하며 일본에서는 기장성이라고도 불리어지고 있다. 또한 양산의 서생포성과 울산의 학성·부산성을 연결하는 요충지에 자리하고 있는데 현재 성곽이 남아 있지만 주위는 밭과 민가로 사용되고 있…","a":"기장죽성리왜성","c":"시도기념물","r":"부산광역시","s":"기장군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645206.jpg"},{"q":"○○○의 한분인 경은 이맹전(1392∼1480)을 제사지내기 위하여 지은 집으로 조선 숙종 39년(1713)에 왕의 명에 따라 후손 이유용·이십용 등이 지었다. 청렴결백하다는 평판을 받았던 이맹전은 단종 1년(1453) 수양대군이 단종을 보좌하는 황보 인·김종서 등을 몰아내고 정권을 빼앗아 나라가 소란해지자, 다음해에 벼슬을 버리고 고향으로 돌아갔다. 귀머거리·장님이라 핑계하며 친한 친구마저도 만나지 않던 이맹전은 30여 년을 문밖에 나가지 않고 지내다가 나이 90여 세에 세상을 떠났다. 앞면 5칸·옆면 1칸 규모이며, 지붕 옆면이 사람 인(人)자 모양인 맞배지붕집이…","a":"생육신이경은선생제단","c":"시도유형문화유산","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640339.jpg"},{"q":"갑사의 창건과정과 역사를 적은 비로, 바윗돌 위에 사각의 비받침돌을 마련하여 비몸을 세운 후 지붕돌을 얹은 모습이다. 비몸에는 4면 모두 비문을 새겼는데 일부 손상된 부분은 읽을 수가 없다. 주민들의 말에 의하면 비석재(碑石材)속에 금이 들어 있어 그것을 파내기 위한 소행이었다고 한다. 조선 현종 원년(1659)에 세운 비로, 비문은 여주 목사 이지천이 짓고 공주목사 이기징이 글씨를 썼다.","a":"갑사사적비","c":"시도유형문화유산","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639090.jpg"},{"q":"경상남도 함양군 서상면 들판에 있는 ○○○의 9부능선을 따라 서쪽 방향으로 쌓은 산성이다. 이 성은 삼국시대에 백제가 신라를 침범하여 약탈을 일삼자 이를 막기 위하여 성을 쌓고 쌀을 비축했다고 해서 ‘합미성’이라고 하며, 일명 ‘금당성’이라고도 한다. 또한 마을 앞산 봉우리가 연못에 떠 있는 연꽃같다고 하여 꽃다운 못, 즉 ‘방지’라 이름하였다 한다. 현재 성벽은 윗부분이 무너져 성의 윤곽을 확인하기 어려우나, 가로 45㎝, 세로 30㎝ 크기의 자연석과 깬돌 이용하여 높이 3∼4m 정도로 쌓았는데, 지금은 약 500m 정도만 남아 있다. 성 안쪽 가운데에는 우물이 있…","a":"함양방지산성","c":"시도기념물","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656143.jpg"},{"q":"조선 선조 때의 무관 박홍장이 살던 집이다. 박홍장(1558∼1598)은 임진왜란 때 활약한 장수로 유성룡이 추천하여 왜란을 수습하기 위해 일본에 통신사로 파견되었다. 도요토미가 사절일행을 멸시하였으나 조금도 굴하지 않고 나라를 위해 의지를 굽히지 않았다. 이 가옥은 선조 3년(1570)에 세워 전하다가 숙종 46년(1720) 건물의 일부가 소실되었다. 앞면 4칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 이루는 팔작지붕이다. 천장에 초가집이 까치구멍집과 비슷한 형태인 투창이 있다는 점이 특이하다.","a":"영덕 농아당 종택","c":"문화유산자료","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663137.jpg"},{"q":"호구단자(戶口單子) 60매와 준호구(準戶口) 5매, 입후성문(立後成文) 및 소지(所志) 연점(連粘)문서 1매, 공명첩(空名帖) 3매, 교지(敎旨) 13매, 전령(傳令) 2매로 구성되어 있다. 대개 시기는 18∼19세기에 걸쳐 있다. 이 중 양자(養子)를 설정하는 당사자의 입후성문(立後成文) 및 여러 사람이 이를 허가해 줄 것을 요청하는 소지(所志)가 같이 연결되어 붙어져 있는 것은 보기 드문 예이다. 이 외에 ‘전령(傳令)’이란 명칭으로 관직에 제수하는 문서도 있는데, 이런 경우도 드물다. 원래 4품 이상은 ‘교지(敎旨)’, 6품 이상은 ‘교첩(敎牒)’, 7품 이하는…","a":"경상대학교소장청주한씨고문서","c":"문화유산자료","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665080.jpg"},{"q":"이 불상은 고려말의 고찰(古刹)로 알려진 서울시 ○○○ 소재 ○○○ 약사보전에 봉안되어 있는 ○○○○으로 전체크기는 79.5cm이다. 신체에 비해 얼굴이 크고, 머리에는 나발이 새겨져 있으며 머리 정상에는 계주가 표현되어 있다. 불상의 저부에 균열이 있고, 전체적으로 호분이 여러 겹 칠해져 있어 불상의 원 상호(原 相好)를 알아보기 어려우나 동그란 얼굴에 이목구비가 섬세한 원만한 얼굴이었을 것으로 추정된다. 불신(佛身)은 전체적으로 위축되었으며 머리의 크기에 비해서 어깨가 좁다. 두꺼운 대의(大衣)를 편단우견식으로 착의하였는데 대의 옷주름이 일정한 간격을 이루며 약간…","a":"일원동불국사석불좌상","c":"문화유산자료","r":"서울특별시","s":"강남구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659311.jpg"},{"q":"옛날 성주 출신의 과거에 합격한 선비들이 선현들의 정신을 기리고, 서로 공부하는 것을 격려하던 곳이다. 조선 선조 21년(1588)에 성주 서문 밖에 세우고 사마소라고 불렀으나, 후에 건물이 무너짐에 따라 철종 11년(1860)에 지금의 장소로 옮겨 짓고 ○○○이라고 했다. 과거에 합격한 여러 가문의 자손들이 해마다 이곳에 모여 학문을 연마하고 토론을 했다고 한다. 지금도 음력 4월 10일에는 여러 가문의 자손들이 모여 선현을 추모하는 장소로 이용되고 있다. 앞면 4칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 4칸 중, 가운데…","a":"연계당및연계소영건일록","c":"문화유산자료","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662621.jpg"},{"q":"귀신사와 가까운 곳에 서 있는 탑으로, 본래의 모습을 많이 잃어 다시 복원한 것이다. 형태는 2층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습이다. 아래층 기단에는 안상(眼象) 무늬를, 위층 기단에는 기둥 모양을 새겨 놓았다. 탑신의 몸돌에도 기둥 모양을 새겼으며, 네 귀퉁이가 살짝 들린 지붕돌은 밑면에 3단의 받침을 두었다. 탑신의 몸돌과 지붕돌이 부분적으로 파괴 되었다. 지붕돌이 백제의 석탑 양식을 보이고 있어, 백제 지역에 세운 고려시대 탑으로 추정된다. 귀신사에서 조금 떨어진 밭가운데에 자리하고 있는데, 밭이 나씨 종중의 소유라 사찰에서 관리 보존할 수…","a":"청도리삼층석탑","c":"문화유산자료","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661808.jpg"},{"q":"○○○ 대웅전에 봉안된, 조선 시대의 ○○○○상이다. 높이가 47cm 정도인 작은 상으로 신체에 비해 머리가 큰 편이다. 민머리의 승려형 보살상으로 둥근 얼굴에 양 볼이 통통하며 얼굴 중앙의 코가 오똑하다. 코 좌우의 두 눈은 가늘고 길며 살짝 다물고 있는 입에는 미소가 감돌아 온화한 인상을 자아낸다. 대의는 양 어깨에 걸쳐진 옷 위로 또 다른 옷자락이 그 일부를 덮고 있는 소위 ‘이중착의’라 부르는 형식이다. 여기에 오른쪽 어깨에 한단 걸쳐진 옷자락과 왼쪽 어깨의 단은 각기 한 번씩 접혀 있다. 또한 왼쪽 어깨에서 흘러내린 자락은 팔뚝에서 Ω형으로 처리되었다. 가슴…","a":"광주극락사석조지장보살좌상","c":"시도유형문화유산","r":"경기도","s":"광주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020022709495300.png"},{"q":"조선 중종의 후궁이며 선조의 할머니인 ○○○○의 신도비(神道碑:조선시대에 왕이나 고관 등의 평생 업적을 기리기 위해 무덤 근처 길가에 세운 비)와 묘소이다. ○○○○는 중종 2년(1507) 9살의 나이에 궁녀로 들어갔으며, 생김새가 단정하고 행동이 정숙하였다. 20세에 중종의 총애를 입게 되어 중종과의 사이에서 영양군과 덕흥대원군, 정신옹주를 두었다. 묘는 처음에 양주 장흥 땅에 있었으나 다음해에 현재의 자리인 동작동 국립묘지 안으로 옮겨졌다. 묘 왼쪽으로는 숙종 9년(1683)에 세운 신도비가 세워져 있다. 비문은 신정이 지었고 글씨는 이정영이 썼다.","a":"창빈 안씨 묘역","c":"시도유형문화유산","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636201.jpg"},{"q":"1898년 중건된 ○○○는 치목, 구조수법 등에 두드러진 특징은 없으나 중앙 마루 후부에 서고를 둔 점과 평면이 전후퇴가 발달한 겹집유형이라는 점과 입면구성에서 장식적 성격이 강하다. 이는 근대 초기 한옥의 경향을 잘 보여주는 것으로 19세기말 ○○지방 재실건축의 특징을 잘 보여준다.","a":"산청 인지재","c":"문화유산자료","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666354.jpg"},{"q":"○○○○○는 조선후기 지리학자인 고산자 김정호가 순조 34년(1834)에 자신이 만든 <청구도>를 27년 후에 증보 수정한 대축척 지도로 분첩절첩식지도첩이다. 형태를 보면, 남북을 120리 간격으로 22층으로 구분하고, 동서를 80리 간격으로 끊어 19판으로 구분했음. 동서방향은 구획된 판을 접어서 연결시켜 1첩으로 만들어 쉽게 볼 수 있도록 했음. 남북으로 동서의 방향을 연결시킨 각 첩을 펼쳐서 순서대로 이어대면 연속된 남북을 볼 수 있게 했음. 지도의 제 1층에는 지도의 제목과 발간연도 및 발간자를 명시하고 본도와는 별도로 서울의 도성도와 경조오부도를 상세하게 그…","a":"대동여지도","c":"시도유형문화유산","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642128.jpg"},{"q":"◦ 보령출신의 조선전기 문신인 김극성(金克成, 1474~1540)의 위패를 봉안한 사당으로 창건연대는 알 수 없으나 처음에는 청라면 장산리에 세웠던 것을 청천저수지의 조성으로 수몰지구가 되자 1960년 후손들이 그의 묘소가 있는 이곳에 옮겼음. ◦ 보령지역에는 김극성의 후손인 광산 김씨들이 유력 성씨를 이루며 오랫동안 세거해 오고 있음. ◦ ○○는 목조 기와집으로 정면 3칸, 측면 2칸의 맞배지붕으로 출입문은 하나이고 토석 혼축으로 담장을 만들었음. ◦ 김극성은 일찍이 사마시(생원․진사시)와 문과에 모두 장원급제하고, 관직에 나가 중종반정에 공을 세워 정국공신(靖國功…","a":"광성부원군 사우","c":"문화유산자료","r":"충청남도","s":"보령시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661131.jpg"},{"q":"완주 ○○○는 867년에 보조국사(普照國師) 체징(體澄)이 창건하였다고 전해지며, 그 뒤 고려 중기에 보조국사 지눌이 다시 고쳐 지었다. ○○○의 ○○○에는 ○○○○상을 주존불(主尊佛)로 모시고, 왼쪽에 보제존자, 그 좌우로 시왕상, 인왕상, 사자상 등이 배치되어 있다. 흙으로 만든 ○○○○은 나무로 만든 연꽃무늬 대좌(臺座) 위에 놓여 있다. 원만한 인상에 눈·코·입 등이 가지런하며, 양 귀는 긴 편이 아니나 큼직하여 근엄하면서도 자비롭다. 옷은 양 어깨를 감싸고 있는데 양 팔에 걸쳐 옆으로 흘러내리고 있다. 오른손은 가슴 높이로 들어 엄지와 중지를 잡고 있으며,…","a":"송광사명부전소조지장보살삼존상및권속상일괄","c":"시도유형문화유산","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2016090818002700.jpg"},{"q":"『동국여지승람』과 『탐라지』 등의 문헌에 나한을 모셨던 절로 기록되어 있는 절터이다. 나한은 아라한의 준말로 인간의 소원을 빨리 성취시켜 주는 복전(福田)이라 하여 일찍부터 신앙의 대상이 되어 왔다. 우리나라에서 규모가 큰 절에는 대부분 영산전을 두어 석가의 10대 제자를 비롯하여 16나한, 500나한 등을 봉안하고 있으며 나한전이나 응진전을 따로 둔 절도 있다. 1990년대의 발굴조사에서 건물지, 부도, 배수시설과 기와조각, 분청사기조각, 백자파편들이 발견되었으며, 1998년부터는 복원 작업이 이루어지고 있다. 이 절을 세운 시기는 알 수 없으나 건물지 북쪽에 있는…","a":"존자암지","c":"시도기념물","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657885.jpg"},{"q":"『○○○○○』과 『불설예수시왕생칠경(佛說預修十王生七經)』이 합본된 1책이다. 이를 수생경(壽生經)이라 하며, 『수생경(壽生經)』은 12지(支) 60갑자(甲子)에 따라 저승의 관 속에 돈과 경전을 시납해야하는 수량을 설명해 놓았다. 『시왕경(十王生)』은 지옥의 고뇌를 면하기 위해 생전에 재공(齊供: 부처님께 공양을 바치는 일)을 할 것을 권한 책이다. 이 책은 예종원년(睿宗;1469)에 신미(信眉), 열학(悅學), 이녕대군(李寧大君), 김수온(金守溫) 등이 개판(開板)한 것을 만력(萬曆: 중국 명나라 신종(神宗) 때의 연호(年號)로 서기(西紀) 1573년부터 1619년…","a":"불설수생경","c":"시도유형문화유산","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638890.jpg"},{"q":"1727년(영조 3) 제작된 ○○○○로 강원특별자치도 내의 탱화로서는 보기드문 18세기 전반의 작품이며, 보존상태가 양호할 뿐만 아니라 단정하고 섬세한 얼굴표현, 유려한 필선과 정교한 문양 등 뛰어난 작품성을 보이고 있다. ○○○○는 천장보살(天藏菩薩)ㆍ지지보살(地持菩薩)ㆍ지장보살(地藏菩薩)과 그 권속을 그린 불화로, 그 도상의 유래가 정확히 밝혀지지 않았으나 지장보살 신앙이 심화되고 확대되어 형성된 것으로 보이며 우리나라에서만 형성되어 발전한 독특한 도상으로 알려져 있다. 천장보살의 권속은 진주(眞珠)ㆍ대진주(大眞株)보살 및 천부중(天部衆)이고, 지지보살의 권속은…","a":"구룡사삼장탱화및복장유물","c":"시도유형문화유산","r":"강원특별자치도","s":"평창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638245.jpg"},{"q":"대전광역시 동구 용운동에 있는 이 산성은 해발 263m로 산 정상부에 만들었으며, 용운동에서 세천동으로 넘어가는‘갈고개’에 있다. 산 정상을 둘러쌓은 형태로 되어 있으며, 둘레는 약 350m이다. 높이 2m의 동쪽 성벽은 네모난 돌로 앞면을 맞추어 쌓았고, 서쪽 성벽은 자연지형을 이용하여 부분적으로만 쌓았다. 성의 평면형태는 남북으로 긴 타원형의 모습을 하고 있으며, 폭 4.8m의 남문터가 남아 있다. 정상부의 가운데에 움푹 파이고 군데군데 돌로 쌓은 듯한 흔적이 보이고 있는데, 이는 저장시설과 관련된 유적으로 짐작된다. 삼국시대의 토기와 기와 조각을 성 안에서 찾아…","a":"갈현성","c":"시도기념물","r":"대전광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645793.jpg"},{"q":"고려 중기의 문신 문극겸(1122∼1189) 선생을 모신 사당이다. 문극겸은 고려 의종(재위 1146∼1170) 때 문과에 급제한 후 여러 관직을 두루 역임하다가 의종 24년(1170) 정중부의 난 때 죽음을 당할뻔 했으나 전에 내시 백선연의 비행을 탄핵한 덕분으로 화를 면하였다. 이후 명종(1170∼1197)이 왕에 오르자 이의방의 추천으로 높은 관직에 올라 많은 문신들을 어려움에서 구하였다. 무신 정권기에 문신으로 장군직을 겸임하여 문무를 겸하는 시초가 되었으며 글씨에도 매우 뛰어났다. 조선 전기에 지어진 것으로 보이는 이 사당의 구조는 앞면 3칸·옆면 1칸으로…","a":"고간원지","c":"시도기념물","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652765.jpg"},{"q":"○○○ 극락전의 주불로 아미타불과 관음보살, 대세지보살의 삼존상이다. 이 불상은 법당이 1733년 화재로 소실된 이후, 1735년부터 1737년까지의 중창불사 때에 법당과 함께 조성된 상이다. 1737년(건륭 2년)에 이루어진 복장 발원문은 다시 불상에 봉안되었는지 조사 때에는 볼 수 없었고, 『寺誌』(충청북도, 1982. P.254)에 수록되어 있어 참고할 수 있다. 그 내용을 보면, 이 불상을 만든 조각장은 演機, 斗策, 守性, 超鵬, 守堅, 廣鵬 등임을 알 수 있다. 아미타불좌상을 본존상으로 하여 관음보살좌상을 좌협시보살로 그리고 대세지보살좌상을 우협시보살로 하…","a":"보은 법주사 복천암 목조아미타여래삼존좌상","c":"시도유형문화유산","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638947.jpg"},{"q":"체화당 안에 있는 건물로 창석 이준(1560∼1635) 선생을 모신 사당이다. 이준 선생은 조선 중기 때 문신으로 임진왜란 때에는 그의 형 월간 이전과 함께 의병을 모아 왜적에 대항했다. 채화는 형제를 의미하는 것으로 이들 형제의 우애를 상징하였다고 한다. ○○○○은 원래 효종 7년(1656) 다른 곳에 지었는데 영조 47년(1771) 월간 선생이 만년에 학문을 수행했던 체화당이 있는 이곳으로 이전하였다. 월간 선생을 모신 사당과 같은 구조로 되어 있으며, 양측 끝에 바람을 막아주는 풍판을 설치하였다.","a":"창석사당(178-2)","c":"문화유산자료","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/0000000001662768.jpg"},{"q":"현재 무량수전에 걸려 있는 이 청동○○는 직경 85.5～85.8cm 크기의 대형이다. 측면에 반원형의 고리 두 개가 붙어 있어 원래는 양쪽 고리로 고정시켰음을 알 수 있다. 전면 중앙에는 돋을새김의 태극원문 당좌가 있다. 당좌의 좌우에는 다섯 개의 도드라진 방형틀이 있으며, 그 안에 양각으로 願文을 새겼다. 당좌의 향우측에는「대황제폐하만만세(大皇帝陛下萬萬歲)」,「순비저하수제년(淳妣邸下壽齊年)」,「영친왕저하수제년(英親王邸下壽齊年)」을, 향좌측에는「황태자전하천천세(皇太子殿下千千歲)」,「황태자비전하수제년(皇太子妣殿下壽齊年)」 이라는 내용을 주조한 것으로 보아, 청동○○의…","a":"양산 통도사 극락암 반자","c":"문화유산자료","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665667.jpg"},{"q":"○○○○은 삼국시대에 초축(初築)된 것으로 판단되며, 내역(來歷), 문화적 영역으로 보아 울산권에 속한다. 이곳은 울산이나 경주로 통하는 중요한 길목으로 산성의 군사적 목적은 충분하였을 것으로 보인다. 현재 성벽은 많이 무너져 있지만 곳곳에 쌓은 상태로 남아 있고, 3개의 고지(高地)에 장대(將臺), 암문(暗門), 통로 등의 시설과 창고와 연못의 위치 확인도 가능하다. 특히 이곳은 신라의 24개의 주요 제장(祭場)이었던 소사(小祀)와 관련된 곳으로도 의미가 있다.","a":"양산우불산성","c":"시도기념물","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657397.jpg"},{"q":"입석사에 있는 탑으로 무너져 있던 것을 세워 둔 것인데, 2기의 석탑 부재가 섞여 있는 듯 하다. 부재들은 두툼하고 네모난 연꽃받침이 2개, 얇은 연꽃받침이 1개, 각 면에 기둥 모양을 새긴 탑신(塔身)의 몸돌이 3개, 네모난 판돌이 4개이다. 연꽃무늬 조각이나 탑신의 몸돌을 다듬은 솜씨로 보아 고려시대 전기의 작품으로 추정된다. 조선 태종(재위 1400∼1418)이 왕위에 오른 후 어린 시절의 스승 운곡 원천석을 자주 불렀으나 응하지 않고 치악산에 들어가 은둔생활을 하며 나타나지 않으니, 그를 생각하며 이 탑을 세우게 되었다는 이야기가 함께 전해 내려온다.","a":"입석사석탑","c":"문화유산자료","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660346.jpg"},{"q":"야산을 뒤로하고 있는 이 집은 마을의 제일 높은 곳에 위치하고 있다. 집을 지은 정확한 연대는 알 수 없지만 약 200년 정도 되었다고 하며, 현재 경주 김씨의 후손이 살고 있다. 전체적으로 H자 모양을 하고 있는 전형적인 겹집으로, 안채와 사랑채·부속건물로 되어 있다. 안채와 사랑채는 지붕 옆면이 여덟 팔(八)자 모양의 화려한 팔작지붕집이고, 부속채는 사람 인(人)자 모양의 단순한 맞배지붕집이다. 안채는 6개의 방이 겹쳐서 배치되었고, 그 오른쪽으로 샛방을 만들어 사랑채와 연결하고 있다. 사랑채 2칸은 외부에 툇마루를 놓아 연결통로로 활용하고 있다. 안채의 왼쪽에는…","a":"양양김택준가옥","c":"시도유형문화유산","r":"강원특별자치도","s":"양양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638090.jpg"},{"q":"임진왜란 때 허물어진 대구토성을 돌로 다시 쌓은 후 이를 기념하고자 세운 비이다. 비는 직사각형으로, 바닥돌 위에 비몸을 세운 간단한 모습이다. 비문에 의하면 성의 둘레는 2,124보(步)이며, 네 개의 문을 만들고 성을 지키기 위한 군량, 전포 등을 갖춘 창고를 두었다. 석성의 공사기간은 6개월이며, 동원된 인원은 78,534명에 달한다. 성이 완성된 뒤에는 여러 장사들을 모아 활쏘기대회를 열어 상을 주었다 한다. 경상도 관찰사였던 민응수가 나라에 건의하여 영조 13년(1737) 대구 남문 밖에 세워두었으며, 민응수가 비문을 짓고, 백상휘가 글씨를 썼다. 광무 10…","a":"영영축성비","c":"시도유형문화유산","r":"대구광역시","s":"수성구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636844.jpg"},{"q":"봉림사가 소장중인 불교전적류 모두 8건으로 각각의 명칭은 묘법연화경권제1, 묘법연화경권제3,4, 묘법연화경권제4~7, 금강반야바라밀경(상), 약사유리광여래본원공덕경, 불정심관세음보살대다라니경, 월인석보제21(상), ○○○○○이다. 구마라습이 지은 묘법연화경 제1권은 목판본으로 간기는 없으나 지질, 판식 등으로 보아 14세기에 간행된 절첩장으로 보인다. 절첩장(折帖裝)은 권자본에 이어 고려 중후기에 많이 만들어진 것으로 서지학적으로 중요한 자료로 취급되고 있다. 본 불경의 경우 인쇄상태가 선명하므로 불경연구, 서지학연구 및 장정연구 등에 아주 귀중한 자료이다.","a":"불설대보부모은중경","c":"시도유형문화유산","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001642623.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다 조선 태종 6년(1406)에 지어졌으며 1864년에 크게 수리했는데『양산교지』에 의하면 별 차이가 없는 것으로 추정된다. 건물의 배치는 공부하는 곳인 명륜당과 동·서재가 앞쪽 평지에 있고 제사지내는 곳인 대성전과 동·서무가 뒤쪽 경사지에 있는 전학후묘의 형태이다. 향교는 본래 건물이 지어진 형식과 규모에 따라 대설위, 중설위, 소설위의 3등급으로 나누어진다. 따라서 이 향교의 출입문인 외삼문이 누각형태로 지어지고 명륜당과 대성전의 규모가 비교적 크다는 점으로 보아 중설위에 해…","a":"양산향교","c":"시도유형문화유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641844.jpg"},{"q":"이 작품은 가선대부 ○○○의 ○○화로 정면향의 전신교의좌상이다. 인물의 육신부는 살색을 바르고 주색으로 윤곽선을 처리하였으며, 육신선을 따라 주색을 바림하여 음영을 표현하였는데, 특히 넓게 펼쳐 바림한 이마와 눈썹이 돋보인다. 상검선은 농묵세선, 하검선은 주색세선으로 처리하고, 눈머리와 눈꼬리에는 담묵으로 바림하였으며, 갈색 눈동자 가운데 농묵을 찍어 동공을 표현하였다. 눈썹·수염의 모근표현은 먼저 담묵으로 펴 바른 뒤 세선의 농묵과 백세선으로 묘사하였고, 귀의 모근표현은 바림 없이 농묵세선으로 그려내어 안면부에 약간의 변화를 주고 있다.","a":"양산 통도사 김경호 초상","c":"시도유형문화유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643050.jpg"},{"q":"청림사의 절터로 전하는 곳에 이 탑이 서 있다. 석탑은 전체의 무게를 받치는 기단(基壇)을 2층으로 쌓고, 3층의 탑신(塔身)을 올렸는데, 원래는 5층이었을 것으로 추정된다. 규모는 비교적 작은 크기이며, 각 부분이 일부 깨져 있다. 기단은 아래층과 윗층의 맨윗돌이 탑신에 비해 지나치게 커보여 비례가 잘 맞지 않는다. 탑신의 각 지붕돌은 얇고 작으며 밑면에 3단의 받침을 두었다. 낙수면은 느린 경사를 이루다 네 귀퉁이에서 살짝 솟아올라 곡선미를 보여준다. 길고 가는 탑신, 지나치게 넓은 기단 등 균형미는 없지만 이 지방만의 독특한 양식을 보여주고 있어, 고려시대의 작…","a":"공주가척리석탑","c":"시도유형문화유산","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639167.jpg"},{"q":"조선 후기의 문신 ○○○를 그린 초상 2점이다. ○○○의 본관은 반남(潘南), 호는 남계(南溪)이다. ○○○의 초상은 관복본과 유복본(儒服本)이 전한다. 관복본은 사모의 높이가 높고, 두 손은 소매 안에 넣은 공수자세를 취하고 정면을 향해 앉은 의좌상이다. 단학 흉배를 달고 금박의 품대를 착용했다. 의자에는 표범가죽이 걸쳐져 있다. 두 발은 발 받침대 위에 팔(八)자형으로 올려놓았다. 17세기 말경의 문인 관복초상화의 전형적인 요소이다. 하지만 ○○○의 관복본은 당시의 원본이 아니라 후대에 베껴 그린 이모본(移模本)이다. 수염은 코 아래의 흰 수염이 턱과 입술 주변의…","a":"남계박세채영정","c":"시도유형문화유산","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637693.jpg"},{"q":"유송(劉宋)시대(420~478) 지엄(智嚴)이 번역한 경전이다. 책의 내용은 부처님이 나열기(羅閱祇)의 기사굴산(耆闍崛山)에 머물 때, 나열기의 왕과 후궁, 태자, 왕녀 등이 부처님이 땅 속에서 솟아 나와 대보연화(大寶蓮花) 위에 앉게 되었는데 그 모습을 본 왕녀 리행(利行)이 부처님에게 그러한 신비한 일을 가능하게 해주는 ○○○○(法華三昧: 법화경을 꾸준히 읽어서 그 묘한 이치를 깨닫는 일)에 대해서 묻고 그에 대해 부처님이 설명하는 형식이다. 부처님은 삼매(三昧: 잡념을 떠나서 오직 하나의 대상에만 정신을 집중하는 경지) 중에서도 ○○○○가 으뜸이라 말하고, ○○…","a":"백지묵서불설법화삼매경","c":"시도유형문화유산","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018101216303900.jpg"},{"q":"김해 김씨 17대 손이 살고 있는 가옥으로 현 소유자의 14대 조부가 세워 지금에 이르고 있으며, 본래 초가였던 것을 60년전 기와로 바꿨다고 한다. 안채와 사랑채로 구분되어 있는데 안채는 양양지방에 남아있는 북방계통의 집이다. 왼쪽으로 넓은 부엌을 배치하고 오른쪽으로 가운데를 갈라 나눈 뒤, 다시 구획하여 6개의 작은 방을 만들었다. 부엌 앞으로 내밀어 지은 외양간은 창고로 개조하였다. 사랑채는 나중에 늘려지은 것으로 보이는데 안채와 달리 큰 방 셋을 마련하고 밖으로 툇마루를 두어 방과 방이 서로 연결되도록 하였다. 대문은 전형적인 솟을대문으로 대문의 왼쪽에 마구간…","a":"양양김성래가옥","c":"문화유산자료","r":"강원특별자치도","s":"양양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660479.jpg"},{"q":"○○○ 초기○○○○○은 ○○시의 중심부를 서쪽에서 동쪽으로 흐르는 전천(箭川)하류의 북쪽 유역에 위치하고 있다. 이 유적은 1996년 관동대학교 박물관이 유적의 남쪽 부분인 ○○항만 확장지역에서 발굴을 실시하여 주거지 4기와 민무늬토기, 두드림무늬토기, 대롱옥, 곱은옥, 유리구슬, 은제귀걸이 등을 수습하였다. 1999년과 2000년에는 강릉대학교 박물관이 ○○○ 중심도로 건설지역과 인근지역에서 초기철기시대 주거지 45기와 9기를 각각 발굴하여 ○○○ 일대가 당시 대규모의 마을이 형성되었던 곳임을 알 수 있게 되었다. 주거지는 대부부 철(凸)자형인 움집이었으며, 벽은…","a":"동해 송정동 철기시대유적","c":"시도기념물","r":"강원특별자치도","s":"동해시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1648952.jpg"},{"q":"이 자료는 운고 김재윤(1808~1893)의 문집 ○○으로 현재 한국국학진흥원에 보관되어 있다. 김재윤은 류치명, 이종상 등과 교류하면서 평생 학문과 후진교육에 힘썼다. 80세에 증직으로 가선대부 동지중추부사 겸 오위장을 제수받았다. 비록 널리 알려진 인물은 아니지만 결판이 없고 조선시대 말 지방에서의 서적간행을 보여주므로 자료적 가치가 높다.","a":"포항 김해김씨 유수공파 소동문중 소장 판목","c":"문화유산자료","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2017122210414000.jpg"},{"q":"여술마을 뒷산 단두리재의 남사면 중턱에 자리하고 있는 백제 후기의 무덤들이다. 발굴조사에 의하면 1기의 앞트기식돌방무덤(횡구식석실분)과 12기의 굴식돌방무덤(횡혈식석실분)이 있는데, 널길(연도)이 달린 굴식(횡혈식) 중에는 긴 벽을 안으로 쌓은 것도 있고, 판석을 이용하여 귀접이하여 짠 형식도 있다. 돌방(석실)의 벽면과 천장, 널길의 틈새는 회같은 물질로 메운 흔적이 있다. 유물은 거의 도굴되어 그 수가 적은데 수습된 유물로는 목짧은 항아리(단경호), 굽다리접시(고배), 심발형토기, 네귀단지, 금귀고리, 은으로 된 꽃모양의 모자장식(은제화형관식) 등이 있다. 특히…","a":"논산육곡리고분군","c":"시도기념물","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652846.jpg"},{"q":"이곳은 조선 ○○○○의 태(胎)를 묻은 석실이다. 왕가에서는 아이가 태어나면 그 태를 소중히 석실에 묻었는데, 이를 태실이라 한다. 원래 완주군 구이면 원덕리 태실 마을 뒷산에 있던 것을 이곳으로 옮겼다. 이 태실은 팔각형 돌 난간 안에 기단석을 놓고 그 위에 둥근 돌을 얹은 다음 지붕돌로 덮었다. 비석은 태실과 함께 옮긴 것으로, ○○○○의 태실임을 알리는 글과 비석의 건립연대를 앞 뒷면에 각각 새겼는데, 건립연대는 선조 11년(1578)이다. 잘 보존된 거북 모양의 받침돌과 뿔 없는 용의 모습을 새긴 머리 돌이 돋보이는 비석이다. 이 태실과 비는 왕실에서 태를 처…","a":"예종대왕태실및비","c":"시도민속문화유산","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658316.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. ○○○○는 태종 7년(1407)에 성동리에 세웠으나 1550년에 옮겼다. 임진왜란 때 불타 없어진 것을 순조 1년(1801)에 현재의 위치에 다시 지었다. 대성전을 중심으로 한 제사공간과 명륜당을 중심으로 하는 배움의 공간이 경사진 곳에 위치하고 있다. 외삼문과 명륜당은 앞쪽에 내삼문과 대성전은 뒤쪽에 일직선으로 놓여 있어 향교의 일반적 배치형식인 전학후묘의 방식을 따르고 있다. 조선시대에는 국가에서 토지·노비·책 등을 지급 받아 학생들을 가르쳤으나, 갑오개혁(1894) 이…","a":"순천향교","c":"시도유형문화유산","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639993.jpg"},{"q":"퇴계 이황 선생의 삼종손 동강 이희정이 세운 서당이다. 조선 광해군 12년(1620)년 세운 것으로 전하는데 건물에 새긴 기록으로는 인조 27년(1649)년경에 지은 것으로 짐작한다. 많은 유학도를 배출하였고 개화기 이후에는 사설학원으로, 한일합병 이후에는 당시 보통학교 2년 과정을 교육하였다. 규모는 앞면 4칸·옆면 2칸이며 지붕은 옆면에서 볼 때 지붕선이 여덟 팔(八)자 모양과 비슷한 팔작지붕이고 앞면은 대청마루를 꾸몄다. 지금은 오동 진성 이씨 종친 모임의 장소로 사용하고 있다.","a":"동강서당","c":"시도유형문화유산","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640882.jpg"},{"q":"향교란 공자를 비롯한 여러 성현께 제사지내고, 지방 백성들의 교육과 교화를 담당했던 국립교육기관을 가리킨다. ○○○○는 조선 세종 5년(1423)에 진사리 현의 서문 밖에 처음 지었다가, 헌종 15년(1849)에 지금의 위치로 옮겨 지었다. 대부분의 향교 건물들이 남쪽을 향하는 것과는 다르게 이 향교는 동쪽을 향하고 있으며, 대성전·명륜당·동재·서재·삼문 등이 남아있다. 중국과 우리나라 유학자들의 위패를 모시고 제사지내는 대성전과 배움공간이었던 강당인 명륜당은 좌우로 나란히 배치되어 있다. 조선시대에는 나라로부터 토지와 책·노비 등을 지급받아 교관 1명이 정원 30명…","a":"정의향교","c":"시도유형문화유산","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643268.jpg"},{"q":"○○○ 선생의 본관은 영천이며, 자는 경부, 호는 대전이며, 세종 11년(1429)에 문과에 급제하여 집현전 박사를 거쳐 사정이 되고 1443년에 사은사의 서장관으로 명나라를 다녀와 주부가 되었음. 1448년에 지대구군사로 재직시 대구에 사창법을 시험적으로 시행했고 문종 때 장령을 지냈음. 정조 때 이조판서에 추증되었고 광주의 대치사 영천의 송곡서원 청안의 향사에 제향되고 있으며 시호는 충장공임. ○○은 총 87매이며 크기는 30×45cm로 박물관 선현유품실에 전시되어 있음.","a":"이보흠 대전실기 목판 및 교지","c":"시도유형문화유산","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642032.jpg"},{"q":"경상남도 함양군 함양읍의 보림사 법당에 모셔진 ○○○○○이다. 원래는 옛 ○○○ 절터 근처에서 발견되어 민가에서 모셨으나 1990년 초에 이곳 보림사로 옮겨왔다. 풍만한 얼굴에 목에는 3줄의 주름인 삼도(三道)가 뚜렷하고, 양 어깨에 걸친 옷자락은 아래까지 굵은 옷주름으로 표현하였다. 손모양은 땅속의 악귀를 물리친다는 의미의 항마촉지인(降魔觸地印)을 하고 있는데, 손가락을 힘주어 펼치고 있는 것이 주목된다. 전체적으로 풍만한 체구인데 반해 키가 작고 어깨가 좁으며 양 발은 어색하게 표현되어 있다. 특히 손모양으로 미루어 보아 밀교(密敎:불교로 해석·설명 할 수 없는…","a":"함양용산사지석조여래입상","c":"시도유형문화유산","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642235.jpg"},{"q":"○○○ 미륵전 오른쪽의 벽면에 봉안되어 있는 이 불상은 두께가 32㎝나 되는 두꺼운 돌에 양각을 한 여래좌상이다. 불신 뒤에는 배(舟) 모양의 광배가 있으며, 현재 시멘트로 된 직사각형의 대좌 위에 안치되어 있다. 민머리 위에 상투 모양의 육계가 사발처럼 솟아있고, 얼굴은 4각형의 평면에 코는 인위적으로 깎아낸 듯 하며 입은 형식화되었다. 목에 3개의 주름인 삼도(三道)가 뚜렷하고 양어깨를 덮은 옷은 옷주름이 섬세하지 못하고 듬성듬성하게 묘사되었다. 손 모양은 오른손은 오른쪽 무릎 가장자리에 대고 있고 왼손은 가슴 위로 올려 보병을 감싸고 있는 듯한 모습을 하고 있다…","a":"영암망월사석불좌상","c":"시도유형문화유산","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640165.jpg"},{"q":"전북특별자치도 고창 선운사에 있는 조선 후기의 범종으로 높이 103㎝, 입 지름 93㎝이고, 종을 매다는 고리인 용뉴를 포함한 전체 높이는 129㎝이다. 용뉴는 2마리 용으로 만들었다. 한국 범종의 특징인 소리의 울림을 도와 준다는 용통이 없는 대신, 종 윗면에 1개의 구멍을 뚫었고, 어깨부분에는 2줄의 선을 돌렸다. 선 안쪽으로 글씨를 새겼는데, 조선 순조 18년(1818)에 다시 만든 것임을 알려준다. 몸체 중앙에는 3개의 돌출된 선을 둘러 위와 아래로 구분해 놓았다. 윗부분에는 꽃과 덩굴로 장식한 4개의 사각형 유곽대를 만들었고, 그 안에 가운데가 돌출된 모양의…","a":"선운사범종","c":"시도유형문화유산","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639406.jpg"},{"q":"경포호의 북쪽 언덕 위에 위치한 정자로 조선 중종(재위 1506∼1544) 때 김습독이 처음 지었다. 그 뒤로 그의 사위 장호를 거쳐 장호의 동생 민의 사위 김몽호에게 넘겨진 후, 지금까지 그의 자손들이 관리하고 있다. 이 부근 대부분의 정자들이 호수가 바라보이는 곳에 있는데 반해, 호수의 동북쪽 깊숙한 산기슭에 자리잡고 있다. 앞면 2칸·옆면 2칸 규모로, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 소박한 모습을 띤 이 정자는 온돌방과 마루방을 두고 방 사이에 분리할 수 있는 분합문을 달아, 필요할 때 하나의 방으로 사용할 수 있게 하였다. 지금도 김몽호의…","a":"강릉호해정","c":"시도유형문화유산","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638007.jpg"},{"q":"배를 타고 들어오는 외적의 침입을 막기 위해 제주도에서는 해안선을 따라가며 성을 쌓았는데 이를 ○○○○이라 한다. 현재 성벽이 남아있는 곳으로는 온평리, 행원리, 한동리. 동복리, 북촌리, 애월리, 고내리 등 14곳이 있다. 김상헌이 지은 『남사록』에는 ○○○○을 일러 ‘탐라의 만리장성’이라 부르고 있다. 현재 남아 있는 ○○○○○ 성벽의 길이는 약 310m이다.","a":"행원환해장성","c":"시도기념물","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657919.jpg"},{"q":"향교는 공자와 여러 성현들께 제사를 지내고, 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 태종 3년(1403) 흑산리에 처음 지었고, 숙종 36년(1710)에 지금 있는 자리로 옮겨 세웠다. ○○○의 규모는 앞면 3칸·옆면 2칸이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 안쪽에는 공자를 비롯한 그 제자와 우리나라 성현들의 위패를 모시고 있다. 조선시대에는 나라에서 토지와 노비·책 등을 지원받아 학생을 가르쳤으나, 지금은 교육 기능은 없어지고 제사 기능만 남아 있다.","a":"임피향교대성전","c":"문화유산자료","r":"전북특별자치도","s":"군산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661705.jpg"},{"q":"○○○로 가는 오솔길 양쪽에 서 있는 한 쌍의 돌장승이다. 사찰 입구에 두는 장승은 절의 경계를 표시하는 역할과 더불어 잡귀의 출입을 막고, 풍수지리적으로 허한 곳의 기운을 불어넣는 등의 기능을 하게 되는데, 이곳의 장승은 사찰의 경계표시·수문장의 역할과 함께 마을 사람들에 의해 그들의 수호신이 되고 있다. 왼쪽에 있는 남장승은 높이 220㎝ 둘레 70㎝의 크기로, 상투를 얹은 듯한 둥근 머리에 관모를 쓰고 있다. 툭 튀어 나온 커다란 눈, 콧구멍이 뚫려있는 주먹코가 특이하며, 콧잔등에는 두 개의 주름을 새겨 놓았고, 꼭 다문 입술 사이로 송곳니 두개가 뻗어 나와 있…","a":"창녕 관룡사 석장승","c":"시도민속문화유산","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659038.jpg"},{"q":"5개의 교각 위에 판석을 얹은 평교로서 〕- - - - -〔 형태를 이루고 동·서 양쪽에 자연석 교대를 쌓았으며, 양쪽의 강가에서 다리로 접근하는 계단을 쌓아 통행토록 하였다. 전체길이 13.5m, 넓이 1.15∼1.38m, 최고높이 약 3.2m이다. 수탕교는 논산과 부여의 경계지역에 위치한 성동 뜰의 넓은 평야지역을 흐르는 석성천을 가로질러 놓여졌던 석교로서 『동국여지승람』 등의 조선시대 지리지에는 ○○○○, 수탕천교, 수탕교 등의 이름으로 기록되어 있으나 현지 주민들은 ‘주창다리’라 부르고 있다. 일제시대까지도 석성 뜰에 농사일을 하러 가는 큰길의 역할을 하였으나…","a":"논산석성수탕석교","c":"문화유산자료","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661567.jpg"},{"q":"경은 이맹전(1392∼1480)의 학덕과 충절을 추모하기 위하여 지은 서원이다. 이맹전은 조선 단종(재위 1452∼1455)을 위하여 수절한 생육신의 한분으로, 수양대군이 어린 단종의 왕위를 탐내자 벼슬을 버리고 고향으로 돌아가 학문을 닦으며 일생을 보냈다. 정조 6년(1782)에 왕명으로 토곡동에 건립된 ○○○○은 고종 5년(1868) 흥선대원군의 서원철폐령으로 인해 노항동으로 옮겨 서당으로 사용되다가, 1976년 영천댐 건설로 인하여 지금의 위치로 옮겨졌다. 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕을 올린 누각건물이다.","a":"용계서원","c":"시도유형문화유산","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640342.jpg"},{"q":"○○○는 경상북도 의성군 비안면 산제1리 화장산 중턱에 위치한 사찰로 1999년 1월 현 주지인 대관(大觀)스님이 불사를 일으키면서, 암자 뒤쪽에 묻혀있는 불상을 발견하고 이를 파내면서 ○○○○○과 대좌, 광배 등을 발견하게 되었다. 사찰은 약 30년전까지 '화장사(花長寺)'로 불려졌지만 대관스님이 중창하면서 사명을 새롭게 '○○○'로 고쳐 부르고 있다. 현재 석등부재와 3층석탑재가 유존하고 있으며, 건물들에 사용된 각종 석재 등이 모아져 있다. 팔각 연화대좌와 주형거신광배(舟形擧身光背)를 갖춘 ○○○○으로 나발로 표현된 두상과 법의는 통견, 가슴부분에 옷매듭이 표현…","a":"만장사석조여래좌상","c":"시도유형문화유산","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641057.jpg"},{"q":"조선 선조 34년(1601)에 문과에 급제하여 호조, 예조정랑 등의 관직을 지낸 옥봉 권위(1552∼1630) 선생이 학문을 익히고, 제자를 양성하기 위해 선조 20년(1587)에 세운 건물이다. 건물의 전체적인 구성은 ㄱ자형으로 왼쪽에는 온돌방이 있고, 오른쪽에는 옥마루를 깔았다. 원래 온돌방은 1칸으로 되어 있었는데 현재는 방 사이에 문틀이 설치되어 있다. 마루 위쪽에는 임진왜란 당시 명나라 장수 주원조와 화답한 시문이 걸려 있으며, 동생인 권오가 쓴 ‘만대헌’이란 현판이 있다.","a":"안동만대헌","c":"시도유형문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640822.jpg"},{"q":"권장(1802∼1874)이 셋째 아들 권숙의 살림집으로 지은 집이다. 조선 철종 1년(1850)에 세웠고 권숙의 호를 따라 ‘○○○○’이라고 부른다. 앞면 6칸·옆면 6칸 규모의 기와집으로 튼 ㅁ자형 구조이다. 안채에는 벽장이 있어 19세기 전통 주택의 변화과정을 보여 주고 있으며, 사랑채는 후학양성을 위한 서당 기능을 갖고 있어 특이하다.","a":"남천고택","c":"문화유산자료","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663144.jpg"},{"q":"취성산 기슭에 있는 절로 신라 진평왕 28년(606)에 혜공이 지었으며 ○○○라 하였다. 고려 공민왕 11년(1362)에 나옹이 다시 지으면서 현재의 이름 ○○○로 부르게 되었다. 그 뒤 조선 인조 19년(1641)과 영조 28년(1762)에 수리하였다. 석가모니를 모신 ○○○은 앞면 3칸·옆면 2칸 규모이며, 지붕은 여덟 팔(八)자 모양인 팔작지붕집이다. 내부는 우물천장과 빗천장으로 되어 있으며, 단청을 하여 전체적으로 매우 화려하게 장식한 조선 중기의 건물이다.","a":"상주사대웅전","c":"시도유형문화유산","r":"전북특별자치도","s":"군산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639422.jpg"},{"q":"내장산에 있는 옛 내장사터로서, 『신증동국여지승람』에 의하면 ‘백련사는 내장사라고도 이르며 내장산에 있다.’라고 하였다. 백련사는 언제 세운 것인지 알 수 없으나 백제 의자왕20년(660)에 유해선사가 세웠다고 한다. 조선시대의 명필인 추사 김정희가 ‘백련(白蓮)’을 ‘벽련사(碧蓮寺)’로 개칭하고, 현판을 써서 걸었으나 한국전쟁 때 소실되었다. 1925년 학명선사가 아미타불을 봉안한 극락보전을 고쳐짓고, 스님들이 생활하던 요사채와, 도량건물인 선원을 세웠으나 역시 한국전쟁 때 소실되었다. 현재 절터에는 연대를 알 수 없는 탑식으로 된 부도가 남아 있으며, 뒷쪽 암벽에…","a":"내장사지","c":"시도기념물","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653572.jpg"},{"q":"○○○은 고려 공민왕 원년(1352)에 해경대사와 월산대사가 세운 절이다. 절 이름은 이 두 스님의 이름에서 따와 ‘○○○’이라 하였다. 조선 명종 11년(1556)에 남원부사가 고쳐 세웠고 영조 23년(1747)에는 거사 양정봉이 고쳐 지었으며, 철종 9년(1858)과 1915년에 다시 고쳐 지어 오늘에 이르고 있다. 현존하는 건물로는 인법당(因法堂)인 본전을 비롯하여 산식각, 요사채 등이 있다. 본전은 ㄱ자형으로 한쪽 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이고, 다른 한쪽은 앞면이 사다리꼴인 우진각지붕으로 꾸몄다. 산신각은 앞면 1칸·옆면 1칸 규…","a":"해월암","c":"문화유산자료","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661639.jpg"},{"q":"이곳은 이름이나 유래가 정확하지 않으나, 출토유물로 보아 백제의 절터로 추정된다. 가람의 배치방식을 살펴보면, 남·북 일직선을 중심으로 하여 중문, 금당, 강당이 있고, 회랑이 중문에서 강당으로 이어졌다. 이 절터에서 납석제 불상편, 기와로 만든 광배조각, 동제 금구편, 동제 불상편과 다양한 토기·기와가 출토되었다. 동남리절터는 탑과 건축이 확인되지 않은 특이한 가람배치를 보이고 있는 절터로, 백제의 불교사원 건축 연구에 중요한 자료가 되고 있다.","a":"동남리사지","c":"시도기념물","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652763.jpg"},{"q":"이 집은 고려말의 큰 학자인 이문정(李文挺)이 고향에 내려와 노년을 보낸 곳이다. 공민왕 6년(1357)에 건립했으며, 임진왜란(1592) 때 불 타 없어진 것을 순조 24년(1824)에 후손들이 다시 세운 것으로, 중앙에 방을 두고 사방에 마루를 깐 정자이다. 벼슬을 그만 두고 내려온 이문정은 이곳에서 성리학을 가르치며 많은 제자와 인재를 양성하는 한편, 상소를 통해 잘못된 나라의 정책을 바로잡는 데도 많은 공을 세웠다. 그후 이문정의 학문과 공적을 기리기 위해 황강서원(黃岡書院)에 그의 위패를 모셔두고 제사 지내고 있다.","a":"문학대","c":"시도기념물","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653378.jpg"},{"q":"신라 김유신(595∼673)장군의 위패를 모신 사당이다. 신라가 삼국을 통일한 후에 변방지역에 말갈족이 자꾸 침입하여 괴롭히자, 명주(지금의 강릉)의 화부산 밑에 장군이 머물면서 적을 퇴치하여 평화를 되찾았다고 한다. 그 후 장군이 세상을 떠나자 백성들이 조선 고종 21년(1884) 화부산의 밑에 사당을 짓고 제사를 지내며 장군을 추모하여 오다가, 1936년 강릉역 확장으로 인하여 지금의 위치로 옮겨졌다. 앞면 3칸·옆면 2칸 규모이며, 지붕 옆면이 사람 인(人)자 모양인 맞배지붕집이다. 경내에는 장군의 생애와 공적이 적힌 ‘순충장열무흥왕화산제기적비(純忠壯烈武興王花山…","a":"화부산사","c":"시도유형문화유산","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637998.jpg"},{"q":"조선 현종 때, 대동법을 주장하여 시행토록 한 김육 선생의 공을 기리기 위해 세운 비이다. 김육(1580∼1658)은 실학사상을 바탕으로 제도개혁을 추진한 조선 후기의 문신이다. 선조 38년(1605) 과거에 급제하여 관직에 나아가 충청도 관찰사, 도승지, 우의정, 좌의정, 영의정 등을 지냈다. 그는 특히 각 지방의 토산물을 바치게 하는 공물법을 폐지하고 쌀과 포로 대신하는 대동법의 실시를 주장하였는데, 이 대동법의 실시로 농민의 부담을 줄이고, 국가의 재정도 나름대로 확보하게 되었다. 비는 거북받침 위에 비몸을 세우고 머릿돌을 얹었다. 머릿돌에는 서로 노려 보는 두…","a":"김육비","c":"문화유산자료","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661294.jpg"},{"q":"갑사는 계룡산 기슭에 있는 삼국시대의 사찰로, 백제시대에 아도화상이 처음 지었다고 전하나 확실하지 않다. 통일신라시대에 의상대사가 크게 다시 지으면서 신라화엄 10찰의 하나가 되었다. 해탈문과 대웅전 사이에 위치하고 있는 강당은 승려들이 법문을 강론하던 건물로 정유재란(1597)으로 불타 없어진 것을 뒤로 다시 지은 것이다. 앞면 3칸·옆면 3칸의 규모이며 지붕의 옆선이 사람 인(人)자 모양인 단순한 맞배지붕집이다. 가운데 부분이 볼록한 배흘림의 기둥 위에 지붕 처마를 받치면서 장식을 겸하는 공포를 짰는데, 공포는 기둥 위와 기둥 사이에도 있는 다포식 건물이다. 단청…","a":"갑사강당","c":"시도유형문화유산","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639159.jpg"},{"q":"나루터신(津神)을 모시고 있는 제당으로, 신라가 가야(伽倻)를 정벌할 때 왕래하던 나루터가 있던 곳에 자리하고 있다. 앞면 1칸·옆면 1칸으로 구성되어 있고, 옆면에서 볼 때 지붕선이 ‘사람인(人)’자 모양과 비슷한 맛배지붕을 올린 목조건축물이다. 내부로 들어서면 제를 올릴 때 사용하는 제상이 있고, 그 위에 머리가 셋인 용을 그려 놓은 그림이 놓여 있다. 현재의 사당은 조선 태종 6년(1406)에 세운 것으로 전하며, 옛 건축물로서 민속신앙을 보여주는 좋은 예가 되고 있다. 지금도 마을사람들은 이곳에서 제사를 지내고 있으며, 여름철 가뭄이 극심할 때에는 기우제를 지…","a":"양산 가야진사","c":"시도민속문화유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659045.jpg"},{"q":"조선 중기 효자 ○○의 묘 앞에 자리하고 있는 비이다. ○○의 본관은 고성으로 어릴 때부터 효심이 지극하여 부모가 병으로 누워있으면 옷을 벗지 않고 웃는 모습을 보이지 않았다고 한다. 또한 대변을 맛보아 병을 짐작하고 밤에는 밖에 나가 하늘에 기도하였다고 한다. 보호각 내 비는 네모 반듯한 받침돌 위로 비몸을 세우고 정교한 조각솜씨가 돋보이는 머릿돌을 올린 형태이다. 머릿돌에는 두 마리 용의 모습이 마치 살아서 꿈틀거리듯 사실적으로 표현되어 있다. 비는 1727년(영조 3)에 세웠다.","a":"진천 이집 묘갈","c":"시도기념물","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650449.jpg"},{"q":"백암사의 연혁에 대한 기록은 남아 있지 않다. 그러나 옛 보원사에는 99개소의 암자가 있었고 100번째 암자인 백암사를 지은 후 모든 암자가 불에 타서 없어졌다는 이야기가 전해지는 것으로 보아 보원사는 가장 융성하던 시기인 고려 전기에 세웠다가 소멸된 것으로 짐작한다. 현재 이곳에는 약 2000여 평의 절터와 세울 당시 쌓은 것으로 보이는 석축이 부분적으로 남아 있다. 또한 석등과 석탑의 일부분이 남아 있는데 그 제작 기법과 모양을 보아 고려시대에 제작된 것으로 추정한다.","a":"백암사지","c":"문화유산자료","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661260.jpg"},{"q":"조선 명종 1년(1546) 부장공 김언광이 묘를 관리하고 제사를 모시던 재사로 세웠으며 숙종 13년(1687) 고쳐 세워 오늘에 이르고 있다. 재실 배치는 전체적으로 ㅁ자형 모습이며, 재사 건축에서 벗어나 절 암자와 유사한 구성법을 보이고 있다. ○○○을 중심으로 오른쪽 건물은 재사 참석자들이 사용하는 공간이고, 왼쪽 건물은 대문에 붙어 있는 집채이다. 이곳은 전체적으로 절 건물에 쓰이는 재료로 사용한 듯한 암자형 재실로 오래된 건축 기법들을 잘 유지하고 있다.","a":"영주 평은리 양지암","c":"시도민속문화유산","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658927.jpg"},{"q":"만회 권득기와 그의 아들 탄옹 권시를 추모하기 위해 세운 서원이다. 권득기는 41세 때 문과에 급제하여 예조좌랑을 지냈으며, 정세가 어지러워지자 벼슬을 버리고 도학을 공부하였다고 한다. 권시도 학문이 뛰어나 대군사부·한성부좌윤 등에 임명되었으나, 벼슬을 버리고 고향인 이곳에서 학문에 힘썼다. 이 서원은 조선 숙종 19년(1693)에 유림들이 뜻을 모아 세운 것으로，숙종 37년(1711)에 나라에서 내린 현판을 받아 사액서원이 되었다. 사당 3칸·묘문 3칸·강당 4칸·서재 3칸·남재 4칸·전사청 3칸 등 모두 23칸 규모를 가진 서원이었다고 하는데, 흥선대원군의 서원…","a":"도산서원","c":"문화유산자료","r":"대전광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659693.jpg"},{"q":"○○○의 금강문으로 누각을 겸한 일종의 다리건물이다. 계곡의 물과 주위 경관이 아름다워, 미인의 가볍고 우아한 걸음걸이를 의미하는 ‘능파(凌波)’라 이름하였다. 이 다리를 건너면 세속의 번뇌를 던져버리고 부처님의 세계로 진입함을 상징한다. 통일신라 문성왕 12년(850)에 혜철선사가 처음 지었고, 고려 태조 24년(941) 광자대사가 수리하였다고 한다. 그 뒤 파손되었던 것을 조선 영조 43년(1767)에 다시 지었다. 다리를 건너는 쪽에서 보았을 때 앞면 1칸·옆면 3칸의 규모이며, 지붕 옆면이 사람 인(人)자 모양인 간결한 맞배지붕이다. 계곡의 양쪽에 바위를 이용…","a":"태안사능파각","c":"시도유형문화유산","r":"전남광주통합특별시","s":"곡성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2026011215182692.jpg"},{"q":"조선 중기의 문신이며 의병장이었던 ○○○ 선생의 ○○화이다. ○○○는 선조 24년(1591) 문과에 급제하고 이듬해 임진왜란이 일어나자 창녕에서 의병을 모집하여 곽재우 휘하에 들어가 활약했으며 그후 광주목사 등을 지내었다. ○○화는 두 손을 소매안에 모으고, 약간 왼쪽을 향한 채 서 있는 전신상으로, 녹색의 명주 바탕에 채색하여 그렸다. 머리에는 상투가 보이고 길게 늘어진 수염과 가늘게 올라간 눈이 인상적이다. 분홍색 겉옷의 옷자락 밑으로는 팔(八)자 모양으로 벌린 가죽신의 끝부분이 보인다.","a":"성안의 초상","c":"문화유산자료","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664464.jpg"},{"q":"강원특별자치도 원주시 ○○○에 있는 ○○○○으로 광배(光背)와 대좌(臺座)를 갖추었지만 손과 얼굴이 깨져 있다. 어깨는 자연스럽고 둥글게 처리되었고, 가슴은 비교적 넓으며 앉아있는 자세도 안정되어 균형잡힌 모습을 보여준다. 팔·다리 등의 신체표현에 적당한 양감이 있어 통일신라 석불상의 특징을 잘 계승하고 있음을 알 수 있다. 양 어깨를 감싸고 있는 옷은 평행 주름모양으로 통일신라 후기에 유행하던 특징과 비슷하지만 다소 형식화 되어가는 시대적 변화를 확인할 수 있다. 배(舟)모양의 광배에는 덩쿨무늬와 테두리에 불꽃무늬가 화려하게 조각되었다. 불상이 앉아 있는 대좌는 3…","a":"원주봉산동석불좌상","c":"시도유형문화유산","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638024.jpg"},{"q":"○○○에 보존되어 있는 ○○○○○인데, 탱화란 천이나 종이에 그림을 그려 액자나 족자 형태로 만들어지는 불화를 말한다. 비단 바탕에 채색하여 그린 이 탱화는, 상하로 2폭을 연결하여 조성하였다. 화면 중앙의 아미타좌상을 비롯하여 그 왼쪽에 관음보살상, 오른쪽에 대세지보살상이 앉아 있으며 위쪽으로는 보살상 2구와 아난·가섭상이 배치되어 있다. 화면의 아래쪽 부분 좌우측에 있는 기록에 의하면 이 불화는 ‘성상즉위22년병신’, 즉 1896년에 조성된 것임을 알 수 있다. 조선시대 불교회화사 연구에 중요한 학술적 자료이다.","a":"양산 통도사 성상22년명 아미타후불탱","c":"문화유산자료","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664820.jpg"},{"q":"읍성이란 군이나 현의 주민을 보호하고, 군사적·행정적인 기능을 함께하는 성을 말한다. 동래읍성은 마안산을 거쳐 구릉지와 동래 시가지의 평탄한 지역을 포함하여 쌓은 읍성으로, 고려말에서 조선초에 만들어진 것으로 보인다. 『고려사』에 의하면 고려 현종 12년(1021)에 동래읍성을 수리하였으며, 그 뒤 우왕 13년(1387)에 왜구를 막기 위해 동래성을 크게 고쳐 쌓아 둘레가 3090자, 높이 13자라고 전한다. 왜적 방어의 제1관문인 이 성은 조선시대에 임진왜란이 일어나면서 부산 진성과 함께 왜적의 1차 공격목표가 되어 치열한 전투가 벌어졌던 곳이다. 임진왜란 이후 방…","a":"동래읍성지","c":"시도기념물","r":"부산광역시","s":"동래구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1644924.jpg"},{"q":"서울특별시 구로구 고척 2동에 있는 함양 여씨의 묘역이다. 함양 여씨의 시조는 중국 내주 사람인 여어매(呂御梅)이며, 본관은 경상남도 함양이다. 여어매는 원래 당나라 사람으로 한림학사를 역임하였는데, 황소의 난을 피하여 통일신라 헌강왕 3년(877) 신라에 귀화하였다. 경상북도 성주군 벽진면에 정착하여 살았고, 고려시대에는 공조전서를 지내었다. 묘역에는 함양 여씨의 선조인 숭의랑공의 묘가 윗쪽에 있고 그 아래쪽에 그의 부인의 묘가 있다. 숭의랑공은 조선 전기의 인물로 태종 때에 호조좌랑, 호조참판 등을 역임하였다. 세종 3년(1421)에 세상을 떠났으며, 세종 10년…","a":"여계묘역","c":"시도유형문화유산","r":"서울특별시","s":"구로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636256.jpg"},{"q":"대웅전 삼존불 사이 앞쪽에 있는 나무로 만든 3점의 패(牌)이다. 전체적인 만든 방법과 형태는 같으나 부분적으로는 차이를 보인다. 그중 하나는 높이 2.28m로 앞면에 임금의 만수무강을 기원하는 글씨가 있고, 뒷면에는 조선 16대 왕인 인조 때 조성된 것이란 제작연대가 있다. 다른 2점은 높이가 2.08m로 같으며, 뒷면에 정조 16년(1792)에 수리하였음을 검은 글씨로 기록하고 있다. 일반적으로 불·보살의 명칭을 적은 다른 위패들과는 달리 왕, 왕비, 세자로 조성한 2m가 넘는 대작이다. 여러 장의 목판을 엮어서 만든 것으로 구름과 용을 뚫어새긴 것이 특징이다.…","a":"송광사목조삼전패","c":"시도유형문화유산","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639649.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 숙종 3년(1677)에 처음 지었으나 모든 건물들이 조선 후기 건축 양식으로 되어 있다. 현재 남아 있는 건물로는 대성전과 명륜당, 동재, 서재, 신문(내삼문) 등이다. 대성전은 앞면 5칸·옆면 3칸 규모로，지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕으로 꾸몄다. 안쪽에는 공자를 비롯하여 중국과 우리나라 성현의 위패를 모시고 있다. 학생들이 모여 공부하는 명륜당은 앞면 5칸·옆면 2칸 규모로 이루어져 있다. 명륜당의 현판은 고려말 명필인 한수(韓修)…","a":"영양향교","c":"문화유산자료","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662499.jpg"},{"q":"절에서 공양할 때 밥통으로 사용하던 식기의 일종으로, 높이 21㎝, 아가리 지름 44.5㎝, 밑 지름 27.5㎝이다. 그릇 몸통 양옆에는 2개의 손잡이 고리가 달려있으며, 그릇받침에는 명문을 새겨 놓았다. 높이와 아가리 지름의 비례가 전체적으로 안정감을 준다. 그릇의 바깥부분은 두 부분으로 도드리지게 처리해 몸통을 3등분하였다. 받침에 ‘도광 2(5?)년’이라는 명문이 새겨 있어, 조선 순조 때인 1822년 또는 1825년에 만들어진 것으로 보인다. 조선 후기 불교의식의 단면을 살펴볼 수 있는 좋은 자료이다.","a":"범어사 유제 대발","c":"문화유산자료","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659348.jpg"},{"q":"남평 문씨의 종가로 약 300년 전에 지은 건물이며 안동지방의 전형적인 평면구성을 취하고 있다. 지금 있는 건물은 임동면 ○○○에 있던 것을 임하댐 건설로 1988년 옮긴 것이다. 앞면 3칸·옆면 2칸으로 중앙 앞쪽에 흙바닥을 그대로 둔 봉당이 있고 그 뒤에 마루가 놓여있다. 마루 왼쪽에 안방, 오른쪽에 상방이 있다. 봉당의 왼쪽에는 부엌, 오른쪽에는 외양간과 그 위에 다락이 설치되어 있다. 벽은 온돌방만 흙으로 하고, 나머지는 널판으로 되었다. 지붕은 기와로 덮었으며 집안의 연기가 빠져나갈 수 있는 ○○○○이라 부르는 구멍을 내었다. ○○○○○의 원형을 유지한 희귀…","a":"안동마령동기와까치구멍집","c":"시도민속문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658748.jpg"},{"q":"충청남도 공주에 있는 갑사 뒷산 사자암에 약사여래입상, 갑사 부도와 같이 있던 것을 갑사 진해당(振海堂)에 옮겨 보관하고 있다. 얼굴은 마멸이 심해 분명하지 않으나 코가 오똑하고 눈은 감은 듯 하다. 옷은 양 어깨를 감싸고 있는데, 한 자락이 오른손 손목을 거쳐 등쪽으로 넘겨졌다. 하체에 걸쳐진 옷은 선이 부드럽고 얇아서 신체의 굴곡을 충실히 표현하고 있다. 가슴부분의 오른손은 뭔가 들고 있는 듯 하나 분명하지 않고, 왼손은 팔을 내려 무릎 부분에서 목이 긴 병을 들고 있다. 전체적으로 잘록한 허리, 어깨 등 조각수법이 세련된 백제시대의 작품으로 보인다.","a":"갑사석조보살입상","c":"시도유형문화유산","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639088.jpg"},{"q":"○○는 처가를 따라 양동마을에 정착하여 세거하였고, 세조5년(1459)에 식년문과에 급제한 후 주부·병조좌랑을 역임했으며, 이시애의 난 때 종사관으로 출정하여 적개공신 2등에 책록되었다. 이후 안동부사·진주목사를 역임하였다. ○○와 ○○○의 건립연대가 오래되었을 뿐만 아니라 ○○의 찬자인 김종직, 서자(書者) 손중돈이 조선초기 사림파를 대표하는 인사들이라는 점에서 역사적 의미가 크다.","a":"양민공 손소 및 정부인 류씨의 묘비, 석인상","c":"시도유형문화유산","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641164.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 조선 세종(재위 1418∼1450) 때 처음 세워지고 그 후 여러 차례 다시 짓고 보수하였으며, 지금 남아있는 건물들은 18세기 이후에 지은 것이다. 명륜당은 학생들이 모여서 공부하는 강당으로 고종 8년(1871) 대원군의 서원철폐령으로 문을 닫은 상현서원의 강당을 옮겨지은 것이다. 앞면 5칸·옆면 2칸의 규모이며, 지붕 옆면이 사람 인(人)자 모양인 단순한 맞배지붕집이다. 사당인 대성전에는 공자를 비롯하여 중국과 우리나라 유학자의 위패가 모셔져 있다. 조선시대에는 나라로부…","a":"보은향교","c":"시도유형문화유산","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638535.jpg"},{"q":"1920년에 왕궁 저수지의 둑이 완성된 후 이를 기념하기 위해서 송병우가 세운 누각이다. 지붕의 옆면이 여덟 팔(八)자 모양인 팔작지붕집으로 정자로서는 규모가 큰 것에 속한다. 정자 주변의 연못에는 중국에서 처음으로 흰색 연꽃을 갖다 심었다고 전한다.","a":"함벽정","c":"시도유형문화유산","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639559.jpg"},{"q":"경상북도 성주군 가야산 정상에서 동남쪽에 위치한 용기골 동편에 있는 ○○○○○이다. 화강암의 평평한 돌을 배(舟)모양으로 다듬어 광배(光背)로 삼고, 가운데 부분에 ○○○○을 돋을새김하였다. 광배 위에는 평평한 큰 돌이 지붕처럼 덮여있어 감실(龕室:불상을 모셔두는 방) 역할을 하고 있다. 머리에는 상투 모양의 머리묶음이 두툼하게 표현되었으며, 풍만한 얼굴에는 엷은 미소를 머금고 있다. 풍만한 어깨를 감싸고 있는 두꺼운 옷은 목부분에서 U자형으로 깊숙히 조각되었으며, 오른쪽 소매는 접어 올린 듯이 표현되었다. 하반신의 치마는 조각수법이 매우 거칠고, 마멸이 심해 뚜렷한…","a":"성주백운리마애여래입상","c":"문화유산자료","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663217.jpg"},{"q":"○○○○ 내에 서 있는 비로, 조선 단종·세조 때의 선비인 엄흥도의 충절을 기리고 있다. 엄흥도는 어린 단종이 세조에 의해 영월에 유배되었을 때에 그 지역의 호장을 지내었던 자로, 단종이 죽임을 당하자 그 시신을 수습하여 지금의 장릉자리에 몰래 장사지낸 후 세조의 보복이 두려워 종적을 감추어 버렸다. 이 후 숙종은 그 충의를 거룩히 여겨 ○○○의를 증직하였고, 영조는 그를 위한 정려문을 내려주었으며 훗날 공조판서에 다시 증직하였다. 정조 23년(1799) 울산의 후손들이 원강사를 세워 그를 위한 제사를 지내었다가, 사람들의 논의에 따라 순조 17년(1817) 원강사원…","a":"증공조참판엄공원강서원비","c":"문화유산자료","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659791.jpg"},{"q":"화면 하단 중앙에 위태천을 중심으로 12신장상을 배치하고, 상단에는 범천과 제석천을 좌우측에 배치하고, 그 주위에 천녀·천동과 제권속들이 둘러싼 모습이다. 색채는 주로 백색·적색외에 녹색과 청색을 사용하였다. 위태천·범천·제석천의 육신부는 백색에 붉은색이 약간 감도는 분홍색을 바르고, 부분적으로 담묵을 사용하여 음영을 표현하였으며, 윤곽은 먹선으로 처리하였다. 위태천은 갑옷을 입고 날개 달린 투구를 썼으며, 갑옷위에 표범무늬의 털가죽을 걸치고 있다. 가죽표현은 담갈색을 바른 뒤 담묵으로 범피문을 표현하고 얇은 백색선과 흑색선으로 가장자리를 둘렀다. 범천·제석천상은 천…","a":"남해 용문사 건양2년명 신중탱","c":"문화유산자료","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665138.jpg"},{"q":"한성기 백제의 지방 마을 유적으로 북쪽 배후의 왕방산 줄기와 남쪽의 한탄강 지류인 ○○천 사이 충적지에 위치한다. 세 차례의 시굴 및 발굴 조사에서 집자리 27기, 작은 구덩이 89기, 도랑 11기, 지상식 건물지 2기 등이 조사되었다. 집자리는 대부분 남쪽에 돌출된 출입 시설이 있는 ‘凸’ 또는 ‘呂’ 모양의 반움집이지만, 거주 공간은 육각형 모습이다. 규모는 다양한데, 경기도박물관이 조사한 2호 집자리는 길이가 23.6m에 이르며, 기와와 철제 못과 같은 건축 부재가 사용된 점에서 이 마을의 최상위 계층 인물이 거주했던 것으로 보인다. 집자리 내부에서는 난방 시설…","a":"포천 자작리 유적지","c":"시도기념물","r":"경기도","s":"포천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647527.jpg"},{"q":"○○○ 대웅전에 소장되어 있는 목 아미타○○○은 광배와 대좌가 없어졌지만 불신(佛身)은 완전한 형태로 남아있는 17세기 중엽의 대표적인 불상으로 평가된다. 머리는 둥근 복발형인데 육계(肉髻)가 표현되지 않았고 정상에 둥글고 낮은 정상계주(頂上髻珠)와 머리중심에 긴 반달형 중심계주(中心髻珠)가 있으며, 나발(螺髮)은 큼직한데 성글게 붙여져 있다. 얼굴은 전체적으로 궁글려 계란형에 가까운 모습이다. 눈썹 사이에 작은 백호(白毫)가 있고, 눈은 도톰하며 입이 작으면서 인중이 돌출하였고, 코는 눈썹 사이에서 돌출하여 17세기의 특징을 잘 보여주고 있다. 상체는 다소 세장한…","a":"환희사 목불좌상(아미타불)","c":"시도유형문화유산","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2593343.png"},{"q":"김해 ○○○○○ 고분은 1997년 부경대 박물관에 의해 발굴 조사되었는데 1기의 봉토분 좌편에 출입구가 있는 횡혈식의 주석실과 3기의 부속석곽이 함께 조성된 것으로 현실은 2차에 걸처 추가장이 이루어졌음이 밟혀졌다. 도굴되었지만 토기류, 철기류, 금동제품, 청동기류 등 58점의 유물이 출토되어 6C 후반 금관가야 멸망후의 이 지역묘제 및 유물편연구에 좋은 자료가 되었다. 원래 사적 75호인 ○○○ 고분군의 일부였으나 99. 8. 3일 도 기념물로 변경 지정되었다.","a":"김해구산동백운대고분","c":"시도기념물","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656818.jpg"},{"q":"전남 장흥군 유치면 봉덕리에 위치한 ○○○의 ○○○○에 들어 있던 유물이다. 고려 중기 지눌이 조계산에 수선사를 세우고 선(禪)사상을 일으켰을 때 처음 불교에 입문한 사람과 수선사의 기강을 위해 저술한 것이다. 불교 수행에 있어 핵심내용을 뽑아 우리나라에 맞게 저술한 것으로, 불교 전문강원의 교재로 채택되었으며 승려는 물론 일반 신도까지 배워야 할 기본서가 되었다. 이 책 뒤에 『몽산화상법어약록』과 『훈몽요초』가 함께 묶여 있는데, 한자구결이 본문에 있어 학술적 가치가 크다. 『훈몽요초』는 지금까지 알려진 것보다 시기가 상당히 앞서 간행된 것으로 밝혀져 주목된다. 지…","a":"보림사사천왕상복장계초심학인문","c":"시도유형문화유산","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020022811420800.jpg"},{"q":"선돌은 길쭉한 자연석이나 커다란 돌을 일부만 다듬어 똑바로 세운 기념물 또는 신앙대상물을 말한다. 입석리 마을 입구에 서 있는 이 선돌은 마을의 당산으로 수호신 기능을 하여, 재앙을 막아주고 풍년을 기원하는 대상이 되고 있다. 사각기둥 모양의 자연석으로 높이 210㎝, 너비 62㎝, 두께 40㎝의 크기이다. 윗부분은 마모가 심하여 확실치 않으나 사람 얼굴 형상과 같은 것이 표현되어 있다. 이곳에서는 매년 음력 정월보름에 당산제를 지낸 뒤 남녀로 편을 나누어 줄다리기를 하는데, 여자편이 이겨야 풍년이 든다고 믿고 있다. 줄다리기가 끝난 뒤에는 사용한 동아줄을 선돌에 감…","a":"월촌입석","c":"시도민속문화유산","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658294.jpg"},{"q":"경상남도 ○○군 설천면 진목리 ○○○의 정상에 지어진 산성으로, 산꼭대기를 빙둘러 돌로 쌓았다. 성의 둘레는 1.5㎞, 성벽의 높이는 5∼6m이고 윗부분의 폭은 2.4m인데, 성벽의 바깥쪽은 깬돌을 이용하여 겹으로 쌓아 올리고, 안쪽은 자갈과 흙을 섞어서 채워 성벽을 다졌다. 성벽의 둘레에는 네모꼴의 망대(적의 동정을 살피기 위하여 세운 높은 대)가 있었던 흔적이 있다. 성 안의 중앙에는 건물터와 연못터가 있으며, 천씨(千氏) 성을 가진 장군과 일곱 시녀 사이에 얽힌 전설이 있는 제사터가 있다. 성의 동남쪽과 북쪽에 성문이 있었던 듯한데, 이중 동남쪽의 문이 정문으로…","a":"남해 대국산성","c":"시도기념물","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654792.jpg"},{"q":"영남학파의 거두인 존재 이휘일(1619∼1672)의 유업을 기리기 위하여 세운 서당이다. 이휘일은 조선 후기의 학자이다. 일찍부터 성리학을 깊이 연구하여 사리를 깨달아 독립된 성리학의 한 유파를 이루었다. 또한 예를 존중하여 상제대요와 절목을 정리하여 예로부터 생활화된 폐단을 시정하였다. 저서로는 『존재집』, 『구인략』, 『홍범연의』가 있다. ○○○○은 영조 33년(1757) 지방 유림들이 세웠다. 세월이 흐르는 동안 여러 차례에 걸쳐 수리·보수하였으며, 최근에는 임하댐 건설로 1989년 지금 있는 자리에 옮겨 세웠다. 바위 위에 동남향으로 자리잡은 2층 누각의 건물…","a":"백호서당","c":"문화유산자료","r":"경상북도","s":"청송군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662775.jpg"},{"q":"이 성책은 사찰의 토지대장으로, ○○○ 소유토지대장 중 일부분이지만 여기에서 250년전의 조계종사찰 재정을 알 수 있을 뿐만 아니라 ○○○의 토지재산을 알 수 있다. 크기는 세로 66㎝, 가로 46㎝이며, 전후 표지를 합해 19매이다. 내용을 보면 ○○○의 본사(本寺)와 여러 소속암자의 토지 및 불양답(佛養畓:사찰에 기증한 토지)을 구분하고, 전답의 소재지·명칭·위치·형태·등급·경작인·조세 등을 표시하고 있다. 그리고 각 전답에는 이 절의 소유토지의 기장번호가 있다. 이것은 250년전에 시행된 토지대장의 정리·측량법· 세제·소유자와 경작권·경작권의 실제 등을 파악할…","a":"실상사위토개량성책","c":"시도유형문화유산","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639492.jpg"},{"q":"○○○란 왕이나 고관 등의 평생업적을 기록하여 그의 묘 남동쪽에 세워두는 것으로, 이 비는 조선 중기의 무신인 ○○○을 기리고 있다. ○○○은 어려서부터 용모가 뛰어나고 몸집도 커서 23세 때인 선조 36년(1603) 무과에 급제하였다. 인조 2년(1624) 이괄의 난이 일어났을 때에는 왕을 모시고 공주로 피난을 갔는데 그 공로로 종2품 가선대부가 되어 영원군에 책봉되었다. 병자호란 때에 왕이 남한산성으로 옮기자 어가를 모시었고, 서쪽 성문을 지키는 수문장이 되었다. 난이 끝난 후에는 여러 관직을 거쳐 지중추부사에 까지 올랐으며, 효종 6년(1655) 76세로 생을…","a":"고홍건신도비","c":"문화유산자료","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661741.jpg"},{"q":"○○○의 뒷모실 마을 뒷쪽에 남북으로 활처럼 휘어져 뻗어내린 구릉 정상부에 위치한 무덤들이다. 모두 15기의 무덤이 분포하고 있는데, 9호 무덤의 봉분 형태가 피라미드형으로 봉분 자락에 도랑을 둘렀다. 봉분 안에는 널무덤(토광묘) 3기와 독무덤(옹관묘) 4기가 확인되었는데, 독무덤은 이음식, 합개식, 단옹식이 사용되고 있다. 유물은 토기류, 철조각, 옥종류가 수습되었고, 봉분 바닥에서는 무덤이 만들어지기 전에 지어진, 원삼국시대의 주거지 4기가 확인되었다. 유물과 무덤 축조방법으로 보아, 이 무덤은 4세기 전반에서 후반사이에 형성된 것으로 생각된다. ○○○무덤들은 동…","a":"영암신연리고분군","c":"문화유산자료","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662093.jpg"},{"q":"선사시대의 유적으로, 제주도의 화산활동에 의해 생긴 동굴을 그대로 이용한 대표적인 집자리이다. 이곳에서는 ‘고두기엉덕’이라 부르는데, 엉덕이란 바위그늘 밑을 뜻하는 말로, 그늘부분이 생활공간이 된 것을 의미한다. 바위밑 그늘은 앞면의 너비가 11m, 높이 2.5m, 길이 3m로, 햇빛이 잘드는 정남향에 입구를 두었으며, 동굴 안으로 들어가면 커다란 바위로 이루어진 평탄한 곳이 펼쳐져 있고, 잡석을 깔아 고르게 만든 부분이 있는데, 잡석을 깔아놓은 곳에서 목탄과 토기, 제분용석기, 조개껍질, 나무열매 등을 발견하였다. 이곳에서는 여러 시기의 문화층이 발견되었다. 가장…","a":"북촌리선사주거지유적","c":"시도기념물","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657884.jpg"},{"q":"임진왜란 때 진주성 전투에서 공을 세우고 순절한 허일과, 그의 셋째 아들 허곤, 6촌 동생 허경의 위패를 모신 사당이다. 허일은 무예가 뛰어나 무과에 급제하여 감찰을 역임하였고 임진왜란 때(1592)는 삼포수방사겸웅천현감으로 재직 중 충무공 이순신을 도와 남해 등지에서 공을 세웠다. 그 뒤 충의공 최경회와 함께 진주성을 사수하다가 이듬해 진주성이 함락되면서 순절하였다. 허곤은 임진왜란 때 아버지를 따라 싸우다 한산전투에서 순절하였고 허경은 이충무공 아래서 전공을 세웠다. 임진왜란 중인 선조 26년(1593)에 처음 세웠다고 하는데 정확한 위치는 알 수 없고 고종 5년…","a":"충열사","c":"문화유산자료","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661900.jpg"},{"q":"○○○는 횃불과 연기를 이용하여 급한 소식을 전하던 옛날의 통신수단을 말한다. 높은 산에 올라가서 불을 피워 낮에는 연기로 밤에는 불빛으로 신호를 보냈다. 사화랑 봉수는 경상도 동래에서 서울 목멱산(지금의 남산) 중앙봉수에 이르는 봉화선로의 중간노선을 연결하는 간봉(間烽)이다. 여기서는 동쪽 가덕도 천성 연대에서 봉수를 받아 장복산 봉수와 ○○의 여음포 봉수에 알렸다. 『웅천읍지』를 비롯한 지리지에 따르면 사화랑봉수에는 임무를 수행하는 요원으로 100명이 있었다고 한다. 전국의 봉수제도를 폐지하던 고종 31년(1894)에 없어졌다.","a":"창원 사화랑산 봉수대","c":"시도기념물","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656350.jpg"},{"q":"조선후기 청화백자 항아리이다. 구연은 곧고 높으며 어깨가 팽창되다가 저부로 가면서 좁아들다가 굽 부분에서 약간 벌어진 형태이다. 유색은 담회청색을 띠며 전체적으로 용융이 잘되어 광택이 좋다. 구연부 바깥쪽과 구연부와 어깨의 경계부위에는 각각 1줄의 청화선을 둘렀다. 어깨에는 여의두문을 돌렸으며 그 밖의 장식문양은 없다. 동체 전면에는 앞뒤로 한 쪽에는 파초가, 다른 한쪽에는 대나무가 심겨진 장탁자 위에 놓인 화분을 그렸으며, ○○○ 사이에는 매화문을 그렸다. 청화는 농담을 이용하여 변화 있게 채색하였다. 굽은 안쪽을 깊고 평평하게 깎은 안굽형으로, 전면을 시유하고 모…","a":"백자청화화분문호","c":"시도유형문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636469.jpg"},{"q":"1919년 지은 집으로 안채와 사랑채가 ㅁ자 평면을 이루고 있고 마당 건너편에는 ㄱ자형 문간채가 있다. 안채는 앞·뒤 2열로 조성된 겹집인데 앞쪽에는 안방을 중심으로 부엌과 건넌방을 배치하였고, 뒤쪽에는 골방과 뒷방, 상방을 두었다. 지금은 앞쪽 마루방을 온돌방으로 개조하였으며 안방과 건넌방을 확장하여 안방으로 사용하고 있다. 사랑채에는 앞쪽과 옆쪽에 툇마루를 두었다.","a":"강릉 회계고택","c":"문화유산자료","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018122714160600.jpg"},{"q":"계초심학입문(誡初心學入文), 묘법연화경 권제1(妙法蓮華經 卷第一) 등 10책 모두 370년이 넘은 고전적(古典籍)이며, 불교사의 희귀 자료이다. 2004년 성주사 안심료(安心寮)에 임시 봉안된 불상을 지장전 건립과 함께 이전하여 개금(改金) 및 개채(改彩)하면서 지장보살불의 복장유물을 확인한 결과 지장보살과 시왕을 비롯한 권속일체가 1681년 신조된 사실과 조성한 화원 및 시주자 명단이 열거되어 있으며, 당시 성주사의 명칭이 웅신사(熊神寺, 곰절) 임을 알 수 있다.","a":"예수천왕통의","c":"시도유형문화유산","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018102913431300.JPG"},{"q":"정송강 유적은 조선 중기 학자이자 정치가인 정철(1536∼1593)이 성산에 와 있을 때 머물렀던 곳으로, ○○○과 식영정으로 구성되어 있다. 정철은 호가 송강으로, 명종 16년(1561) 27세의 나이로 과거에 급제하였다. 그 뒤로 많은 벼슬을 지내다가 정권다툼으로 벼슬을 그만두고 고향인 성산에 내려와 『성산별곡』, 『사미인곡』 등의 문학작품을 지었다. ○○○은 앞면 2칸·옆면 3칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다. 앞면에는 ‘○○○’이라는 현판이, 옆면에는 ‘죽록정’이라는 현판이 걸려 있다. 식영정은 앞면 2칸·옆면 2칸…","a":"담양 송강정","c":"시도기념물","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653904.jpg"},{"q":"○○○○○은 16세기 전반기를 대표하는 성리학자이자 사림파 관료이다. 선조 초, 추숭 과정에서 기대승에 의해 ○○○명이 찬(撰)해졌고, 선조 10년(1577)에 이산해의 글씨로 옥산서원 내에 ○○○가 건립되었다. 9년 뒤인 1586년에는 손엽의 글씨로 ○○○가 다시 묘소 앞에 건립되었다.","a":"문원공 회재 이언적 신도비","c":"시도유형문화유산","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641148.jpg"},{"q":"○○○○는 사찰 입구에 설치해 두는 것으로, 절에 행사나 의식이 있을 때는 당이라는 깃발을 달아둔다. 이 깃발을 걸어두는 길쭉한 장대를 당간이라 하며, 당간의 양쪽에서 이를 지탱해 주는 두 돌기둥을 ○○○○라 한다. 흥덕향교 입구에 자리하고 있는 이 ○○○○는 속해있던 사찰이 ‘갈공사’라는 것만 전할 뿐 구체적인 내용은 남아있지 않다. 현재 ○○○○의 형태는 기단부(基壇部)와 당간받침이 모두 사라진 채 모서리끝을 둥글게 처리한 네모진 좌 ·우 두 기둥만 남아있다. 기둥 안쪽 맨 위에는 당간을 고정시키기 위한 구멍을 두었고, 바깥쪽에는 한면에 3구씩 연꽃무늬를 새기었다…","a":"흥덕당간지주","c":"시도유형문화유산","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639419.jpg"},{"q":"충청남도 천안시 수신면 ○○○에 있는 석불로 4각형의 대좌(臺座) 위에 서 있다. 상투 모양의 머리묶음이 표현된 머리는 몸체에 비해 크고, 코와 눈이 많이 손상된 얼굴은 시멘트로 보수하였다. 목에는 3개의 주름인 삼도(三道)가 있으며, 배 앞에는 속옷의 매듭이 보인다. 손은 배 앞에 모으고 양 손의 엄지를 맞대고 있는 모습이다. 불상 근처에 비석이 서 있는데 강희(康熙) 50년(숙종 42년, 1716)이라고 새겨져 있어서 불상도 비슷한 시기에 만들었을 것으로 추정된다.","a":"천안장산리석불입상","c":"문화유산자료","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661514.jpg"},{"q":"○○○은 영주지역의 연안김씨를 대표하는 건물로서 조선 선조20년(1587)의 건립년대가 확실하고 중수 내용까지 밝혀져 있다. 일반적으로 강학을 위한 평면구성방법은 중당협실형(中堂夾室形)이 많으나 여기서는 특이한 구조를 보이고 있다. 또한 상부구조와 창호구성, 치목수법 등에서 건축년대와 중수시기에 부합되는 부분들이 잘 보존되고 있다.","a":"만취당","c":"문화유산자료","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663488.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○를 처음 지은 정확한 연대는 알 수 없지만，인조 16년(1638)에 이곳 유림들이 지금 있는 자리로 옮겨 세웠다. 그 뒤 8차례 보수를 거쳐 오늘날의 모습을 갖추고 있다. ○○○은 공자를 비롯하여 중국과 우리나라 유학자의 위패를 모시고 제사를 지내는 곳이다. 앞면 3칸·옆면 3칸의 규모이며，지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕으로 되어 있다． 조선시대에는 나라에서 토지와 노비·책 등을 지원받아 학생을 가르쳤으나, 지금은 교육 기능은 없어지고 제사…","a":"정읍향교대성전","c":"문화유산자료","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661689.jpg"},{"q":"동강변의 바위 위에 있던 정자로, 1913년에 짓고 영락정이라 하였다. 1940년 신응인이 인수하여 ○○○으로 이름을 바꾸었으며, 1975년 안동댐 건설공사로 인하여 지금의 위치로 옮겨졌다. 앞면 3칸·옆면 2칸의 규모이며, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다.","a":"용암정","c":"시도유형문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640300.jpg"},{"q":"○○○는 조선조 선조 26년(1593) 6월 29일, 임진왜란 제2차 ○○성 전투에서 ○○성이 함락되고, 7만 민관군이 순절하자, 나라의 원수를 갚기 위해 왜장을 끌어안고 순국한 의기 논개를 제향하기 위해 세운 사당이다. 인조 7년(1629) ○○의 선비들은 논개가 순국한 바위에 의암(義巖)이라는 글자를 전각하였고, 경종 2년(1722)에는 그 위쪽에 「의암사적비」를 세웠다. 영조 16년(1740) 병사 남덕하(南德夏：1688∼1742)는 의기정포(義妓旌褒)를 계청하여 왕의 윤허를 받아 ○○○를 창건하였고, 이후 세 차례의 중수와 중건이 있었다. 지금의 건물은 195…","a":"진주 의기사","c":"문화유산자료","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663792.jpg"},{"q":"○○○ 고분은 해발 10∼15m 정도의 구릉 정상부에 위치하는데 ○○○ 27-1번지에 해당한다. 분구의 형태는 고분의 북서쪽은 모를 이루며 꺾이고 있고 남동쪽은 원형으로 돌아가고 있어서, 방형에 가깝지만 원형의 분위기도 보이고 있다. 다만 고분이 방형이라면 구릉의 능선과 45˚정도 틀어지게 되는데 이는 일반적인 방대형 고분의 입지와 차이를 보이는 것이다. 또한 분정에 형성된 10∼12m의 평탄부는 정연하지는 않지만 원형을 띠고 있어서 원분의 분구 끝자락이 파괴된 것일 가능성이 큰 것으로 생각된다. 분정 평탄부에는 함몰 구덩이가 2군데에서 확인되며 옹관편도 발견되었다.…","a":"나주장동리고분","c":"문화유산자료","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019051809572700.jpg"},{"q":"○○○은 청동기시대의 대표적인 무덤으로 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 ○○○은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 이 ○○○은 ○○읍에서 48번 국도를 따라 인화리 방면으로 가다 송해면과 하점면 경계지점을 지나 ○○○-망월간 도로의 중간지점, 고려산 북쪽에서 흘러내린 주능선의 끝자락에 있는 해발 15m 정도의 낮은 지대의 밭에 위치해 있다. 고임돌이 기울어져 무너져 내린 것…","a":"강화 부근리 점골 고인돌","c":"시도기념물","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2018112111231000.jpg"},{"q":"산을 등지고 자리잡은 이 집은 안채와 사랑채가 접하여 ㄷ자형 구조를 이루고 있는데, 一자형 헛간채가 배치되어 전체로는 ㅁ자형 배치를 띠고 있다. 안채는 툇마루를 설치한 대청마루를 중심으로 오른쪽에 웃방·안방·부엌을 직각으로 배치하였다. 왼쪽으로는 건넌방이 접하여 ㄱ자형을 이루고 있는데 이는 영서·중부 지방 민가 형식이다. 사랑채 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕으로 꾸며 높고 경쾌한 구성을 보이고 있다.","a":"영월 창원리 고택","c":"문화유산자료","r":"강원특별자치도","s":"영월군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660466.jpg"},{"q":"○○○ 마을에 있는 한 채의 비각 안에 나란히 서 있는 2기의 비이다. 앞에서 보아 왼쪽의 것이 효자비이고, 오른쪽의 것은 백비(白碑)인데, 백비는 비문이 많이 닳아 글씨가 거의 보이지 않아 붙여진 이름이다. 2기 모두 받침돌 위로 비몸을 세우고 머릿돌을 얹은 모습이다. 효자비는 영모재 이온 선생의 효행을 기리는 비로, 고려말 이 지역을 순시하던 이성계가 선생의 효행을 듣고 왕에게 보고하자, 우왕 9년(1383) 왕이 고성군수에게 명하여 비각과 비를 세우도록 하였다. 비는 앞면에 효행을 행한 마을이라는 뜻으로 ‘효자리(孝子里)’라 새기고, 뒷면에는 선생이 부친상을 당…","a":"합천 외토리쌍비","c":"시도유형문화유산","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642167.jpg"},{"q":"밀양 박씨의 옛집으로 대대로 진사와 효자가 태어났으며 조선시대 사대부 가옥의 형태를 잘 갖추고 있다. 이 집에서 효자 박효근이 출생하였고, 그의 아들 박한회와 손자가 진사를 지냈다. 조선 후기에 지어져 일제시대에 대규모로 고쳐 지은 이 가옥은 안채와 사랑채 2동, 곡간채 2동, 대문간채로 구성되어 있으며 담장이 잘 보존되어 있다. 대문에는 효자정려 현판이 붙어 있다. 앞면 5칸·옆면 2칸의 안채는 부엌, 방, 대청, 갓방으로 구성되어 있다. 안채를 중심으로 동쪽에 담장을 둘러 별당처럼 안사랑채를 배치하였고 중문간채를 바깥사랑채로 이용하였다. 중문에서 안채가 직접 보이…","a":"고성 박진사 고가","c":"문화유산자료","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664703.jpg"},{"q":"조선 중기 문신 학봉 김성일(1538∼1593) 선생의 종가이다. 김성일은 선조 1년(1568) 과거에 급제하여 정언과 수찬 나주목사 등을 역임하였다. 임진왜란 때는 경상도 초유사로 관군과 의병을 화합시켜 의병의 전투력 향상에 큰 공을 세웠다. 퇴계의 제자로 뛰어난 성리학자이기도 한 그의 학문은 이후 영남학파의 학문 전통에 큰 영향을 미쳤다. 가옥은 一자형 안채와 사당, 문간채, 풍뢰헌, 운장각으로 구성되어 있다. 운장각은 유물의 보관과 전시를 위하여 세운 것으로 선생의 유품과 문중에서 소장하고 있는 책과 옛 문서를 보관하고 있다.","a":"의성김씨학봉종택","c":"시도기념물","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654588.jpg"},{"q":"○○○은 조선 인조 때 이조판서와 대제학을 지낸 우복 정경세(1563∼1633)가 편찬한 아동용 수신 교과서이다. 이 책은 우복 정경세 자신이 나이 여덟살 되던 해에 아버지의 가르침을 받아가며 소학서로 윗사람에게 겸손하고 온순하는 방법을 배우고 이를 행하려 했으나 그리하지 못한 것을 후회하면서 자기 아들만은 자기의 전철을 밟지 않도록 하기 위하여 뛰어난 유학자의 『향교예집』가운데 「동자예편」을 약간 손질하여 어린이들이 쉽게 깨닫도록 만든 것이다. 선조 37년(1604)에 정경세 자신이 직접 손으로 써서 만든 것이다. 초학자의 휴대용 책처럼 간편한 책자나 시험준비서로…","a":"양정편","c":"시도유형문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636313.jpg"},{"q":"높은 터 위에 행랑대문채가 있고 그 안에 사랑채와 안채가 있는 집이다. 대문채는 一자형으로 오른쪽 둘째 칸은 사랑채와 연결되어 있고, 사랑채는 방과 방으로 연결되어 있으며 서쪽에는 툇마루를 달았다. 안채는 행랑대문채의 동북쪽에 자리하고 있고, 대청을 중심으로 좌우에 건넌방과 안방이 배치되어 있다. 안방의 남쪽에 부엌과 방이 있으며, 사랑채와 안채의 옆면 뒷쪽에는 정원으로 출입할 수 있도록 내칸을 두었다. 그리 오래된 것은 아니지만 안채와 정원이 잘 꾸며져 있으며, 전통 한옥건물에서 조금씩 현대화해가는 초기 과정의 특색을 보이고 있는 집이다. ※ 지정명칭을 \"부암동윤응…","a":"반계 윤웅렬 별장","c":"시도민속문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658049.jpg"},{"q":"∙ 조선 고종 17년(1880)의 명문 망와(光緖 六年, 庚辰 四月)로 볼 때 1880년 이전에 건립된 건물로 볼 수 있다. 현재 玉溪 金命欽의 종택으로 보존되어 있는 건물로 옥계문집과 명문 망와, 근대의 수리기록 등은 후대에 보존되어야할 자료이다. ∙ 전형적인 口자형 건물로 중문칸 좌측에 마구간과 고방을, 그리고 우측에는 사랑채를 두었다. 안채 중앙에는 2칸 대청과 반칸의 퇴칸을 둔 上房이 있고 좌측에 안방과 부엌을 배치하고 우측에 庫房을 두어 翼舍를 구성하였다. ∙ 안채 안방의 들창문 위치와, 사랑채의 사랑방과 사랑마루 사이에 둔 전실과 사랑방을 헌함까지 내밀어…","a":"옥계종택","c":"문화유산자료","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663644.jpg"},{"q":"영산강 유역에 펼쳐진 나주평야의 중심지에 있는 이 성은 ‘잣미’라 불리는 야산 정상부를 에워싼 테뫼식 산성이다. ○○○○이란 이름은 성을 뜻하는 우리말 ‘잣’과 산을 뜻하는 우리말 ‘메·뫼·미’가 합쳐진 말로, 성이 있는 산이란 뜻이다. 성의 둘레는 약 740m로 규모는 작으며, 말안장 모양의 산등성이를 흙으로 쌓은 후 돌로 보강한 것이다. 성 안에는 평탄한 건물터와 요왕천이란 샘터가 확인되었고, 문터는 3곳이 있으나 규모는 알 수 없다. 이곳을 중심으로 대안리고분군(사적), 덕산리고분군(사적 ), 신촌리고분군(사적)들이 있어서 성이 이 지역 중심세력의 근거지였음을…","a":"나주자미산성","c":"시도기념물","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654233.jpg"},{"q":"1층 기단(基壇) 위에 5층의 탑신(塔身)을 올린 석탑이다. 기단과 탑신의 1층 몸돌에는 기둥모양을 조각하였다. 두툼한 지붕돌은 밑면의 받침을 두었고, 네 귀퉁이는 살짝 들려있다. 꼭대기에는 노반(露盤:머리장식받침)과 복발(覆鉢 : 엎어놓은 그릇모양장식)이 남아 머리장식을 하고 있다. 전체적으로 탑신의 1층 몸돌이 높고, 2층 몸돌부터는 줄어드는 정도가 작다. 기단이 1층으로 줄어들고 지붕돌이 두꺼우며 지붕돌 밑면받침이 4단으로 줄어든 점 등으로 보아 고려시대에 세운 것으로 추정된다.","a":"강정리오층석탑","c":"시도유형문화유산","r":"전북특별자치도","s":"진안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639472.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다 조선 성종 4년(1473) 현감 최영이 세웠으며, 정유재란 때 불에 타 없어진 것을 영조 12년(1736)에 다시 짓고 그 뒤 여러 차례 수리가 있었다. 건물은 출입문인 재천루, 공부하는 곳인 명륜당, 학생들의 거처였던 회우재·출숙재, 사당인 대성전 등이 있다. 건물의 배치는 명륜당이 앞에 있고 대성전이 뒤에 있는 전학후묘의 형태인데 이것은 평지에 세워진 향교의 일반적인 전묘후학 배치와는 어긋난다. 따라서, 이것을 보안하기 위해 대성전의 기단과 층계를 높이 쌓은 것으로 보인다…","a":"안의향교","c":"시도유형문화유산","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641974.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 세종 27년(1475)에 지금 있는 자리에 처음 지었다. 그 뒤 화재로 인하여 폐교되고 여러 번 자리를 옮기는 등 수난을 겪으면서도 맥을 이어오다가 한국전쟁으로 불타 없어진 것을 1959년 대성전만 다시 세워 오늘에 이르고 있다. 중국과 우리나라 성현의 위패를 모시고 제사를 지내는 대성전은 돌담으로 둘러진 약 150평의 대지 중앙에 자리잡고 있다. 앞면 3칸·옆면 3칸의 규모이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕으로 꾸몄다. 조선시…","a":"동복향교","c":"문화유산자료","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662066.jpg"},{"q":"세운 시기를 정확하게 알 수 없으나 100년 이상 되었다고 전하며 안채와 사랑채, 헛간채로 구성된 ㅁ자형 구조이다. 안채 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 대청 기둥만은 굵은 원형의 기둥을 사용한 점이 특이하며 대청을 중심으로 오른쪽에 건넌방을 두고 왼쪽으로 안방과 부엌을 직각으로 두었다. 사랑채는 앞면 3칸·옆면 1칸 규모에 一자형 평면을 갖추고 있다. 마루방·사랑방·대문으로 구성되어 있는데 방의 앞쪽에는 넓은 툇마루를 설치하였다. 대문 왼쪽에는 2칸 사랑방을 배치하였고 방 앞면에는 툇마루를 놓았다. 헛간채는 나중에 늘려지은 건물로 양…","a":"영월 북쌍리 고택","c":"문화유산자료","r":"강원특별자치도","s":"영월군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660462.jpg"},{"q":"천등산 기슭에 있는 ○○○는 신문왕 2년(682) 의상대사가 지었다고 한다. 부석사를 세운 의상대사가 부석사에서 종이로 봉황새를 만들어 날려 보냈는데, 그 새가 내려앉은 자리에 절을 짓고 ○○○라 이름지었다는 전설이 전하여 온다. ○○○의 ○○○은 지조암과 함께 ○○○의 부속암자로 응진전, 영화실, 송암당, 삼성각, 우화루·관심당 등 5동으로 이루어져 있고, 건물의 구체적인 건립연대는 알 수 없으나 '○○○○○향로전창건기'와 ○○○○○전중수기'등의 사료로 볼 때 19세기 말로 추정된다. 건축적으로는 크게 주목할만한 부분은 없으나 우화루와 송암당 등에서 폐쇄적인 공간을…","a":"봉정사영산암","c":"시도민속문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658876.jpg"},{"q":"표암이란 ‘박바위’, ‘밝은바위’를 뜻하는데, 신라 6촌 가운데 알천 양산촌의 시조 이알평이 이 바위에 내려와 세상을 밝게 하였다하여 표암이라고 부르게 되었다고 한다. B·C 69년 6촌장이 여기에 모여 화백회의를 열고 신라 건국을 의결했으며, 그후 B·C 57년 신라가 건국되었다. 이와같이 표암은 경주이씨 혈맥의 근원지인 동시에 신라 건국의 산실이고 화백이라는 민주 정치제도의 발상지인 성스러운 곳이다. 이러한 뜻을 새긴 유허비가 조선 순조 6년(1806)에 세웠고, 1925년에 표암재가 건립된 뒤 매년 3월에 그 뜻을 기리며 제사를 지내고 있다.","a":"경주표암","c":"시도기념물","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654482.jpg"},{"q":"원래는 울산 도호부 객사였던 학성관의 남쪽 문루인데, 지금은 정자 형식을 갖추고 있다. 객사란 지방에 출장간 관리나 외국 사신이 얼마간 머물던 곳을 말한다. 태화루라 불리기도 했던 이 건물은 일제시대 말에 도서관을 겸해 사용해 오다가 1940년에 울산공립보통학교(지금의 울산초등학교)의 교정을 넓히면서 지금 있는 자리로 옮겨 짓게 되었다. 옮겨 지을 당시, 학성 이씨 월진파의 정각이었던 ○○○의 이름을 빌려왔고 건물도 정자 형식으로 일부 고쳐 지었는데, 누 아래쪽 양쪽 칸을 막아 온돌방을 만듦으로써 문루 형식에서 정자 형식으로 완전히 탈바꿈을 하게 되었다. 지붕은 옆면…","a":"이휴정","c":"문화유산자료","r":"울산광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659768.jpg"},{"q":"부여에 있는 부소산 동쪽 봉우리에 자리잡고 있는 누각으로, 이곳에서 보면 멀리 공주 계룡산의 연천봉이 아득히 바라다 보인다. 원래 이곳에는 영일대가 있어서 계룡산 연천봉에서 떠오르는 해를 맞이하던 곳이라고 전한다. 이 건물은 고종 8년(1871)에 당시 홍산 군수였던 정몽화가 지은 조선시대의 관아문이다. 1964년에 지금 있는 자리인 부소산성 안으로 옮겨 세운 뒤, 집홍정이라는 건물의 이름을 ○○○라고 고쳐 불렀다. ○○○는 앞면 3칸·옆면 2칸 규모의 2층 누각 건물이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여…","a":"영일루","c":"문화유산자료","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661050.jpg"},{"q":"종의 외형은 아래로 갈수록 약간 좁아지며, 고리는 두 마리의 용으로 형상화하였고 천판(天板)은 둥글고 낮게 만들었다. 종의 몸체는 횡선으로 공간을 구획하였는데, 상단과 하단에 2줄을 만들어 세 부분으로 나누었다. 상단에 있는 횡대 윗부분에는 원형범자문이 둘러져 있다. 몸체 중심부에는 보살상과 연곽이 번갈아 배치되었다. 두광을 갖춘 보살상은 두 손을 모으고 구름 위에 서 있으며, 사다리꼴 형태의 연곽 안에는 연꽃 5개가 간략하게 표현되었다. 보살상과 연곽은 종의 몸체에 비해 크게 나타난다. 하단 아래에는 특별한 장식이 없다. 명문에 의하면, ○○은 1767년(영조 43…","a":"함양 백운암 건륭32년 동종","c":"시도유형문화유산","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643163.jpg"},{"q":"전북특별자치도 정읍시 고부면 해발 443m의 두승산 산봉우리를 에워 싼 산성으로, 성 안에 골짜기를 품고 있다. 승고산성 또는 영주산성이라고도 한다. 9개의 봉우리를 이룬 천연의 절벽을 이용하여 쌓은 성벽은 둘레가 500m가 넘으며, 성 안에는 서쪽과 남쪽의 두 골짜기가 있다. 현재 성의 대부분이 무너져 내렸으나, 옛날 모습이 약간 남아있으며, 골짜기를 품고 있는 서쪽과 남쪽에는 문터가 남아 있다. 성이 지어진 연대에 대해서는 확실한 기록이 남아있지는 않지만 성 안에서 발견되는 유물들로 보아 삼국시대 백제가 쌓아서 계속 사용해왔던 것으로 추정된다.","a":"두승산성","c":"시도기념물","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653508.jpg"},{"q":"서울 관악산 북쪽 중턱의 거대한 절벽 바위면에 돋을새김으로 조각한 불상으로, 미래세계에 나타나 중생을 구제한다는 ○○○을 형상화한 것이다. 민머리에 상투 모양의 둥근 머리묶음이 낮게 표현되었으며 얼굴은 갸름한 편이다. 늘씬하게 표현된 신체와 둥글게 깎인 어깨 등으로 보아 상당히 우수한 조각가의 작품으로 보인다. 이 불상은 1630년이라는 절대연대를 가지고 있어서 조선시대 조각사 편년 연구에 귀중한 자료가 되며, ‘미륵존불(彌勒尊佛)’이라는 글을 통해 17세기 조선사회에도 미륵신앙이 유행하고 있었음을 알려준다. 따라서 17세기 조선시대 불상을 대표하는 기준이 될 만한…","a":"봉천동 마애미륵불좌상","c":"시도유형문화유산","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636186.jpg"},{"q":"○○○이 사용한 거문고(현금)와 거문고의 옛날 악보인 『○○○』로 그의 후손이 소장하고 있다. ○○○은 조선 숙종 때 양양부사와 순천부사를 지낸 유경시의 손자이다. 이 거문고는 1726년에 만들어진 것으로, 앞판은 오동나무로 만들었고, 앞판과 뒷판이 서로 떨어져 있다. 앞판의 뒷면에 명문이 있어, 재료의 출처와 만든시기를 알 수 있다. 밤나무로 만든 뒷판은 옆 귀퉁이가 약간 갈라져 있으나, ○○○ 문집의 시를 적어 놓아 이 거문고의 오랜 내력을 증명하고 있다. 전체길이 160㎝로 안족 2개와 괘 16개가 원형대로 남아 있고, 돌괘 1개가 있다. 부속품이 일부 떨어져…","a":"강포유홍원의현금및어은보","c":"시도유형문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641011.jpg"},{"q":"풍호라는 호수를 끼고 바다를 바라보고 있는 얕은 언덕에 위치한 무덤이다. 무덤의 내부구조를 보면 돌덧널(석곽)을 만들고 시신을 위에서 아래로 넣은 구덩식돌덧널무덤(수혈식석곽묘)이다. 돌덧널 안에는 시신을 안치하는 으뜸덧널(주곽)과 껴묻거리(부장품)만 넣는 딸린덧널(부곽)로 구분된다. 출토 유물로는 목긴항아리(장경호)·굽다리접시(고배) 등이 있다. ○○○ 무덤들은 그 구조와 유물을 종합해 볼 때 삼국시대에 만들어진 것으로 생각되는 곳이다.","a":"하시동고분군","c":"시도기념물","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647752.jpg"},{"q":"반계사에 모셔진 조선 선조 때의 정경달(1542∼1602)과 관련된 자료들이다. 반계사는 숙종 40년(1714)에 영광 정씨 문중이 중심이 되어 건립한 것으로,영광 정씨의 정인걸, 정경달, 정명설, 정남일 네 사람과 임진왜란과 정유재란 때 큰 공을 세운 이순신, 임영립을 모시고 제사를 지내는 건물이다. 고종 5년(1868) 훼손 되었던 것을 1957년 지금의 자리에 강당을 새로 짓고, 1959년에 탑을 세워 사우로서의 기능을 대신케 하였다. 유물과 유품들을 살펴보면 다음과 같다. 반곡의『난중일기』는 정경달이 임진왜란 초에 참전했던 일기와 명군접반사로 재직할 당시의 일…","a":"장흥 반계사와 소장유물","c":"시도유형문화유산","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640080.jpg"},{"q":"○○○○○은 영양남씨 참봉공 남필대(南必大: 1608-1666)가 중수한 이후 남달만(南達萬: 1713-1784)이 중수하였다는 기록이 있으며, 이후 지속적인 크고 작은 보수를 통해 오늘날까지 이어져오고 있다. 과거 이 건물은 종가에 딸린 건축물인데 기존의 종가 건축물의 유구를 찾아 볼 수 없는 점은 아쉬운 점이다. 다만 종가의 옛 모습은 한국전쟁 이후 건립한 안채와 사당을 통해 추정해볼 수 있다. 그리고 ○○○은 ○○ 인량리에 약 600여년 간 세거해 온 영양남씨의 대표적인 건물로 문중의 구심점 역할을 해왔으며, 인량리의 영양남씨는 17세기 이후 영남학파의 일원으로…","a":"영덕 처인당","c":"문화유산자료","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018101611535700.JPG"},{"q":"조선 초기의 문신이자 안평대군의 장인인 정연(鄭淵, 1389~1444)의 묘이다. 묘역은 부인 단양 우씨(丹陽禹氏)와 합장된 단분(單墳; 하나의 봉분)의 형태이고, 석물은 원형이 잘 보존되어 있다. 봉분은 사각형태로 매우 크고, 하단에는 장대석으로 둘레석을 조성하여 봉분을 보호하였다. 묘역은 계단식으로 3단으로 나누고 계체석(階砌石 ; 묘역을 구분하는 편평하고 긴 경계석)으로 구분하였다. 봉분 앞에는 묘표(墓表 ; 무덤 주인공의 이름 등을 새긴 비석) 2기를 나란히 세웠는데, 정면 왼쪽이 정연 묘표이고, 정면 오른쪽이 단양 우씨의 묘표이다. 정연의 묘표는 1444년에…","a":"정연묘역","c":"시도기념물","r":"경기도","s":"파주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2018010218461300.jpg"},{"q":"○○○은 태종 4년(1404) 11월에 당시에 생존하고 있던 개국공신, 정사공신, 좌명공신인 3공신 66명이 하늘에 맹세한 후 작성한 글을 목판에 새겨 인쇄한 것이다. 이것은 ○○○ 가문에서 소장하고 있는 ○○○의 ○○○이다. ○○○는 고려 말 조선 초의 변혁기에 무반으로 입신하여 박포의 난이라고 불려지는 정쟁에 참여하여 좌명공신 4등에 책봉되었다. 이후 공조판서, 병조판서 등을 역임하였으며, 평양부원군에 책봉되었다. 그가 죽은 후 나라에서 ‘양경’이라는 시호를 내렸다. 이 판본은 태종 4년(1404)부터 태종 7년(1407)에 인쇄하여 간행되었을 가능성이 많고, 보…","a":"김승주삼공신회맹록판본","c":"시도유형문화유산","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640997.jpg"},{"q":"○○○○○유적지는 중서부 내륙의 암사동유적을 제외한 서해 도서지역에서 확인된 최대 규모(17기)의 신석기 주거지로서, 기존의 패총 중심의 조사와 연구에서 벗어나 도서지역에서의 취락을 통한 생업 및 주거양식에 대한 연구를 진전시킬 수 있었다. 즉, 서해안 일대의 유적들이 내륙 주민들의 자원 획득을 위한 방문 및 단기 점유로 형성된 것이라는 기존의 가설이 해당 지역의 모든 유적을 설명해 줄 수 없다는 점이 제기되었다. 주거지 내에서 발견되는 유물 및 시설은 서해 중부지역 신석기시대 문화의 연구에 새로운 가능성을 제공할 것이다. 유적지에서는 신석기시대의 수혈주거지 17기,…","a":"삼목도 선사 유적","c":"시도기념물","r":"인천광역시","s":"영종구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645728.jpg"},{"q":"이 가옥은 해방 전후시기 대표적인 정치지도자로서 광복 후 제헌국회 부의장, 국회의장을 역임한 해공(海公) 신익희(申翼熙, 1894∼1956)의 생가이다. 원래는 지금 위치에서 동남쪽으로 약 200m 지점에 가옥이 있었으나 1865년 을축년 대홍수로 집이 파손되어 1867년경에 현위치로 이전하였다고 전한다. 그러나 건축물대장에 의하면 집은 1925년에 건축되었다고 기재되어 있다. 가옥은 안채와 바깥채로 구성되어 있으며 모두 목조 기와집으로 전통한옥의 외관을 잘 간직하고 있다. 안채는 전체적으로 T자형을 이루는데 중앙의 2칸 대청을 중심으로 우측에 안방, 좌측으로 건넌방…","a":"신익희생가","c":"시도기념물","r":"경기도","s":"광주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646687.jpg"},{"q":"조선 초기 개국공신이자 청백리의 한 사람인 하정(夏亭) 유관(柳寬, 1346∼1433) 선생의 묘이다. 묘역은 부인 광주 안씨(廣州安氏)와 함께 매장된 쌍분(雙墳; 두개의 봉분)의 형태이다. 봉분은 아래 부분에 사각형의 둘레석을 조성하였는데 고려말~조선 초기의 특징이다. 봉분의 옆에는 원수방부형(圓首方趺形; 둥근 머릿돌과 사각 받침돌의 비석 형태)의 옛 묘표(墓表; 무덤 주인공의 이름 등을 새긴 비석)가 있다. 처음 묘역을 조성할 당시의 옛 석물로는 석인 1쌍이 있다. 장대형의 지물을 쥐고 있는 독특한 시자석인(侍者石人)으로, 머리에는 사방관(四方冠)을 쓰고, 직령포…","a":"유관선생묘","c":"시도기념물","r":"경기도","s":"양평군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646136.jpg"},{"q":"강원특별자치도 화천군 간동면 ○○○ 절터에 있는 불상으로, 현재 머리와 목 부분을 잃어버린 상태이다. 상체와 하체는 딴 돌로 만들어져 분리될 수 있다. 상체는 떡 벌어진 어깨와 발달된 가슴으로 당당한 모습이다. 얇은 옷을 몸에 밀착시켜서 잘록한 허리가 더욱 강조되었다. 양 어깨에 두른 옷에는 U자형의 옷주름이 새겨져 있다. 도식적인 옷주름 처리로 사실성이 결여되고 조각수법의 미숙으로 생동감이 떨어지고 있다. 오른쪽 어깨와 손목 부분이 깨졌는데, 다소 부자연스럽게 표현된 두 손은 정확한 모양을 알 수 없다. 왼손은 팔을 약간 벌린 듯 구부려 왼쪽 가슴에 얹고 있으며,…","a":"화천성불사지석불입상","c":"시도유형문화유산","r":"강원특별자치도","s":"화천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638152.jpg"},{"q":"조선 초기(朝鮮初期)의 명재상(名宰相)이며 청백리의 표상인 방촌 황희(厖村 黃喜, 1363∼1452)선생의 유업을 기리기 위하여 후손들이 영정을 모시고 제사를 지내는 곳이다. 선생의 호를 따라 방촌영당이라고도 한다. ○○○○은 오늘 날에도 존경받는 조선의 최장수 재상으로 고려말부터 조선으로 교체되던 우리 역사의 격동기 속에서 활동했었다. 그는 여러 요직을 두루거치며 문물과 제도 정비에 노력하여 조선 태종(太宗)대에 국가기반을 확립하는데 큰 업적을 남겼다. 그리고 세종(世宗)대에는 20여년 동안 국정을 총리하는 의정부(議政府)의 최고 관직인 영의정부사(領議政府事)로서…","a":"황희선생영당지","c":"시도기념물","r":"경기도","s":"파주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645997.jpg"},{"q":"장열공 정담(1548∼1592)선생의 위패를 모신 사당이다. 정담 선생은 조선 선조 임금대의 충신으로 여러 벼슬을 지낸 분이다. 청주목사로 있던 선조 25년(1592)에 임진왜란이 터지자 의병을 일으켜 의병장 황박, 나주판관 이복남과 함께 웅치를 방어하다가 전사하였다. 임진왜란 후 선생은 병조참판 겸 의금부사에 추증되고 비도 세웠다. 숙종 16년(1690)에는 정충각을 세웠고 향현사에 모셔 제사를 지냈는데, 순조 임금 때 ‘장렬공’이라는 시호를 받았다. 이 사당에는 교지 7점과 장군의 공적을 적은 『충렬록』, 판각 85매와 『충렬록 전적』 2권 등의 유물들을 보관하고…","a":"영양 야성정씨 참판공 종택","c":"문화유산자료","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662514.jpg"},{"q":"조선 후기의 무신인 감고당 권희학(1672∼1742) 선생의 초상화이다. 권희학은 영조 4년(1728) 이인좌의 난이 난을 평정하고 공신으로 봉해졌는데, 이 그림은 그 이후에 그려진 것으로 보인다. 약간 오른쪽을 바라보고 앉아 있는 전신상으로, 머리에 사모를 쓰고 관복을 차려입은 채, 두 손은 관복의 옷소매 안으로 단정하게 넣은 자세이다. 사모는 꼼꼼히 표현하였으며, 관복의 가슴에는 구름과 학무늬를 둔 흉배를 그려 넣었다. 얼굴은 수염을 세밀하게 묘사하여 그 윤곽을 대신하였으며, 눈과 눈썹은 위로 치켜오르게 표현하여 담대한 무인의 상을 나타냈다. 뛰어난 화가의 솜씨는…","a":"화원군영정","c":"시도유형문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640873.jpg"},{"q":"석곡리 마을회관 내에 자리하고 있는 탑으로, 이곳에서 조금 떨어진 옛 절터에서 옮겨왔으며, 함께 발견된 석곡리미륵불(충청남도문화유산자료)이 옆에 남아 있다. 탑은 1층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습인데, 탑신부의 3층 몸돌은 없어진 상태이다. 기단은 네장의 판돌을 세워 4면을 이루고 있고, 각 면의 모서리와 가운데에 기둥 모양을 새겨두었으며, 탑신부의 각 몸돌에도 모서리마다 기둥 모양을 새겨 놓았다. 지붕돌은 밑면에 3단씩의 받침을 두고 있고, 처마는 수평을 이루다 네 귀퉁이에서 살며시 들려 있다. 기단의 일부가 깨져 있거나 비뚤어진 상태이고, 지…","a":"석곡리석탑","c":"문화유산자료","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661201.jpg"},{"q":"서부동 마을 뒤의 호두산 아래 골짜기에 남아 있는 탑의 일부분들이다. 주변에서 통일신라시대, 고려, 조선에 이르는 기와조각과 자기조각들이 발견되어 사찰이 조선 중기까지는 존재하고 있었던 것으로 추정된다. 원래의 탑은 일반적인 3층 석탑이었을 것으로 보이는데, 현재 탑신(塔身)의 1·2층 부재만 남아 있다. 남아 있는 1층 지붕돌은 네 귀퉁이가 살짝 치켜 올라갔고, 두께도 얇으며, 밑면에는 5단의 받침을 두었다. 원형을 알 수 없지만 지붕돌 양식으로 보아 통일신라시대에 세운 것으로 추정된다. 또한 이 골짜기는 임진왜란 당시 왜병의 진로였다는 설이 있어, 그 때 탑이 무…","a":"김천 서부리 삼층석탑","c":"문화유산자료","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662632.jpg"},{"q":"조선 중종(재위 1506∼1544) 때 기묘사화로 희생된 안처순을 중심으로 정환·정황·이대병 등의 위패를 모신 서원이다. 안처순은 조선 중기 문신으로 지방학교를 발전시키고자 노력한 사람이다. ○○○○은 광해군 11년(1619)에 세웠으며, 숙종 12년(1686)에 나라에서 현판을 내려 사액서원이 되었다. 고종 5년(1868)에 철거되었다가 광복 후에 후손들이 다시 세워 오늘에 이르고 있다. 사당은 앞면 3칸·옆면 2칸 규모의 건물로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 공부하는 장소인 강당 역시 맞배지붕으로 꾸몄으며, 규모는 앞면 3칸·옆면…","a":"영천서원","c":"문화유산자료","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661635.jpg"},{"q":"불상을 모시기 위해 나무나 돌, 쇠 등을 깎아 일반적인 건축물보다 작은 규모로 만든 공간을 불감(佛龕)이라 한다. 불감은 그 안에 모셔진 불상의 양식뿐만 아니라, 당시의 건축 양식을 살필 수 있는 중요한 자료가 된다. 송광사의 16번째 국사인 고봉화상이 소지했던 원불(願佛)이라 전하고 있다. 이 불감은 문을 열면 바로 양편 문 내벽에 문짝이 있고, 내부벽에 불·보살 등을 양각으로 조각하였다. 중앙에 있는 주존불(主尊佛)은 대일여래불로 손모양은 통일신라시대 이후 전통적인 비로자나불이 보통 취하는 손모양이 아닌 금강권인을 하고 있다. 좌우 부처는 모두 여래상으로서 왼쪽에…","a":"고봉국사주자원불","c":"시도유형문화유산","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639852.jpg"},{"q":"청동기시대 고인돌과 신라의 무덤이 섞여 분포하고 있는 곳이다. 발굴조사 결과 총 유구의 수는 27기이며 그 중 16기는 BC 5∼6세기 청동기시대의 고인돌(지석묘)이고 나머지 유구는 신라시대 무덤이다. 대부분의 고인돌 유구는 2∼4매의 덮개돌이 남아 있고 덮개돌이 없는 유구는 경작으로 유실된 것으로 보인다. 유물은 민무늬토기(무문토기), 간석기(마제석기) 등이 있다. 신라시대 무덤은 대부분 앞트기식 돌방무덤(횡구식석실묘)으로서 주위에 묘를 보호하는 의미를 갖고 있는 둘레돌(호석)이 둘러져 있다. ○○○○○무덤들은 청동기시대 고인돌과 신라의 무덤이 같은 장소에 있어 두…","a":"거제 아주동 고분군","c":"시도기념물","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655950.jpg"},{"q":"일제에 의해 강제로 체결된 을사조약과 한일합방을 통탄해하며 자결한 송병선(1836∼1905)과 송병순(1839∼1912) 형제의 위패와 영정을 모시고 제사 드리는 사당이다. 송병선은 우암 송시열 선생의 9대 손으로 학문이 뛰어나 천거되었으나 관직에 나가지 않았다. 19세기말 외세가 물밀듯이 들어와 나라의 앞날이 어려워지자 『근사속록』을 간행하였다. 또한 1905년 불법적인 을사조약이 체결되었을 때는 고종에게 조약 파기와 을사 5적을 처단할 것을 진언하기도 하였다. 다시 고종을 만나려다가 일본 헌병들에게 체포되었는데 상소문을 올리고 음독 자결하였다. 송병순은 고종 25…","a":"문충사","c":"문화유산자료","r":"대전광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659695.jpg"},{"q":"중원탑평리칠층석탑(국보)에서 남쪽으로 2㎞쯤 되는 지점에 자리한 5층 석탑으로, 원래는 민가의 뒷뜰에 있던 것을 100여m 남쪽으로 옮겨 복원해 놓은 것이다. 2층 기단(基壇) 위에 5층의 탑신(塔身)을 올린 모습이며, 현재 맨 위의 머리장식이 없어진 채 그 받침돌만 남아 있다. 위로 오를수록 조금씩 규모가 줄어드는 탑신의 각 몸돌에는 네 모서리마다 기둥모양의 조각을 두었다. 지붕돌과 몸돌은 각기 다른 돌로 조성되어 있는데 5층에서만은 한 돌로 되어 있어 흥미롭다. 지붕은 네 귀퉁이가 부드럽게 치켜올라갔고, 위로 올라갈수록 밑면의 받침수가 줄어드는 특징을 보인다. 이…","a":"충주 창동리 오층석탑","c":"시도유형문화유산","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638405.jpg"},{"q":"○○○ 선생이 살았던 마을에 서 있는 비로, 선생의 효행을 기리고 있다. 삼우당 ○○○은 고려시대 후기의 학자이자 문신이다. 중국에서 목화씨를 가져온 것으로도 잘 알려진 그는 효성이 지극하여 모친이 돌아가시자 묘곁에서 움막을 짓고 살았다. 당시는 왜적의 침입이 잦아 그들이 지나가는 곳마다 노략질이 심하여 모두 피난을 가고 있었는데, 그 만이 홀로 평상시와 같이 곡을 하고 있었다. 왜적도 그의 이러한 효성에 감동하여 나무를 다듬어 ‘효자를 해치지 말라’라고 써서 세워 놓도록 하니, 그 때부터 이 지역이 평안하였다 한다. 그 후 조정에서는 고려 우왕 9년(1383) 그에…","a":"산청 문익점 효자비","c":"문화유산자료","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663915.jpg"},{"q":"조선 세조(재위 1455∼1468) 대의 공신인 ○○○ 선생의 묘소이다. 그는 병조판서 등의 주요 관직을 지낸 후 세조 7년(1461) 목천현 오동 부락에 내려가 살았다. 그 뒤 조정에서 좌의정의 관직을 내렸으나 나가지 않고 시골에 묻혀 살았으며 성종 1년(1470)에 세상을 떠났다. 조정에서는 이를 가상히 여겨 장례품을 내리고 예를 갖추어 장례를 치루도록 명하였다. 묘는 조선 초기의 전형적인 양식으로 봉분 아래에는 둘레석을 둘렀으며, 주위에는 문인상과 묘비 등을 세웠다. 후대에 보수한 흔적이 있으나 비교적 본래의 모습을 유지하고 있다.","a":"신자경선생묘","c":"시도기념물","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652799.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. ○○○○는 태조 1년(1392)에 능주 서쪽에 지었으나 임진왜란 때 불에 타 없어져 선조 33년(1600)에 하응도가 지금의 자리로 옮겼다. 그 뒤에 여러 차례의 수리를 거쳐 오늘에 이르고 있다. 경사진 곳에 위치하여 뒤쪽 높은 곳에 대성전과 동무·서무가 제사공간을 형성하고, 앞쪽에는 명륜당과 동재·서재가 배움의 공간을 형성하여 전학후묘의 배치를 이루고 있다. 조선시대에는 국가로부터 토지, 노비, 책 등을 지급 받아 학생들을 가르쳤으나, 갑오개혁(1894) 이후에 교육적 기…","a":"능주향교","c":"시도유형문화유산","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639986.jpg"},{"q":"1558년 돈암 정지영이 현 위치보다 조금 상류인 덕추폭포 부근에 초가로 건립하였으나 임란 때 소실되었고 1770년에 후손들이 중수하였으나 풍수해로 훼철되었다. 1845년 7세손 정복운 등이 현재의 위치에 재건하였으며 1948년에 중수가 있었다. 심원정은 용추계곡 입구의 매표소 바로 우측을 흐르는 지우천 계곡의 제 1담소인 청심담의 거북바위위에 건립되었으며 심진동 초입에 세운 정자이다. 옛 안의에는 삼가승경(三佳勝景)인 심진동 심원정, 원학동 수승대, 화림동 농월정을 삼가승경(三佳勝景)으로 불렀다. 심원정은 정면 3칸, 측면 2칸 규모이며 단동으로 세워진 중층 누각건…","a":"함양심원정","c":"문화유산자료","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665621.jpg"},{"q":"이 ○○○은 전체적으로 본지의 박락과 안료의 변색으로 인해 화면이 칙칙하고 어두운 상태이며, 군데군데 곰팡이가 피어 있고 또한 화면 하단의 화기란 일부도 손실된 상태이다. 화면은 상하로 이분되어 상단에는 합장한 제석천이 천자와 천녀·동자를 거느리고 모두 서서 향우측을 향해 나아가는 모습이며, 하단에는 합장한 위태천이 용왕과 신중 등의 3위와 함께 역시 향우측을 향하여 서 있는 모습이다. 전체적으로 녹색과 적색을 주조색으로 하여 일부 금박을 사용하여 선명함을 살리고 있으나, 안료의 변색으로 원래의 색조보다 훨씬 퇴색된 상태이다. 이 ○○○은 기존의 제석천도와는 달리 입…","a":"남해운대암제석신중탱","c":"문화유산자료","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666277.jpg"},{"q":"이 동종은 옛부터 ○○○에서 조석으로 타종해온 것으로 전하며, 고봉절정 암자에서 들려오는 이 종소리에 옛 어느 고승께서 「운암모종(雲庵暮鐘)」이라는 시를 읊었다고 한다. 총 높이 49cm 정도의 동제범종으로 천판과 종신 표면이 일부 매끄럽지 못하고 다듬은 흔적이 역력하나, 파손된 부분은 잘 보수되어 있어 그 본래의 형태를 잘 유지하고 있다. 제작시기는 종의 비례와 용뉴, 범자원권문(梵字圓圈文) 배치 등으로 보아 중국 범종의 영향을 받은 조선후기 작품으로 보이나, 다행히 종신 하단에 점자 명문을 통해 ‘건륭오십년을사(乾隆伍拾年乙巳)년’, 즉 1785년에 남해 화방사(花…","a":"남해망운암건륭을사명동종","c":"문화유산자료","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665026.jpg"},{"q":"○○○는 선사 시대의 돌무덤인 고인돌을 말한다. 처음에는 ○○○ 마을 앞 서쪽 들판 입구에 8기가 반경 30m안에 분포되어 있다. 주민들은 예로부터 이 ○○○를 7기로 인식하였고 ‘칠성바위’라고 부르며 일부는 보호 울타리를 둘러 관리하고 있다. 받침돌 위에 올려진 큰 돌을 덮개돌이라고 하는데 ○○○○○의 덮개돌의 규모는 대체로 30cm~60cm이다. 가장 큰 2기의 ○○○의 덮개돌은 340cm×260cm×20cm이다. 1968년에 경지를 정리할 때 ○○○ 주변에서 돌널무덤과 돌뚜껑움무덤이 확인되었고 그 내부에서 돌을 갈아서 만든 단검인 간 돌검과 그릇의 겉에 붉은 칠…","a":"고성 학림리 지석묘","c":"시도기념물","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654907.jpg"},{"q":"여타의 고승 진영 작품과 비교해 19세기 초반의 작품으로 추정된다. 배경의 산수 처리기법이 원형 화문으로 시문된 점은 독특하며 민화적인 요소가 엿보이는 작품으로 향후 고승 진영이나 민화, ○○○ 연구적 자료 가치가 있다. 이 ○○○은 일명 나반존자라고도 칭하며 미래에 사바세계에 출현할 미륵존불을 기다리며 천태산상에서 독수선정에 들어 있는 독성을 묘사한 불화이다. 화기에 연화질의 명기를 생략한 상태를 보아 지장시왕탱 조성과 동시에 조성된 것으로 추정되며, 이는 1855년(咸豊 5년)의 작품으로 보인다. 약간의 훼손은 되었으나 비교적 양호한 상태로 수장고에 보관, 관리되…","a":"남해 화방사 독성탱","c":"문화유산자료","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666676.jpg"}]);